__reload_all = true
local System = require("System.System")
local readonly = System.readonly
local Text_Voice = readonly({
  Voice_100335_AwakerVoiceContent = {
    Text = "Penjaga, kapan aku bisa mengunjungi kuburan di akademi? Jiwa-jiwa agung yang terbaring di sana pasti bisa memberiku inspirasi yang luar biasa! Jangan khawatir, aku berjanji tidak akan lagi menggali mayat-mayat itu untuk melihatnya dari dekat..."
  },
  Voice_100335_AwakerVoiceTitle = {
    Text = "Bicara Santai: Tentang Model"
  },
  Voice_100336_AwakerVoiceContent = {
    Text = "Tunggu! Saya baru saja memikirkan cara baru untuk mengekspresikannya, pasti akan mengejutkan seluruh dunia seni lukis!"
  },
  Voice_100336_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_100337_AwakerVoiceContent = {
    Text = "Saya adalah cahaya dan bayangan, saya adalah warna, saya... adalah lukisan itu sendiri!"
  },
  Voice_100337_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_100338_AwakerVoiceContent = {
    Text = "Sss… warna yang belum pernah aku lihat sebelumnya, bersinar di dunia roh-mu… apakah itu…"
  },
  Voice_100338_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_100338_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_100339_AwakerVoiceContent = {
    Text = "Betapa hebatnya cat hitam ini! Aku telah mengumpulkan banyak cairan pelarutan untuk melukis, dan akhirnya semua lukisan itu menghilang. Warna dari alam semesta yang primordial, setiap gambar telah ditelan, lukisan yang tidak diingat oleh siapa pun… Bukankah itu lebih hebat?!"
  },
  Voice_100339_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Krisis"
  },
  Voice_100340_AwakerVoiceContent = {
    Text = "Biarkan saya mendekat sedikit… Biarkan saya melihat lebih banyak! Bayangan-bayangan ini, warna-warna ini, sikap-sikap ini… dibandingkan dengan mereka, apa yang saya lukiskan sebelumnya hanyalah tumpukan kertas sampah…"
  },
  Voice_100340_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_100340_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_100341_AwakerVoiceContent = {
    Text = "Dulserain terus menerus memberitahu saya betapa seninya memasaknya, meminta saya untuk melihat, makan dan seni sama sekali tidak ada hubungannya! Tidak hanya harus membuang waktu berharga untuk melakukan pekerjaan pengolahan mayat yang rumit, dengan susah payah menciptakan makanan yang sempurna, dan kemudian harus menggigit dan melahapnya! Ini benar-benar merupakan sebuah kejahatan terhadap seni!"
  },
  Voice_100341_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_100342_AwakerVoiceContent = {Text = "Ngh..."},
  Voice_100342_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_100343_AwakerVoiceContent = {
    Text = "Model yang buruk…"
  },
  Voice_100343_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_100344_AwakerVoiceContent = {
    Text = "Tidak, tidak, ini lagi-lagi lukisan yang buruk…… harus ke mana untuk mencari inspirasi. Pemakaman? Atau lokasi eksekusi……"
  },
  Voice_100344_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_100345_AwakerVoiceContent = {
    Text = "Meskipun saya merasa bahwa bentuk seni pahat ini terlalu kaku dan kuno, tetapi pemahat yang bernama Sanga, pahatannya memiliki daya ungkit ekspresi yang melebihi apa yang bisa dibawa oleh bentuk seni ini... sungguh seorang jenius yang langka!"
  },
  Voice_100345_AwakerVoiceTitle = {
    Text = "Percakapan: Tentang Sanga"
  },
  Voice_100345_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Sanga\", akan terbuka."
  },
  Voice_100346_AwakerVoiceContent = {
    Text = "Apakah kamu melihat lukisan ini, Penjaga? Ini adalah potret yang aku lukis untukmu. Lihat saja bagaimana tampangnya saat kamu mengigit mayat, betapa menawannya! Aku tahu, tidak semua orang bisa memahami karyaku, tapi keindahan kegilaan yang disampaikan oleh lukisan ini, pasti sudah kamu sentuh, kan?! Bagi aku, itu sudah cukup, sangat cukup......"
  },
  Voice_100346_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_100346_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_100347_AwakerVoiceContent = {
    Text = "Anda baru saja mengatakan ingin membeli lukisan ini… Benarkah?! Terima kasih, Penjaga! Sangat sedikit manusia yang bisa menghargai ini…"
  },
  Voice_100347_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_100347_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_100348_AwakerVoiceContent = {
    Text = "Penjaga, apakah kamu masih punya waktu untuk menjadi modelku? Dibandingkan dengan penampilan yang kulihat di dirimu saat terakhir kali, model lainnya sama sekali membuang-buang waktuku..."
  },
  Voice_100348_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_100349_AwakerVoiceContent = {
    Text = "Saksikan kehidupan baru di lukisan ini!"
  },
  Voice_100349_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_100350_AwakerVoiceContent = {
    Text = "Lihat garis-garis hidup ini!"
  },
  Voice_100350_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_100351_AwakerVoiceContent = {
    Text = "Saya memiliki firasat, apa yang diciptakan oleh kuas ini, akan membuat semua orang terkesima!"
  },
  Voice_100351_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_100352_AwakerVoiceContent = {
    Text = "Ah! Sebuah cat yang baru dan unik… aku akan mengoleskannya di tempat yang paling tepat!"
  },
  Voice_100352_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_100353_AwakerVoiceContent = {
    Text = "Tempat ini benar-benar tempat yang penuh inspirasi! Saya mendapatkan beberapa ide baru lagi, Penjaga, apakah Anda punya waktu untuk mengunjungi studio lukisanku baru-baru ini? Ayo, ayo!"
  },
  Voice_100353_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_100353_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_100354_AwakerVoiceContent = {
    Text = "Betul sekali, betul sekali! Kemenangan yang disiram darah! Betapa hebatnya komposisi!"
  },
  Voice_100354_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_100355_AwakerVoiceContent = {Text = "Ngh..."},
  Voice_100355_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_100356_AwakerVoiceContent = {
    Text = "Ah! Silakan duduk, Penjaga. Menjadi modelku adalah pekerjaan yang melelahkan. Jangan khawatir, aku pasti akan menciptakan karya seni yang luar biasa untukmu."
  },
  Voice_100356_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_100356_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_100357_AwakerVoiceContent = {
    Text = "Seorang seniman seharusnya hanya memiliki karya seni di matanya dan tidak peduli dengan pandangan orang lain terhadap dirinya, namun aku tidak bisa melakukannya... Sejak pertama kali aku mengambil kuas, aku sudah berharap untuk membawa keindahan sejati kepada semua orang."
  },
  Voice_100357_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_100357_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_100358_AwakerVoiceContent = {
    Text = "Tempat ini mengingatkanku pada hari-hari di akademi seni. Meskipun profesor dan rekan-rekan sebagian besar adalah orang-orang yang sama sekali tidak memahami seni, pasti akan selalu ada satu atau dua orang yang mengerti dapat melihat keindahan yang saya lihat dari lukisan saya."
  },
  Voice_100358_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Mythag"
  },
  Voice_100359_AwakerVoiceContent = {
    Text = "Pertunjukan liar ini, akan menghasilkan seni apa yang mengerikan?!"
  },
  Voice_100359_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_100360_AwakerVoiceContent = {
    Text = "Palet warna saya!"
  },
  Voice_100360_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_100361_AwakerVoiceContent = {
    Text = "Penderitaan juga merupakan seni……"
  },
  Voice_100361_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_100362_AwakerVoiceContent = {
    Text = "Ah! Aku melihatnya… mata buta yang tersembunyi di bawah jurang, pemandangan akhir dari alam semesta… tunggu sebentar lagi, Penjaga, kita sudah hampir menyelesaikannya!"
  },
  Voice_100362_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_100362_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_100363_AwakerVoiceContent = {
    Text = "Kuas lukis saya, terbuat dari tulang kering saya. Palet warna, warna-warna ini saya kumpulkan dari kuburan di dua puluh kota... dan kanvas kulit yang berharga! Penjaga, tolong ambil ini, dan buatkan saya sebuah potret! Tidak, tidak, tidak, Anda tidak perlu memiliki keterampilan melukis... Saya percaya, ketika resonansi jiwa ini terpampang di kanvas, pasti akan menjadi lukisan yang sangat indah yang belum pernah saya bayangkan...!"
  },
  Voice_100363_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_100363_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_100364_AwakerVoiceContent = {
    Text = "Saya adalah cahaya dan bayangan, saya adalah warna, saya... adalah lukisan itu sendiri!"
  },
  Voice_100364_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_100365_AwakerVoiceContent = {
    Text = "Cobalah warna ini!"
  },
  Voice_100365_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_100366_AwakerVoiceContent = {
    Text = "Esensi seni adalah kegilaan...!"
  },
  Voice_100366_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_100367_AwakerVoiceContent = {
    Text = "Apakah Anda berarti, pada kesempatan berikutnya saya bisa mencoba untuk memperbesar bagian ini dalam lukisan? Hmm… saya tidak pernah memikirkannya! Itu adalah ide yang sangat genius!"
  },
  Voice_100367_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_100368_AwakerVoiceContent = {Text = "Hati-hati!"},
  Voice_100368_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_100369_AwakerVoiceContent = {
    Text = "Esensi seni adalah kegilaan...!"
  },
  Voice_100369_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_100370_AwakerVoiceContent = {
    Text = "Palet warna saya!"
  },
  Voice_100370_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_100371_AwakerVoiceContent = {
    Text = "Oh! Rahang yang halus ini, mata yang cerah, bentuk yang sempurna, dan, dan dunia roh yang luas seperti langit berbintang ini… aku adalah seniman Pikman, bolehkah aku mengundangmu untuk menjadi modelku?"
  },
  Voice_100371_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_100372_AwakerVoiceContent = {
    Text = "Filsafat seni yang saya yakini adalah kegilaan, gelombang ketidakstabilan, musik Hameln sama sekali berbeda, sangat rapi seperti batu nisan di kuburan yang membosankan. Tetapi entah kenapa, saya selalu dapat melihat kekacauan yang paling kuat di kedalaman alam semesta di dalam nada-nada yang teratur itu…"
  },
  Voice_100372_AwakerVoiceTitle = {
    Text = "Bicara Santai: Tentang Hamel"
  },
  Voice_100372_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Hameln\", akan terbuka."
  },
  Voice_100373_AwakerVoiceContent = {
    Text = "Lihat, Penjaga! Gambar yang abadi dan gila di kanvas, betapa menggugah perasaan, betapa putsasa! Dari kegilaan dan penderitaan yang paling akhir, itulah yang disebut seni......"
  },
  Voice_100373_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_100373_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_100374_AwakerVoiceContent = {
    Text = "Ah! Maaf, Penjaga… aku melihat pemandangan yang belum pernah ada sebelumnya padamu… lebih mengerikan dari jurang, lebih memesona dari jurang…"
  },
  Voice_100374_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_100374_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_100375_AwakerVoiceContent = {
    Text = "Tidak mengerti, mengapa manusia tidak ingin menjadi zombie jika ada kesempatan? Keindahan kegilaan yang penuh darah seperti ini, tidak jauh lebih menarik daripada menjadi manusia yang tidak bergairah di rumah besar?!"
  },
  Voice_100375_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_100376_AwakerVoiceContent = {Text = "Ha!"},
  Voice_100376_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_116964_AwakerVoiceContent = {
    Text = "Hukuman untuk kejahatan!"
  },
  Voice_116964_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  },
  Voice_116965_AwakerVoiceContent = {
    Text = "Hukuman untuk kejahatan!"
  },
  Voice_116965_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Dua"
  },
  Voice_117791_AwakerVoiceContent = {
    Text = "Saya mengakui bahwa kemampuan dia mencuri memang hebat, tetapi seorang wanita elegan tidak perlu menggunakan trik yang begitu rendah, barang yang saya inginkan, biarkan semua orang 'memberikannya' kepada saya, bukan?"
  },
  Voice_117791_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Jenkin"
  },
  Voice_117791_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Jenkin\", akan terbuka."
  },
  Voice_117792_AwakerVoiceContent = {
    Text = "Hahaha, permen semuanya milik Mizag sekarang! Tunggu apa lagi, ikuti penyihir ini, segera bersiap-siap untuk menaklukkan toko permen di seluruh Londinium!"
  },
  Voice_117792_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_117792_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_117793_AwakerVoiceContent = {
    Text = "Tak memberi? Maka penyihir ini akan serius!"
  },
  Voice_117793_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_117794_AwakerVoiceContent = {
    Text = "Kamu bertanya bagaimana isian permen ini dimasukkan, sama sekali tidak menemukan celah atau lubang jarum, benar-benar ingin agar orang yang menciptakan permen ini juga bekerja di restoran Mythag, setiap hari menciptakan pencuci mulut baru untuk nyonya ini!"
  },
  Voice_117794_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_117795_AwakerVoiceContent = {
    Text = "Kamu telah membuat penyihir marah!"
  },
  Voice_117795_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_117796_AwakerVoiceContent = {
    Text = "Sebelumnya, selalu merasa bahwa permen dibandingkan dengan kue terlalu sederhana dan tidak cukup elegan, sekarang terlihat, dariku sendiri menyepelekan hal-hal kecil yang ada di dalam kertas plastik berwarna-warni ini. Khususnya dibandingkan dengan kue, masa simpan permen ini jauh lebih lama, bisa disimpan berapa banyak tanpa takut busuk, ingin sekali mengisi seluruh rumah!"
  },
  Voice_117796_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_117797_AwakerVoiceContent = {
    Text = "Kamu menemukan permen baru? Tunjukkan padaku... apa ini, permen cincin ini terlihat sangat lucu, mana ada cincin berlian sebesar telur! Tunggu, apa maksudnya kamu memberiku cincin? Jelas-jelaskan padaku!"
  },
  Voice_117797_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_117797_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_117798_AwakerVoiceContent = {
    Text = "Dengar kabar penyihir biasanya diikuti oleh seekor kucing hitam misterius, memilih kucing liar di kampus benar-benar kurang sopan, jadi aku putuskan, biarkan kau memakai headband telinga kucing, untuk menjadi kucing hitamku!"
  },
  Voice_117798_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_117798_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_117799_AwakerVoiceContent = {
    Text = "Melawan tidak ada gunanya."
  },
  Voice_117799_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_117800_AwakerVoiceContent = {
    Text = "Sedikit, sedikit, sedikit!"
  },
  Voice_117800_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_117801_AwakerVoiceContent = {
    Text = "Apakah benar ada penyihir di dunia ini? Mereka tinggal sendirian di hutan yang tidak ada bayangan manusia, siapa yang memasak, mencuci, dan menyiapkan makanan penutup untuk mereka? Jika tidak ada teh sore, hidup seperti itu ada artinya apa, memikirkannya saja sudah membuatku tak nyaman."
  },
  Voice_117801_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_117801_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_117802_AwakerVoiceContent = {
    Text = "Penyihir datang!"
  },
  Voice_117802_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_117803_AwakerVoiceContent = {
    Text = "Apakah kamu masih memegang cokelat? Bagus, berikan semuanya padaku. Ada apa? Barangmu adalah barangku, apakah itu tidak wajar?"
  },
  Voice_117803_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_117803_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_117804_AwakerVoiceContent = {
    Text = "Kamu bertanya jenis permen apa yang paling aku suka? Biarkan aku berpikir, rasa hazelnut yang enak, cokelat karamel juga sangat enak, permen lunak isi stroberi dan anggur memiliki rasa yang menarik, juga ada satu jenis permen karamel yang bisa ditarik sangat panjang, warnanya terlihat cantik seperti madu... Tidak, tidak bisa memilih, setiap jenis permen memiliki ciri khasnya sendiri, yang penting ada banyak dalam keranjang labu, aku akan mengambil semuanya!"
  },
  Voice_117804_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_117804_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_117805_AwakerVoiceContent = {
    Text = "Tujuan hidup saya sekarang adalah mencicipi semua jenis permen di dunia, setiap kali saya memikirkan ada begitu banyak jenis permen yang menunggu saya, saya merasa semangat untuk bangun setiap hari. Anda bilang kue? Kue adalah tujuan hidup saya yang lain."
  },
  Voice_117805_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_117805_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_117806_AwakerVoiceContent = {
    Text = "Jangan lihat dia yang terlihat seperti anak kecil, sebenarnya usianya sudah cukup tua untuk dikuburkan. Jangan dikatakan permen, bahkan barang-barang yang disukai orang hidup lainnya pun tidak akan menarik baginya. Jadi, lebih baik berikan semua permen yang akan kamu berikan kepadanya padaku, karena aku adalah orang yang paling tidak akan mengkhianati mereka."
  },
  Voice_117806_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Tulu"
  },
  Voice_117806_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Tulu\", akan terbuka."
  },
  Voice_117807_AwakerVoiceContent = {
    Text = "Jika saya jadi penyihir, saya pasti harus menjadi penyihir yang tinggal di istana mewah, yang ramai, dan mencari sepuluh koki terbaik untuk membuatkan saya kue dan permen yang berbeda setiap hari...... Anda bilang itu disebut putri? Kenapa, saya bisa jadi penyihir putri!"
  },
  Voice_117807_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_117807_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_117808_AwakerVoiceContent = {
    Text = "Hei, cepat siapkan beberapa jenis pasta gigi untukku, tidak, aku tidak makan banyak permen, aku tidak memiliki gigi berlubang, hanya sedikit sakit saat tidur malam..."
  },
  Voice_117808_AwakerVoiceTitle = {
    Text = "Obrolan santai - Tentang Permen"
  },
  Voice_117809_AwakerVoiceContent = {
    Text = "Walaupun aturan di restoran Mythag seringkali tidak menyenangkan, tetapi keterampilan mereka dalam membuat pencuci mulut, hmm... masih bisa diterima."
  },
  Voice_117809_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_117810_AwakerVoiceContent = {
    Text = "Di dunia ini memang ada banyak tempat gelap dan menjijikkan, daripada khawatir akan kehancuran dunia, lebih baik makan beberapa permen sebelum itu terjadi."
  },
  Voice_117810_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_117811_AwakerVoiceContent = {
    Text = "Aduh, sakit!"
  },
  Voice_117811_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_117812_AwakerVoiceContent = {
    Text = "Walaupun sekarang tidak ada lagi permadani domba, kalung mutiara hitam dari lautan, piyama sutra timur, tetapi setiap hari bisa bangun di kamar penuh dengan permen, mengulurkan tangan dan menyentuh keranjang labu yang penuh, kehidupan seperti ini mungkin memang gambaran kebahagiaan yang seharusnya... Hei, jangan tersenyum dengan begitu bangga, kau harus terus melayani Nyonya, kamu masih harus berusaha lebih keras!"
  },
  Voice_117812_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_117812_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_117813_AwakerVoiceContent = {
    Text = "Mizag yang jahat berani menghalangiku mengambil permen, kan? Tidak apa-apa, kan? Aku tetap bisa memakannya!"
  },
  Voice_117813_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_117814_AwakerVoiceContent = {
    Text = "Apa? Ingin memakan permen saya? Hmph, itu bukan tidak mungkin saya memberikannya, datanglah, panggil Nona Penyihir!"
  },
  Voice_117814_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_117815_AwakerVoiceContent = {
    Text = "Bagaimana ini bisa disebut perampok? Saya hanya menjalankan hak mulia seorang wanita."
  },
  Voice_117815_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_117816_AwakerVoiceContent = {
    Text = "Witch Permen Keadilan telah datang, semua permen yang hilang harus kembali ke tempatnya!"
  },
  Voice_117816_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_117817_AwakerVoiceContent = {
    Text = "Jahat sekali, orang pelit, sang penyihir akan mengingatmu..."
  },
  Voice_117817_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_117818_AwakerVoiceContent = {
    Text = "Kenapa tikus kecil itu bisa dengan percaya diri merampok permen, tapi aku tidak bisa? Ini adalah diskriminasi terhadap wanita! Tidak hormat!"
  },
  Voice_117818_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_117819_AwakerVoiceContent = {
    Text = "Tak memberi? Maka penyihir ini akan serius!"
  },
  Voice_117819_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_117820_AwakerVoiceContent = {
    Text = "Ayo, aku akan memberimu permen!"
  },
  Voice_117820_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_117821_AwakerVoiceContent = {
    Text = "Dibandingkan dengan pelayan di restoran itu, kamu adalah yang paling pengertian, tahu menyiapkan satu permen khusus untukku, teruslah berusaha ya, pelayanku yang khusus."
  },
  Voice_117821_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_117821_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_117822_AwakerVoiceContent = {
    Text = "Sedikit, sedikit, sedikit!"
  },
  Voice_117822_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_117823_AwakerVoiceContent = {
    Text = "Terlalu berlebihan!"
  },
  Voice_117823_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_117824_AwakerVoiceContent = {
    Text = "Kenapa kamu menghalangiku? Sebagai pelayan setia Miss, bukankah kamu seharusnya membantu Miss mengambil semua permen... mengambilnya?"
  },
  Voice_117824_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_117825_AwakerVoiceContent = {
    Text = "Berhenti, perampokan! Saya sarankan kamu lebih kooperatif, serahkan semua permen selagi kamu bisa, jika tidak, hmm..."
  },
  Voice_117825_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_117826_AwakerVoiceContent = {
    Text = "Lembut, keras, renyah, garing, rasa susu, rasa buah, rasa kacang, rasa cokelat... Ah, bagaimana mungkin ada begitu banyak jenis permen yang belum aku coba di dunia ini? Sudah memutuskan, akan mengusulkan kepada Mythag untuk merayakan festival para suci sekali seminggu!"
  },
  Voice_117826_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_117827_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_117827_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_117828_AwakerVoiceContent = {
    Text = "Penyihir besar pasti akan menang! Dewa permen melindungiku, dan aku melindungi semua permen! Ahahaha!"
  },
  Voice_117828_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_117829_AwakerVoiceContent = {
    Text = "Melawan tidak ada gunanya."
  },
  Voice_117829_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_117830_AwakerVoiceContent = {
    Text = "Semua permen pada akhirnya akan menjadi milikku!"
  },
  Voice_117830_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_117831_AwakerVoiceContent = {
    Text = "Anak itu patuh sampai sedikit menyeramkan, selama kamu meminta permen darinya, dia akan memberikannya, bahkan tidak menyisakan satu untuk dirinya sendiri, membuat orang merasa agak malu... ehm, maksudku, karena dia begitu pengertian, penyihir yang baik hati tentu akan memberinya sedikit sebagai hadiah."
  },
  Voice_117831_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Lily"
  },
  Voice_117831_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Lily\", akan terbuka."
  },
  Voice_117832_AwakerVoiceContent = {
    Text = "Kamu telah membuat penyihir marah!"
  },
  Voice_117832_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_117833_AwakerVoiceContent = {
    Text = "Saya marah!"
  },
  Voice_117833_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_117834_AwakerVoiceContent = {
    Text = "Semua permen pada akhirnya akan menjadi milikku!"
  },
  Voice_117834_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_117835_AwakerVoiceContent = {
    Text = "Apa yang kamu katakan, permen kapas ini bisa dipanggang? Huh, apakah yang hangat dan lengket ini bisa enak? Biarkan aku mencoba? Baiklah, aku akan memaksakan diri untuk mencicipinya, jika kamu berani memperdayaku... Hmm?! Teksturnya yang renyah dan lembut, sangat enak!"
  },
  Voice_117835_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_117835_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_122115_AwakerVoiceContent = {
    Text = "Bohong, kesalahan, semuanya adalah takdir!"
  },
  Voice_122115_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_122117_AwakerVoiceContent = {
    Text = "Bohong, kesalahan, semuanya adalah takdir!"
  },
  Voice_122117_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_123312_AwakerVoiceContent = {
    Text = "Karena sudah menghadapi teror yang sebenarnya, jadi tidak takut pada diriku yang sebenarnya? Hmph, jawaban yang sangat licik, tapi malah membuatku semakin penasaran padamu..."
  },
  Voice_123312_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_123312_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_123313_AwakerVoiceContent = {
    Text = "Dunia di matamu seperti apa? Di mana batas-batas menakutkan itu? Tidak, aku tidak ingin mendengar ceritamu, aku ingin merasakan bersamamu, merasakan kegilaan, kematian, dan ketakutan itu. Aku sudah memutuskan! Sebelum rasa ingin tahuku terpenuhi, aku tidak akan meninggalkanmu."
  },
  Voice_123313_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_123313_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_123314_AwakerVoiceContent = {
    Text = "Orang gila yang tidak terkontrol? Kamu benar. Di sini bukan duniamu, tidak ada hukum dan aturan membosankan itu... Di sini, aku bisa melakukan apa pun yang aku inginkan, jadi Penjaga, kamu harus hati-hati, jangan sampai digigit oleh orang gila yang kehilangan kendali."
  },
  Voice_123314_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_123314_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_123315_AwakerVoiceContent = {
    Text = "Untuk kesehatan fisik dan mentalku, ingin melakukan percakapan mendalam? Baiklah, mari kita mulai cepat, hal yang membosankan ini, semakin cepat dimulai semakin cepat selesai."
  },
  Voice_123315_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_123315_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_123316_AwakerVoiceContent = {
    Text = "Aku hanya berpura-pura menjadi orang biasa untuk menjawab pertanyaanmu? Ah, ternyata kamu sudah mengetahuinya—jadi, apakah kamu sudah siap untuk melihat wujud asliku?"
  },
  Voice_123316_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_123316_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_123770_AwakerVoiceContent = {
    Text = "Pukul kepalamu."
  },
  Voice_123770_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_123771_AwakerVoiceContent = {
    Text = "Semua orang, tua dan muda, menyukainya! Berkilau☆Puting Beliung——!!"
  },
  Voice_123771_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_123772_AwakerVoiceContent = {
    Text = "Yang seharusnya jatuh bukan aku..."
  },
  Voice_123772_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_123773_AwakerVoiceContent = {
    Text = "Dampak Badai!"
  },
  Voice_123773_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_123774_AwakerVoiceContent = {
    Text = "Kau ingin menyelamatkan dunia yang terdistorsi dan mengerikan ini? Sungguh cara mati yang gila dan menarik—biarkan aku melihat seberapa jauh kau bisa melangkah."
  },
  Voice_123774_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_123775_AwakerVoiceContent = {
    Text = "Sayang-sayang, mau mencicipi kapakku? Jangan khawatir, ini akan segera datang..."
  },
  Voice_123775_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_123776_AwakerVoiceContent = {
    Text = "Penjaga, sepertinya aku melihat cahaya, apakah ini berarti... Aku tidak tahu bagaimana kabar rekan-rekan dari tim penyelidikan. Jangan biarkan aku memiliki banyak pekerjaan, aku tidak ingin lembur."
  },
  Voice_123776_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_123776_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_123777_AwakerVoiceContent = {
    Text = "Apakah aku bisa pulang melalui ritual ini? Kamu yakin? Ini sudah berapa kali percobaan... Baiklah, tidak ada salahnya mencoba lagi."
  },
  Voice_123777_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_123777_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_123778_AwakerVoiceContent = {
    Text = "Haha, ternyata dibandingkan dengan kehidupan sehari-hari yang membosankan, kehidupan yang membuat adrenalin meningkat seperti ini lebih cocok untukku!"
  },
  Voice_123778_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_123779_AwakerVoiceContent = {Text = "Ha!"},
  Voice_123779_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_123780_AwakerVoiceContent = {
    Text = "Yang seharusnya jatuh bukan aku..."
  },
  Voice_123780_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_123781_AwakerVoiceContent = {
    Text = "Bercahaya☆Supernova——Radiasi!"
  },
  Voice_123781_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_123782_AwakerVoiceContent = {
    Text = "Semua orang, tua dan muda, menyukainya! Berkilau☆Puting Beliung——!!"
  },
  Voice_123782_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_123783_AwakerVoiceContent = {
    Text = "Perasaan sekarang... seperti masuk ke dalam kabut. Bicara tentang kabut, saya teringat pada makhluk-makhluk kecil di dalam kabut itu. Sayang sekali, ketika suasana hati tidak baik, saya tidak bisa mencarinya untuk meluapkan perasaan."
  },
  Voice_123783_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_123783_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_123784_AwakerVoiceContent = {
    Text = "Benci? Aku tidak akan mengatakan itu, aku hanya benar-benar berharap semua pertemuan yang membosankan, sosialisasi, dan nilai-nilai universal menghilang saja."
  },
  Voice_123784_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_123785_AwakerVoiceContent = {
    Text = "Begitulah... Saya bisa merasakan bahwa saya semakin dekat dengan \"diri saya yang sejati\"."
  },
  Voice_123785_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_123786_AwakerVoiceContent = {
    Text = "Ah, kegagalan yang sudah terduga. Hidup memang seperti ini, naik turun terus-menerus, nanti juga akan terbiasa... Namun, terima kasih atas usaha kamu kali ini."
  },
  Voice_123786_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_123786_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_123787_AwakerVoiceContent = {
    Text = "Seperti bencana kabut, saya juga tidak tahu apa-apa tentang pelarutan. Itulah yang membuatnya begitu menarik, bukan?"
  },
  Voice_123787_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Krisis"
  },
  Voice_123788_AwakerVoiceContent = {
    Text = "Moyasha, tim penyelidikan... oh tidak, sekarang bukan lagi penyerang tim penyelidikan. Jadi, izinkan saya memperkenalkan diri lagi—nama saya Moyasha, hanya seorang gadis cantik~"
  },
  Voice_123788_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_123789_AwakerVoiceContent = {Text = "Enyahlah!"},
  Voice_123789_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_123790_AwakerVoiceContent = {
    Text = "Tempat ini terlalu dekat dengan pemukiman manusia, di mana saja ada orang dewasa yang membosankan... Apakah pernah terpikir untuk memindahkan sekolah ke hutan terpencil yang sepi?"
  },
  Voice_123790_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Mythag"
  },
  Voice_123791_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_123791_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_123792_AwakerVoiceContent = {
    Text = "Aku hampir jatuh cinta dengan perasaan mengembara di dunia lain ini, tubuh yang kuat membangkitkan, pencairan yang menakutkan, dan dewa-dewa yang tidak diketahui! Ah, semuanya adalah kenyamanan yang jauh dari masyarakat biasa!"
  },
  Voice_123792_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_123793_AwakerVoiceContent = {
    Text = "Masih ada? Aku sedang sangat senang bermain—cepat, siapa yang membiarkan aku memotong sekali lagi."
  },
  Voice_123793_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_123794_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_123794_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_123795_AwakerVoiceContent = {
    Text = "Sekali gagal tidak berarti apa-apa... bohong. Kalian semua bersihkan leher kalian dan tunggu aku!"
  },
  Voice_123795_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_123796_AwakerVoiceContent = {
    Text = "Ada tugas? Tidak perlu memberi salam lain kali, kita sudah cukup akrab untuk tidak perlu melakukan \"proses pertemuan sosial\"."
  },
  Voice_123796_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_123797_AwakerVoiceContent = {
    Text = "Mengorbankan diri untuk orang lain adalah pemikiran yang bodoh dan membuat marah. Tidak ada yang bisa meminta orang lain melakukan hal itu, bahkan dewa sekalipun."
  },
  Voice_123797_AwakerVoiceTitle = {
    Text = "Ngobrol: Tentang Salvador"
  },
  Voice_123797_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Salvador\", akan terbuka."
  },
  Voice_123798_AwakerVoiceContent = {
    Text = "Tidak buruk juga——"
  },
  Voice_123798_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_123799_AwakerVoiceContent = {
    Text = "Akhirnya tidak perlu berpura-pura lagi... Selanjutnya, mari kita bersenang-senang."
  },
  Voice_123799_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_123800_AwakerVoiceContent = {
    Text = "Upacara belum berakhir? Saya benar-benar ingin segera pulang untuk makan ikan rebus Rivenrog dan segelas teh hazelnut yang panas, tentu saja, teh Ceylon di sini dan kue Andalusia juga tidak buruk."
  },
  Voice_123800_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_123800_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_123801_AwakerVoiceContent = {
    Text = "Selalu meningkatkan kemampuanku, apakah kamu tidak takut aku akan kehilangan kendali suatu hari nanti... Haha, hanya bercanda."
  },
  Voice_123801_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_123802_AwakerVoiceContent = {
    Text = "Sebenarnya, tinggal sementara di dunia ini juga tidak buruk. Aku akan mengingat segala sesuatu yang terjadi di sini, menuliskannya, dan ketika kembali, akan kubagikan kepada semua orang di sana. Hmm, namanya akan disebut \"Petualangan di Dunia Lain Moyasha\", terdengar bagus, kan?"
  },
  Voice_123802_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_123802_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_123803_AwakerVoiceContent = {
    Text = "Aku mengakui dia sangat imut... hmm, benar, melihat dia mengejar dan bertarung dengan kucing liar yang berkeliaran di kampus memang sangat menggemaskan."
  },
  Voice_123803_AwakerVoiceTitle = {
    Text = "Gosip: Tentang Murphy"
  },
  Voice_123803_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Murphy\", akan terbuka."
  },
  Voice_123804_AwakerVoiceContent = {
    Text = "Meskipun kekuatan ini tidak bisa membawaku kembali ke duniamu, menjadi lebih kuat selalu baik."
  },
  Voice_123804_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_123805_AwakerVoiceContent = {
    Text = "Pelayan, saya juga pernah melakukannya, cari waktu untuk menunjukkan padanya cara saya bertarung menggunakan penyedot debu!"
  },
  Voice_123805_AwakerVoiceTitle = {
    Text = "Ngobrol Santai: Tentang Karen"
  },
  Voice_123805_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Karen\", akan terbuka."
  },
  Voice_123806_AwakerVoiceContent = {
    Text = "Haha, ternyata dibandingkan dengan kehidupan sehari-hari yang membosankan, kehidupan yang membuat adrenalin meningkat seperti ini lebih cocok untukku!"
  },
  Voice_123806_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_124737_AwakerVoiceContent = {
    Text = "Sekali serang, mati."
  },
  Voice_124737_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Dua"
  },
  Voice_124738_AwakerVoiceContent = {
    Text = "Antre dengan baik, satu per satu."
  },
  Voice_124738_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  },
  Voice_124769_AwakerVoiceContent = {Text = "Hilanglah!"},
  Voice_124769_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  },
  Voice_126946_AwakerVoiceContent = {
    Text = "Jangan berpikir, jangan mengganggu, dengarkan secara buta dan ikuti tanpa suara, semua hal di dunia ini hanya beban!"
  },
  Voice_126946_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_126947_AwakerVoiceContent = {
    Text = "Jangan berpikir, jangan mengganggu, dengarkan secara buta dan ikuti tanpa suara, semua hal di dunia ini hanya beban!"
  },
  Voice_126947_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_126948_AwakerVoiceContent = {
    Text = "Anda bertanya mengapa mereka kosong di dalam kepala? Hmm, mungkin memang begitu sejak lahir."
  },
  Voice_126948_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_126949_AwakerVoiceContent = {
    Text = "Hentikan kemarahan dan keluhan, semua hal menjadi kosong."
  },
  Voice_126949_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_126950_AwakerVoiceContent = {
    Text = "Begitu perhatian, akan membuatku tidak bisa menahan diri untuk lebih menggoda Anda."
  },
  Voice_126950_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_126951_AwakerVoiceContent = {Text = "Aduh!"},
  Voice_126951_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_126952_AwakerVoiceContent = {
    Text = "Apakah Anda mengharapkan saya lebih cantik, atau lebih menakutkan?"
  },
  Voice_126952_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_126953_AwakerVoiceContent = {
    Text = "Orang itu, putri yang lahir dari kebahagiaan, mengenakan gaun yang disulam dengan benang emas, kulitnya sehalus gading, dan aroma cendana mengelilinginya, membuat orang terpesona saat tatapan matanya berkilau."
  },
  Voice_126953_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_126953_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_126954_AwakerVoiceContent = {
    Text = "Segera dia merasa muak dengan kesenangan ini, para pengikutnya hanya terus-menerus mengulang skenario yang sama, terjebak dalam cinta yang lahir dari keinginan, atau keinginan yang lahir dari cinta. Karena kehilangan dan pengkhianatan yang menyakitkan, kebodohan mereka membuatnya muak, dan air mata mereka juga membuatnya muak."
  },
  Voice_126954_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_126954_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_126955_AwakerVoiceContent = {
    Text = "Pandangan kalian yang rendah, benar-benar membuatku jengkel."
  },
  Voice_126955_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_126956_AwakerVoiceContent = {
    Text = [[
Nyonya Merah itu pernah mengirimkan undangan salon kepada saya beberapa kali. 
 Rasa kue-kue asingnya cukup enak, tetapi... 
 Seharusnya dia memberi tahu saya lebih awal, bahwa di kediamannya, camilan dan pelayan bukanlah hal yang sama.]]
  },
  Voice_126956_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Sorel"
  },
  Voice_126956_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Sorel\", akan terbuka."
  },
  Voice_126958_AwakerVoiceContent = {
    Text = [[
Bukankah itu bukan cinta? Mengapa merasa takut saat dikelilingi? Bukankah itu bukan kebencian? Mengapa menangis saat tidak bisa kembali? 
 Ah, apakah sekarang kamu takut pada bayanganku? Aroma cendana, apakah sudah berubah menjadi manis dan amis yang tidak bisa kamu pahami?]]
  },
  Voice_126958_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_126958_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_126959_AwakerVoiceContent = {Text = "Ya!"},
  Voice_126959_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_126960_AwakerVoiceContent = {
    Text = "Eh? Anda bertanya mengapa mereka memiliki pola seperti itu di ketiak mereka? Apakah Anda tidak merasa itu sangat lucu?"
  },
  Voice_126960_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Orang banyak"
  },
  Voice_126961_AwakerVoiceContent = {Text = "Aduh!"},
  Voice_126961_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_126963_AwakerVoiceContent = {
    Text = "Dibandingkan dengan persembahan para pengikut, ini lebih sesuai dengan keinginanku."
  },
  Voice_126963_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_126964_AwakerVoiceContent = {
    Text = "Pertama adalah sikap, kemudian bentuk tubuh, sampai mereka juga memiliki sepasang... atau bisa dibilang yang tersisa untuk diingat hanyalah sepasang mata yang indah dan memikat—seperti mata saya."
  },
  Voice_126964_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_126964_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_126965_AwakerVoiceContent = {
    Text = [[
Aku benar-benar sangat bosan hari ini, apakah Anda tidak memiliki keinginan yang perlu diwujudkan?
Sangat disayangkan, hanya untuk beberapa tujuan yang membosankan, banyak orang bersedia mengangkat sabit untuk memberikan darah dan makanan untukku.
Tapi jika itu dari Anda...]]
  },
  Voice_126965_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_126965_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_126966_AwakerVoiceContent = {
    Text = "Mengapa Yōyōshū mengikuti diri hamba ini, dan mengapa mereka dibentuk? Pertanyaan yang menarik. Apakah Anda juga pernah memiliki seseorang yang tak bisa diraih, penyesalan atas ketidakberdayaan?\n\nUmm, sepertinya tidak, sayang sekali.\n\nEkspresi berjuang dalam keputusasaan itu, jika muncul di wajah Anda, pasti akan sangat~ sangat menarik."
  },
  Voice_126966_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_126966_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_126967_AwakerVoiceContent = {
    Text = "……Jika Anda terus melangkahi batas seperti ini, cara hamba menghadapi Anda, mungkin tidak akan seperti sekarang."
  },
  Voice_126967_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_126968_AwakerVoiceContent = {
    Text = "Cerita dia, aku hampir melupakan segalanya, tetapi itu adalah cerita tentang kebahagiaan, cerita tentang kekejaman, cerita yang pada awalnya tentang pengabaian dan pembalasan, kemudian tentang pengorbanan dan mengikuti buta."
  },
  Voice_126968_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_126968_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_126969_AwakerVoiceContent = {
    Text = "Buatlah aku senang, bunuh diri sendiri dalam rasa sakit dan ketakutan~"
  },
  Voice_126969_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_126970_AwakerVoiceContent = {
    Text = "… ini memang membuatku merasa sedikit tertarik."
  },
  Voice_126970_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_126971_AwakerVoiceContent = {
    Text = [[
Setiap orang akan melihat wajah orang yang mereka cintai di bawah kipas saya. Saya meminjamkan kekuatan ini kepada yang lemah, menjadikannya bilah tajam, untuk bersenang-senang. 
 Namun mungkin, saya hanya berkata, mungkin. 
 Jika Anda ingin terpesona karena ini, saya akan merasakan kebahagiaan yang sejati dan tiada tara.]]
  },
  Voice_126971_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_126971_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_126972_AwakerVoiceContent = {
    Text = "Tidak perlu khawatir, Anda berbeda dengan orang-orang bodoh itu. \n Hush, jangan melihat di belakang diriku, jangan pedulikan sentuhan tak terlihat—lihatlah ke mata diriku."
  },
  Voice_126972_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_126972_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_126973_AwakerVoiceContent = {
    Text = "*Sedikit tertawa Apakah kalian berani melihat wujud asliku?"
  },
  Voice_126973_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_126975_AwakerVoiceContent = {Text = "Bising."},
  Voice_126975_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_126976_AwakerVoiceContent = {
    Text = "Bagaimana? Lagi-lagi menatap kipas saya, terpesona? \n Hehe, apapun wajah siapa yang ingin Anda lihat di bawah kipas, saya akan memuaskan Anda... Ayo, dekati sedikit lagi—\n Eh, tidak? Mengatakan kata-kata yang begitu dingin, tetapi ekspresinya sangat menggemaskan..."
  },
  Voice_126976_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_126976_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_126977_AwakerVoiceContent = {
    Text = "Anda datang ke Tidak Mimpi Kampung, ingin mencari apa?"
  },
  Voice_126977_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_126978_AwakerVoiceContent = {
    Text = "Hentikan kemarahan dan keluhan, semua hal menjadi kosong."
  },
  Voice_126978_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_126979_AwakerVoiceContent = {
    Text = "Tidak boleh tidak sopan."
  },
  Voice_126979_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_126980_AwakerVoiceContent = {Text = "Ya!"},
  Voice_126980_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_126981_AwakerVoiceContent = {
    Text = [[
Aku juga pernah memiliki seorang gadis kecil yang cantik dan penurut. 
 Kuncup bunga yang mencolok, tentu saja harus ditambahkan beberapa duri, tidak boleh dimasukkan ke dalam vas bunga.]]
  },
  Voice_126981_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Lily"
  },
  Voice_126981_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Lily\", akan terbuka."
  },
  Voice_126982_AwakerVoiceContent = {
    Text = "Kampus dengan tegas menolak permohonan saya untuk bekerja di ruang konsultasi psikologis, sungguh aneh, apa sebenarnya yang salah?"
  },
  Voice_126982_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Mythag"
  },
  Voice_126983_AwakerVoiceContent = {
    Text = [[
Segala sesuatu pada akhirnya akan kembali ke kekosongan, mengapa tidak mencari sedikit kesenangan bersama hamba?
Jangan khawatir, jika suatu hari Anda tidak dapat bertahan, hamba tidak akan membiarkan Dia mengambil Anda terlebih dahulu.]]
  },
  Voice_126983_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Krisis"
  },
  Voice_126984_AwakerVoiceContent = {
    Text = "Membosankan."
  },
  Voice_126984_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_126985_AwakerVoiceContent = {
    Text = [[
Anda benar-benar orang yang luar biasa, di dunia yang pasti akan punah, malah sibuk dengan begitu banyak hal yang tidak penting. 
 Membuatku juga tidak bisa menahan rasa ingin tahuku.]]
  },
  Voice_126985_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_126985_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_126986_AwakerVoiceContent = {
    Text = "Jangan mendekat!"
  },
  Voice_126986_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_126988_AwakerVoiceContent = {
    Text = "Hamba adalah Tuan Tidak Mimpi, Xu. Jika di dalam hati Anda, ada seseorang yang ingin Anda temui namun tidak bisa, hamba bersedia membuka kipas, agar Anda dapat melihatnya."
  },
  Voice_126988_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_127088_AwakerVoiceContent = {
    Text = [[
Semua anak dari makhluk hidup itu sangat merepotkan. 
 Kecil, lembut, berisik, tanpa sengaja mengendalikan segala sesuatu di sekitarnya. Aku suka keramaian, tetapi sebenarnya tidak suka keramaian seperti ini, tolong biarkan mereka menjauh sedikit.]]
  },
  Voice_127088_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_127089_AwakerVoiceContent = {
    Text = [[
Bunga melati kecilku, sayangku yang patuh, aku manis seperti madu terbenam dalam permainan rumah-rumahan~
Ah, beberapa omongan gila yang menyenangkan, kamu tidak perlu khawatir.]]
  },
  Voice_127089_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_127090_AwakerVoiceContent = {
    Text = [[
Dalam legenda Kerajaan Naga Batu, burung merak adalah makhluk buas yang cantik dan mencolok. 
 Cantik dan jahat, terdengar membuat orang berdebar, jika jelek tetapi baik, maka akan terasa membosankan.]]
  },
  Voice_127090_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_129651_AwakerVoiceContent = {
    Text = "Makan, makan, semuanya makan"
  },
  Voice_129651_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_129652_AwakerVoiceContent = {
    Text = "Guruh guruh~"
  },
  Voice_129652_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_129653_AwakerVoiceContent = {
    Text = "Bola arang kecil, saya, makan, bersama? Bersama!"
  },
  Voice_129653_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_129653_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_129654_AwakerVoiceContent = {
    Text = "Mosk! Sangat kuat!"
  },
  Voice_129654_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_129655_AwakerVoiceContent = {
    Text = "Jurang! Spiral! Kehancuran! Semua—— menjadi Vortex!"
  },
  Voice_129655_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_129656_AwakerVoiceContent = {Text = "Sakit!"},
  Voice_129656_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_129657_AwakerVoiceContent = {
    Text = "Jangan sentuh aku, tidak! Sentuh aku, rusak!"
  },
  Voice_129657_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_129657_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_129658_AwakerVoiceContent = {
    Text = "Kerang, berkilauan! Berkilauan, bagus, untukmu!"
  },
  Voice_129658_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_129658_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_129659_AwakerVoiceContent = {
    Text = "Dingin, menakutkan, Mosk, bersembunyi!"
  },
  Voice_129659_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Doll"
  },
  Voice_129659_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Boneka\", akan terbuka."
  },
  Voice_129660_AwakerVoiceContent = {Text = "Yahuu!"},
  Voice_129660_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_129661_AwakerVoiceContent = {
    Text = "Berburu, sial! Rusak! Mosk, pukul mereka, rusak!"
  },
  Voice_129661_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_129662_AwakerVoiceContent = {
    Text = "Sangat menyenangkan! Sampai jumpa lagi! Aku ingin lagi!"
  },
  Voice_129662_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_129662_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_129663_AwakerVoiceContent = {
    Text = "Sentuh, baik! Mosk, kamu, sentuh!"
  },
  Voice_129663_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_129664_AwakerVoiceContent = {
    Text = "Tidak, jangan! Bola arang kecil, Mosk, lindungi!"
  },
  Voice_129664_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Krisis"
  },
  Voice_129665_AwakerVoiceContent = {
    Text = "Coba lagi? Coba lagi!"
  },
  Voice_129665_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_129666_AwakerVoiceContent = {
    Text = "Hehe, Mosk, ayo bermain!"
  },
  Voice_129666_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_129667_AwakerVoiceContent = {
    Text = "Gelombang besar datang!"
  },
  Voice_129667_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_129668_AwakerVoiceContent = {Text = "Buang!"},
  Voice_129668_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_129669_AwakerVoiceContent = {Text = "Sakit!"},
  Voice_129669_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_129670_AwakerVoiceContent = {Text = "Ih!"},
  Voice_129670_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_129671_AwakerVoiceContent = {
    Text = "Upacara?! Bawa aku bersamamu!"
  },
  Voice_129671_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_129671_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_129672_AwakerVoiceContent = {
    Text = "Pusaran! Kekuatan! Tongkat!"
  },
  Voice_129672_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_129672_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_129673_AwakerVoiceContent = {Text = "Dentang!"},
  Voice_129673_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  },
  Voice_129674_AwakerVoiceContent = {Text = "Yay!"},
  Voice_129674_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_129675_AwakerVoiceContent = {Text = "Hulahula~"},
  Voice_129675_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_129676_AwakerVoiceContent = {Text = "Bertarung!"},
  Voice_129676_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Goliath"
  },
  Voice_129676_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Goliath\", akan terbuka."
  },
  Voice_129677_AwakerVoiceContent = {
    Text = "Menemukan banyak, berkilau!"
  },
  Voice_129677_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_129677_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_129678_AwakerVoiceContent = {
    Text = "Jurang! Spiral! Kehancuran! Semua—— menjadi Vortex!"
  },
  Voice_129678_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_129679_AwakerVoiceContent = {Text = "Wahou!"},
  Voice_129679_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_129680_AwakerVoiceContent = {Text = "Ih!"},
  Voice_129680_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_129681_AwakerVoiceContent = {
    Text = "Mosk! Sangat kuat!"
  },
  Voice_129681_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_129682_AwakerVoiceContent = {
    Text = "Makan, makan, semuanya makan"
  },
  Voice_129682_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_129683_AwakerVoiceContent = {
    Text = "Nautilus, Nautila, Bola arang kecil! Bercahaya!"
  },
  Voice_129683_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_129684_AwakerVoiceContent = {
    Text = "Mosk, isi peluru!"
  },
  Voice_129684_AwakerVoiceTitle = {
    Text = "Keterampilan·II·Mengisi Satu"
  },
  Voice_129685_AwakerVoiceContent = {
    Text = "Mosk, lari!"
  },
  Voice_129685_AwakerVoiceTitle = {
    Text = "Keterampilan·II·Pengisian·Dua"
  },
  Voice_129686_AwakerVoiceContent = {
    Text = "Peluk! Mosk! Suka!"
  },
  Voice_129686_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_129686_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_129687_AwakerVoiceContent = {
    Text = "Bola arang kecil, teman! Mosk, selamanya!"
  },
  Voice_129687_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_129688_AwakerVoiceContent = {
    Text = "Cepat, cepat!"
  },
  Voice_129688_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_129688_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_129689_AwakerVoiceContent = {
    Text = "Mosk! Bola arang kecil! Bersama, selamanya? Selamanya!"
  },
  Voice_129689_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_129689_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_129690_AwakerVoiceContent = {
    Text = "Huaa huaa~ Gelombang besar bangkit!"
  },
  Voice_129690_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_129690_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_129691_AwakerVoiceContent = {
    Text = "Teman! Banyak! Suka!"
  },
  Voice_129691_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Mythag"
  },
  Voice_129692_AwakerVoiceContent = {
    Text = "Mosk! Hebat!"
  },
  Voice_129692_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_129693_AwakerVoiceContent = {
    Text = "Nautila, ingin bertemu. Eh, Nautila, Mosk, Mosk!"
  },
  Voice_129693_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Nautila"
  },
  Voice_129693_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Nautila\", akan terbuka."
  },
  Voice_129694_AwakerVoiceContent = {
    Text = "Menjadi lebih kuat!"
  },
  Voice_129694_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_129695_AwakerVoiceContent = {
    Text = "Aku! Mosk! Halo!"
  },
  Voice_129695_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_130511_AwakerVoiceContent = {Text = "Hu——"},
  Voice_130511_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua·Pengisian Tiga"
  },
  Voice_133720_AwakerVoiceContent = {
    Text = "Kesalahan akan diperbaiki."
  },
  Voice_133720_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_133721_AwakerVoiceContent = {
    Text = "Tragedi yang Anda saksikan, hanyalah sekilas dari ribuan kemungkinan. Menyibak tirai takdir, aku melihat panggung yang gelap gulita itu. Lampu padam, orang bubar, segala fenomena kembali ke jurang kekacauan. Namun…… semua ini bukanlah akhir. Kehendakku masih ada, cukup untuk menopang kerja keras yang sia-sia ini, menunggu berkas cahaya berikutnya menyala."
  },
  Voice_133721_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Krisis"
  },
  Voice_133722_AwakerVoiceContent = {
    Text = "Takdir semua orang dituntun oleh benang…… tapi takdir Anda, adalah naskah yang tak bisa kubaca. Aku menantikan, pertunjukan improvisasi sehebat apa yang akan Anda bawakan untuk dunia ini?"
  },
  Voice_133722_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_133723_AwakerVoiceContent = {
    Text = "Wahai boneka pemeran utama, naiklah ke panggung milikmu."
  },
  Voice_133723_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_133724_AwakerVoiceContent = {Text = "Hm?"},
  Voice_133724_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_133725_AwakerVoiceContent = {
    Text = "Segala yang telah berlalu, hanyalah prolog. Babak baru kita, menanti untuk Anda tulis, Penjaga Rahasia."
  },
  Voice_133725_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_133725_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_133726_AwakerVoiceContent = {
    Text = "Jika Anda menyukai komedi, \"A Midsummer Night's Dream\" adalah pilihan yang bagus. Aku terutama menyukai igauan licik Puck — di balik tawa cekikikan para peri, selalu tersembunyi bisikan rahasia yang tak sengaja dibocorkan oleh takdir."
  },
  Voice_133726_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_133726_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_133727_AwakerVoiceContent = {
    Text = "Tunduk pada ini."
  },
  Voice_133727_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_133728_AwakerVoiceContent = {
    Text = "Roda pintal, berputar di sini."
  },
  Voice_133728_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_133729_AwakerVoiceContent = {
    Text = "Wahai tahanan malang dari takdir, terimalah vonis yang telah ditakdirkan untukmu."
  },
  Voice_133729_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_133730_AwakerVoiceContent = {
    Text = "Bahkan pengamat yang memahami segalanya, tak lebih dari aktor canggung dalam naskahnya sendiri. Menguasai jaring takdir, namun akhirnya terikat oleh benang pintal — dalam keadaan yang telah ditakdirkan ini, kami berjalan di jalan yang berbeda, tapi tak pernah menyerah pada pencarian yang sia-sia itu. Entah bodoh atau gila, aku begini, dan dia pun demikian."
  },
  Voice_133730_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Tavi"
  },
  Voice_133730_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Tawil\", akan terbuka."
  },
  Voice_133731_AwakerVoiceContent = {
    Text = "Sebuah twist yang tak terduga?"
  },
  Voice_133731_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_133732_AwakerVoiceContent = {
    Text = "Terima kasih telah menemani sepanjang tirai naik dan turun. Di masa depan, aku pasti tidak akan mengecewakan harapan Anda, dan akan mempersembahkan malam drama yang lebih menggugah jiwa."
  },
  Voice_133732_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_133732_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_133733_AwakerVoiceContent = {
    Text = "Penyanyi yang begitu berbakat, suara anugerah Tuhan, jernih namun membara, seolah bersumber dari suara takdir…… Jika bisa diundang ke teaterku, pastilah bahkan penonton yang paling pemilih pun akan merasa terkejut."
  },
  Voice_133733_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Tinkter"
  },
  Voice_133733_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Tinct\", akan terbuka."
  },
  Voice_133734_AwakerVoiceContent = {
    Text = "Kau dan aku, dua helai benang takdir yang tak bisa terlihat jelas, telah lama saling terjalin erat, tak terpisahkan, merajut sangkar dan jalan. Aku tak bisa melihat batas sangkar itu, juga tak bisa melihat ujung jalan itu. Inilah bagian paling memesona dari kisah ini."
  },
  Voice_133734_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_133734_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_133735_AwakerVoiceContent = {
    Text = "Benang takdir, telah terjulur turun."
  },
  Voice_133735_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_133736_AwakerVoiceContent = {
    Text = "Dia sering datang duduk di teaterku…… tapi aku tahu, dia bukan datang untuk drama, melainkan meminjam panggung ini untuk mencerminkan gayanya sendiri. Namun, akting yang begitu memukau, jika hanya menjadi penonton, sungguh sayang. Seharusnya ia bersinar di bawah sorotan lampu, bukan bersembunyi di balik bayangan kursi penonton."
  },
  Voice_133736_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Sorel"
  },
  Voice_133736_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Sorel\", akan terbuka."
  },
  Voice_133737_AwakerVoiceContent = {
    Text = "Aku pernah mendengar permainannya, melodi yang indah itu, membuat jiwa bergetar…… Mungkin, sebaiknya mengundangnya untuk menggubah sebuah simfoni takdir untuk drama baruku?"
  },
  Voice_133737_AwakerVoiceTitle = {
    Text = "Bicara Santai: Tentang Hamel"
  },
  Voice_133737_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Hameln\", akan terbuka."
  },
  Voice_133738_AwakerVoiceContent = {
    Text = "Satu lagi kisah yang sempurna, tirainya telah turun."
  },
  Voice_133738_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_133739_AwakerVoiceContent = {
    Text = "Jaring takdir yang tak berujung, aku telah melihat keseluruhannya."
  },
  Voice_133739_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_133740_AwakerVoiceContent = {
    Text = "Jika Anda mengizinkan…… aku ingin merajut sebuah drama dua orang yang hanya milik Anda dan aku. Tanpa penonton, tanpa latihan…… aku hanya menantikan, saat Anda berdiri di bawah cahaya, benang yang tak bisa kulihat itu, akan menunjukkan lompatan yang menakjubkan seperti apa."
  },
  Voice_133740_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_133740_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_133741_AwakerVoiceContent = {
    Text = "Penari yang malang, aku menyaksikan langkah tarinya. Itu adalah keindahan yang mendekati kehancuran — setiap putaran menyalakan kembang api hijau, berusaha membakar benang takdir, namun sayang pada akhirnya akan dirobek oleh benang-benang itu menjadi pemandangan yang paling tragis nan memesona. Jika ada kesempatan, aku ingin menulis sebuah drama tari yang hanya miliknya."
  },
  Voice_133741_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Liz"
  },
  Voice_133741_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Liz\", akan terbuka."
  },
  Voice_133742_AwakerVoiceContent = {
    Text = "Di sini ditenun, di sini ditimbang, di sini diputuskan."
  },
  Voice_133742_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_133743_AwakerVoiceContent = {
    Text = "Redamlah……"
  },
  Voice_133743_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_133744_AwakerVoiceContent = {
    Text = "Satu helai benang lagi, menjadi jelas."
  },
  Voice_133744_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_133745_AwakerVoiceContent = {
    Text = "Tirai telah terbuka untukmu, naskah takdir menanti untuk dibuka. Katakan padaku, lintasan takdir mana yang lebih Anda pilih? Akhir yang tragis, ataukah prolog yang penuh kebahagiaan?"
  },
  Voice_133745_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_133745_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_133746_AwakerVoiceContent = {
    Text = "Memang aku tenggelam dalam pemintalan hari demi hari ini…… Dalam tarikan yang berulang dan sunyi, meramalkan awal dan akhir ribuan kisah, menyaksikan turunnya tirai semua takdir, seolah telah melampaui takdir itu sendiri. Namun, jaring takdir tak bisa dihindari, sekadar menjadi penonton pada akhirnya tetap sepi. Maka, aku melangkah ke teater, dalam peran yang kumainkan, merasakan sendiri suka dan duka yang kupintal dengan tanganku sendiri namun belum pernah kualami."
  },
  Voice_133746_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_133747_AwakerVoiceContent = {Text = "Ngh..."},
  Voice_133747_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_133748_AwakerVoiceContent = {Text = "Heh……"},
  Voice_133748_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_133749_AwakerVoiceContent = {
    Text = "Di sini ditenun, di sini ditimbang, di sini diputuskan."
  },
  Voice_133749_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_133750_AwakerVoiceContent = {
    Text = "Bisikan takdir, semakin dekat."
  },
  Voice_133750_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_133751_AwakerVoiceContent = {
    Text = "Teater baru saja menampilkan komedi romantis baru. Aku telah menyisakan satu kursi kosong di bangku takdir untukmu. Aku akan menanti di setiap malam panjang saat takdir saling terjalin, menunggu cahaya bintang pertemuan denganmu."
  },
  Voice_133751_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_133751_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_133752_AwakerVoiceContent = {
    Text = "Begitu gigih memetik benang pintal takdir…… Anda, juga ingin mengintip babak yang menjadi milik Anda sendiri?"
  },
  Voice_133752_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_133753_AwakerVoiceContent = {
    Text = "Masa depan telah tiba."
  },
  Voice_133753_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_133754_AwakerVoiceContent = {
    Text = "Jika Anda bersedia melangkah ke istana tragedi, izinkan saya mempersembahkan \"Antigone\" untuk Anda. Di antara pertentangan hukum ilahi dan duniawi, setiap langkahnya menginjak benang yang dipintal takdir, hingga ia melangkah ke dalam bayangan kelam makam batu. Justru karena belenggu ini tak bisa dilepaskan, kehendak yang meledak dari tubuh mungilnya itu bersinar bagai nyala api sendirian di kegelapan malam yang panjang."
  },
  Voice_133754_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_133754_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_133755_AwakerVoiceContent = {
    Text = "Dari akhir yang tak menentu, tak bisa lolos dari jaring sebab-akibat……"
  },
  Voice_133755_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_133756_AwakerVoiceContent = {
    Text = "Di atas benang pintal, aku melihat warna-warni pelangi yang berputar tanpa henti — ia menghubungkan jaring tak berujung, membentangkan dunia tak terbatas, memperluas kemungkinan tanpa batas, dan akhirnya merajut pola paling megah dan semarak di dunia. Baik dewa maupun manusia fana, pahlawan maupun penjahat, semua dikendalikan oleh seutas benang pintal yang halus, berlari tanpa ragu menuju akhir milik mereka sendiri di bawah tatapan takdir."
  },
  Voice_133756_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Mythag"
  },
  Voice_133757_AwakerVoiceContent = {
    Text = "Kukira tak ada lagi pilihan di dunia ini yang bisa membuatku terkejut…… Selera Anda terhadap drama sungguh mengesankan."
  },
  Voice_133757_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_133757_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_133758_AwakerVoiceContent = {
    Text = "Benang takdir selalu terhubung di kegelapan…… Anda telah menyentuh benang ini, dan juga mengusik diriku."
  },
  Voice_133758_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_133758_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_133759_AwakerVoiceContent = {
    Text = "Aku selalu tak ingin melihat drama template yang itu-itu saja. Makna memasuki teater, sejak awal adalah untuk mengalami langsung pertunjukan langsung yang tak bisa direplikasi. Jika setiap pertunjukan hanyalah pengulangan mekanis, maka panggung menjadi sangkar yang indah, dan menonton drama pun menjadi ziarah yang melelahkan terhadap akhir yang sudah diketahui. Pertunjukan seperti itu, semegah apa pun, telah kehilangan jiwanya. Bagaimana pandangan Anda?"
  },
  Voice_133759_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_133760_AwakerVoiceContent = {
    Text = "Benang-benang takdir semula mengalir teratur di telapak tanganku…… hingga kemunculan Anda, membuat lintasan mereka beriak tak terduga."
  },
  Voice_133760_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_133760_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_133761_AwakerVoiceContent = {
    Text = "Wahai tahanan malang dari takdir, terimalah vonis yang telah ditakdirkan untukmu."
  },
  Voice_133761_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_133762_AwakerVoiceContent = {
    Text = "Aku memintal satu-satunya lintasan di antara helai benang yang tak berujung."
  },
  Voice_133762_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_133763_AwakerVoiceContent = {
    Text = "Di atas panggung takdir, segala makhluk menanti giliran tampil dalam sebab-akibat masing-masing, segala suka dan duka terbentuk diam-diam di antara putaran roda gigi…… Tirai telah terangkat, Penjaga Rahasia, kisah antara kau dan aku, mulai dari sini."
  },
  Voice_133763_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_133764_AwakerVoiceContent = {
    Text = "Pertikaian telah tiba. Yang akan Anda perankan, pahlawan yang merobek jaring, atau figuran yang tunduk pada takdir?"
  },
  Voice_133764_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_133765_AwakerVoiceContent = {
    Text = "Perlawanan yang sia-sia."
  },
  Voice_133765_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_139865_AwakerVoiceContent = {
    Text = "Terima kasih. Aku akan menjaga hadiah ini baik-baik."
  },
  Voice_139865_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_139866_AwakerVoiceContent = {
    Text = "Aku sudah banyak belajar tentang struktur Awakener, sudah bisa dibilang ahli lho. Tapi hal yang disebut \"Spiritualitas\" di dalam Silver Core, masih agak sulit dipahami ya……"
  },
  Voice_139866_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_139866_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_139867_AwakerVoiceContent = {
    Text = "Inilah, awal dari dunia baru……"
  },
  Voice_139867_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_139868_AwakerVoiceContent = {
    Text = "Aku bisa melakukan hal seperti itu lho. Merestrukturisasi tubuh makhluk hidup lain, menyesuaikannya……"
  },
  Voice_139868_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_139868_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_139869_AwakerVoiceContent = {
    Text = "Bagaimana cara menyesuaikan bagian mana, itu berbeda-beda tergantung jenis makhluk hidupnya, jadi kalau tidak belajar dengan baik tidak boleh lho."
  },
  Voice_139869_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_139869_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_139870_AwakerVoiceContent = {
    Text = "Tidak menakutkan ya, penampilanku? Eh, agak membosankan ya……"
  },
  Voice_139870_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_139871_AwakerVoiceContent = {
    Text = "Tidak akan kubiarkan siapa pun menghalangi kita."
  },
  Voice_139871_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_139872_AwakerVoiceContent = {
    Text = "Aku sudah siap, lho."
  },
  Voice_139872_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_139873_AwakerVoiceContent = {
    Text = "Makhluk hidup benar-benar penuh keberagaman ya. Ingin tahu lebih banyak!"
  },
  Voice_139873_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_139875_AwakerVoiceContent = {
    Text = "Mau bermain bersama Saya?"
  },
  Voice_139875_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_139876_AwakerVoiceContent = {Text = "Ah!"},
  Voice_139876_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_139877_AwakerVoiceContent = {
    Text = "Inilah, awal dari dunia baru……"
  },
  Voice_139877_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_139878_AwakerVoiceContent = {
    Text = "Sudah kenyang, terima kasih atas hidangannya!"
  },
  Voice_139878_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_139880_AwakerVoiceContent = {
    Text = "Penjaga Rahasia, pernahkah kamu mencintai seseorang, merindukan seseorang?"
  },
  Voice_139880_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_139880_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_139881_AwakerVoiceContent = {Text = "Eep!"},
  Voice_139881_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_139882_AwakerVoiceContent = {
    Text = "Apakah ini tempatnya?"
  },
  Voice_139882_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_139883_AwakerVoiceContent = {
    Text = "Kerja keras! Apakah ada hasil yang bagus?"
  },
  Voice_139883_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_139884_AwakerVoiceContent = {
    Text = "Setelah melakukan berbagai verifikasi, secara garis besar sudah kupahami lho. \"Spiritualitas\" yang dimiliki setiap Awakener itu benar-benar berbeda. Dan, spiritualitas di dalam Silver Core-ku tampaknya adalah \"Cinta\"."
  },
  Voice_139884_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_139884_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_139885_AwakerVoiceContent = {
    Text = "Bagaimana, kaget kan?"
  },
  Voice_139885_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_139886_AwakerVoiceContent = {
    Text = "Ini adalah hadiah terakhir untukmu."
  },
  Voice_139886_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_139887_AwakerVoiceContent = {
    Text = [[
"Di salah satu bintang-bintang itu, bungaku sedang mekar..." Begitulah katanya.
Kamu juga pernah mengatakan hal serupa, kan.]]
  },
  Voice_139887_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_139887_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_139888_AwakerVoiceContent = {
    Text = "Benda yang disebut \"Silver Core\" ini, tampaknya terhubung dengan kehendak yang sangat jauh. Sungguh misterius ya……"
  },
  Voice_139888_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_139888_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_139889_AwakerVoiceContent = {
    Text = "Ini adalah hadiah terakhir untukmu."
  },
  Voice_139889_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_139891_AwakerVoiceContent = {Text = "Ya!"},
  Voice_139891_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_139892_AwakerVoiceContent = {
    Text = "Pangeran Kecil bilang, perawatannya terhadap mawar itulah yang membuat mawar itu berbeda dari yang lain…… Menurutmu juga begitu?"
  },
  Voice_139892_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_139892_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_139893_AwakerVoiceContent = {
    Text = "Kemarin, aku melihat sebuah buku berjudul \"Le Petit Prince\" di rak buku Lily. Aku meminjamnya. Mau membacanya bersamaku?"
  },
  Voice_139893_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_139893_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_139895_AwakerVoiceContent = {
    Text = "Hmm, aku juga sudah meneliti struktur Silver Core, dan mulai memahami gambaran umum tentang Awakener lho."
  },
  Voice_139895_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_139895_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_139896_AwakerVoiceContent = {Text = "Ya!"},
  Voice_139896_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_139897_AwakerVoiceContent = {Text = "Hey!"},
  Voice_139897_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_139899_AwakerVoiceContent = {
    Text = "Mohon bimbingannya!"
  },
  Voice_139899_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_139900_AwakerVoiceContent = {
    Text = "Halo! ……Apa begini sudah benar?\nAku Saya. Mm……salam kenal—"
  },
  Voice_139900_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_139901_AwakerVoiceContent = {
    Text = "Ada bunga yang disebut dandelion, yang membiarkan bijinya terbang terbawa angin. Biji-biji berbulu halus itu dibawa angin, pergi jauh sekali dari kampung halamannya, mungkin jatuh di gurun pasir tanpa satu pun tumbuhan. Saat seperti itu, apa yang dipikirkan biji kecil itu ya……"
  },
  Voice_139901_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_139901_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_139902_AwakerVoiceContent = {
    Text = "Sebanyak apapun dilakukan tetap menyenangkan!"
  },
  Voice_139902_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_139903_AwakerVoiceContent = {Text = "Hei——"},
  Voice_139903_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_139906_AwakerVoiceContent = {
    Text = "Bahaya——"
  },
  Voice_139906_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_140533_AwakerVoiceContent = {
    Text = "Sangat suka makanan enak! Juga suka orang yang lembut pada Saya. Kalau diperlakukan dengan lembut, benar-benar senang sekali——"
  },
  Voice_140533_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_140534_AwakerVoiceContent = {
    Text = "Itu orang yang membangunkanku ya? Rasanya sangat menyilaukan…… Hmm~ kalau begitu, kamu sudah membantunya menemukan kakaknya?"
  },
  Voice_140534_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Tinkter"
  },
  Voice_140534_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Tinct\", akan terbuka."
  },
  Voice_140535_AwakerVoiceContent = {
    Text = "Setiap kali Saya ingin memonopoli Penjaga Rahasia, selalu ada banyak orang aneh yang mengerumuni. Lebih suka saat berada di dalam Alam Rahasia——"
  },
  Voice_140535_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Mythag"
  },
  Voice_140536_AwakerVoiceContent = {
    Text = "Oh begitu. Mengerti!"
  },
  Voice_140536_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_140537_AwakerVoiceContent = {
    Text = "Penjaga Rahasia, tautan, tubuh kebangkitan, kamu yang memberitahuku tentang hubungan itu kan. Bisa merasakan jiwa dua orang terhubung bersama…… melalui benang perak? Atau semacamnya, hmm— rasanya semuanya sulit dipahami ya……"
  },
  Voice_140537_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_140538_AwakerVoiceContent = {
    Text = "Menggunakan daging dan darah untuk mengangkut biji? Hmm~ ternyata begitu. Agak tertarik dengan dombanya."
  },
  Voice_140538_AwakerVoiceTitle = {
    Text = "Ngobrol: Tentang Thais"
  },
  Voice_140538_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Thais\", akan terbuka."
  },
  Voice_140539_AwakerVoiceContent = {
    Text = "Ancaman tertentu terhadap dunia ini, kegelapan yang bisa menyebabkan kepunahan eksistensi, kan? Aku tahu kok. Aku sudah banyak mendengarnya dari Profesor Dole."
  },
  Voice_140539_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Krisis"
  },
  Voice_140540_AwakerVoiceContent = {
    Text = "Tidak suka orang yang kasar. Membuat perasaan tidak nyaman……"
  },
  Voice_140540_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_140541_AwakerVoiceContent = {
    Text = "Rasnya, sepertinya juga mengandalkan perampasan kelompok lain untuk mendapatkan kesempatan berkembang biak di planet baru. Hmm~ ternyata begitu……"
  },
  Voice_140541_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Winkor"
  },
  Voice_140541_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Kerang\", akan terbuka."
  },
  Voice_141963_AwakerVoiceContent = {Text = "Anak baik."},
  Voice_141963_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Dua"
  },
  Voice_141964_AwakerVoiceContent = {Text = "Eh!"},
  Voice_141964_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Tiga"
  },
  Voice_141965_AwakerVoiceContent = {Text = "Ya!"},
  Voice_141965_AwakerVoiceTitle = {
    Text = "Terkena·Lima"
  },
  Voice_143501_AwakerVoiceContent = {
    Text = "Sungguh disayangkan, ketika kamu berubah pikiran, kamu tahu di mana harus menemukanku."
  },
  Voice_143501_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_143501_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_143502_AwakerVoiceContent = {Text = "Sialan..."},
  Voice_143502_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_143503_AwakerVoiceContent = {
    Text = "Kulit, otot, saraf, tulang, semuanya akan direkonstruksi, kembali sehat dan utuh, kembali bersemangat."
  },
  Voice_143503_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_143503_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_143504_AwakerVoiceContent = {
    Text = "Di hadapan laut, tidak ada musuh yang tidak bisa dihancurkan!"
  },
  Voice_143504_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_143505_AwakerVoiceContent = {
    Text = [[
Pesta, Buruan, perlindungan?
Berdoalah kepadaku, air laut tertua akan memberitahumu namaku.
Aku adalah penguasa jurang, Pontos.]]
  },
  Voice_143505_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_143506_AwakerVoiceContent = {
    Text = "Hehe, merindukan waktu di Epoyanis…\nIa ada di dalam tubuh ini, selalu menyambutmu kembali kapan saja."
  },
  Voice_143506_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_143507_AwakerVoiceContent = {
    Text = "Meskipun aku tidak melakukannya, jika suatu hari kamu mendengar suara air laut dan kepakan sayap di telingamu, jangan khawatir, itu hal yang wajar."
  },
  Voice_143507_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_143508_AwakerVoiceContent = {
    Text = "Serahkan inderamu, dan merenunglah selamanya di dalam jurang!"
  },
  Voice_143508_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_143509_AwakerVoiceContent = {
    Text = [[
Aku menyukai anak muda yang penuh semangat, sayang sekali, pengendalian Mythag terhadap pesta pora terlalu ketat, bahkan tidak ada satu pun arena berburu yang layak.
Dan lagi, Di Dalam sana masih ada benda kotor yang berani berkeliaran terang-terangan, bahkan menyandang gelar profesor.]]
  },
  Voice_143509_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Mythag"
  },
  Voice_143510_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_143510_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_143511_AwakerVoiceContent = {
    Text = "Aku sudah melakukan begitu banyak hal, kamu bahkan tidak mau memanggilku paman sekali lagi, sungguh menyebalkan."
  },
  Voice_143511_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_143513_AwakerVoiceContent = {
    Text = "Tidak perlu terburu-buru, kegelapan di kedalaman laut terdalam pasti akan Devour kalian."
  },
  Voice_143513_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_143514_AwakerVoiceContent = {
    Text = "Berlutut, jadilah pupuk bagi Epoyanis."
  },
  Voice_143514_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Tiga"
  },
  Voice_143515_AwakerVoiceContent = {
    Text = "Adapun keberadaan yang memilihku… hanya bisa dikatakan baik hati sekaligus jahat.\nJatuh di mana pun sesuai suasana hati, pasti akan menyelamatkanmu dari bahaya, namun apakah tempat itu adalah bahaya lain, itu bukan sesuatu yang perlu dipikirkan dalam \"perjalanan\" kali ini.\nSungguh menarik, sungguh tak terduga, aku sedang mempertimbangkan untuk meneruskan tradisi ini."
  },
  Voice_143515_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_143515_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_143516_AwakerVoiceContent = {
    Text = "Aku memiliki hubungan istimewa dengan Epoyanis, lebih tepatnya, aku adalah Epoyanis, Epoyanis terhubung denganku, ada melalui tubuhku."
  },
  Voice_143516_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Epoyanis"
  },
  Voice_143517_AwakerVoiceContent = {
    Text = "Angkat kepalamu, perlihatkan tenggorokanmu."
  },
  Voice_143517_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_143518_AwakerVoiceContent = {
    Text = "Menghapus ingatan, menghapus keberadaan. Terasa familiar… kamu mengerti maksudku, meski berasal dari Sumber yang berbeda, tampaknya Mereka selalu tumbuh dari tempat tanpa cahaya."
  },
  Voice_143518_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Krisis"
  },
  Voice_143519_AwakerVoiceContent = {
    Text = "Kalian seharusnya tidak cukup bodoh untuk mengganggu kewibawaanku."
  },
  Voice_143519_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_143520_AwakerVoiceContent = {
    Text = "Terlalu lemah."
  },
  Voice_143520_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_143521_AwakerVoiceContent = {
    Text = "Di Epoyanis, pesta pora tidak akan pernah berhenti, dan musuh-musuh Epoyanis pun tidak akan pernah mendapat ketenangan."
  },
  Voice_143521_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_143521_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_143522_AwakerVoiceContent = {
    Text = [[
Ah, aku merasakan gemetar yang sama sepertimu, tapi itu sama sekali tidak perlu, temanku yang muda.
Terimalah rasa takutmu terhadap kemerosotan dan pengikisan diri, lihatlah aku, kamu mengerti bahwa kamu selalu memiliki pilihan lain.]]
  },
  Voice_143522_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_143522_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_143523_AwakerVoiceContent = {
    Text = [[
Benar, aku tahu bencana itu bukan atas perintah langsungnya, hanya kebetulan di tengah kesenangannya, tapi ini jelas hanya akan membuatku semakin ingin membunuhnya.
Kabut hitam itu sebaiknya tidak sendirian, dan jangan sampai tertangkap olehku.]]
  },
  Voice_143523_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_143524_AwakerVoiceContent = {
    Text = "Orang Ikan yang lengket itu bukanlah temanku, melainkan musuhku. Mengejutkan? laut memang tidak pernah menjadi milik mereka."
  },
  Voice_143524_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_143524_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_143525_AwakerVoiceContent = {
    Text = "Selamanya, tinggallah di sini!"
  },
  Voice_143525_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_143526_AwakerVoiceContent = {
    Text = "Sudah siap, para mangsa!"
  },
  Voice_143526_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_143527_AwakerVoiceContent = {
    Text = "Spiritualitas melahirkan tubuh baru, tubuh diisi dengan pengetahuan yang tidak penting, lalu individu-individu yang indah dan lincah itu akan berkumpul selamanya di satu tempat.\nMasih ingat yang kukatakan, kedalaman terdalam laut menampung segalanya… menyimpan segalanya."
  },
  Voice_143527_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_143527_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_143528_AwakerVoiceContent = {
    Text = "Nightmare, hadang Mereka."
  },
  Voice_143528_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_143529_AwakerVoiceContent = {
    Text = "Semoga makhluk-makhluk kecil ini tidak menguras kantongmu, kamu tahu, membesarkan satu keluarga besar memang bukan hal yang mudah."
  },
  Voice_143529_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_143530_AwakerVoiceContent = {
    Text = [[
Pada zaman dahulu kala, sebelum daratan muncul ke permukaan laut, planet ini telah membangkitkan beberapa spiritualitas yang istimewa. Kuat, agung, tidak dapat diintai.
Mereka tidak dapat didefinisikan sebagai bermusuhan atau bersahabat, manusia seperti makhluk-makhluk yang telah berlalu sebelumnya, tidak berarti bagi Mereka, akan dihapus seperti debu, namun juga akan dilindungi bersama wilayah kekuasaan.]]
  },
  Voice_143530_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_143530_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_143531_AwakerVoiceContent = {
    Text = "Hanya penuaan yang merupakan petualangan yang harus kamu hadapi sendiri, sahabat terbaikmu sekaligus musuh paling tangguh, cahaya Epoyanis akan mengusirnya hingga tuntas… Hanya Saja beberapa kenangan yang tidak berarti, kamu tidak perlu terjangkar oleh mereka."
  },
  Voice_143531_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_143531_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_143532_AwakerVoiceContent = {
    Text = "Lepaskan khayalan Pelarian."
  },
  Voice_143532_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  },
  Voice_143533_AwakerVoiceContent = {
    Text = "Kamu akan hancur menjadi abu putih kelabu."
  },
  Voice_143533_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_143534_AwakerVoiceContent = {Text = "Hah!"},
  Voice_143534_AwakerVoiceTitle = {Text = "Pukulan"},
  Voice_143535_AwakerVoiceContent = {
    Text = "Tindakan yang cerdas, anak kecil, para pengikut monster dari luar selalu cukup bodoh untuk melempar mayat ke laut, itu tidak bisa dianggap sebagai Hadiah, bukan?"
  },
  Voice_143535_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_143536_AwakerVoiceContent = {
    Text = "Kamu sudah diincar."
  },
  Voice_143536_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Dua"
  },
  Voice_143537_AwakerVoiceContent = {
    Text = "Meski enggan mengakuinya, pada beberapa kesempatan yang sangat jarang, aku merasa penuaan bukanlah satu-satunya hal yang dibawa oleh waktu, melainkan Hanya Saja sebuah simbol.\nMaka, aku mengizinkannya ada Pada diriku. Tentu saja — hanya sebatas penampilan."
  },
  Voice_143537_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_143539_AwakerVoiceContent = {
    Text = "Doa itu efektif, bayangkan saja, bahkan jika serangga membentuk tulisan Leo di hadapanmu, kamu pun akan mempertimbangkan untuk merespons permohonan serangga itu."
  },
  Voice_143539_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_143539_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_143540_AwakerVoiceContent = {
    Text = [[
Hahaha, sudah, jangan pasang Ekspresi itu, temanku yang kecil.
Itu hanyalah tradisi yang harus diikuti oleh beberapa "dewa-dewa lama", sedangkan untukmu, tanpa syarat dan harga apapun, aku akan selalu berada di sisimu.]]
  },
  Voice_143540_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_143540_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_143554_AwakerVoiceContent = {
    Text = [[
Hmph, monster kecil yang bersekutu dengan monster asing.
Ada makhluk bodoh yang menempatkanku dan dia di altar yang sama, sungguh penghinaan!]]
  },
  Voice_143554_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Tulu"
  },
  Voice_143554_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Tulu\", akan terbuka."
  },
  Voice_143555_AwakerVoiceContent = {
    Text = "Musuh dari musuhku adalah temanku, jika ada kesempatan, aku tidak keberatan melakukan transaksi bagus dengan merampas mainan favorit musuh bebuyutanku."
  },
  Voice_143555_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Ryker"
  },
  Voice_143555_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Ryker\", akan terbuka."
  },
  Voice_146158_AwakerVoiceContent = {
    Text = "Oh? Ingin berkelahi denganku di sini? Aku tidak keberatan."
  },
  Voice_146158_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_146159_AwakerVoiceContent = {
    Text = "Lebih banyak, berikan aku lebih banyak Kekuatan!"
  },
  Voice_146159_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_146160_AwakerVoiceContent = {
    Text = "Aku tidak menyukai orang yang tidak murni, karena ketidakmurnian biasanya berarti kelemahan. Namun kamu adalah pengecualian. Aku pernah berpikir bahwa seseorang yang menanggung banyak hal tidak bisa melangkah lebih jauh ke depan. Namun Jalan yang kamu tempuh, bahkan membuatku terkejut… Mungkin, seseorang yang berjalan di Jalan yang berbeda, justru adalah sosok yang lebih layak untuk dikembangkan dan ditantang. Kamu setuju, bukan, \"lawan\"?"
  },
  Voice_146160_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_146161_AwakerVoiceContent = {
    Text = "Paus Pengembara Langit Bintang, Devour segalanya!"
  },
  Voice_146161_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_146162_AwakerVoiceContent = {
    Text = "Berbanggalah karena telah menjadi lawanku!"
  },
  Voice_146162_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_146163_AwakerVoiceContent = {
    Text = "Biarkan lautan bintang, Menyaksikan Kehancuran!"
  },
  Voice_146163_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_146164_AwakerVoiceContent = {
    Text = "Tidak cukup, masih jauh dari cukup…"
  },
  Voice_146164_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_146165_AwakerVoiceContent = {Text = "Heh."},
  Voice_146165_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_146166_AwakerVoiceContent = {Text = "Hmph."},
  Voice_146166_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_146167_AwakerVoiceContent = {
    Text = "Aku tidak peduli dengan segala yang lenyap, namun aku tidak akan membiarkannya menjadi penghalang di Jalan pencarianku akan Kekuatan."
  },
  Voice_146167_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Krisis"
  },
  Voice_146168_AwakerVoiceContent = {
    Text = "Karena Pembantaian yang pasti akan datang, lalu mulai Merasakan keraguan akan makna dari segala keberadaan… Aku tidak tertarik untuk ikut dalam perdebatan membosankan ala anak kecil semacam ini. Tidak peduli dengan Kehancuran, dan tidak perlu mengabadikannya. Kekuatan itu sendiri, itulah maknanya."
  },
  Voice_146168_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Doll: Inferno"
  },
  Voice_146168_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Boneka·Melt\" akan terbuka"
  },
  Voice_146169_AwakerVoiceContent = {
    Text = "Di dalam matamu, aku melihat kehendak yang bukan berasal dari sini. Itu tidak murni, namun cukup tangguh. Baiklah, buktikan padaku, dengan Kekuatan dan hasrat seperti apa kamu berdiri di hadapanku."
  },
  Voice_146169_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_146170_AwakerVoiceContent = {Text = "Ha!"},
  Voice_146170_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_146171_AwakerVoiceContent = {
    Text = "Berbanggalah karena telah menjadi lawanku!"
  },
  Voice_146171_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_146172_AwakerVoiceContent = {
    Text = "Aroma Chaos, sudah lama tidak terasa… Sejak saat aku lahir dari Void ini, apa yang aku kejar tidak pernah berubah."
  },
  Voice_146172_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_146172_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_146173_AwakerVoiceContent = {
    Text = "Ingin menantangku? Aku menghargai keberanianmu, dan aku bersedia memberikanmu kehormatan untuk dikalahkan. Ini adalah rasa hormatku kepada \"Penjaga Mythag\"."
  },
  Voice_146173_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_146173_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_146174_AwakerVoiceContent = {
    Text = "Sebuah utopia palsu yang penuh sesak dengan para lemah, pengecut, dan orang-orang bodoh yang menipu diri sendiri. Tapi tidak masalah, tempat ini bisa menghadirkan musuh yang paling mengasyikkan bagiku, itu sudah cukup."
  },
  Voice_146174_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Mythag"
  },
  Voice_146175_AwakerVoiceContent = {
    Text = "Jelas-jelas memiliki Kekuatan yang luar biasa, namun karena Ketakutan, rasa bersalah, dan kelelahan, mengurung bakatnya sendiri Di Dalam Mimpi yang panjang, sungguh pemborosan."
  },
  Voice_146175_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Tulu"
  },
  Voice_146175_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Tulu\", akan terbuka."
  },
  Voice_146176_AwakerVoiceContent = {
    Text = "Tidak ada tandingannya."
  },
  Voice_146176_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_146177_AwakerVoiceContent = {
    Text = "Sealed sedikit Longgar… Kekuatan dari kedalaman lautan bintang sedang mengalir ke atas. Sudah lama sekali aku tidak merasakan perasaan seperti ini…"
  },
  Voice_146177_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_146177_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_146178_AwakerVoiceContent = {
    Text = "Paus Pengembara Langit Bintang, Devour segalanya!"
  },
  Voice_146178_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_146179_AwakerVoiceContent = {
    Text = "…Memuaskan."
  },
  Voice_146179_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_146180_AwakerVoiceContent = {
    Text = "Aku telah berkelana di antara lautan bintang selama bertahun-tahun tanpa hitung, mengirimkan mereka yang mengaku kuat ke dalam jurang dengan tanganku sendiri. Kamu memiliki keistimewaanmu sendiri, namun jika ingin berdiri sejajar denganku, belajarlah dulu untuk mengangkat kepalamu di hadapanku. Teman seperjalanan yang pengecut, tidak kubutuhkan."
  },
  Voice_146180_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_146180_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_146181_AwakerVoiceContent = {
    Text = "Yang berani, yang pengecut, yang kuat, yang Fragile… heh, tidak, aku tidak peduli seperti apa sosok seorang lawan. Apapun orangnya, selama ia adalah lawan yang memiliki kemampuan, itu sudah cukup membuatku merasa senang."
  },
  Voice_146181_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_146182_AwakerVoiceContent = {
    Text = "Lemah. Di dunia ini ada tak terhitung hal yang menjijikkan, namun kelemahan adalah dosa asal yang paling memalukan. Setiap orang datang ke dunia ini membawa pedang, tidak ada yang berhak untuk Longgar genggamannya sebelum mencapai ujung, melangkah ke medan perang yang telah ditakdirkan dengan pikiran kekalahan. Itu adalah penghinaan bagi lawan, sekaligus bagi diri sendiri."
  },
  Voice_146182_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_146183_AwakerVoiceContent = {
    Text = "Sisa Bintang yang telah membusuk, Bangkitlah—"
  },
  Voice_146183_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_146184_AwakerVoiceContent = {
    Text = "Heh… lawan yang menyenangkan. Lain kali, aku tidak akan menahan diri lagi."
  },
  Voice_146184_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_146185_AwakerVoiceContent = {
    Text = "Tulang-tulangku gemetar karena kegembiraan… Aku telah melihat usaha yang kamu kerahkan. Ini adalah bukti bahwa kamu layak berdiri di sisiku, Penjaga."
  },
  Voice_146185_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_146185_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_146186_AwakerVoiceContent = {
    Text = "Heh… kamu melihatnya dengan jelas, Penjaga. Belenggu Kekuatan, memang diciptakan untuk dihancurkan!"
  },
  Voice_146186_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_146186_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_146187_AwakerVoiceContent = {Text = "Hm?"},
  Voice_146187_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_146188_AwakerVoiceContent = {Text = "Hm?"},
  Voice_146188_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_146189_AwakerVoiceContent = {
    Text = "Tepat di depan… ujung dari Kekuatan yang telah kucari sepanjang hidupku… Kamulah yang mengikutiku sepanjang Jalan ini, membimbingku hingga ke sini. Aku sangat menantikannya, Menyaksikan hari yang paling akhir itu bersamamu!"
  },
  Voice_146189_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_146189_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_146190_AwakerVoiceContent = {
    Text = "Mungkin kata-kataku sebelumnya terlalu gegabah… Kecepatan Pertumbuhanmu, dan Kekuatan tersembunyi yang ada padamu, sedikit di luar perkiraanku. Aku telah menyaksikan terlalu banyak HP yang lenyap dalam Pembantaian waktu, namun kamu… memang tidak biasa. Aku sangat ingin tahu, dari mana gerangan rahasia Kekuatan yang ada padamu itu berasal?"
  },
  Voice_146190_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_146190_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_146192_AwakerVoiceContent = {
    Text = "Mulut neraka, terbukalah untukku!"
  },
  Voice_146192_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_146193_AwakerVoiceContent = {
    Text = "Ah, aku melihatnya… ujung dari Kekuatan, tidak pernah ada sejak awal… Tantangan sejati, kini baru terbuka untukku! Kamulah yang membawaku ke sini, membuatku melihat segalanya dengan jelas. Segera, aku akan membawa seorang pejuang yang jauh lebih sempurna ke hadapanmu. Kuharap pada saat itu, aku juga bisa melihat dirimu yang jauh lebih sempurna, \"lawan\"-ku."
  },
  Voice_146193_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_146193_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_146194_AwakerVoiceContent = {
    Text = "Trik kecil."
  },
  Voice_146194_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_146195_AwakerVoiceContent = {
    Text = "Kekuatan mendidih di dalam sumsum tulang!"
  },
  Voice_146195_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_146196_AwakerVoiceContent = {
    Text = "Devour hingga habis!"
  },
  Voice_146196_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_146197_AwakerVoiceContent = {
    Text = "Belas kasih, kelemahan, kebingungan… matamu dipenuhi oleh kotoran. Seseorang yang tidak cukup murni, tidak akan pernah bisa memahami apa itu Kekuatan."
  },
  Voice_146197_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_146197_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_146198_AwakerVoiceContent = {
    Text = "Kekuatan sejati tidak pernah ada hubungannya dengan balas dendam atau perlindungan. Strength hanyalah Strength, diriku yang lain tidak pernah \"benar-benar\" memahami kebenaran ini. Inilah akar dari mengapa dia tidak cukup kuat."
  },
  Voice_146198_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Lotan"
  },
  Voice_146198_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Lotan\", akan terbuka."
  },
  Voice_146199_AwakerVoiceContent = {
    Text = [[
Dengarkan baik-baik, aku hanya akan mengatakannya sekali:
Aku, Lotan, mengakuimu sebagai lawan yang layak untuk Menunggu.
Sebelum kamu mencapai puncak, aku akan menjadi pedang yang paling bisa kamu andalkan. Janjiku dan kesetiaanku tidak ada hubungannya dengan emosi. Kamu adalah lawan yang paling menyenangkan bagiku, aku tidak akan membiarkanmu terjatuh di tengah perjalanan.]]
  },
  Voice_146199_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_146199_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_146200_AwakerVoiceContent = {
    Text = "Ayo, bunuh aku, atau, dibunuh olehku."
  },
  Voice_146200_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_146201_AwakerVoiceContent = {
    Text = "Mulut neraka, terbukalah untukku!"
  },
  Voice_146201_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_146521_AwakerVoiceContent = {
    Text = "Di mana pisau tulang mengarah, segalanya hancur berkeping!"
  },
  Voice_146521_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  },
  Voice_147047_AwakerVoiceContent = {
    Text = "Kekuatan… tiada batas!"
  },
  Voice_147047_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Dua"
  },
  Voice_147493_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_147493_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_147494_AwakerVoiceContent = {
    Text = "(Sebuah nyanyian serak dan datar)"
  },
  Voice_147494_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_147495_AwakerVoiceContent = {
    Text = "Penonton, membutuhkan lebih banyak penonton…"
  },
  Voice_147495_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_147496_AwakerVoiceContent = {
    Text = "Pasir… gurun putih… di sini sangat berbahaya, cepat ikut aku pergi."
  },
  Voice_147496_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_147496_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_147497_AwakerVoiceContent = {
    Text = "Aku masih ingat peta rumah baru, semuanya penuh warna dan sangat indah. Inilah tempat yang seharusnya kita tuju. Kita bisa bernyanyi, dan kita bisa mendapatkan kebahagiaan."
  },
  Voice_147497_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_147498_AwakerVoiceContent = {Text = "Ah"},
  Voice_147498_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_147499_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_147499_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_147500_AwakerVoiceContent = {Text = "Eh…?"},
  Voice_147500_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_147501_AwakerVoiceContent = {
    Text = "Itu adalah... suara langit berbintang..."
  },
  Voice_147501_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_147502_AwakerVoiceContent = {
    Text = "Kamu datang lagi. Seperti dulu, duduklah di sampingku dan kita tunggu bersama. Menunggu apa...? Ya, menunggu saja."
  },
  Voice_147502_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_147503_AwakerVoiceContent = {
    Text = "Gladi bersih yang sempurna, saya pikir saya sudah siap untuk tampil di atas panggung."
  },
  Voice_147503_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_147503_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_147504_AwakerVoiceContent = {Text = "Jatuhlah."},
  Voice_147504_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_147505_AwakerVoiceContent = {
    Text = "Untuk kehancuran dan kematian."
  },
  Voice_147505_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_147506_AwakerVoiceContent = {
    Text = "Saya bukan orang gila, dan saya tidak pernah merasa sedih. Jangan dengarkan rumor yang konyol."
  },
  Voice_147506_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_147507_AwakerVoiceContent = {
    Text = "Aneh, sepertinya mereka sangat takut dengan suaraku…"
  },
  Voice_147507_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_147508_AwakerVoiceContent = {Text = "Ssst……"},
  Voice_147508_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_147509_AwakerVoiceContent = {
    Text = "Benar-benar kostum pertunjukan yang indah, berkilauan, berkilauan…"
  },
  Voice_147509_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_147509_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_147510_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_147511_AwakerVoiceContent = {
    Text = "Kilauan bintang yang masih tersisa hingga saat ini."
  },
  Voice_147511_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_147512_AwakerVoiceContent = {
    Text = "Bernyanyilah."
  },
  Voice_147512_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_147513_AwakerVoiceContent = {
    Text = "Latihan vokal yang benar...? Tapi aku cukup puas dengan suaraku saat ini."
  },
  Voice_147513_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_147513_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_147514_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_147515_AwakerVoiceContent = {
    Text = "Sepertinya ada beberapa perubahan pada suara……"
  },
  Voice_147515_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_147515_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_147516_AwakerVoiceContent = {
    Text = "Bagaimana, apakah suaraku enak didengar?"
  },
  Voice_147516_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_147517_AwakerVoiceContent = {
    Text = "Tidurlah dengan tenang..."
  },
  Voice_147517_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_147518_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_147519_AwakerVoiceContent = {Text = "Baik."},
  Voice_147519_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_147520_AwakerVoiceContent = {Text = "Ah"},
  Voice_147520_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_147521_AwakerVoiceContent = {
    Text = "Terima kasih… Apakah aku harus mengucapkan terima kasih?"
  },
  Voice_147521_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_147522_AwakerVoiceContent = {Text = "Haah..."},
  Voice_147522_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_147523_AwakerVoiceContent = {
    Text = "Bersinarlah."
  },
  Voice_147523_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_147524_AwakerVoiceContent = {
    Text = "Perasaan yang sudah lama tak terasa... akhirnya kembali ke panggung. Terima kasih, Penjaga."
  },
  Voice_147524_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_147524_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_147525_AwakerVoiceContent = {
    Text = "Maaf mengganggu... bisakah kamu menurunkan saya dari pohon ini? Saya tidak ingat mengapa saya naik ke sini, mungkin karena awan di atas terlihat agak membuat saya merasa nostalgia..."
  },
  Voice_147525_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_147526_AwakerVoiceContent = {
    Text = "Orang-orang sukuku tidak pernah meninggalkanku, mereka hanya pergi ke tempat yang sangat, sangat jauh."
  },
  Voice_147526_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Klan"
  },
  Voice_147527_AwakerVoiceContent = {
    Text = "Apakah kamu mendengarnya?"
  },
  Voice_147527_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_147528_AwakerVoiceContent = {Text = "Oh."},
  Voice_147528_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_147529_AwakerVoiceContent = {
    Text = "Kamu selalu berkeliaran di sekitarku... Aku mengerti, kau pasti penggemar laguku, kan."
  },
  Voice_147529_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_147529_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_147530_AwakerVoiceContent = {
    Text = "Lalalala~ apa, ada Clades kehancuran dunia di sini? Ah... aku harus merapikan rambutku dengan baik, dan aku juga harus mencari kakak..."
  },
  Voice_147530_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_147531_AwakerVoiceContent = {
    Text = "Ssst... jangan bicara, ada orang jahat datang. Mereka ingin membawa aku dan kakakku pergi, dan tidak mengizinkan kami naik kapal..."
  },
  Voice_147531_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Keamanan"
  },
  Voice_147532_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_147532_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_147533_AwakerVoiceContent = {
    Text = "Ketika aku terbangun, planet sedang mengalami kehancuran. Aku melihat langit malam mengelupas satu per satu, dunia menjadi kanvas yang ditiup angin kencang, pertama berubah bentuk, lalu robek, dan hancur berkeping-keping."
  },
  Voice_147533_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_147533_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_147534_AwakerVoiceContent = {
    Text = "Ini adalah poster tanda tanganku, yang digambar oleh Tuan Pickman untukku. Aku memberikannya kepadamu."
  },
  Voice_147534_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Pingsan"
  },
  Voice_147534_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Pingsan\", akan terbuka."
  },
  Voice_149667_AwakerVoiceContent = {
    Text = "Hmm? Penasaran? Perbendaharaan Ibu Peri tidak bisa sembarangan diperlihatkan ke orang luar. Kalau ingin tahu apa yang ada di dalamnya yang penuh sesak itu, lebih baik bergabunglah dengan Sekte Peri sekarang, hehe?"
  },
  Voice_149667_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_149668_AwakerVoiceContent = {
    Text = "Kau tidak percaya kesimpulan Caraboo? Huhu, ternyata memang sulit menipu semua orang… Sebenarnya aku adalah putri haram @1 Adipati Bohémond VI, menyembunyikan identitas dan tersesat di dunia manusia, mengaku sebagai peri hanya untuk menghindari kejaran musuh… Aku sudah memberitahumu rahasia terpentingku, masa kau masih tidak percaya padaku?"
  },
  Voice_149668_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_149668_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_149669_AwakerVoiceContent = {
    Text = "Sakit sekali~"
  },
  Voice_149669_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_149670_AwakerVoiceContent = {
    Text = "Terlalu banyak makan permen? Tidak tidak tidak, ini adalah rahasia Ibu Peri untuk tetap tersenyum, tidak mungkin berhenti hanya karena hal sepele seperti gigi berlubang kan? ~~"
  },
  Voice_149670_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_149671_AwakerVoiceContent = {
    Text = "Ayo, berdirilah di sisi Peri ini. Apa? Semua orang berbagi persembahan bersama? … Baiklah, kalau memang itu aturan Mythag… maka aku… aku pasti tidak ada keberatan sama sekali, ayo, mari kita ramai-ramai bersama!"
  },
  Voice_149671_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_149671_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_149672_AwakerVoiceContent = {
    Text = "Aduh, sungguh domba kecil yang saleh ya."
  },
  Voice_149672_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_149673_AwakerVoiceContent = {
    Text = "Sedikit lagi, baru peri akan memberikan berkahnya padamu?"
  },
  Voice_149673_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_149674_AwakerVoiceContent = {
    Text = "Kalian masih terlalu hijau~"
  },
  Voice_149674_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_149676_AwakerVoiceContent = {
    Text = "Upacara pemujaan kali ini jauh lebih meriah dari biasanya, dan jumlah persembahannya pun harus lebih banyak… Aduh, tentu saja bukan manusia cacat ya, aku ini peri yang baik hati, tidak akan melakukan hal yang menyakiti orang lain~"
  },
  Voice_149676_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_149676_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_149677_AwakerVoiceContent = {
    Text = [[
Penjaga, apakah Anda sudah siap mendengar kata-kata tulus Caraboo?
Dari mana Caraboo berasal, itu sama sekali tidak penting. Yang penting adalah, Anda adalah hadiah paling berharga yang diberikan langit kepadaku, Caraboo sudah memutuskan untuk selalu, selalu tinggal di sisi Anda yang mulia ini.
Anda pikir ini juga bagian dari tipu muslihat, agar Anda tidak menyelidiki lagi? Hehe, menurut Anda?
Pokoknya, sebagai hadiah karena sudah mengucapkan kata-kata tulus, bolehkah Caraboo diberi sepotong permen karet rasa apel?]]
  },
  Voice_149677_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_149677_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_149678_AwakerVoiceContent = {Text = "Hehe~"},
  Voice_149678_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_149680_AwakerVoiceContent = {
    Text = "Tidak apa-apa, lain kali fokus melindungi peri ini, maka tidak akan gagal lagi~"
  },
  Voice_149680_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_149682_AwakerVoiceContent = {
    Text = "Jangan coba-coba menipuku!"
  },
  Voice_149682_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_149683_AwakerVoiceContent = {
    Text = "Wah, ternyata ada begitu banyak persembahan… Ehm, hehe, bagus sekali, layak mendapat pujian! Sini, peri memberikanmu ciuman peri! Pikir apa, tentu saja di dahi!"
  },
  Voice_149683_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_149683_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_149684_AwakerVoiceContent = {
    Text = "Terima kasih atas persembahan para umat! Ibu Peri yang penuh pengertian ini akan memahatkan patung emas murni untukmu di dalam kuil. Aduh, demi patung ini bisa menampilkan postur tubuhmu yang dingin nan indah itu, masih perlu mencari bahan yang lebih baik lagi~"
  },
  Voice_149684_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_149684_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_149685_AwakerVoiceContent = {
    Text = "Kamu? … Kamu adalah salah satu anggota gereja kami yang belum tercerahkan, Caraboo akan dengan sabar menunggu hari saat kamu menyadari kebenaran sejati dunia. Pada saat itu, ingatlah untuk mempersembahkan raga, kesetiaan, dan hartamu kepada pemimpin gereja, hehe."
  },
  Voice_149685_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_149686_AwakerVoiceContent = {
    Text = "Barang-barang di daftar itu… sudah terkumpul semua? Kekayaan Mythag sungguh tak terduga dalamnya… Kalau tahu begini, aku akan… Hmm? Apa yang aku gumamkan? Hanya sedang berterima kasih atas kemurahan hati Lord Dexter, hehe~"
  },
  Voice_149686_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_149686_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_149687_AwakerVoiceContent = {
    Text = "Hal yang paling dibenci? Tentu saja para penyihir yang tidak punya jiwa kontrak. Ada rahasia yang mau kuberitahu diam-diam, sebenarnya semua penyihir adalah penipu besar, semua ramalan dan kutukan yang mereka ucapkan hanyalah untuk menipumu hingga jatuh miskin! Adapun cara mencegahnya… cukup biarkan uangmu mendapat berkah dari peri saja!"
  },
  Voice_149687_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_149688_AwakerVoiceContent = {
    Text = "Perkenalan pertama, aku adalah peri pucat dari negeri jauh, tertarik untuk mengenalku lebih lanjut? Berkah peri memiliki intensitas berbeda sesuai tingkatan iuran, hehe~"
  },
  Voice_149688_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_149689_AwakerVoiceContent = {
    Text = "Dalam upacara pemujaan sebelumnya, selain prosesi tujuh kali sembahyang dan tiga kali sumpah, para pengikut juga akan membangun kuil baru khusus untukku dan mempersembahkan persembahan yang melimpah. Ini daftarnya!"
  },
  Voice_149689_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_149689_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_149690_AwakerVoiceContent = {
    Text = "Marilah, kubur semua hal yang ingin kau lepaskan ke dalam salju yang dalam…"
  },
  Voice_149690_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_149691_AwakerVoiceContent = {
    Text = "Aku dengar kau sedang mencari tahu asal-usulku, hehe, itu adalah rahasia Ibu Peri. Tapi, kalau kau benar-benar ingin menyelidiki, di Sekte Peri ada biografi yang aku tulis sendiri, cukup serahkan seratus ribu keping Perak untuk bisa membacanya, mau coba?"
  },
  Voice_149691_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_149691_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_149692_AwakerVoiceContent = {
    Text = "Bagus sekali, di sini ada banyak anak-anak yang sangat menggemaskan dan tunjangan hidup yang dermawan hingga mengejutkan. Dengan mereka, cepat atau lambat aku bisa mengumpulkan cukup ongkos perjalanan ke timur…"
  },
  Voice_149692_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Mythag"
  },
  Voice_149693_AwakerVoiceContent = {
    Text = "Ingat untuk menyembah sang ibu baptis ya, hehe."
  },
  Voice_149693_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_149694_AwakerVoiceContent = {
    Text = "Maaf ya, wilayah kekuasaan peri sangat sakral, mohon maaf tidak bisa menerima manusia serigala yang aneh… Soal ada bau kebohongan di udara atau semacamnya, mungkin hidungnya saja yang tidak berfungsi?"
  },
  Voice_149694_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Ryker"
  },
  Voice_149694_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Ryker\", akan terbuka."
  },
  Voice_149695_AwakerVoiceContent = {
    Text = "Eh, ada yang bilang aku peri palsu… ketahuan juga ya, hehe. Aku tahu kau tidak akan peduli, kan?"
  },
  Voice_149695_AwakerVoiceTitle = {
    Text = "Obrolan · Tentang Desas-desus"
  },
  Voice_149696_AwakerVoiceContent = {
    Text = "Mmm, enak sekali~"
  },
  Voice_149696_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_149697_AwakerVoiceContent = {
    Text = "Tenang saja~"
  },
  Voice_149697_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_149698_AwakerVoiceContent = {
    Text = "Domba-domba yang tersesat, peri ini datang untuk membersihkan dosa kalian, hehe~"
  },
  Voice_149698_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_149699_AwakerVoiceContent = {
    Text = "Masih belum menyerah juga? Baiklah, biar Caraboo sendiri yang memberitahumu. Sebenarnya Caraboo adalah putri dari dewi Umapati yang menguasai gunung salju menjulang tinggi di timur… Hmm, kau bilang dewi itu hanya punya dua putra dan tidak punya putri? Catatan tentang para dewa memang selalu ada yang kurang."
  },
  Voice_149699_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_149699_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_149700_AwakerVoiceContent = {
    Text = "Jreng jreng~ Cahaya peri sudah menyinarimu, maju terus!"
  },
  Voice_149700_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_149701_AwakerVoiceContent = {
    Text = "Sudah sudah, jangan diselidiki lagi, boleh tidak? Sebagai kompensasi karena sudah baik hati menghentikan tindakan lancang ini, aku bisa diam-diam membagi setengah permen paling berhargaku untukmu. Ketahuilah, di medan perang pasukan Perang Salib, permen manis adalah barang langka."
  },
  Voice_149701_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_149701_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_149702_AwakerVoiceContent = {
    Text = "Berkah Caraboo bisa menyembuhkan segala penyakit di dunia, tentu saja juga bisa menyembuhkan wabah hitam ini… Tentu saja benar, asalkan kau cukup saleh dan cukup percaya pada Caraboo, hehe."
  },
  Voice_149702_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Krisis"
  },
  Voice_149703_AwakerVoiceContent = {
    Text = "Menyebalkan!"
  },
  Voice_149703_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_149704_AwakerVoiceContent = {
    Text = "Cahaya sang peri~"
  },
  Voice_149704_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_149705_AwakerVoiceContent = {
    Text = "Tujuh kali sembahyang, tiga kali sumpah, gunakan mereka untuk mendapatkan pengampunan dari peri!"
  },
  Voice_149705_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_150079_AwakerVoiceContent = {
    Text = "Rasakan saja!"
  },
  Voice_150079_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_150104_AwakerVoiceContent = {
    Text = "Eh, kenapa Ogier membiarkan Anda masuk? Bukankah sudah sepakat untuk menghalangi semua orang? Anda adalah tuannya… ? Anak kecil yang tidak bisa diandalkan sungguh merepotkan, untuk pertemuan kali ini aku sudah mengeluarkan banyak tenaga untuk mempersiapkannya. Bagaimana kalau… persembahan yang diterima dibagi lima puluh-lima puluh, Anda tutup mata untuk kali ini?"
  },
  Voice_150104_AwakerVoiceTitle = {
    Text = "Obrolan: Tentang Ogier"
  },
  Voice_150104_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Ogier\", akan terbuka."
  },
  Voice_22276_AwakerVoiceContent = {
    Text = "Ayo cepat selesaikan, jangan berlama-lama di jalanan."
  },
  Voice_22276_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_36679_AwakerVoiceContent = {
    Text = "Dia bergabung dengan sekte saat aku sedang tidur, aku tidak punya banyak interaksi dengannya. \nNamun, kabarnya dia datang sendiri. Ingin menyerahkan bentuk manusianya dan menjadi \"Pelaut\" sepenuhnya… Hmph, satu lagi orang bodoh yang kehilangan akal karena kekuatan."
  },
  Voice_36679_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Caecus"
  },
  Voice_36679_UnlockDesc = {
    Text = "Setelah menyelesaikan Bab 6 dari \"Operasi\""
  },
  Voice_36680_AwakerVoiceContent = {
    Text = "Goliath tidak pernah menjadi anak anjing yang setia, aku benar-benar tidak mengerti kenapa Miryam begitu mempercayainya… Jika tidak diikat dengan rantai, dia pasti akan menjadi yang pertama melarikan diri."
  },
  Voice_36680_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Goliath"
  },
  Voice_36680_UnlockDesc = {
    Text = "Setelah menyelesaikan Bab 6 dari \"Operasi\""
  },
  Voice_36681_AwakerVoiceContent = {
    Text = "Pelaut tidak terlahir dalam bentuk seperti ini. Untuk berbaur dengan keramaian, paruh pertama hidup mereka tidak berbeda dengan manusia…\nKamu harus berhati-hati, siapa tahu pemilik toko kue favoritmu juga adalah salah satu dari mereka, ya?"
  },
  Voice_36681_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Pelaut"
  },
  Voice_36681_UnlockDesc = {
    Text = "Setelah menyelesaikan Bab 6 dari \"Operasi\""
  },
  Voice_36682_AwakerVoiceContent = {
    Text = "Lagu kapal yang fals dari Celeste, hidangan andalan kapten yaitu daging asap dan ikan segar rebus, selimut yang bau amis dan keras akibat terpaan angin laut… meskipun penuh bahaya dan ketegangan, saya tidak akan pernah melupakan bulan-bulan kami mengungsi di lautan bersama mereka."
  },
  Voice_36682_AwakerVoiceTitle = {
    Text = "Percakapan Santai · Tentang \"Kapal Hantu\""
  },
  Voice_36682_UnlockDesc = {
    Text = "Setelah menyelesaikan Bab 6 dari \"Operasi\""
  },
  Voice_36683_AwakerVoiceContent = {
    Text = [[
Meskipun semua orang di sekolah terlihat sibuk, tapi...
Namun, di sini ada rasa ketenangan yang belum pernah kurasakan sebelumnya.
Rasanya saat berkumpul dengan tujuan yang sama dan berusaha bersama-sama... Hmm, cukup menyenangkan.]]
  },
  Voice_36683_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag · II"
  },
  Voice_36683_UnlockDesc = {
    Text = "Setelah menyelesaikan Bab 6 dari \"Operasi\""
  },
  Voice_36684_AwakerVoiceContent = {
    Text = [[
Tempat tidurnya terlalu keras, cuacanya terlalu dingin, teh merah di sore hari selalu terasa seperti air cucian rumput... Saya punya seribu alasan untuk tidak menyukai tempat ini. 
Namun, hanya karena "kamu ada di sini", saya rasa saya bisa tetap tinggal dengan terpaksa...]]
  },
  Voice_36684_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Penjaga·III"
  },
  Voice_36684_UnlockDesc = {
    Text = "Setelah menyelesaikan Bab 6 dari \"Operasi\""
  },
  Voice_36685_AwakerVoiceContent = {
    Text = [[
Te-terima kasih... Eh? Kenapa aku harus berterima kasih padamu? Ini, ini sudah jelas! Tentu saja karena semua yang telah kau lakukan untukku di laut... 
 Tunggu sebentar, kenapa kau tertawa? Kau pasti ingin melihatku kelabakan, kan!]]
  },
  Voice_36685_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Penjaga·II"
  },
  Voice_36685_UnlockDesc = {
    Text = "Setelah menyelesaikan Bab 6 dari \"Operasi\""
  },
  Voice_36686_AwakerVoiceContent = {
    Text = [[
Aku pernah berpikir bahwa ada ikatan keluarga antara aku dan dia... 
Namun, setelah semua itu terjadi, aku baru menyadari bahwa mungkin, kehangatan sesaat itu sejak awal hanyalah angan-anganku belaka. 
Bagaimana pun kau memperlakukannya, itu urusan kalian. Asalkan jangan biarkan dia mendekatiku lagi.]]
  },
  Voice_36686_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Miryam·II"
  },
  Voice_36686_UnlockDesc = {
    Text = "Setelah menyelesaikan Bab 6 dari \"Operasi\""
  },
  Voice_36687_AwakerVoiceContent = {
    Text = [[
Aneh sekali... perasaan ini benar-benar aneh. 
Jantung sudah tidak berdetak lagi, tapi tubuh masih hangat... Hei, kemarilah dan sentuh tanganku, katakan padaku ini bukan halusinasi.]]
  },
  Voice_36687_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang \"Pembangun\""
  },
  Voice_36687_UnlockDesc = {
    Text = "Setelah menyelesaikan Bab 6 dari \"Operasi\""
  },
  Voice_45153_AwakerVoiceContent = {
    Text = "Meskipun saya mungkin tidak dilahirkan di Kerajaan Leo, Gereja adalah tempat saya memperoleh hidup kedua saya. Jadi, apa salahnya jika saya menganggap tempat ini sebagai Rumah saya?"
  },
  Voice_45153_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Rumah"
  },
  Voice_45154_AwakerVoiceContent = {
    Text = [[
Setelah wabah tak terlihat menyebar selama bertahun-tahun, akhirnya Bapa mendengar doaku dan memberikan "Berkat" ini yang dapat melawan penderitaan. Memang, itu bisa memberikan hidup, tetapi juga membutuhkan harga yang harus dibayar. 
Sebagai pelaksana, sudah sepantasnya aku menanggung beban mereka yang menerima Berkat ini.]]
  },
  Voice_45154_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang \"Berkat\""
  },
  Voice_45155_AwakerVoiceContent = {
    Text = [[
Bagi saya, keadaan Pembangun adalah anugerah yang diberikan oleh Sang Pencipta kepada jiwa-jiwa di pelukan-Nya. Ini adalah hidup kedua, dan juga kesempatan untuk memperbaiki penyesalan masa lalu.
Saya akan terus melakukan pekerjaan Sang Pencipta, menjalankan tugas sebagai pelaksana-Nya, dan menghilangkan lebih banyak penderitaan.]]
  },
  Voice_45155_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang \"Pembangun\""
  },
  Voice_45156_AwakerVoiceContent = {
    Text = "Izinkan saya sekali lagi menyampaikan rasa terima kasihku, Penjaga. Kau telah menghormati pendapatku dan menjaga rahasia untukku dari Komite. Jika mereka ikut campur, kemungkinan besar mereka tidak akan mengizinkanku untuk terus melayani Gereja."
  },
  Voice_45156_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Penjaga·II"
  },
  Voice_45156_UnlockDesc = {
    Text = "Terbuka setelah menyelesaikan Catatan Misi Khusus \"Warna Darah\""
  },
  Voice_45157_AwakerVoiceContent = {
    Text = "Anak itu tulus, teguh, dan baik hati, memiliki jiwa yang cerah dan langka. Terakhir kali saya melihat seseorang seperti ini adalah pada kehidupan pertama saya."
  },
  Voice_45157_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Ogier"
  },
  Voice_45157_UnlockDesc = {
    Text = "Terbuka setelah menyelesaikan Catatan Misi Khusus \"Warna Darah\""
  },
  Voice_45158_AwakerVoiceContent = {
    Text = "Kehilangan penglihatan bukan berarti saya menjadi buta sepenuhnya. Ketika Ayah memberikan kedatangan kegelapan kepada saya, Dia juga membuat saya mampu melihat cahaya redup dari jiwa."
  },
  Voice_45158_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Visual"
  },
  Voice_45159_AwakerVoiceContent = {
    Text = [[
Pada saat itu, meskipun aku diberkati dengan "Berkat", aku tetap hanyalah seorang manusia biasa. Terlalu banyak yang menderita, terlalu banyak orang yang membutuhkan "Berkat". Aku ingin menyelamatkan mereka semua, namun gagal. 
Ini adalah penyesalan terbesarku, dan juga rasa bersalah yang abadi.]]
  },
  Voice_45159_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Hidup Pertama"
  },
  Voice_45160_AwakerVoiceContent = {
    Text = "Banyak orang di dalam Gereja percaya bahwa \"api putih\" yang disebutkan dalam 《Kitab Suci》 mengacu pada cahaya bulan: utusan pucat akan muncul dari cahaya bulan dan memimpin kita keluar dari penderitaan. \nNamun, aku tahu bahwa api sejati adalah jiwa yang menyala-nyala di dalam hati kita."
  },
  Voice_45160_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang \"Api Pucat\""
  },
  Voice_45161_AwakerVoiceContent = {
    Text = [[
Sebenarnya, menyembunyikan identitasku adalah kehendak Uskup Agung. Beliau tidak menjelaskan alasannya secara rinci, hanya memperingatiku: bahkan tempat yang paling murni pun bisa menyimpan bayangan, berbuat baik pun perlu ekstra hati-hati.
Tentu saja, kepadamu, aku sepenuhnya percaya.]]
  },
  Voice_45161_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Menyembunyikan Identitas"
  },
  Voice_45161_UnlockDesc = {
    Text = "Terbuka setelah menyelesaikan Catatan Misi Khusus \"Warna Darah\""
  },
  Voice_4908_AwakerVoiceContent = {
    Text = "Apakah nyanyian saya bisa membantu Anda?"
  },
  Voice_4908_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_4909_AwakerVoiceContent = {
    Text = "Sialan, dia juga masih anak kecil, kenapa kalian semua begitu menghormatinya! Tunjukkan sikap yang sama kepada tuan putri ini, mengerti!"
  },
  Voice_4909_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Tulu"
  },
  Voice_4909_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Tulu\", akan terbuka."
  },
  Voice_4910_AwakerVoiceContent = {
    Text = "Hei, kamu tahu apa yang biasanya dilakukan oleh Pembangun lainnya? Jangan salah paham, aku tidak ingin berteman, aku hanya ingin... ya, aku hanya ingin melakukan inspeksi!"
  },
  Voice_4910_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Kehidupan Sehari-hari"
  },
  Voice_4911_AwakerVoiceContent = {
    Text = "Sialan sialan sialan! Lain kali harus melemparkan mayat mereka untuk memberi makan laba-laba!"
  },
  Voice_4911_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_4912_AwakerVoiceContent = {Text = "Sisa rasa."},
  Voice_4912_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_4913_AwakerVoiceContent = {Text = "Irama."},
  Voice_4913_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_4914_AwakerVoiceContent = {
    Text = "Percobaan yang berani."
  },
  Voice_4914_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_4915_AwakerVoiceContent = {
    Text = "Tidak perlu terlalu terburu-buru… Ada yang bisa saya bantu untuk Anda?"
  },
  Voice_4915_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_4916_AwakerVoiceContent = {Text = "Berani!"},
  Voice_4916_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_4917_AwakerVoiceContent = {
    Text = "(Pertanyaan dengan penuh rasa ingin tahu)"
  },
  Voice_4917_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_4918_AwakerVoiceContent = {
    Text = "Alam adalah anugerah terbesar yang diberikan kepadaku. Apakah menurutmu ini tidak sesuai dengan diriku?"
  },
  Voice_4918_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_4919_AwakerVoiceContent = {
    Text = "Apa yang harus dilakukan?"
  },
  Voice_4919_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_4920_AwakerVoiceContent = {
    Text = "Aku sudah melakukan yang terbaik, kan? Lalu, bayarannya. —— Apa, di dunia ini tidak ada makan siang gratis!"
  },
  Voice_4920_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_4921_AwakerVoiceContent = {Text = "Pergilah!"},
  Voice_4921_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_4922_AwakerVoiceContent = {Text = "Hati-hati!"},
  Voice_4922_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_4923_AwakerVoiceContent = {
    Text = "Benar-benar kemenangan yang luar biasa... Aku akan mengukir momen ini menjadi kenangan abadi."
  },
  Voice_4923_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_4924_AwakerVoiceContent = {
    Text = "Merasakan sumber yang tidak suci... semakin dekat dengan inti diriku... Aaaaaah, biarkan aku merobek dunia ini!"
  },
  Voice_4924_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_4924_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_4925_AwakerVoiceContent = {
    Text = "Kami... sudah siap. Berikan perintah Anda, Penjaga."
  },
  Voice_4925_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_4925_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_4926_AwakerVoiceContent = {
    Text = "Tuan, Anda benar-benar orang yang baik hati. Sayangnya, saya tidak memiliki apa pun untuk membalas kebaikan Anda, saya hanyalah seseorang yang tidak berguna..."
  },
  Voice_4926_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_4926_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_4927_AwakerVoiceContent = {
    Text = "......Jika melangkah lebih jauh, akankah aku bisa sepenuhnya terpisah dari \"mereka\"?"
  },
  Voice_4927_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_4927_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_4928_AwakerVoiceContent = {
    Text = "Eh, aku masih hidup... Apakah Anda benar-benar tidak akan mencuri organ-organ saya atau menangkap saya untuk dijadikan eksperimen?"
  },
  Voice_4928_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_4928_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_4929_AwakerVoiceContent = {
    Text = "Ras asli Kerang memiliki kemampuan untuk memasuki otak makhluk hidup, dan kehendak dari luar yang menyatu dengan saya sangat gentar terhadapnya. Namun, dia sekarang hanyalah jiwa yang malang, terjebak dalam tubuhnya sendiri."
  },
  Voice_4929_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Kerang"
  },
  Voice_4929_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Kerang\", akan terbuka."
  },
  Voice_4930_AwakerVoiceContent = {
    Text = "Segalanya, Aigis sangat menyukainya. Saat makan, ketika semua orang berkumpul mengelilingi meja untuk berdoa; saat Penjaga sedang bertugas di luar, dan semua orang menunggu Anda kembali dengan selamat… udara selalu dipenuhi dengan aroma kebahagiaan… apakah aku benar-benar pantas menikmati semua keindahan ini?"
  },
  Voice_4930_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_4931_AwakerVoiceContent = {
    Text = "Tenggelamlah."
  },
  Voice_4931_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_4932_AwakerVoiceContent = {Text = "Mekarlah."},
  Voice_4932_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_4933_AwakerVoiceContent = {
    Text = "\"Kepercayaan\",\"Kepatuhan\",\"Perbudakan\",\"Cinta\",\"Rasa hormat\"... Modul bahasa sedang dalam proses rekonstruksi dan pembelajaran, mohon bimbingan lebih lanjut dari Penjaga."
  },
  Voice_4933_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_4933_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_4934_AwakerVoiceContent = {
    Text = "Erica saat ini dalam keadaan standby, sistem akan selesai pendinginan dalam satu jam lima belas menit, <Del: jika ingin memulai, lakukan pertukaran dengan jantungmu> apakah ingin melakukan startup darurat? … Memverifikasi izin … Verifikasi izin tertinggi Penjaga selesai. Halo, Penjaga."
  },
  Voice_4934_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_4934_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_4935_AwakerVoiceContent = {
    Text = [[
Tingkat bahaya rata-rata untuk misi penyelidikan adalah 7, rata-rata konsumsi medis adalah 8 botol suplemen alkimia, dan rata-rata waktu penanganan jenazah adalah sepuluh jam. 
 Kesimpulan: Pekerjaan Penjaga sangat berbahaya, harap perhatikan keselamatan selama operasi.]]
  },
  Voice_4935_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_4935_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_4936_AwakerVoiceContent = {
    Text = "Sedang memeriksa arsip pengajar: Erica Rayfield, dosen jurusan Mekanika dan Otomasi Perak, telah meninggal — apakah ini bukan yang ingin kamu cari? Baik, sedang mencari ulang kata kunci \"Erica\"."
  },
  Voice_4936_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_4936_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_4937_AwakerVoiceContent = {
    Text = "Jika Anda ingin mencari informasi, harap sebutkan nama file secara lengkap. Fungsi pencarian kabur untuk sementara tidak tersedia."
  },
  Voice_4937_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_4937_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_4938_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_4938_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_4939_AwakerVoiceContent = {Text = "Ah"},
  Voice_4939_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_4940_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_4940_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_4941_AwakerVoiceContent = {Text = "Ah"},
  Voice_4941_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_4942_AwakerVoiceContent = {
    Text = "Isi ulang selesai, siap untuk meledak."
  },
  Voice_4942_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_4943_AwakerVoiceContent = {
    Text = "Isi ulang selesai, siap untuk meledak."
  },
  Voice_4943_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_4944_AwakerVoiceContent = {
    Text = "Hal kecil seperti ini, lain kali jangan mengganggu waktu istirahat Putri."
  },
  Voice_4944_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_4945_AwakerVoiceContent = {
    Text = "Aku akan melindungimu seperti melindungi Tinct."
  },
  Voice_4945_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_4946_AwakerVoiceContent = {
    Text = "Aku bukan siapa-siapa, hanya setetes kecil di antara banyak pengikut… Selama aku bisa melayani Yang Mulia dan menarik perhatian-Nya, aku bersedia mempersembahkan seluruh energi dan semangatku…"
  },
  Voice_4946_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Masa Lalu"
  },
  Voice_4946_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Tulu\", akan terbuka."
  },
  Voice_4947_AwakerVoiceContent = {Text = "Lihat aku!"},
  Voice_4947_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_4948_AwakerVoiceContent = {Text = "Lihat aku!"},
  Voice_4948_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_4949_AwakerVoiceContent = {
    Text = "...Namun, asalkan mereka tidak mengganggu saya dengan ritual pemujaan yang berlebihan, berbagi ruangan dengan mereka juga bukan masalah."
  },
  Voice_4949_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Pelaut"
  },
  Voice_4949_UnlockDesc = {
    Text = "Setelah mendapatkan salah satu Pembangun \"Miryam\", \"Goliath\", \"Caecus\", \"Sanga\", atau \"Faros\", akan terbuka."
  },
  Voice_4950_AwakerVoiceContent = {
    Text = "Aku benci perasaan gelap itu, seolah-olah bagian dalam diriku terkuras habis. Perasaan tidak puas membuat seluruh tubuhku terasa gatal…"
  },
  Voice_4950_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_4951_AwakerVoiceContent = {
    Text = "Jangan... jangan... jangan... jangan... jangan... jangan menyebutkan..."
  },
  Voice_4951_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_4953_AwakerVoiceContent = {Text = "Ha!"},
  Voice_4953_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_4954_AwakerVoiceContent = {Text = "Ya!"},
  Voice_4954_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_4955_AwakerVoiceContent = {
    Text = "Para sejarawan yang mengklaim bahwa Ranah dewa telah runtuh berbicara dengan nada sombong yang menjengkelkan... namun, tak perlu khawatir, kata-kata tidak akan menjadi penghalang bagi kejayaan Ranah dewa untuk bersinar kembali."
  },
  Voice_4955_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_4956_AwakerVoiceContent = {
    Text = "Sebenarnya… rahasia, aku tidak terlalu puas dengan motor sekarang — bukan berarti aku tidak suka! Hanya saja, aku selalu merasa ada sesuatu yang kurang…"
  },
  Voice_4956_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_4957_AwakerVoiceContent = {Text = "Ha!"},
  Voice_4957_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_4958_AwakerVoiceContent = {Text = "Cincang!"},
  Voice_4958_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua·Manik"
  },
  Voice_4959_AwakerVoiceContent = {
    Text = "Maaf...... Aku tidak ingin seperti ini……"
  },
  Voice_4959_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua·Depresi"
  },
  Voice_4960_AwakerVoiceContent = {
    Text = "(Ekspresi penuh minat dengan gumaman rendah)"
  },
  Voice_4960_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_4961_AwakerVoiceContent = {
    Text = "Pada tahun @1@2, Tuan Ward Phillips, Keralkesh, dan Tawil bersama-sama mendirikan Perguruan tinggi mythag. Setelah melalui perkembangan panjang, akhirnya <Del:Universitas ini sialan> Universitas mythag pun lahir."
  },
  Voice_4961_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_4962_AwakerVoiceContent = {
    Text = "Keadilan, kesetiaan, ketangguhan, dan disiplin. Semua ini telah lama terpatri di dalam hatiku."
  },
  Voice_4962_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_4963_AwakerVoiceContent = {
    Text = "Saya akan menyelesaikan tugas yang Anda berikan dengan baik."
  },
  Voice_4963_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_4964_AwakerVoiceContent = {
    Text = "Orang tua yang tidak bertanggung jawab seperti apa yang akan menamai putrinya dengan Perisai Banshee? Kau bilang anak itu tidak punya orang tua? Hmm… percakapan kita ini, tidak perlu dia ketahui."
  },
  Voice_4964_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Aigis"
  },
  Voice_4964_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Aigis\", akan terbuka."
  },
  Voice_4965_AwakerVoiceContent = {
    Text = "Jika merasa bosan, bagaimana kalau kamu \"menemaniku\" di Labirin? Lagipula, hidupmu yang tanpa harapan dan Labirin tanpa akhir ini, pada dasarnya tidak ada bedanya!"
  },
  Voice_4965_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Labirin"
  },
  Voice_4966_AwakerVoiceContent = {
    Text = "Ketika Boneka ada, efisiensi para Penyelidik secara umum meningkat sebesar 78.312%, namun lebih banyak orang yang jatuh ke dalam suasana hati yang suram. Mengutip salah satu ucapannya: \"Jika beberapa orang bisa menjaga mulut mereka, dunia akan berjalan lebih lancar.\""
  },
  Voice_4966_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Boneka"
  },
  Voice_4966_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Boneka\", akan terbuka."
  },
  Voice_4967_AwakerVoiceContent = {
    Text = "Kedatangan!"
  },
  Voice_4967_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_4968_AwakerVoiceContent = {Text = "Bagaimana?"},
  Voice_4968_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_4969_AwakerVoiceContent = {
    Text = "Bagaimana mungkin ada orang yang tidak suka petualangan? Menyusuri wilayah misterius yang belum pernah dijelajahi, menemukan hal-hal yang tidak diketahui, menenun Cerita mereka sendiri… Betapa mengasyikkannya!"
  },
  Voice_4969_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Petualangan"
  },
  Voice_4970_AwakerVoiceContent = {
    Text = "Salam sejahtera, saya Nymphaea dari Febvre. Anda telah memberikan saya tubuh ini yang dapat bernapas bebas... Apa yang harus saya lakukan untuk membalas budi Anda?"
  },
  Voice_4970_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_4971_AwakerVoiceContent = {
    Text = "Baru saja aku seperti mendengarnya lagi, jeritan dari mereka yang mengaku sebagai tuanku — sungguh indah."
  },
  Voice_4971_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_4971_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_4972_AwakerVoiceContent = {
    Text = "Apakah saya bisa tidak makan sayuran? Meskipun Tinct pernah berkata jangan pilih-pilih makanan, tapi saya tidak suka dengan warna-warninya…"
  },
  Voice_4972_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_4973_AwakerVoiceContent = {
    Text = "Pencipta berfirman: Penderitaan bukanlah Relik-Ku. Tanggung dan selesaikanlah itu, wahai pelaksana-Ku, dirikanlah kerajaan tanpa penderitaan di bumi. Untuk itu, aku bersedia mengorbankan segalanya, termasuk Hidup."
  },
  Voice_4973_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_4973_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_4974_AwakerVoiceContent = {
    Text = "Di hadapan kutukan penghancuran yang meluluhlantakkan segalanya, penderitaan lainnya tampak memudar. Meskipun aku tidak bisa menanggung kutukan itu untuk orang lain, aku akan berusaha sepenuhnya untuk meringankan penderitaan mereka."
  },
  Voice_4974_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_4974_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_4975_AwakerVoiceContent = {
    Text = "Apakah aku sekarang sudah cukup untuk meringankan penderitaan mereka dan menghibur jiwa mereka?"
  },
  Voice_4975_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_4975_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_4976_AwakerVoiceContent = {
    Text = "Dengan demikian, aku dapat menanggung penderitaan segala sesuatu dan membuka jalan bagi semua makhluk hidup menuju tempat tanpa penderitaan."
  },
  Voice_4976_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_4976_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_4977_AwakerVoiceContent = {
    Text = "Kehangatan mendalam dari jiwa ini… Terima kasih atas pemberianmu, Api Pucat. Dengan kekuatan ini, mungkin aku akhirnya bisa memenuhi tanggung jawab sebagai pelaksana tugas dan menyelamatkan lebih banyak orang."
  },
  Voice_4977_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_4977_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_4978_AwakerVoiceContent = {
    Text = "Apakah aku benar-benar bisa makan sebanyak ini?"
  },
  Voice_4978_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_4978_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_4979_AwakerVoiceContent = {
    Text = "Hmph... itu bukan kematian, melainkan masa depanmu, masa depanku, dan masa depan dunia ini."
  },
  Voice_4979_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_4980_AwakerVoiceContent = {
    Text = "Tinct… mendengar nyanyian penuh kesedihan darinya, seseorang akan tak tertahankan ingin menari…"
  },
  Voice_4980_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Tinct"
  },
  Voice_4980_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Tinct\", akan terbuka."
  },
  Voice_4981_AwakerVoiceContent = {
    Text = "Apakah pelatihan duniawi juga bisa membangkitkan nilai darah? Ini benar-benar di luar dugaanku."
  },
  Voice_4981_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_4982_AwakerVoiceContent = {
    Text = "Senjata terasa lebih nyaman digunakan."
  },
  Voice_4982_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_4983_AwakerVoiceContent = {
    Text = "Jangan kira aku akan berterima kasih padamu karena ini, rasaku tidak mengizinkan hal tersebut."
  },
  Voice_4983_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_4984_AwakerVoiceContent = {Text = "Ah iya!"},
  Voice_4984_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_4985_AwakerVoiceContent = {
    Text = "Pria itu... Hei, tunggu sebentar, pertaruhan kita belum selesai, kan?"
  },
  Voice_4985_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Orang Lain"
  },
  Voice_4986_AwakerVoiceContent = {
    Text = "Saya sangat menyukai alat perekam dari akademi. Jika bisa membuat versi portabel yang memberikan pengingat secara real-time tentang hal-hal yang saya lupakan, itu akan sangat membantu…"
  },
  Voice_4986_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_4987_AwakerVoiceContent = {
    Text = "Serangga kecil berkerumun di mana-mana… tidak, mereka bahkan bukan serangga, hanya remah-remah roti, memberikan nutrisi untuk kelahiran-Nya."
  },
  Voice_4987_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_4988_AwakerVoiceContent = {
    Text = "Pasokan ada di sini."
  },
  Voice_4988_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_4989_AwakerVoiceContent = {
    Text = "Pasokan ada di sini."
  },
  Voice_4989_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_4990_AwakerVoiceContent = {
    Text = "Hmm...... lebih kuat, sedikit lebih kuat. Ya, seperti itu......"
  },
  Voice_4990_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_4991_AwakerVoiceContent = {
    Text = "Belum sepenuhnya Bangun, sudah menang dengan mudah."
  },
  Voice_4991_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_4992_AwakerVoiceContent = {
    Text = "Aduh, topinya miring... Hmm, begini sudah pas, ya? Bagus sekali!"
  },
  Voice_4992_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_4992_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_4993_AwakerVoiceContent = {
    Text = [[
"Apakah aku, yang memiliki kemampuan seperti ini, masih benar-benar manusia?" Setiap hari sejak aku mulai menerima pelatihan pertempuran, aku selalu bertanya pada diri sendiri tentang hal itu. Aku mencintai dunia ini, meskipun begitu suram, kotor, dan membosankan, keberadaan kalian membuatnya bersinar seperti berlian di antara debu. 
 Aku pernah sangat takut bahwa dengan meningkatnya kekuatan, posisiku sebagai manusia akan berubah... Sekarang, aku merasa bersyukur memiliki dirimu di sisiku, kekompakan di antara kita mengikatku erat pada dunia manusia. Di masa depan, aku harap kau bisa terus membantu, Penjaga.]]
  },
  Voice_4993_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_4993_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_4994_AwakerVoiceContent = {
    Text = "Ah ah... Kamu memiliki keraguan, itu hal yang wajar. Ini karena pertimbanganku kurang matang. Sebagai pasangan, aku seharusnya menjelaskan semuanya sejak awal. Seperti yang kamu lihat, ada sesuatu yang berbeda pada diriku dibandingkan orang biasa, dan ini mungkin terkait dengan asalku. Tidak mungkin aku tidak penasaran, kan? Namun, bisa memiliki tempat seperti Akademi ini sebagai tempat berlindung adalah keberuntunganku. Jadi, aku memilih untuk tidak membuka tabir takdir."
  },
  Voice_4994_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_4994_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_4995_AwakerVoiceContent = {
    Text = [[
Apa kamu sudah bertemu dengan wanita itu? Pembangun yang mengenakan kerudung putih, dia adalah salah satu fondasi berdirinya universitas ini... 
Tapi jujur, aku tidak suka dia. Sikapnya yang angkuh dan seolah-olah tidak peduli pada seluruh dunia benar-benar membuatku kesal... Ah, apa kamu bilang aku mirip dengannya? Ayo kita pergi ke rumah sakit kampus untuk memeriksa penglihatanmu.]]
  },
  Voice_4995_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_4995_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_4996_AwakerVoiceContent = {
    Text = "Apakah kamu penasaran dengan hubunganku dengan Profesor? Bukan rahasia besar, jadi tidak masalah jika aku memberitahumu. Profesor Dexter adalah ayah angkatku, sedangkan untuk ibu angkat... aku tumbuh di sekolah dan dirawat oleh semua guru di sana. Namun, dibandingkan yang lain, aku lebih dekat dengan Boneka."
  },
  Voice_4996_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_4996_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_4997_AwakerVoiceContent = {
    Text = "Baik itu prosedur di kantor urusan Pembangun, atau tanggal penyediaan masakan India di kantin, semua urusan akademi bisa aku jawab untukmu — jangan khawatir menggangguku. Apakah aku terlihat begitu tidak ramah?"
  },
  Voice_4997_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_4997_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_4998_AwakerVoiceContent = {
    Text = "Cermin Ajaib, siapakah penyihir terhebat di dunia? Aku? Benar sekali!"
  },
  Voice_4998_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_4998_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_4999_AwakerVoiceContent = {
    Text = "Cukup bagus."
  },
  Voice_4999_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5000_AwakerVoiceContent = {
    Text = "Benar-benar bagus~"
  },
  Voice_5000_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5001_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_5001_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5002_AwakerVoiceContent = {
    Text = "Berhasil...? Apakah saya sudah membantu Anda?"
  },
  Voice_5002_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5003_AwakerVoiceContent = {
    Text = "Tidak ada gunanya!"
  },
  Voice_5003_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5004_AwakerVoiceContent = {
    Text = "(Menahan Diri)"
  },
  Voice_5004_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5005_AwakerVoiceContent = {
    Text = "Lihat ke sini!"
  },
  Voice_5005_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  },
  Voice_5006_AwakerVoiceContent = {
    Text = "Mari kita jadikan tempat ini lautan keriuhan untuk semua orang!"
  },
  Voice_5006_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5007_AwakerVoiceContent = {
    Text = "Apakah kamu membutuhkan pengawal untuk menemanimu? Jika tujuanmu adalah keadilan, aku akan membantu."
  },
  Voice_5007_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5008_AwakerVoiceContent = {
    Text = "Tidak dapat terbakar habis."
  },
  Voice_5008_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5009_AwakerVoiceContent = {
    Text = "Tidak dapat terbakar habis."
  },
  Voice_5009_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5010_AwakerVoiceContent = {
    Text = "Apakah kamu menginginkan sebuah pelukan?"
  },
  Voice_5010_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5011_AwakerVoiceContent = {
    Text = "Lihatlah belenggu-belenggu di tubuhku ini —— mereka bukan hiasan, melainkan pengingat. Agar aku tidak melupakan rasa penghianatan dan diinjak-injak."
  },
  Voice_5011_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5012_AwakerVoiceContent = {
    Text = [[
Jika kamu ingin mengetahui sejarah Akademi, saya sarankan kamu pergi ke Arsip untuk mencari informasi. 
 Tolong, termasuk pendahulu Akademi, itu adalah sejarah panjang selama 300 tahun! Apakah kamu benar-benar ingin saya menceritakannya tahun demi tahun?]]
  },
  Voice_5012_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5013_AwakerVoiceContent = {
    Text = "Apakah ini tantangan untukku? Aku siap kapan saja!"
  },
  Voice_5013_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5014_AwakerVoiceContent = {
    Text = "Aequor akan memberikanmu tidur abadi."
  },
  Voice_5014_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5015_AwakerVoiceContent = {
    Text = "Aequor akan memberikanmu tidur abadi."
  },
  Voice_5015_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5016_AwakerVoiceContent = {
    Text = "Tenggelamlah, terbakarlah! Tarian kehancuran!"
  },
  Voice_5016_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5017_AwakerVoiceContent = {
    Text = "Di sini, kuserahkan Tarian Kehancuran Api Hijau Abadi!"
  },
  Voice_5017_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5018_AwakerVoiceContent = {
    Text = "Nona yang seperti mercusuar itu… dalam pelayaran di malam abadi, jika saja aku bisa melihat cahaya terangnya yang begitu menyilaukan, mungkin aku tak akan tersesat…"
  },
  Voice_5018_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Faros"
  },
  Voice_5018_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Faros\", akan dibuka."
  },
  Voice_5019_AwakerVoiceContent = {
    Text = "Sebaiknya kau bisa menunjukkan nilai yang layak untuk membuatku meninggalkan laboratorium, Penjaga baru."
  },
  Voice_5019_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5020_AwakerVoiceContent = {
    Text = "Aku adalah tuan, dan kau adalah pelayan. Apa pun yang aku inginkan, harus segera tersedia. Ada apa? Kau, pelayan ini, masih meminta imbalan? Baiklah baiklah, ini untukmu!"
  },
  Voice_5020_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5021_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_5021_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5022_AwakerVoiceContent = {
    Text = "Rasa malu, bersihkan dengan cara ini!"
  },
  Voice_5022_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5023_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_5023_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5024_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_5024_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5025_AwakerVoiceContent = {
    Text = "Apa yang diberikan adalah apa yang diperoleh."
  },
  Voice_5025_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5026_AwakerVoiceContent = {
    Text = "Apa yang diberikan adalah apa yang diperoleh."
  },
  Voice_5026_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5027_AwakerVoiceContent = {
    Text = "Akan terluka!"
  },
  Voice_5027_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5028_AwakerVoiceContent = {
    Text = "Jangan mendekat!"
  },
  Voice_5028_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5029_AwakerVoiceContent = {
    Text = "Saya suka cahaya bulan keemasan saat purnama. Misterius, lembut, dan ketika angin berhembus, permukaan laut berkilauan dengan cahaya fosfor keemasan, seperti sebuah mimpi yang penuh romansa."
  },
  Voice_5029_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5030_AwakerVoiceContent = {
    Text = "Jika rumah kami tidak mengalami pelarutan, aku dan Tinct tidak akan berpisah… Aku sangat membenci pelarutan, lebih dari kebencian terhadap sayuran."
  },
  Voice_5030_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5031_AwakerVoiceContent = {
    Text = "Bagi saya, tidak ada bedanya apakah di depan terdapat harta karun atau pelabuhan. Misi saya adalah melindungi Anda agar dapat kembali dengan selamat."
  },
  Voice_5031_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5031_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5032_AwakerVoiceContent = {
    Text = "Ikuti jejak burung surga, tujuan ada di depan biru kehijauan."
  },
  Voice_5032_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5032_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5033_AwakerVoiceContent = {
    Text = "Sering kali saya menatap garis cakrawala laut, membayangkan pemandangan di sisi lain horizon—sebuah benua yang jauh, semakin dekat namun tak pernah bisa saya capai. Jika suatu hari nanti tiba, izinkanlah Anda melihatnya bersama saya."
  },
  Voice_5033_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5033_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5034_AwakerVoiceContent = {
    Text = "Berkat kasih sayang Anda, sekarang, bahkan di lautan yang ganas, saya memiliki keberanian untuk menyampaikan berkah tanpa penyesalan kepada Anda."
  },
  Voice_5034_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5034_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5035_AwakerVoiceContent = {
    Text = "Seolah-olah mendengar nyanyian para pendayung, aroma Rumah yang familiar."
  },
  Voice_5035_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5035_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5036_AwakerVoiceContent = {
    Text = "Kamu datang untuk menyelamatkanku, kan? Dari Pembusukan, dari kebencian yang memenuhi pandanganku, dari api hijau abadi…"
  },
  Voice_5036_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5037_AwakerVoiceContent = {
    Text = "Orang yang tidak sopan!"
  },
  Voice_5037_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5038_AwakerVoiceContent = {
    Text = "Saya menganggap ini sebagai surat pernyataan kesetiaan Anda."
  },
  Voice_5038_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5038_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5039_AwakerVoiceContent = {
    Text = "Rasakan hukuman ini!"
  },
  Voice_5039_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5040_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_5040_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5041_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_5041_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5042_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_5042_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5043_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5044_AwakerVoiceContent = {
    Text = "Rasakan kehebatan tikus!"
  },
  Voice_5044_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5045_AwakerVoiceContent = {
    Text = "Rasakan kehebatan tikus!"
  },
  Voice_5045_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5046_AwakerVoiceContent = {
    Text = "Dadu telah dilempar. Jadi, selesaikan dengan cepat!"
  },
  Voice_5046_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5047_AwakerVoiceContent = {
    Text = "Saya akan mencantumkan nama Anda dalam pidato penghargaan. Berkat Anda, kedua kaki yang ternoda oleh darah hitam ini dapat kembali melangkah ke dunia balet yang indah. Mulai sekarang, tolong teruslah menyaksikan saya menari, Penjaga."
  },
  Voice_5047_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5047_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5048_AwakerVoiceContent = {
    Text = "Bagaimanapun kerasnya berusaha, tetap tidak mampu melawan takdir. Namun, cahaya sesaat itu akan membeku menjadi keabadian."
  },
  Voice_5048_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5048_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5049_AwakerVoiceContent = {
    Text = "Apa yang harus kita lakukan dengan para pecundang ini?"
  },
  Voice_5049_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5050_AwakerVoiceContent = {
    Text = "Meskipun tidak ada lagi hasrat di dalam dada, aku akan tetap memerankan angsa itu dengan baik."
  },
  Voice_5050_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5050_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5051_AwakerVoiceContent = {
    Text = "Tutup mata, beritahu saya, apa yang Anda lihat? Cahaya bulan yang tak ternoda, permukaan danau yang tenang…"
  },
  Voice_5051_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5051_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5052_AwakerVoiceContent = {
    Text = "Tuhan kehancuran dan malapetaka, mengapa mengikat aku dan saudara perempuanku dengan nasib ini?"
  },
  Voice_5052_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5053_AwakerVoiceContent = {
    Text = "Terimalah cintaku."
  },
  Voice_5053_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5054_AwakerVoiceContent = {
    Text = "Terimalah cintaku."
  },
  Voice_5054_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5055_AwakerVoiceContent = {
    Text = "Saya merasa jauh lebih nyaman, terima kasih."
  },
  Voice_5055_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5056_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_5056_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5057_AwakerVoiceContent = {
    Text = "Jika memungkinkan, saya ingin memberikan Anda bunga teratai ungu muda sebagai balasan."
  },
  Voice_5057_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5058_AwakerVoiceContent = {
    Text = "Apakah aku juga bisa menjadi lebih kuat?"
  },
  Voice_5058_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5059_AwakerVoiceContent = {
    Text = "Akan mulai…!"
  },
  Voice_5059_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5060_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_5060_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5061_AwakerVoiceContent = {
    Text = [[
Kaki yang terluka ini? Tidak disangka kau juga memperhatikan hal ini. Ini adalah bekas dari medan perang saat aku masih hidup.
Tidak perlu khawatir, setelah menjadi Pembangun, itu tidak akan mengganggu pertempuranku lagi.
Rasa sakit? Tidak, aku tidak pernah memikirkan masalah seperti itu.]]
  },
  Voice_5061_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5061_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5062_AwakerVoiceContent = {
    Text = "Sylvia menanyakan tentang keadaan mental saya, apakah kamu yang memanggilnya? Saya mengakui bahwa rasa sakit pada anggota tubuh yang hilang kadang-kadang muncul. Tapi tidak perlu memperhatikan perasaan saya. Saya adalah pedangmu, adalah senjatamu, selama saya masih bisa berjuang demi keadilan, rasa sakit ini tidak akan memberikan dampak apa pun."
  },
  Voice_5062_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5062_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5063_AwakerVoiceContent = {
    Text = "Pesta teh, pesta teh, ayo adakan pesta teh! Aku mendapat banyak teh dan kue dari Sylvia! Hmm, aku menukarnya dengan Tarian Fortvolken!"
  },
  Voice_5063_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5064_AwakerVoiceContent = {
    Text = "Panggilan untuk diriku sendiri? Apakah Anda begitu peduli dengan urusan pribadiku? Hanya ingin mengobrol saja… Baiklah. \nDi militer, kami tidak membedakan rekan satu tim berdasarkan gender, termasuk kekuatan dan kecepatan, serta tentu saja juga mencakup gaya rambut dan sebutan. Lama kelamaan, aku terbiasa dengan cara penyebutan seperti itu."
  },
  Voice_5064_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5064_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5065_AwakerVoiceContent = {
    Text = "Menarik... Apakah kamu tidak takut bahwa setelah mendapatkan kekuatan, aku akan merobekmu menjadi fragmen dan memberi makan ikan denganmu?"
  },
  Voice_5065_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5066_AwakerVoiceContent = {
    Text = "Untuk menjadi Penjaga yang pantas bagi saya, kamu juga sudah berusaha keras ya!"
  },
  Voice_5066_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5067_AwakerVoiceContent = {
    Text = "Sudah waktunya untuk merobek tenggorokan beberapa orang lemah dan mencobanya."
  },
  Voice_5067_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5068_AwakerVoiceContent = {
    Text = "Tarian itu murni. Kata-kata dapat menimbulkan kesalahpahaman, tetapi gerakan tari tidak."
  },
  Voice_5068_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Tarian"
  },
  Voice_5069_AwakerVoiceContent = {
    Text = "Aku membenci lautan, itu hal yang wajar, bukan? Lautan telah melahap semua yang aku cintai…"
  },
  Voice_5069_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5070_AwakerVoiceContent = {
    Text = "Lupakan atau hilangkan, kali ini kita pasti akan kembali!"
  },
  Voice_5070_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5071_AwakerVoiceContent = {
    Text = "Lupakan atau hilangkan, kali ini kita pasti akan kembali!"
  },
  Voice_5071_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5072_AwakerVoiceContent = {
    Text = "Tolong, tolong jangan mendekat lagi, sangat berbahaya."
  },
  Voice_5072_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5073_AwakerVoiceContent = {
    Text = "Sentuh saja... ini semua adalah bekas luka yang ditinggalkan dari Arena, medali kehormatan seorang pria!"
  },
  Voice_5073_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5074_AwakerVoiceContent = {
    Text = "(Teriakan kesakitan)"
  },
  Voice_5074_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5075_AwakerVoiceContent = {
    Text = "Aduh aduh aduh!"
  },
  Voice_5075_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5076_AwakerVoiceContent = {
    Text = "(Gemuruh kesakitan)"
  },
  Voice_5076_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5077_AwakerVoiceContent = {
    Text = "(Gumaman yang kesal)"
  },
  Voice_5077_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5078_AwakerVoiceContent = {
    Text = "Sepertinya ada sesuatu yang mendidih di dalam tubuh, apakah ini perasaan Mencerahkan?"
  },
  Voice_5078_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5078_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5079_AwakerVoiceContent = {
    Text = "Apakah ini teknologi baru? Anggota tubuh buatan saya terasa jauh lebih ringan."
  },
  Voice_5079_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5079_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5080_AwakerVoiceContent = {
    Text = "Mencium bau asin dari angin laut, jarak ke negaraku sudah tidak jauh lagi."
  },
  Voice_5080_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5080_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5081_AwakerVoiceContent = {
    Text = "Rekan yang telah tiada, bisakah mereka menemukan jalan pulang dengan mengikuti cahaya ini?"
  },
  Voice_5081_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5081_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5082_AwakerVoiceContent = {
    Text = "Saya telah mencari selama ribuan hingga jutaan tahun, tidak masalah menunggu ratusan tahun ini. Sebelum sampai di sisi lainmu, saya akan terus membantu kamu."
  },
  Voice_5082_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5082_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5083_AwakerVoiceContent = {
    Text = "Aku hanya akan bersinar demi tanah airku, kamu…"
  },
  Voice_5083_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5083_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5084_AwakerVoiceContent = {
    Text = "Saya merasakan hembusan angin sepoi-sepoi, yang membawa butiran pasir halus meluncur di permukaan kakiku."
  },
  Voice_5084_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5084_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5085_AwakerVoiceContent = {
    Text = "Kekuatan yang bisa kuberikan untukmu sampai di sini saja, terlalu serakah itu tidak baik, lho?"
  },
  Voice_5085_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5085_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5086_AwakerVoiceContent = {
    Text = "Dengan ini, apa yang Anda harapkan saya balas? Hanya Pertempuran?"
  },
  Voice_5086_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5086_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5087_AwakerVoiceContent = {
    Text = "Kepala cinta, kepala dendam, kepala kebencian, kepala nafsu... Oh, Anda datang lagi?"
  },
  Voice_5087_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5087_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5088_AwakerVoiceContent = {
    Text = "Karena ini adalah transaksi, saya tidak bisa hanya menerima pemberian Anda. Apakah Anda ingin memilih sesuatu di toko ini?"
  },
  Voice_5088_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5088_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_50898_AwakerVoiceContent = {
    Text = "Aku akan mengajarkanmu tentang kebahagiaan, kesenangan, dan perasaan puas saat mencapai puncak… Sebagai imbalannya, kau juga harus jujur menampakkan Keinginanmu, oke?"
  },
  Voice_50898_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Penjaga 2"
  },
  Voice_50899_AwakerVoiceContent = {
    Text = "Aku adalah Pohon Ibu, dan Pohon Ibu juga adalah aku. Getah pohon mengalir deras dalam darahku, dan kehendak pohon berkelana di lautan kesadaranku..."
  },
  Voice_50899_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Pohon Ibu"
  },
  Voice_50899_UnlockDesc = {
    Text = "Setelah menyelesaikan Bab 7 dari \"Operasi\""
  },
  Voice_5089_AwakerVoiceContent = {
    Text = "Bayarlah harga untuk perbuatan Penghianatan!"
  },
  Voice_5089_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_50900_AwakerVoiceContent = {
    Text = "Saat saya mencari tempat tersembunyi di Key Mound tadi, sepertinya saya melihat batu nisan Anda... Apakah mumi saya juga akan dimakamkan di sini? Tidak? Benar-benar memalukan."
  },
  Voice_50900_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Makam Kunci"
  },
  Voice_50900_UnlockDesc = {
    Text = "Setelah menyelesaikan Bab 7 dari \"Operasi\""
  },
  Voice_50901_AwakerVoiceContent = {
    Text = "Saudara serigala... Dia dan N memiliki hubungan yang sulit dijelaskan dengan kata-kata..."
  },
  Voice_50901_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Ryker"
  },
  Voice_50901_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Ryker\", akan terbuka."
  },
  Voice_50902_AwakerVoiceContent = {
    Text = "Mendekatlah padaku, peluk aku, rasakan aku... Jangan lupakan aku."
  },
  Voice_50902_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Penjaga 3"
  },
  Voice_50902_UnlockDesc = {
    Text = "Setelah menyelesaikan Bab 7 dari \"Operasi\""
  },
  Voice_50903_AwakerVoiceContent = {
    Text = "Dia adalah anak yang terlalu rajin dan hati-hati, tentu saja aku tidak akan menyalahkannya~ Jika bukan karena dia, populasi yang bertindak sesuka hati mungkin sudah menghadapi kehancuran dalam perubahan itu, kan?"
  },
  Voice_50903_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Alva"
  },
  Voice_50903_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Alva\", akan terbuka."
  },
  Voice_50904_AwakerVoiceContent = {
    Text = "Dilahirkan di padang pasir, dan kembali ke dalam pasir. Dalam perjalanan singkat ini, Anda harus meninggalkan sesuatu, menabur sesuatu, bukan?"
  },
  Voice_50904_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Gurun"
  },
  Voice_50905_AwakerVoiceContent = {
    Text = "Keinginan semua berasal dari cinta, cinta adalah benih pertama sebelum pohon raksasa menjulang tinggi."
  },
  Voice_50905_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Keinginan"
  },
  Voice_50906_AwakerVoiceContent = {
    Text = "Aduh, seekor tikus kecil yang lucu berlari melewati… Aku pernah mendengar bahwa tikus suka mencuri makanan, sayangnya yang satu ini masih terlalu kecil, masih dalam tahap belajar…"
  },
  Voice_50906_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Jenkin"
  },
  Voice_50906_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Jenkin\", akan terbuka."
  },
  Voice_50907_AwakerVoiceContent = {
    Text = "Mereka melanjutkan daging dan darahku, berubah menjadi sungai yang mengalir deras untuk memperkaya Lermwah… Mulai sekarang, hanya bisa mengandalkanmu untuk melanjutkan keturunanku…"
  },
  Voice_50907_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Aran"
  },
  Voice_50907_UnlockDesc = {
    Text = "Setelah menyelesaikan Bab 7 dari \"Operasi\""
  },
  Voice_50908_AwakerVoiceContent = {
    Text = "Laba-laba... laba-laba. Hmm~ Aku suka laba-laba, mereka langsung mendapatkan kekuatan untuk berjalan begitu lahir dalam jumlah yang banyak. Kemampuan reproduksi dan bertahan hidup mereka benar-benar mengagumkan..."
  },
  Voice_50908_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Agrippa"
  },
  Voice_50908_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Agrippa\", akan terbuka."
  },
  Voice_50909_AwakerVoiceContent = {
    Text = "Semua makhluk hidup yang mengalirkan darah pohon adalah anak-anakku. Kamu, yang telah menelan biji pohon, juga sama, lho?"
  },
  Voice_50909_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Anak Keturunan"
  },
  Voice_50909_UnlockDesc = {
    Text = "Setelah menyelesaikan Bab 7 dari \"Operasi\""
  },
  Voice_5090_AwakerVoiceContent = {
    Text = "Barang yang aku jual? Bisa dibilang lengkap, memenuhi semua Keinginanmu… hanya saja harus membayar harga yang sesuai."
  },
  Voice_5090_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5090_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_50910_AwakerVoiceContent = {
    Text = "Ah, harus kuakui aku kalah olehnya sekali ini... Untungnya, Anda yang dipilih olehnya juga akan meminum air pohon itu, membawa darah dan benihku ke dunia baru, kan?"
  },
  Voice_50910_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Tawil"
  },
  Voice_50910_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Ramona\", akan terbuka."
  },
  Voice_50911_AwakerVoiceContent = {
    Text = "Juga merupakan salah satu dari tiga badan besar, dia adalah monster yang sulit dipahami. Jangan mudah percaya pada kata-kata manisnya, aku akan sangat sedih jika kau melakukannya…"
  },
  Voice_50911_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang N"
  },
  Voice_50912_AwakerVoiceContent = {
    Text = "Jika ada sesuatu yang memiliki kesadaran, maka akan ada keinginan. Bahkan makhluk mekanis pun tidak akan terkecuali, kan?"
  },
  Voice_50912_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Erica"
  },
  Voice_50912_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Erica\", akan terbuka."
  },
  Voice_5091_AwakerVoiceContent = {
    Text = "Bayarlah harga untuk perbuatan Penghianatan!"
  },
  Voice_5091_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5092_AwakerVoiceContent = {
    Text = "Selamat datang di negeri yang luar biasa!"
  },
  Voice_5092_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5093_AwakerVoiceContent = {
    Text = "(Nada rendah)"
  },
  Voice_5093_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5094_AwakerVoiceContent = {
    Text = "Aku sangat memahami penderitaan yang terukir dan panasnya perubahan. Namun, semua ini, di hadapan keindahan abadi, hanyalah seperti debu."
  },
  Voice_5094_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5094_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5095_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5096_AwakerVoiceContent = {
    Text = "Kata-kata yang tak pernah terucap, akan kusampaikan kepadamu melalui karya ini."
  },
  Voice_5096_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5096_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5097_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_5097_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5098_AwakerVoiceContent = {
    Text = "Penguasa yang tertidur berbisik di telingaku, reruntuhan laut dalam terus membentuk di depanku... Apakah pemandangan yang berulang kali muncul dalam mimpiku akhirnya menjadi kenyataan?"
  },
  Voice_5098_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5098_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5099_AwakerVoiceContent = {
    Text = "Terima kasih telah menyiapkan studio untuk saya. Di sini, segalanya disinari oleh sinar matahari. Sepertinya setiap karya, setiap pahat, memancarkan cahaya keemasan. Oh, musim semi itu berwarna emas."
  },
  Voice_5099_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5099_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5100_AwakerVoiceContent = {
    Text = "Meskipun sifatnya berbeda, aku sangat menyukai anak itu. Dia memiliki keberanian yang cukup untuk melepaskan diri dari semua kesulitan dan belenggu. Jika saja aku bisa seberani dan sekuat itu, mungkin aku tidak akan memilih untuk mengakhiri hidup di lautan..."
  },
  Voice_5100_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Murphy"
  },
  Voice_5100_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Murphy\", akan terbuka."
  },
  Voice_5101_AwakerVoiceContent = {
    Text = "Nyonya Merah berbeda dari semua tuan yang pernah aku layani… Bukan, aku tidak membencinya, hanya saja, hanya saja agak sulit untuk menghadapinya…"
  },
  Voice_5101_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Sorel"
  },
  Voice_5101_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Sorel\", akan terbuka."
  },
  Voice_5102_AwakerVoiceContent = {
    Text = "Peluk kegilaan!"
  },
  Voice_5102_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5103_AwakerVoiceContent = {
    Text = "Bertahan hidup dengan susah payah."
  },
  Voice_5103_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5104_AwakerVoiceContent = {
    Text = "Binasakan semuanya!"
  },
  Voice_5104_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5105_AwakerVoiceContent = {
    Text = "Anda tidak perlu melakukan ini..."
  },
  Voice_5105_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5106_AwakerVoiceContent = {
    Text = "Hati adalah jurang tanpa dasar, dan selamanya tidak akan bisa dipenuhi."
  },
  Voice_5106_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5107_AwakerVoiceContent = {
    Text = "Tidak sakit, tapi... tetap sangat berterima kasih."
  },
  Voice_5107_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5108_AwakerVoiceContent = {
    Text = "Ah... Apakah kamu sedang berbicara padaku? Maaf, aku baru saja mengingat pemandangan yang kulihat dari atas tiang kapal. Bisakah kamu mengulangi pertanyaanmu sekali lagi?"
  },
  Voice_5108_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Masa Lalu"
  },
  Voice_5109_AwakerVoiceContent = {
    Text = "Dia adalah tuan, juga ibu."
  },
  Voice_5109_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5110_AwakerVoiceContent = {
    Text = "Kesempatan yang bisa dimanfaatkan!"
  },
  Voice_5110_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5111_AwakerVoiceContent = {
    Text = "Kesempatan yang bisa dimanfaatkan!"
  },
  Voice_5111_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5112_AwakerVoiceContent = {Text = "Siap——"},
  Voice_5112_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5113_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5113_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5114_AwakerVoiceContent = {
    Text = "Sedikit lebih keras~"
  },
  Voice_5114_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5115_AwakerVoiceContent = {
    Text = "Cinta yang membara!"
  },
  Voice_5115_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5116_AwakerVoiceContent = {
    Text = "Fenomena-d... Saya tidak bisa memberitahu Anda terlalu banyak. Namun, kemunculan hal ini jauh lebih awal daripada yang kalian bayangkan."
  },
  Voice_5116_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5118_AwakerVoiceContent = {Text = "Ukh——"},
  Voice_5118_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5119_AwakerVoiceContent = {Text = "Hm."},
  Voice_5119_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5120_AwakerVoiceContent = {
    Text = "Mari berangkat."
  },
  Voice_5120_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5121_AwakerVoiceContent = {
    Text = "Heh, boneka putri kita, menangis lagi ya. Apakah botol susunya tidak pas di mulut, atau lagu nina bobonya tidak enak didengar?"
  },
  Voice_5121_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Murphy"
  },
  Voice_5121_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Murphy\", akan terbuka."
  },
  Voice_5122_AwakerVoiceContent = {
    Text = "Hiks... Aku tidak ingin menghadapi hal-hal itu..."
  },
  Voice_5122_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5123_AwakerVoiceContent = {
    Text = "Sekarang, giliran saya untuk membalas budi Anda."
  },
  Voice_5123_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5124_AwakerVoiceContent = {
    Text = "Sensasi peningkatan kekuatan, seperti api yang membara dan mengikis tulang."
  },
  Voice_5124_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5125_AwakerVoiceContent = {
    Text = "Ah... maaf, tolong jangan bergerak sembarangan!"
  },
  Voice_5125_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5126_AwakerVoiceContent = {
    Text = "Suhu yang terasa begitu dekat..."
  },
  Voice_5126_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5127_AwakerVoiceContent = {
    Text = "Mawar di halaman sedang mekar."
  },
  Voice_5127_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5128_AwakerVoiceContent = {
    Text = "Kerja bagus, apakah masih ada tenaga untuk terus maju?"
  },
  Voice_5128_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5129_AwakerVoiceContent = {
    Text = "Ksatria adalah sesuatu yang tak berwujud; kesetiaan, keberanian, dan kebajikan memberikan bentuk padanya. Senjataku juga demikian; kehendak untuk melindungi memberikan bentuk tombak dan perisai padanya."
  },
  Voice_5129_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Ksatria"
  },
  Voice_5130_AwakerVoiceContent = {
    Text = "Jenkin, Diana, Mike, Tyoog, Cokelat... Wow! Maaf, aku hanya bicara sendiri! Kamu bertanya padaku, kenapa aku menyebut nama-nama ini? Karena Aigis tidak ingin melupakan semua orang..."
  },
  Voice_5130_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Teman"
  },
  Voice_5131_AwakerVoiceContent = {
    Text = "Jangan mendekatiku!"
  },
  Voice_5131_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5132_AwakerVoiceContent = {
    Text = "Benci sekali!"
  },
  Voice_5132_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_5133_AwakerVoiceContent = {Text = "Ah~hei!"},
  Voice_5133_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5134_AwakerVoiceContent = {Text = "Ah~hei!"},
  Voice_5134_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5135_AwakerVoiceContent = {
    Text = "Terima kasih telah memanggil saya. Jika ada kebutuhan untuk memberikan suara, mohon beritahu saya terlebih dahulu."
  },
  Voice_5135_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5137_AwakerVoiceContent = {
    Text = "Itu adalah... cairan hitam kental yang mengalir deras di dalam pembuluh darah, kekuatan ultimat yang menenggelamkan semua erangan! \"Aku\"dilahirkan dari sini, untuk kehancuran! Hahaha!"
  },
  Voice_5137_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5138_AwakerVoiceContent = {
    Text = "Memanggilku keluar, apakah ini untuk bertaruh? ... Apa? Menyelidiki kasus? Jangan deh, terlalu membuang-buang keberuntungan..."
  },
  Voice_5138_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5139_AwakerVoiceContent = {
    Text = "Kuliah teori cukup membosankan. Saat kelas berlangsung, aku selalu diam-diam membaca catatan Penyelidikan di bagian belakang kelas. Hal ini hanya kukatakan padamu, jangan sampai Boneka tahu."
  },
  Voice_5139_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5140_AwakerVoiceContent = {
    Text = "Rasakan akibat buruknya!"
  },
  Voice_5140_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5141_AwakerVoiceContent = {
    Text = "Rasakan akibat buruknya!"
  },
  Voice_5141_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5142_AwakerVoiceContent = {
    Text = "Aku tidak pernah menyalahkan Juliette. Dia hanyalah korban dari penderitaan hitam, tetapi... sepertinya dia tidak mau mendengarku. Bisakah kau menyampaikan ini kepadanya, utusan?"
  },
  Voice_5142_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Juliette"
  },
  Voice_5142_UnlockDesc = {
    Text = "Suara belum diimplementasikan"
  },
  Voice_5143_AwakerVoiceContent = {Text = "Perlahan."},
  Voice_5143_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5144_AwakerVoiceContent = {Text = "Hm."},
  Voice_5144_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5145_AwakerVoiceContent = {
    Text = "Hei! Berhenti menyentuhnya, kau membuat semuanya berantakan! … Ah, sudahlah, aku ini orangnya pemaaf."
  },
  Voice_5145_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5146_AwakerVoiceContent = {
    Text = "Tidak perlu!"
  },
  Voice_5146_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5147_AwakerVoiceContent = {Text = "Ck!"},
  Voice_5147_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5148_AwakerVoiceContent = {
    Text = "Sejak hari kamu membangunkanku dari kegelapan, aku yakin bahwa kamu bisa menyelamatkan segala sesuatu dari keputusasaan yang disebut Pelarutan, dan membawanya ke tanah suci yang Murni. Aku menantikan kedatangan hari itu."
  },
  Voice_5148_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Penjaga·I"
  },
  Voice_5149_AwakerVoiceContent = {
    Text = "Mencium bau... darah."
  },
  Voice_5149_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5150_AwakerVoiceContent = {
    Text = "Di mana targetnya? Sebagai balasan karena membangunkan aku, aku akan menyelesaikan pihak itu untukmu."
  },
  Voice_5150_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5151_AwakerVoiceContent = {
    Text = "Topi saya sudah tidak sabar!"
  },
  Voice_5151_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5152_AwakerVoiceContent = {
    Text = "Raga ini seharusnya tidak bergetar untuk keberadaan selain Dia… tapi suhu tubuhmu…"
  },
  Voice_5152_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5153_AwakerVoiceContent = {
    Text = "Apa, ingin bertarung?"
  },
  Voice_5153_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5154_AwakerVoiceContent = {
    Text = "Pengotor..."
  },
  Voice_5154_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5155_AwakerVoiceContent = {
    Text = "Tidak bisa dimaafkan."
  },
  Voice_5155_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5156_AwakerVoiceContent = {
    Text = "Erica saat ini beroperasi dengan baik, terhubung dengan peralatan listrik di dalam Universitas Mythag. Apakah saya perlu menyalakan lampu di asrama?"
  },
  Voice_5156_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Erica"
  },
  Voice_5157_AwakerVoiceContent = {
    Text = "Selanjutnya, saatnya makan, hehe…"
  },
  Voice_5157_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5159_AwakerVoiceContent = {
    Text = "Jangan biarkan wanita yang memakai topi lebar berwarna ungu mendekati panggung! Tanpa alasan apa pun, kecuali jika kamu tidak ingin melihat substansi abu-abu lengket mengalir dari topi itu, jangan biarkan dia mendekat!"
  },
  Voice_5159_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Daffdell"
  },
  Voice_5159_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Narsis\", akan terbuka."
  },
  Voice_5160_AwakerVoiceContent = {
    Text = "Apa kamu selalu seperti ini? Menyerahkan punggungmu kepada semua orang dan memberikan kepercayaan begitu saja? Terlalu polos."
  },
  Voice_5160_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5161_AwakerVoiceContent = {
    Text = "Kebencian mungkin bisa mereda, namun tidak akan pernah sepenuhnya hilang."
  },
  Voice_5161_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5162_AwakerVoiceContent = {
    Text = "Pembangun? Hmm… memang begitu, waktu Bangun terbaik adalah pukul tujuh! Besok pagi jam tujuh kita pergi ke pantai untuk mengumpulkan kerang, ya!"
  },
  Voice_5162_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pembangun"
  },
  Voice_5163_AwakerVoiceContent = {
    Text = "Menganugerahkanmu kehidupan abadi!"
  },
  Voice_5163_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5164_AwakerVoiceContent = {Text = "Haa!"},
  Voice_5164_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5165_AwakerVoiceContent = {Text = "Haa!"},
  Voice_5165_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5166_AwakerVoiceContent = {
    Text = "Maaf, jika kehadiran Aigis di sini mengganggu Anda, saya akan segera pergi!"
  },
  Voice_5166_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5166_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5167_AwakerVoiceContent = {
    Text = "Anda memberi saya tempat berlindung, saya sangat bersyukur. Namun, mohon maaf, saya sudah tidak layak berdiri di atas panggung lagi."
  },
  Voice_5167_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5168_AwakerVoiceContent = {
    Text = "Terima kasih telah mengizinkan saya tinggal di sini. Jika ada yang bisa saya lakukan untuk membalas budi, Aigis siap melakukan apa saja. Apakah Anda membutuhkan secangkir teh?"
  },
  Voice_5168_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5168_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5169_AwakerVoiceContent = {
    Text = "Karena terasa hangat, aku tidak tega pergi. Saat sendirian, rasanya sangat gelap, dingin, dan menakutkan..."
  },
  Voice_5169_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5169_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5170_AwakerVoiceContent = {
    Text = "Aigis... apakah aku benar-benar bisa kembali ke keramaian? Aku belum siap, tapi kamu sudah menerimaku... kalau begitu, tolong bantu aku ke depannya juga... Penjaga."
  },
  Voice_5170_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5170_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5171_AwakerVoiceContent = {
    Text = "Aku ingat, aku ingat...! Darah kotor manusia telah memenjarakanku... Aku, aku gagal bertransformasi! Bagaimana bisa, bagaimana aku... Insangku? Kenapa mereka tidak bergerak?! Mengapa!"
  },
  Voice_5171_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5172_AwakerVoiceContent = {
    Text = "Saya suka makan gurita panggang, gurita rebus, gurita goreng... beberapa orang mengira saya dengan sengaja menista Dewa, maaf, karena gurita itu sangat lezat, hahahaha!"
  },
  Voice_5172_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5173_AwakerVoiceContent = {
    Text = "Cacing. Bintang-bintang. Aku adalah...... Uvhash! Bunuh...... biarkan aku membunuh!"
  },
  Voice_5173_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5173_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5174_AwakerVoiceContent = {
    Text = "Tubuh berwarna merah tua, tentakel yang berdenyut, mulut yang terus membuka dan menutup... Bagus, bagus! Aku sudah tidak sabar untuk merobek tenggorokan seseorang!"
  },
  Voice_5174_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5174_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5175_AwakerVoiceContent = {
    Text = "Hahahaha, inilah sensasi yang kumaksud! Berikan aku lebih banyak lagi... dua kali lipat, tidak, sepuluh kali lipat dosisnya!"
  },
  Voice_5175_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5175_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5176_AwakerVoiceContent = {
    Text = "Aku akan terus bertahan."
  },
  Voice_5176_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5177_AwakerVoiceContent = {
    Text = "Perasaan ajaib ini... tidak buruk. Lebih baik daripada belladonna dari Penyihir Levant."
  },
  Voice_5177_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5177_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5178_AwakerVoiceContent = {
    Text = "Teman? Hmph... Tidak membutuhkan teman. Aku tidak akan terbebani dua kali oleh hal yang sama."
  },
  Voice_5178_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5178_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5179_AwakerVoiceContent = {
    Text = "Aku akan bekerja sama denganmu, hanya karena kau telah menunjukkan kekuatan yang sepadan denganku. Jangan lupa, kontrak ini akan berakhir saat kekuatanmu melemah. Pada saat itu, aku tidak akan ragu untuk memenggal kepalamu."
  },
  Voice_5179_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5179_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5180_AwakerVoiceContent = {
    Text = "Saya melihat di matamu... kilauan cahaya, itu adalah api ambisi dan keinginan. Makhluk fana, kenali dirimu sendiri! Kita adalah sesama!"
  },
  Voice_5180_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5180_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5181_AwakerVoiceContent = {
    Text = [[
Kau tahu albatros, kan? Mereka tak pernah menganggap manusia serius, melainkan mengepakkan sayap sekuat tenaga, menyambut tantangan badai. Namun begitu dibuang ke daratan, jatuh di tengah cemooh dan makian, sayap besar yang menjuntai itu justru menjadi penghalang yang menyedihkan.
Cerita ini tak punya makna mendalam, hanya saja bersamamu terasa santai, jadi aku mengobrol saja.]]
  },
  Voice_5181_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5181_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5182_AwakerVoiceContent = {
    Text = [[
Mungkin, zaman memang sudah berubah. Saat ini, orang yang lemah pun bisa melampaui karang dan menguasai ombak, menjadi Raja Langit Biru. 
Manusia biasa, aku menantikan hari ketika kau menulis ulang sejarah. Pada saat itu, aku akan merasa sangat terhormat menjadi pedang raksasa di tanganmu!]]
  },
  Voice_5182_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5182_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5183_AwakerVoiceContent = {
    Text = "Tingkat konversi terlalu rendah. Besok, laporkan ke kantor saya untuk belajar ulang."
  },
  Voice_5183_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5184_AwakerVoiceContent = {
    Text = "Apakah kamu sudah bertemu dengan Boneka lainnya? Apa yang disebut \"kebenaran dunia\", ternyata bisa mengubah Boneka yang begitu tenang dan rasional menjadi seseorang yang sama sekali berbeda… Pada akhirnya, apakah kamu dan aku juga akan berubah menjadi seperti itu?"
  },
  Voice_5184_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang @2"
  },
  Voice_5184_UnlockDesc = {
    Text = "Dapatkan Pembangun @2 untuk membuka kunci"
  },
  Voice_5185_AwakerVoiceContent = {
    Text = "Tuan... saya memerlukan perintah, tolong berikan saya perintah."
  },
  Voice_5185_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5186_AwakerVoiceContent = {
    Text = "Performa unit telah ditingkatkan."
  },
  Voice_5186_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5189_AwakerVoiceContent = {Text = "Hmm hmmm!"},
  Voice_5189_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5190_AwakerVoiceContent = {
    Text = "Lebih banyak teman!"
  },
  Voice_5190_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5191_AwakerVoiceContent = {
    Text = "Lebih banyak teman!"
  },
  Voice_5191_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5192_AwakerVoiceContent = {
    Text = "Maaf, aku tidak bisa meninggalkan buaian... Kalau seperti ini, sepertinya akan menghalangi pandangan orang lain, jadi aku lebih baik tetap di bagian belakang kelas saja."
  },
  Voice_5192_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5193_AwakerVoiceContent = {
    Text = "Apa! Karpet dari Konstantinopel, teh hitam Ceylon, churros dari Andalucía… tidak ada satu pun yang berhasil dibeli?! Hu… wanita itu selalu bisa mendapatkan barang-barang ini dengan mudah, kupikir itu hal yang biasa…"
  },
  Voice_5193_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5194_AwakerVoiceContent = {
    Text = "Masih jauh dari sosok awal saya."
  },
  Voice_5194_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5194_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5195_AwakerVoiceContent = {
    Text = "Begitu mendesak, bagi seseorang seberbakat Anda, agak kasar."
  },
  Voice_5195_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5196_AwakerVoiceContent = {
    Text = "Tidak peduli seberapa banyak ditingkatkan, penampilan binatang ini tidak akan berubah. Pada akhirnya, itu hanyalah manifestasi dari Kekuatan-ku saja."
  },
  Voice_5196_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5196_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5197_AwakerVoiceContent = {
    Text = "Rasanya seperti kembali ke lautan kekacauan lagi, lumayan."
  },
  Voice_5197_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5197_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5198_AwakerVoiceContent = {
    Text = "Melihat usaha keras yang kamu lakukan, aku dengan berat hati mengakui kamu sebagai rekan perjalanan."
  },
  Voice_5198_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5198_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5199_AwakerVoiceContent = {
    Text = "Seperti memecahkan dinding labirin, hancurkan penghalang kekuatan."
  },
  Voice_5199_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5199_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5200_AwakerVoiceContent = {
    Text = "Makanan tidak boleh disobek sembarangan, dan kursi kantin juga tidak boleh dihancurkan… Baiklah, Lily tidak akan melakukannya lagi lain kali."
  },
  Voice_5200_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5200_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5201_AwakerVoiceContent = {
    Text = "Bolehkah saya memanggil Anda, Ibu?"
  },
  Voice_5201_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5201_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5202_AwakerVoiceContent = {
    Text = [[
Ada perintah apa, Tuan?
"Jangan berjalan di luar dengan membawa mereka, semua orang akan takut."?
Lily mengerti, Lily akan segera menyembunyikannya.]]
  },
  Voice_5202_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5202_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5203_AwakerVoiceContent = {
    Text = "Ternyata, beginilah rasanya menjadi Pembangun."
  },
  Voice_5203_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5203_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5204_AwakerVoiceContent = {
    Text = "Ibu, bolehkah aku tidur di sampingmu? Saat sendirian, aku sering bermimpi yang gelap gulita. Tangan dan kaki Lily terlepas, rasanya sangat sakit..."
  },
  Voice_5204_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5204_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5205_AwakerVoiceContent = {
    Text = "Ah! Terima kasih atas perhatian Tuan, Karen hanyalah seorang pelayan rendah hati..."
  },
  Voice_5205_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5205_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5206_AwakerVoiceContent = {Text = "Hmmm~"},
  Voice_5206_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5207_AwakerVoiceContent = {
    Text = "Saya perlu mengumpulkan beberapa bahan ukiran, sebaiknya yang cukup segar."
  },
  Voice_5207_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5208_AwakerVoiceContent = {
    Text = "Harap tenang."
  },
  Voice_5208_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5209_AwakerVoiceContent = {
    Text = "Orang yang keras kepala, melakukan hal-hal yang sia-sia."
  },
  Voice_5209_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5209_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5210_AwakerVoiceContent = {
    Text = "Melihat situasi ini, aku lebih atau kurang bisa memahami maksudmu. Tidak apa-apa, lanjutkan saja."
  },
  Voice_5210_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5210_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5211_AwakerVoiceContent = {
    Text = "Yu melihat tekadmu. Sebelum jatuh ke dalam tidur panjang sekali lagi, Yu akan menjadi saksi bagimu, menyaksikan perbuatan besar anak manusia yang melawan takdir. Namun untuk saat ini, aku membutuhkan sedikit waktu untuk beristirahat."
  },
  Voice_5211_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5211_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5212_AwakerVoiceContent = {
    Text = "Mengikuti takdir, bukankah itu baik? Mengapa harus melawan kehendak nasib."
  },
  Voice_5212_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5212_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5213_AwakerVoiceContent = {
    Text = "Untuk mewujudkan keinginanmu, kamu ternyata bisa berkorban sebanyak ini…"
  },
  Voice_5213_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5213_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5214_AwakerVoiceContent = {
    Text = "Hah? Apakah kalian tidak merasa terganggu? Jangan ganggu aku lagi dengan urusan orang itu! …Ah, terserah kalian saja, anggap saja sebagai pengisi waktu."
  },
  Voice_5214_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5215_AwakerVoiceContent = {
    Text = "Pelarutan… cairan hitam kotor itu sering mengganggu mimpi Yu, sangat menjengkelkan."
  },
  Voice_5215_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5216_AwakerVoiceContent = {
    Text = "Kekuasaan adalah pedang bermata dua, bagaimana mungkin aku tidak mengerti itu... hanya saja aku menyadarinya terlalu terlambat, sangat terlambat. Begitu aku melepaskannya, mereka akan menerkam dan merobekku menjadi fragmen... Jika sejak awal aku bisa sesadar dirimu, mungkin aku tidak akan berakhir dengan cara yang begitu tragis. Eh, eh? Kau bilang, aku bisa mengadakan salon di ruang istirahat nanti?! Ini benar-benar... Selain melayanimu secara pribadi, bagaimana lagi aku bisa membalas budi padamu..."
  },
  Voice_5216_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5216_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5217_AwakerVoiceContent = {
    Text = "Anda benar-benar tamu yang sulit diajak bicara. Bagaimana seharusnya saya memperlakukan Anda agar Anda bersedia melepaskan hak istimewa di tangan Anda? Kekuasaan hanya akan menimbulkan masalah, prinsip sederhana seperti itu pasti sudah Anda pahami, bukan?"
  },
  Voice_5217_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5217_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5218_AwakerVoiceContent = {
    Text = "Sebelum salon dimulai, apakah Anda ingin mendengar sebuah cerita? Cerita tentang seorang gadis desa yang berhasil meraih mahkota kekuasaan… Haruskah saya mulai dari mana? Dari saat dia dipaksa oleh orang tuanya menikahi seorang pria tua renta, atau Anda lebih tertarik pada bagian ketika dia bersinar di taman kaum bangsawan?"
  },
  Voice_5218_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5218_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5219_AwakerVoiceContent = {
    Text = "Dulu, para tamu memanggil saya dengan sebutan \"Nyonya Merah\". Tentu saja, Anda juga bisa memanggil saya \"Sorel\", karena Anda adalah tamu paling istimewa saya…"
  },
  Voice_5219_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5219_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5220_AwakerVoiceContent = {
    Text = "Sebagai tuan rumah salon, menjadikan setiap tamu puas adalah tanggung jawab saya."
  },
  Voice_5220_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5220_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5221_AwakerVoiceContent = {Text = "Ah"},
  Voice_5221_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5222_AwakerVoiceContent = {
    Text = "Tuan? Apakah ada masalah dengan cara berdiri saya?"
  },
  Voice_5222_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5223_AwakerVoiceContent = {Text = "Aduh!"},
  Voice_5223_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5224_AwakerVoiceContent = {Text = "Kesialan~"},
  Voice_5224_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5225_AwakerVoiceContent = {Text = "Ah"},
  Voice_5225_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5226_AwakerVoiceContent = {
    Text = "Saya ingat perasaan ini, saat yang penuh kemuliaan akan segera tiba…"
  },
  Voice_5226_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5226_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5227_AwakerVoiceContent = {
    Text = "Meskipun bekas insang masih belum muncul, aku sudah tidak merasa cemas karenanya. Membran sayap ini akan berubah menjadi perisai yang melindungimu, Penjaga."
  },
  Voice_5227_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5227_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5228_AwakerVoiceContent = {
    Text = "Kamu... memang lebih sabar dibandingkan manusia lainnya... ternyata kamu mencurahkan begitu banyak sumber daya untukku, apakah kamu benar-benar... tidak membenciku?"
  },
  Voice_5228_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5228_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5229_AwakerVoiceContent = {
    Text = "Apa? Ritual sudah selesai, tapi kenapa aku masih belum bisa menumbuhkan insang? Transformasi gagal lagi! Sial! Sial! Sial!"
  },
  Voice_5229_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5229_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5230_AwakerVoiceContent = {
    Text = "Suara itu memanggilku lagi… suara merdu dari kedalaman Aequor!"
  },
  Voice_5230_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5230_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5231_AwakerVoiceContent = {
    Text = "Tebak——salah——lagi——"
  },
  Voice_5231_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5232_AwakerVoiceContent = {
    Text = "Dari Sanga, pemahat dari Cité, dengan ini mempersembahkan pahat. Anda mungkin memiliki banyak kekurangan, namun tetap layak untuk dipahat."
  },
  Voice_5232_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5238_AwakerVoiceContent = {
    Text = "Anak-anak yang nakal, berkumpulah~"
  },
  Voice_5238_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5239_AwakerVoiceContent = {
    Text = "Seni sejati tidak memerlukan penjelasan."
  },
  Voice_5239_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5240_AwakerVoiceContent = {
    Text = "Seni sejati tidak memerlukan penjelasan."
  },
  Voice_5240_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5241_AwakerVoiceContent = {
    Text = "Aurita, bisa membantu?"
  },
  Voice_5241_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5242_AwakerVoiceContent = {
    Text = "Tiupkan terompet!"
  },
  Voice_5242_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5243_AwakerVoiceContent = {
    Text = "Dengan segala biaya!"
  },
  Voice_5243_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5244_AwakerVoiceContent = {
    Text = "Sensasi mandi di bawah sinar matahari... ternyata begitu lembut, hingga membuat seseorang ingin menangis."
  },
  Voice_5244_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5244_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5245_AwakerVoiceContent = {
    Text = "Sebagai ungkapan rasa terima kasih... saya akan membangun sebuah Altar rahasia untuk Anda di kedalaman penderitaan saya."
  },
  Voice_5245_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5245_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5246_AwakerVoiceContent = {
    Text = "Caro kakak dan Tubuhku semakin menyatu dengan erat..."
  },
  Voice_5246_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5246_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5247_AwakerVoiceContent = {
    Text = "Saya lebih tangguh daripada yang kamu bayangkan. Jadi, saat menggunakan saya, kamu bisa lebih keras lagi, tidak perlu ragu-ragu."
  },
  Voice_5247_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5247_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5248_AwakerVoiceContent = {
    Text = "Apakah ini hanya ilusi saya? Dahaga akan darah tampaknya berkurang sedikit."
  },
  Voice_5248_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5248_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5249_AwakerVoiceContent = {
    Text = "Sejak sebelum resmi masuk sekolah, aku sudah menantikan kedatanganmu. Sepertinya sekarang kita bekerja sama dengan cukup baik, kan? Partner."
  },
  Voice_5249_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5250_AwakerVoiceContent = {
    Text = "Sungguh tidak pantas."
  },
  Voice_5250_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5251_AwakerVoiceContent = {Text = "Yaa!"},
  Voice_5251_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5252_AwakerVoiceContent = {Text = "Hahahaha!"},
  Voice_5252_AwakerVoiceTitle = {
    Text = "Pukulan·Mania"
  },
  Voice_5253_AwakerVoiceContent = {Text = "Hmm..."},
  Voice_5253_AwakerVoiceTitle = {
    Text = "Pukulan·Depresi"
  },
  Voice_5254_AwakerVoiceContent = {
    Text = "Lakukan apa pun untuk memberikan kerusakan pada saya!"
  },
  Voice_5254_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5255_AwakerVoiceContent = {
    Text = "Aigis sangat takut. Bukan, bukan takut kepada kalian semua, melainkan takut bahwa dirinya akan membawa kembali rasa takut dan kesedihan kepada kalian."
  },
  Voice_5255_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5256_AwakerVoiceContent = {
    Text = "Buku dongeng di era ini jauh lebih menarik daripada yang aku baca dulu! Ah. Ah! Tuan, jangan salah paham! Aku sudah melewati usia mendengarkan cerita sebelum tidur!"
  },
  Voice_5256_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5257_AwakerVoiceContent = {
    Text = "Lakukan apa pun untuk memberikan kerusakan pada saya!"
  },
  Voice_5257_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5258_AwakerVoiceContent = {
    Text = "Hu... Apakah Aigis tidak merepotkan semuanya?"
  },
  Voice_5258_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5259_AwakerVoiceContent = {
    Text = "Kau selalu memegang kepercayaan yang penuh tawa itu, berada di sampingku... baiklah, mungkin, menggunakan itu untukmu bukanlah hal yang buruk. Tapi ingat: aku tidak bisa mentolerir pengkhianatan apapun, terutama dari dirimu."
  },
  Voice_5259_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5259_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5260_AwakerVoiceContent = {
    Text = "Aku hanya menyesal saat itu tidak memaku tulang mereka di tiang dan menggantungnya di tembok! Setiap orang yang melakukan penghianatan terhadapku, menginjak-injakku, dan mempermalukanku, tidak akan kulewatkan satu pun!"
  },
  Voice_5260_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5260_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5261_AwakerVoiceContent = {
    Text = "Benar, aku juga pernah merendahkan diri di depan mereka, itu tidak bisa disangkal. Mereka memanfaatkan kebodohanku, dan akhirnya aku membuat mereka membayar mahal untuk itu."
  },
  Voice_5261_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5261_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5262_AwakerVoiceContent = {
    Text = "Apakah kau pikir beberapa kata manis dan perlakuan baik selama beberapa hari bisa membuatku secara sukarela mengenakan belenggu lagi dan menjadi mainanmu?"
  },
  Voice_5262_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5262_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5263_AwakerVoiceContent = {
    Text = "Semua orang yang mencoba menguasai saya, memanfaatkan saya, akhirnya saya sendiri yang mengirim mereka ke alam baka — saya tidak keberatan untuk mengantarmu juga."
  },
  Voice_5263_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5263_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5264_AwakerVoiceContent = {
    Text = "Ah... maaf, tolong jangan bergerak sembarangan!"
  },
  Voice_5264_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5265_AwakerVoiceContent = {
    Text = "Jangan sentuh aku!"
  },
  Voice_5265_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5266_AwakerVoiceContent = {
    Text = "Tidak hormat!"
  },
  Voice_5266_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5267_AwakerVoiceContent = {
    Text = "Menyerahlah… Selamat datang di negara kesenangan dan mimpi."
  },
  Voice_5267_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5268_AwakerVoiceContent = {
    Text = "Inilah kota yang hilang, tempat ribuan jiwa yang telah meninggal berkeliaran tanpa tujuan."
  },
  Voice_5268_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5269_AwakerVoiceContent = {
    Text = "Aigis akan berjuang keras!"
  },
  Voice_5269_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5270_AwakerVoiceContent = {
    Text = "Ehm... aku tidak bisa mengendalikan diri saat menyerap kehidupan, jadi tolong jangan masukkan tanganmu ke dalam buaian. Melakukannya akan membuatmu sakit."
  },
  Voice_5270_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5271_AwakerVoiceContent = {
    Text = "Harap semoga saat kita melakukan percakapan ini, dia tidak mengalami kesalahan. Wahai asisten yang manis namun menjengkelkan, sudah tidak ada laboratorium cadangan untuknya hancurkan lagi."
  },
  Voice_5271_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Erica"
  },
  Voice_5271_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Erica\", akan terbuka."
  },
  Voice_5272_AwakerVoiceContent = {
    Text = "Lengan, lengan yang menjengkelkan! Mereka selalu menarik rambutku. Aku bahkan tidak bisa mengendalikan tanganku sendiri, aku benar-benar orang yang tak berguna... mungkin lebih baik..."
  },
  Voice_5272_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Diri Sendiri"
  },
  Voice_5274_AwakerVoiceContent = {
    Text = "Terima kasih atas bimbinganmu, akhirnya aku memahami pilihan Pingsan. Aku menganggap semua ini sudah semestinya, tak disangka memberikan beban psikologis yang begitu besar baginya. Mulai sekarang, aku akan mencoba hidup untuk diriku sendiri…"
  },
  Voice_5274_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5274_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5275_AwakerVoiceContent = {
    Text = "Dalam waktu yang sangat lama, hanya ada saya dan Pingsan... Namun, sekarang saya memiliki orang penting baru... Penjaga, izinkan saya menarik kembali perkataan saya sebelumnya. Anda berbeda dari mereka. Anda tidak hanya memperhatikan suara dan gaun saya, tetapi juga melihat saya. Oleh karena itu, saya juga akan melihat Anda."
  },
  Voice_5275_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5275_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5276_AwakerVoiceContent = {
    Text = "Bintang-bintang dalam mimpi yang terlelap, pergi ke tempat seharusnya, menunjuk ke arah Ranah Dewa!"
  },
  Voice_5276_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5277_AwakerVoiceContent = {
    Text = "Kenapa aku selalu mengenakan gaun ini kapan pun dan di mana pun? Dengan begini, aku bisa menyanyi untukmu kapan saja."
  },
  Voice_5277_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5277_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5278_AwakerVoiceContent = {
    Text = "Apa yang ingin kulakukan sendiri? …… Maaf, aku tidak mengerti apa yang kamu maksud …… Sebenarnya, Pingsan juga sudah bertanya kepadaku berkali-kali tentang hal ini, tapi aku hanya berharap dia bisa sembuh secepatnya ……"
  },
  Voice_5278_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5278_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5279_AwakerVoiceContent = {
    Text = "Di planet tandus, belas kasihan dari para tokoh besar memberi kami bersaudara dua sumber daya untuk bertahan hidup. Pada akhirnya, mereka juga memberiku kesempatan untuk melarikan diri dari planet tandus, meskipun hanya untuk satu orang. Mereka semua adalah penyelamatku, sama seperti Penjaga yang memberiku tempat berlindung, Anda."
  },
  Voice_5279_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5279_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5280_AwakerVoiceContent = {
    Text = "Kamu adalah orang baik yang memberi saya tempat tinggal, Aigis akan mendengarkanmu. Seandainya Aigis bisa sedikit lebih berguna lagi…"
  },
  Voice_5280_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5281_AwakerVoiceContent = {
    Text = "Jangan lupa untuk menyiapkan tempat. Tempat yang kamu pesan tidak akan lebih kecil daripada yang di Elworth, kan?"
  },
  Voice_5281_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5281_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5282_AwakerVoiceContent = {
    Text = "Bagus sekali, Karen sekarang lebih bersemangat, bisa membersihkan dua puluh kamar sehari!"
  },
  Voice_5282_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5282_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5283_AwakerVoiceContent = {
    Text = "Ini adalah musik yang sama tuanya dengan danau, milik \"kita\". Tuan, ayo menari bersama! Sebelum suara Karen diambil oleh \"Dia\"..."
  },
  Voice_5283_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5283_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5284_AwakerVoiceContent = {
    Text = "Tuan! Suara Karen... menghilang... tolong..."
  },
  Voice_5284_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5284_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5285_AwakerVoiceContent = {
    Text = "Penglihatan Karen meningkat...... Tuan, apakah kamu lupa menyisir rambut lagi!"
  },
  Voice_5285_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5285_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5286_AwakerVoiceContent = {
    Text = "Meskipun menjadi lebih kuat, Karen sama sekali tidak ingin membalas dendam. Karen hanya ingin bernyanyi! Menari! Mengadakan pesta!"
  },
  Voice_5286_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5286_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5287_AwakerVoiceContent = {
    Text = "Agar dapat tetap ada di dunia setelah segalanya mengalami kehancuran, aku telah membagikan jiwa dan darahku kepada terlalu banyak orang. Kekuatan yang kumiliki sekarang jauh berbeda dibandingkan saat pertama kali menerima kehendak ini…"
  },
  Voice_5287_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Masa Lalu"
  },
  Voice_5288_AwakerVoiceContent = {
    Text = "Jangan harap bisa menemukanku di gedung perkuliahan. Tempat ini penuh dengan bau apek dari para akademisi tua yang membosankan, aku tidak tahan di sini walau hanya sehari."
  },
  Voice_5288_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5289_AwakerVoiceContent = {
    Text = "Jangan kabur."
  },
  Voice_5289_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_5290_AwakerVoiceContent = {
    Text = "Negara asalku mempercayai \"Dewa\", dan sesuai dengan itu, Raja yang aku ikuti secara alami adalah seorang \"orang yang dapat berkomunikasi dengan dewa\"."
  },
  Voice_5290_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Kerajaan Abadi"
  },
  Voice_5291_AwakerVoiceContent = {
    Text = "Di sini Anda memiliki banyak bakat, layak untuk sebuah salon yang meriah... Tenang saja, pada saatnya nanti, undangan pasti akan dikirimkan oleh pelayan saya ke tangan Anda."
  },
  Voice_5291_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5292_AwakerVoiceContent = {Text = "Ayo!"},
  Voice_5292_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5293_AwakerVoiceContent = {
    Text = "Jika ada lebih banyak teman..."
  },
  Voice_5293_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5294_AwakerVoiceContent = {
    Text = "Aku dan dia itu berbeda, dia hanya memberikan ketegangan dan ketakutan yang penuh permusuhan, sedangkan aku memberikan keintiman kulit, rasa manis yang menyengat, serta cinta, lho?"
  },
  Voice_5294_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Wanda"
  },
  Voice_5294_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Wanda\", akan terbuka."
  },
  Voice_5295_AwakerVoiceContent = {
    Text = "Jangan berpikir semuanya akan berlalu begitu saja! Penghinaan yang aku alami kali ini, akan kubalas satu per satu!"
  },
  Voice_5295_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5296_AwakerVoiceContent = {
    Text = "Tanganmu sama hangatnya dengan jiwamu, api pucat, aku… berterima kasih atas sentuhanmu."
  },
  Voice_5296_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5297_AwakerVoiceContent = {
    Text = "Apa salahnya bermain bridge di kelas? Ada meja, ada orang, saya membawa kartu, itu berarti \"permainan dimulai\"!"
  },
  Voice_5297_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5299_AwakerVoiceContent = {Text = "Jangan..."},
  Voice_5299_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5300_AwakerVoiceContent = {
    Text = "Menatap Jurang!"
  },
  Voice_5300_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5301_AwakerVoiceContent = {
    Text = "Menatap Jurang!"
  },
  Voice_5301_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5302_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_5302_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5303_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_5303_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5304_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_5304_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5305_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_5305_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5306_AwakerVoiceContent = {
    Text = "Mandikan diri dalam cahaya ilahi!"
  },
  Voice_5306_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5307_AwakerVoiceContent = {Text = "Hei!"},
  Voice_5307_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5308_AwakerVoiceContent = {
    Text = "Jiwa yang lemah berkumpul bersama, selain berisik, apa lagi yang bisa mereka lakukan, huh…"
  },
  Voice_5308_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5311_AwakerVoiceContent = {
    Text = "Perang selalu membawa penderitaan, dan menahan siksaan adalah kewajiban seorang prajurit. Meskipun kehilangan kedua tangan, kehilangan kedua kaki, kehilangan segalanya, aku tetap akan berjuang untukmu dan demi keadilan dunia."
  },
  Voice_5311_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5312_AwakerVoiceContent = {
    Text = "Apakah ini persembahan yang kau berikan kepada-Nya?"
  },
  Voice_5312_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5313_AwakerVoiceContent = {
    Text = "Apakah kau pikir ini bisa mengubah masa depan?"
  },
  Voice_5313_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5314_AwakerVoiceContent = {
    Text = "Kehidupan-Nya... berkembang di dalam perutku..."
  },
  Voice_5314_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5315_AwakerVoiceContent = {
    Text = "Huh, berarti kau tahu diri."
  },
  Voice_5315_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5316_AwakerVoiceContent = {
    Text = "Memberi upeti kepada tuan adalah hal yang wajar."
  },
  Voice_5316_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5317_AwakerVoiceContent = {
    Text = "Caramu berusaha menyenangkan aku, tampak cukup menggemaskan."
  },
  Voice_5317_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5318_AwakerVoiceContent = {
    Text = "Brownies, puding karamel, kue sahara, mousse cokelat, kue kering… Harus ada di setiap meja!"
  },
  Voice_5318_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5318_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5319_AwakerVoiceContent = {
    Text = "Tolong periksa, apakah gaun saya sudah dirapikan? Tidak boleh ada kerutan, tidak boleh ada yang longgar… Ada apa? Apakah ada sesuatu yang tidak memuaskanmu?"
  },
  Voice_5319_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5319_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5320_AwakerVoiceContent = {
    Text = "Selamat datang di upacara pencerahan terakhir saya! Segalanya telah didesain dengan cermat oleh saya. Tentu saja, Penjaga juga memiliki sedikit kontribusi..."
  },
  Voice_5320_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5320_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5321_AwakerVoiceContent = {
    Text = "Meja dan kursi harus dihias dengan renda yang sesuai dengan kepribadian saya, tanaman dalam pot harus menggunakan tanaman gantung berwarna merah… Segera siapkan!"
  },
  Voice_5321_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5321_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5322_AwakerVoiceContent = {
    Text = "Pergi dan atur tamu! Kenapa hal sekecil ini saja tidak bisa dilakukan?"
  },
  Voice_5322_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5322_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5323_AwakerVoiceContent = {
    Text = "Tidak ada jalan keluar!"
  },
  Voice_5323_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5324_AwakerVoiceContent = {
    Text = "Tidak ada jalan keluar!"
  },
  Voice_5324_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5325_AwakerVoiceContent = {
    Text = "Aku akan berusaha keras! Untuk tidak mengecewakan harapan Tuan."
  },
  Voice_5325_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5325_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5326_AwakerVoiceContent = {
    Text = "Saya cukup menyukai wanita itu, kita memiliki... apa ya... oh iya, bahasa yang sama!"
  },
  Voice_5326_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Wanda"
  },
  Voice_5326_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Wanda\", akan terbuka."
  },
  Voice_5327_AwakerVoiceContent = {
    Text = "Orang yang kasar!"
  },
  Voice_5327_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5328_AwakerVoiceContent = {
    Text = "Orang yang kasar!"
  },
  Voice_5328_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5329_AwakerVoiceContent = {
    Text = "Menjadi reruntuhan."
  },
  Voice_5329_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_5330_AwakerVoiceContent = {Text = "Hancurkan."},
  Voice_5330_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5331_AwakerVoiceContent = {
    Text = "Menembus batas realitas!"
  },
  Voice_5331_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5332_AwakerVoiceContent = {
    Text = "Apakah kamu berencana untuk menyeberangi lautan dalam waktu dekat? Bisakah kamu memenuhi permintaan tak masuk akal ini dan mengizinkan aku ikut bersamamu? Selama aku bisa sampai di laut lepas…"
  },
  Voice_5332_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5332_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5333_AwakerVoiceContent = {
    Text = "Jika kamu masih percaya padaku, izinkan aku menjadi penanda jalan dalam perjalanan ini. Namun, meskipun pekerjaan semudah ini, aku pernah gagal melaksanakannya…"
  },
  Voice_5333_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5333_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5334_AwakerVoiceContent = {
    Text = "Tidak ingin pergi ke laut lepas? Biarkan aku melihat peta laut saat ini... 47 derajat 9 menit lintang selatan, 126 derajat 43 menit bujur barat. Di sinilah tempatnya."
  },
  Voice_5334_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5334_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5335_AwakerVoiceContent = {
    Text = "Diriku di masa lalu telah memicu banyak bencana, bahkan hampir menyebabkan kehancuran beberapa peradaban... Aku... Jika dikatakan itu bukan disengaja, apakah sudah terlambat?"
  },
  Voice_5335_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5335_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5336_AwakerVoiceContent = {
    Text = "Aku adalah penjaga gerbang Kerajaan Abadi, yang menunjukkan arah bagi mereka yang kembali ke Rumah. Betapa menggelikan, seseorang dengan tanggung jawab seperti ini bisa melupakan tempat asalnya sendiri…\nApakah kau… akan menjadi mercusuar bagiku?"
  },
  Voice_5336_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5336_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5337_AwakerVoiceContent = {
    Text = "Gugus bintang."
  },
  Voice_5337_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5338_AwakerVoiceContent = {Text = "Ah"},
  Voice_5338_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5339_AwakerVoiceContent = {
    Text = "Kabut tebal."
  },
  Voice_5339_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5340_AwakerVoiceContent = {Text = "Hmph."},
  Voice_5340_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5341_AwakerVoiceContent = {
    Text = "Kebanyakan pelindung yang bertugas mengawal orang lain tidak ada bedanya, kecuali wanita itu. Jika memungkinkan, tolong atur rute lain untuk saya."
  },
  Voice_5341_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Miryam"
  },
  Voice_5341_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Miryam\", akan terbuka."
  },
  Voice_5342_AwakerVoiceContent = {Text = "Ah"},
  Voice_5342_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5343_AwakerVoiceContent = {
    Text = "Tidak apa-apa."
  },
  Voice_5343_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5344_AwakerVoiceContent = {
    Text = "Pindahkan tanganmu."
  },
  Voice_5344_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5345_AwakerVoiceContent = {
    Text = "Sebelum aku kembali ke istana bawah laut, dengan terpaksa ku pinjamkan sedikit Kekuatan Aequor kepada manusia lemah sepertimu, hanya itu saja."
  },
  Voice_5345_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5346_AwakerVoiceContent = {Text = "Ayo!"},
  Voice_5346_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5347_AwakerVoiceContent = {
    Text = "Suka? Aku suka rasa sakit, suka kulit yang memerah dan panas, suka erangan yang bercampur antara kenikmatan dan penderitaan. Bukankah rasa sakit adalah Keinginan yang paling primitif dan nyata?"
  },
  Voice_5347_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5348_AwakerVoiceContent = {
    Text = "Bergabunglah dengan Aurita!"
  },
  Voice_5348_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5349_AwakerVoiceContent = {
    Text = "Bergabunglah dengan Aurita!"
  },
  Voice_5349_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5350_AwakerVoiceContent = {
    Text = "Kakak perempuan itu selalu menatap saya dengan tatapan tajam. Namun, entah mengapa, saya selalu merasakan kehangatan yang akrab. Apakah karena dia mirip ibu?"
  },
  Voice_5350_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Helot"
  },
  Voice_5350_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Helot\", akan terbuka."
  },
  Voice_5351_AwakerVoiceContent = {
    Text = "Pikiran menjadi lebih lincah, rasanya cukup menyenangkan."
  },
  Voice_5351_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5351_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5352_AwakerVoiceContent = {
    Text = "Dibandingkan dengan tugas lapangan, aku lebih suka bekerja di laboratorium—jangan bilang kau mengira alat bantu itu diambil dari laut?"
  },
  Voice_5352_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5352_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5353_AwakerVoiceContent = {
    Text = "Baik itu sekrup maupun paku, tentu saja semakin banyak akan lebih baik."
  },
  Voice_5353_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5354_AwakerVoiceContent = {
    Text = "Tubuh sudah sulit menahan kekuatan ini, tapi sekarang bukan waktunya untuk mengganti boneka. Kenapa berdiri diam di sana? Bantu aku memegang kaki ini, aku perlu menyesuaikannya."
  },
  Voice_5354_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5354_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5355_AwakerVoiceContent = {
    Text = "Beban yang membimbing cahaya dapat membuat orang suci yang murni terjatuh. Jika kau merasa lelah, Api pucat-ku, tolong beritahu aku. Aku pasti akan melakukan yang terbaik untuk meringankan kesedihanmu dan berbagi beban dari ribuan berkah ini."
  },
  Voice_5355_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Kelelahan"
  },
  Voice_5356_AwakerVoiceContent = {
    Text = "Pengakuannya adalah alasan keberadaanku sebagai seorang kesatria."
  },
  Voice_5356_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5356_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5357_AwakerVoiceContent = {
    Text = "Mandikan diri dalam cahaya redup dewa, apakah ini kekuatan ilahi yang dimiliki oleh Tuan-ku? Begitu megah, begitu suci."
  },
  Voice_5357_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5357_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5358_AwakerVoiceContent = {
    Text = "Pintu para dewa sudah berada dalam jarak yang sangat dekat."
  },
  Voice_5358_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5358_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5359_AwakerVoiceContent = {
    Text = "Semakin terang, semakin jelas…"
  },
  Voice_5359_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5359_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5360_AwakerVoiceContent = {
    Text = "Ternyata bisa kembali menjadi manusia utuh meski sebagai Pembangun… Aku sudah mendengarnya, suara suci yang dimainkan oleh Ranah dewa untukku…"
  },
  Voice_5360_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5360_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5361_AwakerVoiceContent = {
    Text = "Dia akan membawa saya ke Gereja, memberikan saya tempat beristirahat dengan damai…"
  },
  Voice_5361_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5361_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5362_AwakerVoiceContent = {
    Text = "Tenang saja, kami semua sangat berguna. Saya bisa menjahit dan membersihkan, yang lainnya ahli dalam pertempuran, dan ada juga yang lainnya..."
  },
  Voice_5362_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5363_AwakerVoiceContent = {
    Text = "Aku benci hal-hal yang terang dan lembut. Kelembutan seperti cermin, semua keburukan, keserakahan, dan kerapuhan tidak bisa bersembunyi di hadapannya."
  },
  Voice_5363_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5364_AwakerVoiceContent = {
    Text = "Ingin menyentuh Cokelat? Aku tidak bisa memutuskan. Kau harus bertanya langsung padanya."
  },
  Voice_5364_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5365_AwakerVoiceContent = {
    Text = "Ingin membuatku senang? Kalau begitu, berlututlah, rentangkan lehermu, dan pastikan tetap diam sampai aku menghisapmu kering."
  },
  Voice_5365_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5366_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5366_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5367_AwakerVoiceContent = {
    Text = "Semalam saya bermimpi, itu adalah titik awal perjalananku mengembara di antara bintang-bintang."
  },
  Voice_5367_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5367_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5368_AwakerVoiceContent = {
    Text = "Apakah Aigis bisa membantu?"
  },
  Voice_5368_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5368_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5369_AwakerVoiceContent = {
    Text = "Bisa merasakannya~"
  },
  Voice_5369_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5370_AwakerVoiceContent = {Text = "Tak!"},
  Voice_5370_AwakerVoiceTitle = {
    Text = "Keterampilan·Tiga"
  },
  Voice_5371_AwakerVoiceContent = {Text = "Hati-hati!"},
  Voice_5371_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5372_AwakerVoiceContent = {Text = "Mundur."},
  Voice_5372_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5373_AwakerVoiceContent = {
    Text = "Tidak ada yang akan menerima kerusakan… di dunia ini…"
  },
  Voice_5373_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5374_AwakerVoiceContent = {Text = "(Manja)"},
  Voice_5374_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5375_AwakerVoiceContent = {
    Text = "Izinkan aku mendirikan sebuah Altar untuk Tuhanku. Ini adalah patung suci yang diukir dengan kekuatan seorang pengikut yang saleh, dan tidak akan membawa kutukan apapun padamu."
  },
  Voice_5375_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5376_AwakerVoiceContent = {
    Text = "Hanya sedikit..."
  },
  Voice_5376_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5377_AwakerVoiceContent = {
    Text = "Kunci pas saya belum siap!"
  },
  Voice_5377_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5378_AwakerVoiceContent = {
    Text = "Kimia, fisika, aplikasi inti perak... apakah di era ini sudah tidak perlu mempelajari tujuh keterampilan ksatria? Begitu ya. Kalau begitu, tolong Tuan juga mengaturkan kursus yang sesuai untukku!"
  },
  Voice_5378_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5379_AwakerVoiceContent = {
    Text = "Aurita sudah pernah bepergian! Bukan terbawa ombak, melainkan bepergian dengan karavan!"
  },
  Voice_5379_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5379_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5380_AwakerVoiceContent = {
    Text = "Ubur-ubur mercusuar, ubur-ubur mahkota, dan ubur-ubur bunga persik semuanya bergerak dalam kelompok. Tentu saja, Aurita juga! Aurita harus bersama semua orang!"
  },
  Voice_5380_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5380_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5381_AwakerVoiceContent = {
    Text = "Hal-hal sebelumnya? Tidak terlalu ingat... tapi Aurita ingat pernah bekerja di akuarium! Upah harian adalah 2 Pensh!"
  },
  Voice_5381_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5381_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5382_AwakerVoiceContent = {
    Text = "Rahasia ya, sebenarnya Aurita adalah Alan, Trans… Eh, pokoknya Aurita itu orang laut! Selama Aurita nurut, makan sayur yang banyak, dan berteman dengan banyak orang, Yatus dan lainnya pasti akan menyambut Aurita!"
  },
  Voice_5382_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5382_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5383_AwakerVoiceContent = {
    Text = "Rumah Aurita, teman-teman di akuarium, dan ubur-ubur kesayangannya, semuanya menghilang… Apakah kamu juga akan menghilang? Tidakkah kamu bisa terus bermain dengan Aurita selamanya?"
  },
  Voice_5383_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5383_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5384_AwakerVoiceContent = {
    Text = "Menang? Bagus sekali…"
  },
  Voice_5384_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5387_AwakerVoiceContent = {
    Text = "Untuk perdamaian."
  },
  Voice_5387_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5388_AwakerVoiceContent = {
    Text = "Demi keadilan."
  },
  Voice_5388_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5389_AwakerVoiceContent = {
    Text = "Aku tahu kau berada di dalam tubuhku!"
  },
  Voice_5389_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5390_AwakerVoiceContent = {
    Text = "Manusia, dewa palsu, Pembangun, bahkan Pelarutan… semua yang ada di dunia ini akan menjadi batu fondasi bagi saya untuk membangun kembali tanah air abadi."
  },
  Voice_5390_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5391_AwakerVoiceContent = {
    Text = "Bangunlah, bangunlah, aku tahu kau berada di dalam tubuhku!"
  },
  Voice_5391_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5392_AwakerVoiceContent = {
    Text = "Uvhash... Dia agak seperti kakak laki-lakiku, selalu mengingatkanku pada hari-hari yang suram, dingin, dan tanpa tidur."
  },
  Voice_5392_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Uvhash"
  },
  Voice_5392_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Uvhash\", akan terbuka."
  },
  Voice_5393_AwakerVoiceContent = {
    Text = "Hubungan kita seperti Sherlock Holmes dan Watson, kan? Apakah Anda memperhatikan majalah populer akhir-akhir ini?"
  },
  Voice_5393_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5394_AwakerVoiceContent = {
    Text = "Merangkaklah di hadapan keindahan."
  },
  Voice_5394_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5395_AwakerVoiceContent = {
    Text = "Merangkaklah di hadapan keindahan."
  },
  Voice_5395_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5396_AwakerVoiceContent = {
    Text = "Jijik, kata sifat, berarti merasa tidak suka terhadap sesuatu. Benci, kata kerja, berarti perasaan tidak suka dan menghindari sesuatu. Rasa jijik, kata benda, perasaan tidak suka, <Del:Tidak suka tertekan membiarkan aku merusak membiarkan aku merusak membiarkan aku> —— maaf, saya khawatir saya tidak mengerti apa itu \"benci\"."
  },
  Voice_5396_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5397_AwakerVoiceContent = {
    Text = "Pada akhirnya tetap saja…"
  },
  Voice_5397_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5398_AwakerVoiceContent = {
    Text = "Menjadi semakin berbeda."
  },
  Voice_5398_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5399_AwakerVoiceContent = {
    Text = "Ingatlah namaku, Goliath. Nama ini ditakdirkan untuk menginjak-injak sejarah manusia yang tak berarti."
  },
  Voice_5399_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5400_AwakerVoiceContent = {
    Text = "Jangan memiliki keraguan."
  },
  Voice_5400_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5401_AwakerVoiceContent = {
    Text = "Semoga kamu tidak mengecewakan potensimu dan harapan umat manusia, Penjaga."
  },
  Voice_5401_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5402_AwakerVoiceContent = {Text = "Overload."},
  Voice_5402_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5403_AwakerVoiceContent = {
    Text = "Beroperasi secara supercepat."
  },
  Voice_5403_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5404_AwakerVoiceContent = {
    Text = "Hmm, foto yang kamu temukan di dompet? Ah, itu aku yang dulu. Penampilanku sekarang dibentuk oleh teman judi dan juga lawanku."
  },
  Voice_5404_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5404_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5405_AwakerVoiceContent = {
    Text = "Tepat sekali —— mau bertaruh? Jika kamu menang, aku akan memberitahumu sebuah Rahasia lho? \nNamun, hati-hati, jangan sampai Alva menangkapmu~"
  },
  Voice_5405_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5405_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5406_AwakerVoiceContent = {
    Text = "Apakah kamu sangat peduli dengan bulu ini? Maukah kamu menyentuhnya? Jangan khawatir, aku sangat terbuka!"
  },
  Voice_5406_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5406_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5407_AwakerVoiceContent = {
    Text = "Tentu saja ada juga keuntungannya, bukankah aku bertemu dengan Watson-ku? Dibandingkan dengan hal ini, hidup, mati, dan penampilan tidak begitu penting, kan?"
  },
  Voice_5407_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5407_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5408_AwakerVoiceContent = {
    Text = "Apakah kamu bertanya apakah aku menyesal? Sama sekali tidak. Jika hidup selalu berjalan mulus, bukankah itu akan terlalu membosankan, kan?"
  },
  Voice_5408_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5408_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5409_AwakerVoiceContent = {
    Text = "Di masa saya, sekolah adalah tempat untuk melatih para pejuang, dan tampaknya sekarang juga masih sama."
  },
  Voice_5409_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5410_AwakerVoiceContent = {
    Text = "Mason... tidak, seperti ini sudah cukup baik, setidaknya kita bisa bersama lagi, \"24\"."
  },
  Voice_5410_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang\"24\""
  },
  Voice_5410_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"24\", akan terbuka."
  },
  Voice_5411_AwakerVoiceContent = {
    Text = "Aku sudah melakukan yang terbaik, kan? Lalu, bayarannya. —— Apa, di dunia ini tidak ada makan siang gratis!"
  },
  Voice_5411_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5412_AwakerVoiceContent = {
    Text = "Saya berasal dari Cité. Di sana, semua orang ingin menjadi aktor, tak seorang pun rela hanya menjadi penonton. Faktanya, kita semua hanyalah catatan kaki yang menyedihkan di kota ini."
  },
  Voice_5412_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Masa Lalu"
  },
  Voice_5413_AwakerVoiceContent = {
    Text = "Pernahkah Anda melihat ukiran batu kuno? Menyatu dengan gunung, mengandalkan alam untuk meloloskan diri dari keausan waktu, betapa indahnya Relik ini… sayangnya, masih belum cukup…"
  },
  Voice_5413_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5414_AwakerVoiceContent = {
    Text = "Burung merpati, belum kembali.."
  },
  Voice_5414_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5415_AwakerVoiceContent = {Text = "Mundur!"},
  Voice_5415_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_5416_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5416_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5417_AwakerVoiceContent = {
    Text = "Jalankan perintah!"
  },
  Voice_5417_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5418_AwakerVoiceContent = {Text = "Bodoh"},
  Voice_5418_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5419_AwakerVoiceContent = {
    Text = "……Eh? Apakah kamu memanggilku? Aku sedang memperbaiki motor dan tidak mendengarnya……Ngomong-ngomong, orang asing yang baik hati, apakah kamu melihat kunci pas saya?"
  },
  Voice_5419_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5419_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5420_AwakerVoiceContent = {
    Text = "Memoriku selalu kabur, aku hanya bisa fokus pada hal-hal yang sedang terjadi saat ini. Namun, aku akan berusaha mengukir namamu dalam memoriku... siapa namamu lagi?"
  },
  Voice_5420_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5420_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5421_AwakerVoiceContent = {
    Text = "Kamu tampak agak familiar, tapi aku tidak bisa mengingat namamu... Apakah kamu asistenku? Kalau begitu, bisakah kamu membawakan tujuh mur untukku?"
  },
  Voice_5421_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5421_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5422_AwakerVoiceContent = {
    Text = "Aku mengukir namamu di Fatamorgana. Suatu hari, ketika kita pergi berpetualang bersama, aku tidak akan lupa bagaimana memanggilmu."
  },
  Voice_5422_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5422_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5423_AwakerVoiceContent = {
    Text = "Sangat familiar, sangat familiar. Pasti ada sesuatu yang terjadi di antara kita! Beri aku waktu sebentar untuk mengingat... Ah, itu kamu, Penjaga!"
  },
  Voice_5423_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5423_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5424_AwakerVoiceContent = {
    Text = "Kamu benar-benar anak yang tidak terbuka. Untungnya, saya memiliki cukup waktu dan kesabaran untuk menunggumu…"
  },
  Voice_5424_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5425_AwakerVoiceContent = {
    Text = "\"Semua bahagia,\" bukan begitu?"
  },
  Voice_5425_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5426_AwakerVoiceContent = {
    Text = "Mendapatkan kepala yang cukup bagus... Meskipun tidak bisa dibandingkan dengan koleksi terbaikku, perjalanan mencari koleksi baru selalu mengasyikkan. Ajak aku lagi lain kali."
  },
  Voice_5426_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5427_AwakerVoiceContent = {Text = "Hmm..."},
  Voice_5427_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5428_AwakerVoiceContent = {
    Text = "Maid yang profesional akan membantu tuannya membersihkan segalanya, termasuk orang jahat~"
  },
  Voice_5428_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5429_AwakerVoiceContent = {
    Text = "Mungkin sekarang kita bisa dianggap sebagai kawan seperjuangan, ya. Jika suatu hari kamu terlantar di jalanan, aku tidak akan membiarkanmu bertahan hidup dengan memakan sampah."
  },
  Voice_5429_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5430_AwakerVoiceContent = {
    Text = "Berkembanglah, bertumbuhlah, bibit kecilku."
  },
  Voice_5430_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5431_AwakerVoiceContent = {
    Text = "Berkembanglah, bertumbuhlah, bibit kecilku."
  },
  Voice_5431_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5432_AwakerVoiceContent = {
    Text = "Rasanya keberuntungan lemparan dadu meningkat sedikit!"
  },
  Voice_5432_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5433_AwakerVoiceContent = {
    Text = "Wah! Keberuntunganmu sangat bagus!"
  },
  Voice_5433_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5434_AwakerVoiceContent = {Text = "Beruntung~"},
  Voice_5434_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5435_AwakerVoiceContent = {
    Text = "Jangan mendekati aku."
  },
  Voice_5435_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5436_AwakerVoiceContent = {
    Text = "Jangan mendekati aku."
  },
  Voice_5436_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5437_AwakerVoiceContent = {
    Text = "Saya harus menuduh Anda, Penjaga. Anda terlalu lembut kepada saya, ini membuat saya sangat gelisah — bagi saya, hanya rasa sakit fisik yang nyata dan abadi."
  },
  Voice_5437_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5438_AwakerVoiceContent = {
    Text = "Bagus, pelayananmu cukup memuaskan."
  },
  Voice_5438_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5439_AwakerVoiceContent = {
    Text = "Masih jauh dari cukup."
  },
  Voice_5439_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5440_AwakerVoiceContent = {
    Text = "Katakan, hadiah apa yang kamu inginkan?"
  },
  Voice_5440_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5441_AwakerVoiceContent = {
    Text = "Aduh! Kotoran dan kekacauan ini tersebar di mana-mana... Tidak ada tempat untuk meletakkan kakiku. Kalau begitu, persembahkanlah punggungmu yang lembut, wahai manusia."
  },
  Voice_5441_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5442_AwakerVoiceContent = {
    Text = "Akhirnya… ketemu!"
  },
  Voice_5442_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5443_AwakerVoiceContent = {
    Text = "Bahkan bulu Brown pun menjadi lebih halus."
  },
  Voice_5443_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5443_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5444_AwakerVoiceContent = {
    Text = "Menjadi petugas keamanan mungkin agak berat, tetapi semua pekerjaan mengantar surat bisa kuserahkan padaku."
  },
  Voice_5444_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5444_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5445_AwakerVoiceContent = {
    Text = "Lihat saja ekspresimu saat menghadapi Cokelat. \n … Hehe, Tuan Cokelat malam ini akan memakan jari kaki penakut. Siapa yang akan menjadi korban malang itu, ya?"
  },
  Voice_5445_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5445_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5446_AwakerVoiceContent = {
    Text = "Tidak tahu apakah bisa bertambah tinggi."
  },
  Voice_5446_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5446_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5447_AwakerVoiceContent = {
    Text = "Apa sudah siap bekerja? Baiklah baiklah, Cokelat, semangat!"
  },
  Voice_5447_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5447_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5448_AwakerVoiceContent = {
    Text = "Agrippa? Maaf, aku telah mengantarkan banyak orang dengan tanganku sendiri. Kebanyakan dari mereka tampak kabur, tanpa ada lawan yang pantas diingat."
  },
  Voice_5448_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Agrippa"
  },
  Voice_5448_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Agrippa\", akan terbuka."
  },
  Voice_5449_AwakerVoiceContent = {
    Text = "Kru yang berbahaya... bukan, hanya dari sudut pandang keselamatan pelayaran..."
  },
  Voice_5449_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Faros"
  },
  Voice_5449_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Faros\", akan dibuka."
  },
  Voice_5450_AwakerVoiceContent = {
    Text = "Jangan mendekat!"
  },
  Voice_5450_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5451_AwakerVoiceContent = {
    Text = "Harap berhati-hati!"
  },
  Voice_5451_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5452_AwakerVoiceContent = {
    Text = "Instruksi Anda sudah saya selesaikan... Ah, saya sudah membuatnya berantakan lagi, kan?"
  },
  Voice_5452_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5453_AwakerVoiceContent = {
    Text = "Ah, ini adalah bagian yang kubutuhkan, terima kasih! … Eh? Apakah aku menyuruhmu mencarinya? Aku sama sekali tidak ingat. Mungkin kamu salah paham?"
  },
  Voice_5453_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Komponen"
  },
  Voice_5454_AwakerVoiceContent = {
    Text = "Inspirasi, terus menerus"
  },
  Voice_5454_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5455_AwakerVoiceContent = {
    Text = "Selera bagus."
  },
  Voice_5455_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5456_AwakerVoiceContent = {
    Text = "Anda telah memilih pahat yang paling sesuai untuk saya."
  },
  Voice_5456_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5457_AwakerVoiceContent = {
    Text = "Aku benci kehilangan kendali. Namun, keberadaanmu membuatku menyadari bahwa sedikit kehilangan kendali yang halus juga bisa membawa kesenangan yang unik."
  },
  Voice_5457_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5458_AwakerVoiceContent = {
    Text = "Apakah sudah sedikit lebih besar?"
  },
  Voice_5458_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5459_AwakerVoiceContent = {
    Text = "Maaf, aku sulit mengembangkan tubuh…"
  },
  Voice_5459_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_54601_AwakerVoiceContent = {
    Text = "Dengan cara ini, kita bisa mengenal dunia."
  },
  Voice_54601_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_54602_AwakerVoiceContent = {
    Text = "Dengan cara ini, kita bisa mengenal dunia."
  },
  Voice_54602_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_54605_AwakerVoiceContent = {
    Text = "Ini Pesananmu!"
  },
  Voice_54605_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_54606_AwakerVoiceContent = {
    Text = "Ini Pesananmu!"
  },
  Voice_54606_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_54607_AwakerVoiceContent = {
    Text = "Selanjutnya, lakukan perhitungan terhadap esensi dunia!"
  },
  Voice_54607_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_54608_AwakerVoiceContent = {
    Text = "Selanjutnya, lakukan perhitungan terhadap esensi dunia!"
  },
  Voice_54608_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_54609_AwakerVoiceContent = {
    Text = "Mengorbankan diri! Kembalikan tuanku ——"
  },
  Voice_54609_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_5460_AwakerVoiceContent = {
    Text = "Te-terima kasih banyak atas jamuan ini..."
  },
  Voice_5460_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_54610_AwakerVoiceContent = {
    Text = "Mengorbankan diri! Kembalikan tuanku ——"
  },
  Voice_54610_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_54611_AwakerVoiceContent = {
    Text = "Jangan mengganggu aku!"
  },
  Voice_54611_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_54612_AwakerVoiceContent = {
    Text = "Di dalam Jurang… akan ada cahaya keadilan."
  },
  Voice_54612_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_54613_AwakerVoiceContent = {
    Text = "Jangan mengganggu aku!"
  },
  Voice_54613_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_54614_AwakerVoiceContent = {
    Text = "Tenggelam dalam penderitaan yang unik ini!"
  },
  Voice_54614_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_54615_AwakerVoiceContent = {
    Text = "Tenggelam dalam penderitaan yang unik ini!"
  },
  Voice_54615_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_54616_AwakerVoiceContent = {
    Text = "\"Ya, anakku, engkau telah tenggelam di sungai yang bergelora!\""
  },
  Voice_54616_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_54617_AwakerVoiceContent = {
    Text = "\"Ya, anakku, engkau telah tenggelam di sungai yang bergelora!\""
  },
  Voice_54617_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_54618_AwakerVoiceContent = {
    Text = "Wahai entitas tanpa bentuk, jadilah perisai pelindung!"
  },
  Voice_54618_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_54619_AwakerVoiceContent = {
    Text = "Wahai entitas tanpa bentuk, jadilah perisai pelindung!"
  },
  Voice_54619_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_5461_AwakerVoiceContent = {
    Text = "Saya sangat berterima kasih atas kerja keras Anda."
  },
  Voice_5461_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5461_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_54620_AwakerVoiceContent = {
    Text = "Binatang Jurang, melahap segalanya!"
  },
  Voice_54620_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_54621_AwakerVoiceContent = {
    Text = "Binatang Jurang, melahap segalanya!"
  },
  Voice_54621_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_54622_AwakerVoiceContent = {
    Text = "Di dalam Jurang… akan ada cahaya keadilan."
  },
  Voice_54622_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_54623_AwakerVoiceContent = {
    Text = "Aku adalah orang yang merobek belenggu—Tokuli—Li!"
  },
  Voice_54623_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_54624_AwakerVoiceContent = {
    Text = "Aku adalah orang yang merobek belenggu—Tokuli—Li!"
  },
  Voice_54624_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_54625_AwakerVoiceContent = {
    Text = "Diriku ini adalah orang yang akan mengungkapkan masa depan!"
  },
  Voice_54625_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_54626_AwakerVoiceContent = {
    Text = "Diriku ini adalah orang yang akan mengungkapkan masa depan!"
  },
  Voice_54626_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_54627_AwakerVoiceContent = {
    Text = "Menunduk di bawah rokku dan mencium ujung kakiku!"
  },
  Voice_54627_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_54628_AwakerVoiceContent = {
    Text = "Semua kerang ada di sini!"
  },
  Voice_54628_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_54629_AwakerVoiceContent = {
    Text = "Semua kerang ada di sini!"
  },
  Voice_54629_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_5462_AwakerVoiceContent = {
    Text = "Kekuatan luar biasa hanya bisa ditanggung oleh mereka yang memiliki tubuh Aequor. Kamu pasti sangat iri padaku, haha. Dilahirkan sebagai manusia yang lemah bukanlah kesalahanmu, cobalah untuk menerimanya."
  },
  Voice_5462_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5462_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_54630_AwakerVoiceContent = {
    Text = "Menunduk di bawah rokku dan mencium ujung kakiku!"
  },
  Voice_54630_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_5463_AwakerVoiceContent = {
    Text = "Bisakah aku memperlakukan orang-orang yang kalah ini sebagai budakku?"
  },
  Voice_5463_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5464_AwakerVoiceContent = {Text = "Heh."},
  Voice_5464_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5465_AwakerVoiceContent = {
    Text = "Hanya seperti ini."
  },
  Voice_5465_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5466_AwakerVoiceContent = {Text = "Ah"},
  Voice_5466_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5467_AwakerVoiceContent = {Text = "Ah"},
  Voice_5467_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5468_AwakerVoiceContent = {
    Text = "Jika saja aku bisa mengetahuinya lebih awal, bahwa orang-orang pada masa itu menderita dan berjuang karena kutukan yang meluluhlantakkan segalanya, aku… tidak, mengetahuinya sekarang pun tidak terlambat. Aku harus menghilangkannya, menghapus semua penderitaan, meskipun aku harus membayar dengan Hidup sekali lagi."
  },
  Voice_5468_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5469_AwakerVoiceContent = {
    Text = "Jangan patah semangat. Lautan akan menerima semua orang."
  },
  Voice_5469_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5470_AwakerVoiceContent = {
    Text = "Hanya dengan tubuh yang lemah seperti ini, menjadi rekan seperjalanan masih terlalu berat bagimu. Ayo pergi, aku akan membawamu ke klub olahraga akademi untuk melihat-lihat dan memperkuat latihanmu!"
  },
  Voice_5470_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5471_AwakerVoiceContent = {
    Text = "Orang malang yang meminjamkan kekuatannya padaku, dia benar-benar menderita karena pelarutan... apa pandanganmu itu? Jangan berpikir macam-macam! Aku tidak akan memberitahumu di mana dia berada!"
  },
  Voice_5471_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5472_AwakerVoiceContent = {
    Text = "Asalkan cukup beruntung, kamu juga bisa tidak terkalahkan."
  },
  Voice_5472_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5473_AwakerVoiceContent = {
    Text = "Apakah ini akan terlalu kasar?"
  },
  Voice_5473_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5474_AwakerVoiceContent = {
    Text = "Eh, kebanyakan orang di sini masih anak-anak. Sang pria terhormat sudah beruban, pemuda bermuka dingin itu kehilangan satu tangannya, bukanlah pilihan yang sempurna... benar-benar sulit."
  },
  Voice_5474_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5475_AwakerVoiceContent = {
    Text = "Apakah ini akan terlalu kasar?"
  },
  Voice_5475_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5476_AwakerVoiceContent = {
    Text = "Rune yang digambar dengan cermat, patung dewa yang dipahat dengan penuh kesalehan, ramuan Tabu yang diperhalus berulang kali… semuanya tidak boleh ada yang terlewat."
  },
  Voice_5476_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5476_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5477_AwakerVoiceContent = {
    Text = "Takhta harus dibangun dari batu biru kuno yang ditambang dari Aequor, dan Altar harus dilumuri dengan darah korban persembahan... Apakah kamu belum mempersiapkannya?"
  },
  Voice_5477_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5477_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5478_AwakerVoiceContent = {
    Text = "Panggil semua orang itu, mereka seharusnya gemetar dan bersujud menyambut Kedatangan-Nya."
  },
  Voice_5478_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5478_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5479_AwakerVoiceContent = {
    Text = "Aku akan menuju reruntuhan Aequor, dengan air laut tempat Dia dilahirkan untuk membersihkan diri…"
  },
  Voice_5479_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5479_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5480_AwakerVoiceContent = {
    Text = "Selamat datang di upacara kelahiran-Nya, bersama-sama menyaksikan hari kelahiran-Nya… Apa? Kau mengatakan bahwa kehancuran-Nya juga adalah takdir yang sudah ditentukan? … Tidak, itu mustahil… Aku sudah membayar begitu banyak harga…"
  },
  Voice_5480_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5480_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5481_AwakerVoiceContent = {
    Text = "Mengikuti perintah Tuhan."
  },
  Voice_5481_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5482_AwakerVoiceContent = {
    Text = "Apakah di sisimu akan menjadi tempat berlabuh bagi aku dan Pingsan?"
  },
  Voice_5482_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5482_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5483_AwakerVoiceContent = {
    Text = "Hmm, pada saat itu, aku kehilangan suaraku. Berkat bantuanmu, suaraku pulih seperti semula."
  },
  Voice_5483_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5483_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5484_AwakerVoiceContent = {
    Text = "Mengikuti perintah Tuhan."
  },
  Voice_5484_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5485_AwakerVoiceContent = {
    Text = "Luasnya angkasa, tanpa batasnya ruang angkasa yang dalam, perjalanan tanpa akhir pernah membuatku tersesat…"
  },
  Voice_5485_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5485_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5486_AwakerVoiceContent = {
    Text = "Cara untuk meningkatkan mengambil jalan pintas, tetapi pelatihan keterampilan juga tidak boleh terabaikan."
  },
  Voice_5486_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5487_AwakerVoiceContent = {
    Text = "Ternyata metode ini juga bisa diterapkan pada diriku..."
  },
  Voice_5487_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5488_AwakerVoiceContent = {
    Text = "Perasaan yang ajaib."
  },
  Voice_5488_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5492_AwakerVoiceContent = {
    Text = "Kedatangan-Nya akan mengakhiri penderitaan yang dibawa oleh kematian hitam ini, bukan?"
  },
  Voice_5492_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5493_AwakerVoiceContent = {
    Text = "Selamat siang, Tuan. Jika Anda akan keluar untuk melakukan Penyelidikan, harap pastikan saya bisa menemani dan melindungi Anda."
  },
  Voice_5493_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5493_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5494_AwakerVoiceContent = {
    Text = "Apa yang harus dilakukan? Jika bosan, tulis saja Laporan Misi kali ini."
  },
  Voice_5494_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5495_AwakerVoiceContent = {
    Text = "Akhirnya akan dimulai, ya? Binatang kecil saya sudah sangat lapar untuk waktu yang lama…"
  },
  Voice_5495_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5496_AwakerVoiceContent = {
    Text = "Kekuatan darah sedang memancar."
  },
  Voice_5496_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5497_AwakerVoiceContent = {
    Text = "...Sebentar, aku pernah melihat benda seperti ini. Air yang mereka berikan padaku mengandung lendir hitam seperti ini. Mungkin Kekuatan Api Hijau yang kudapatkan ada hubungannya dengan ini? Itu juga bisa dianggap sebagai berkah dari musibah."
  },
  Voice_5497_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5498_AwakerVoiceContent = {
    Text = "Ramona Dexter, panggil saja Ramona. Menantikan kerja sama denganmu, Penjaga."
  },
  Voice_5498_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5499_AwakerVoiceContent = {Text = "Ya."},
  Voice_5499_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_5500_AwakerVoiceContent = {
    Text = "Instruksi diterima."
  },
  Voice_5500_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5501_AwakerVoiceContent = {
    Text = "Hmph, orang yang tidak sopan, biar nona ini menemani kalian bermain-main."
  },
  Voice_5501_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5502_AwakerVoiceContent = {
    Text = "Hal yang menyebalkan? Pipa rokok yang kebetulan habis, kereta kuda yang tidak sempat dikejar, hujan yang turun saat memakai sepatu kulit baru. Singkatnya, semua nasib buruk sangat menjengkelkan."
  },
  Voice_5502_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5503_AwakerVoiceContent = {
    Text = "Kunci pas, kunci inggris, kunci sok, obeng minus, obeng plus, baut kepala tenggelam, baut kepala bulat... Apapun yang bisa memperbaiki barang rusak, aku suka semuanya."
  },
  Voice_5503_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5504_AwakerVoiceContent = {
    Text = [[
Eh~ ketahuan deh~ 
 Tenang saja, kekuatan roh Pembangun begitu melimpah, setidaknya harus mencuri 365 kali lagi agar mereka menjadi boneka tanpa kesadaran~ Tidak bisa? Baiklah, lain kali aku akan lebih berhati-hati! Hmm, hanya sedikit "ketakutan" saat tubuh terpotong, tidak masalah kan?]]
  },
  Voice_5504_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5504_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5505_AwakerVoiceContent = {
    Text = "Hei, kamu sudah tahu rahasia sulap Casiah, kan? Hmm, untuk mencegah kebocoran rahasia, ke mana pun kami melakukan tur, kamu harus mengikuti aku~ Haha, apa kamu bilang aku mengumpulkan emosimu? Ternyata tidak ada rahasia yang bisa tersembunyi darimu!"
  },
  Voice_5505_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5505_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5506_AwakerVoiceContent = {
    Text = [[
Kamu, jadilah asisten sulap Casiah! Jangan takut~ Cukup masuk ke dalam kotak sulap saya sebentar saja. 

Sudah bersembunyi? Saya akan menusukkan pedang sekarang~ Oh ya, tidak ada jebakan di dalamnya~]]
  },
  Voice_5506_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5506_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5507_AwakerVoiceContent = {
    Text = "Ayo, pakailah topi ini! Lalu, sebutkan hadiah yang paling kamu inginkan. Baiklah, begitu ya, aku mengerti! Sekarang, raba bagian dalam topi ini—"
  },
  Voice_5507_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5507_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5508_AwakerVoiceContent = {
    Text = "Agak bingung juga. Setiap kali anak-anak itu datang untuk melihat pertunjukan, persediaanku hampir habis… Hmm, seorang pesulap tidak bisa melakukan trik yang sama di depan penonton yang sama. Menciptakan sulap baru? Maaf, aku tidak memiliki bakat seperti itu, aku hanya pandai meniru saja."
  },
  Voice_5508_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5508_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5509_AwakerVoiceContent = {
    Text = "Akademi ini sangat tua dan bobrok, hanya ruang istirahat milik direktur yang agak layak. Bagaimana menurut Anda?"
  },
  Voice_5509_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5509_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5510_AwakerVoiceContent = {
    Text = "Mereka yang sombong dan hina, semuanya akan menjadi arwah di bawah kendaliku."
  },
  Voice_5510_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5511_AwakerVoiceContent = {
    Text = "Pisau balas dendam semakin tajam."
  },
  Voice_5511_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5512_AwakerVoiceContent = {
    Text = "Salon saya tidak sepolos pesta dansa. Apakah Anda sudah siap?"
  },
  Voice_5512_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5512_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5513_AwakerVoiceContent = {
    Text = "Salonku adalah tanah, adalah taman; keindahan dan kekuasaan yang memabukkan akan mekar di sini…"
  },
  Voice_5513_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5513_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5514_AwakerVoiceContent = {
    Text = "Kain sutra lembut, teh merah, macaron… Saya juga membutuhkan mawar segar dengan embun pagi yang masih menempel di dahan untuk menghiasi ruang tamu saya."
  },
  Voice_5514_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5514_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5515_AwakerVoiceContent = {
    Text = "Apakah tidak bisa memberi kelonggaran agar para tamu di luar juga bisa masuk ke akademi?"
  },
  Voice_5515_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5515_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5516_AwakerVoiceContent = {
    Text = "Kesalahan runtime, kesalahan, kesalahan, kesalahan..."
  },
  Voice_5516_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5517_AwakerVoiceContent = {
    Text = "Ya! Sekarang jam berapa! Maafkan saya, Tuan... Karen tidak seharusnya lengah saat bekerja! Tapi saya benar-benar sangat mengantuk..."
  },
  Voice_5517_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5518_AwakerVoiceContent = {
    Text = "Apakah aku hanya bisa menunggu kematian? Apakah ada seseorang yang bisa membantu aku? Apakah aku bisa melawan kontrol mereka? Dulu, aku bertanya pada diriku sendiri setiap hari. Sebenarnya, jawabannya selalu ada di pikiranku, hanya saja aku tidak berani menghadapinya... Jika kamu tidak muncul, aku tidak yakin apakah aku memiliki keberanian untuk terus melawan sampai akhir. \n Te-terima kasih — jangan salah paham, ini bukan pengakuan cinta atau apa pun!"
  },
  Voice_5518_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5518_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5519_AwakerVoiceContent = {
    Text = "Aku hidup dalam mimpi-mimpi palsu mereka, kehilangan kualifikasi sebagai orang biasa karena sebuah ramalan yang konyol, bahkan tanpa hak untuk memilih… Untuk melarikan diri dari kehidupan seperti ini, aku bersedia melakukan apa saja."
  },
  Voice_5519_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5519_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5520_AwakerVoiceContent = {
    Text = [[
"Teratai yang rendah di sekitarnya menghela napas, 
di antara alder yang tidur, dia sesekali terbangun; 
seekor burung di sarang bergerak gemetar, 
lagu misterius turun dari bintang-bintang emas." 
Ah, apakah Anda mendengarnya? Maafkan saya, itu adalah kalimat yang sangat saya sukai... Apakah Anda ingin membacanya bersama?]]
  },
  Voice_5520_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Membaca"
  },
  Voice_5521_AwakerVoiceContent = {
    Text = "Jangan sembarangan masuk ke kamar seorang gadis, dan jangan mengomentari sikap seorang gadis. Segera pergi, aku ingin beristirahat."
  },
  Voice_5521_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5521_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5522_AwakerVoiceContent = {
    Text = "Sebaiknya jangan berlagak sombong terhadapku, sadari siapa dirimu, dan perhatikan dengan jelas siapa sebenarnya tuan yang sesungguhnya."
  },
  Voice_5522_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5522_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5523_AwakerVoiceContent = {
    Text = "Aduh, apakah perlu menampilkan barang?"
  },
  Voice_5523_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5524_AwakerVoiceContent = {
    Text = "Kerja bagus. Saatnya membawa se tong rum untuk merayakan kemenangan!"
  },
  Voice_5524_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5525_AwakerVoiceContent = {
    Text = "Menghilanglah."
  },
  Voice_5525_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_5526_AwakerVoiceContent = {
    Text = "Serahkan padaku!"
  },
  Voice_5526_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5527_AwakerVoiceContent = {
    Text = "Rasanya pasti sangat memuaskan berada di bawah kakiku, bukan~"
  },
  Voice_5527_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5528_AwakerVoiceContent = {Text = "Tahan, ya!"},
  Voice_5528_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5529_AwakerVoiceContent = {
    Text = "Apakah kamu sangat penasaran dengan penampilan di balik penutup mata? Pada saat yang lebih tepat, aku akan menunjukkannya padamu, jadi jangan terlalu terburu-buru."
  },
  Voice_5529_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5530_AwakerVoiceContent = {
    Text = "Begitu cepat sudah selesai? …… Minatku baru saja terbangkitkan."
  },
  Voice_5530_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5531_AwakerVoiceContent = {
    Text = "Hei, jangan berbuat macam-macam padaku. Prajurit sejati tidak pernah bergantung pada hal-hal eksternal."
  },
  Voice_5531_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5531_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5532_AwakerVoiceContent = {
    Text = "Aigis menjadi lebih kuat… Aku akan membuat musuh tak bisa bergerak dengan mata ini!"
  },
  Voice_5532_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5533_AwakerVoiceContent = {
    Text = "Universitas Mythag dan pasukan tidak berbeda. Setiap dari kami berjaga di garis depan, mengasah senjata, dan bersiap untuk bertempur."
  },
  Voice_5533_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5534_AwakerVoiceContent = {Text = "Sempurna!"},
  Voice_5534_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5535_AwakerVoiceContent = {Text = "Sempurna!"},
  Voice_5535_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5536_AwakerVoiceContent = {
    Text = "Aku bisa dipasangkan belenggu, bisa ditarik rambutku dan berlutut di hadapanmu, menjadi budakmu. Semua itu tidak masalah—asal aku bisa membunuh, pematung, orang yang membawa lampu, nenek asma yang lewat... siapa saja, aku jamin akan membantumu merobek tenggorokan mereka dan meminum darah mereka hingga kering."
  },
  Voice_5536_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5536_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5537_AwakerVoiceContent = {
    Text = "Dari luka pelarutan yang mengalir keluar, selain cairan hitam kental, ada juga inspirasi yang terus-menerus mengalir. Jujur, aku tidak keberatan mendapat sedikit lagi."
  },
  Voice_5537_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5538_AwakerVoiceContent = {
    Text = "Takut? Hahahaha, itu benar! Biar semuanya pergi ke neraka, aku hanya ingin merasakan ketakutan kalian."
  },
  Voice_5538_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5538_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5539_AwakerVoiceContent = {
    Text = "Menarik, rasa darahmu... sangat manis, seperti anggur madu."
  },
  Voice_5539_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5539_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5540_AwakerVoiceContent = {
    Text = "Pada saat itu, puluhan ribu orang bersorak menyebutkan namaku, lautan yang disebut \"Uvhash\" membanjiri segalanya, merayakan bahwa aku baru saja mematahkan leher seorang brengsek botak. Perasaan itu sungguh luar biasa, sebagai temanku, kau pasti bisa memahaminya."
  },
  Voice_5540_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5540_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5541_AwakerVoiceContent = {
    Text = "Tunggu, tunggu!"
  },
  Voice_5541_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5542_AwakerVoiceContent = {Text = "Jangan!"},
  Voice_5542_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5543_AwakerVoiceContent = {Text = "Aduh!"},
  Voice_5543_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5544_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_5544_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5545_AwakerVoiceContent = {
    Text = "Mencari \"Pelarutan\" di arsip wilayah luas... Tidak perlu? Apakah kamu ingin tahu sikapku terhadap Pelarutan? Aku mengerti, sedang membangun pencarian di domain pribadi sistem untuk \"senjata anti-Pelarutan\"... Hasilnya: \"0\"."
  },
  Voice_5545_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5546_AwakerVoiceContent = {
    Text = "Palsu, rapuh seperti debu, seutas angin lembut saja bisa meniupkannya pergi…"
  },
  Voice_5546_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Murphy"
  },
  Voice_5546_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Murphy\", akan terbuka."
  },
  Voice_5547_AwakerVoiceContent = {
    Text = "Sedikit berisik, apakah itu para siswa?\nMereka sangat mirip dengan albatros, apakah kamu tahu burung itu? Energi yang tak ada habisnya, perjalanan seolah-olah tidak pernah berakhir…"
  },
  Voice_5547_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5548_AwakerVoiceContent = {Text = "Ha"},
  Voice_5548_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5549_AwakerVoiceContent = {Text = "Hm"},
  Voice_5549_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5550_AwakerVoiceContent = {
    Text = "Di akademi, hanya anak itu, Ramona, yang cukup menarik. Dia memiliki bakat luar biasa dalam pedang, sisanya hanyalah orang-orang yang terpaku pada aturan... Kamu tidak seperti itu, kan? Apakah kamu benar-benar berpikir bahwa menulis Laporan misi itu menarik?"
  },
  Voice_5550_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5551_AwakerVoiceContent = {
    Text = "Tidak ada yang perlu disebutkan."
  },
  Voice_5551_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5552_AwakerVoiceContent = {
    Text = [[
Ibu dan ibu tidak selalu sama. Ada ibu yang baik, ada juga ibu yang buruk. 
Tuan adalah seorang ibu yang baik.]]
  },
  Voice_5552_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5552_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5553_AwakerVoiceContent = {
    Text = "Ini semua salahku karena tidak bisa melindungi Anda..."
  },
  Voice_5553_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5554_AwakerVoiceContent = {
    Text = "Apakah tempat sudah dipesan? Harus lebih dari seratus lima puluh meter persegi taman, ya!"
  },
  Voice_5554_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5554_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5555_AwakerVoiceContent = {
    Text = "Darah dari orang yang akan mati adalah cairan yang licin. Cukup dengan satu goresan ringan di leher, darah mengalir melalui celah antara gigi, berubah menjadi beberapa aliran hangat yang perlahan memasuki perutku... hehe, sungguh lezat."
  },
  Voice_5555_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Darah"
  },
  Voice_5556_AwakerVoiceContent = {Text = "Aah"},
  Voice_5556_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  },
  Voice_5557_AwakerVoiceContent = {Text = "Hei!"},
  Voice_5557_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  },
  Voice_5558_AwakerVoiceContent = {Text = "Eh"},
  Voice_5558_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  },
  Voice_5559_AwakerVoiceContent = {
    Text = "Terima kasih atas kebaikan hati Anda, memberikan saya tempat berlindung. Semoga saya tidak membawa takdir tragis kepada Anda…"
  },
  Voice_5559_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5560_AwakerVoiceContent = {
    Text = "Saya berasal dari planet asing yang jauh. Di sana, badai salju mengamuk dan suhu sangat dingin. Namun, tidak masalah, karena di kediaman saya terdapat lebih dari seribu pelayan. Kehangatan mereka membuat saya merasa sangat nyaman."
  },
  Voice_5560_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Masa Lalu"
  },
  Voice_5561_AwakerVoiceContent = {
    Text = "Sebelum menyambut Anda kembali, saya tidak boleh jatuh di sini."
  },
  Voice_5561_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5562_AwakerVoiceContent = {
    Text = "Sebelum menyambut Anda kembali, saya tidak boleh jatuh di sini."
  },
  Voice_5562_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5563_AwakerVoiceContent = {
    Text = "Astaga, bagaimana mungkin ada tamu seangkuh ini di dunia, menginginkan \"senjata paling hebat di dunia\"? Aku memberitahunya bahwa dia harus menukarnya dengan kepala yang dipenuhi kebencian, lalu dia pergi dengan wajah kesal…"
  },
  Voice_5563_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Goliath"
  },
  Voice_5563_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Goliath\", akan terbuka."
  },
  Voice_5564_AwakerVoiceContent = {
    Text = "Kamu tampak begitu penuh tekad, seakan-akan siap berkorban kapan saja demi \"menyelamatkan dunia\", membuat orang yang melihatmu merasa gatal di persendian."
  },
  Voice_5564_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5564_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5565_AwakerVoiceContent = {
    Text = "Sebelum kalian memberlakukan larangan penelitian, aku hampir saja membuat kehancuran menutupi tempat perlindungan pelarutan ini... Sayang sekali, sangat disayangkan."
  },
  Voice_5565_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5565_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5566_AwakerVoiceContent = {
    Text = "Ya, aku memiliki tubuh cadangan dalam jumlah tak terhitung, dan juga banyak kesempatan untuk melarikan diri dari pelarutan. Namun, ketika sebuah jalan menuju kebenaran terbentang di hadapanku, tidak ada seorang cendekiawan pun yang akan menolaknya. Aku mengikuti panggilan hatiku, dan untuk itu, aku sama sekali tidak menyesal."
  },
  Voice_5566_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5566_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5567_AwakerVoiceContent = {
    Text = "Kenyataan dunia, awal dunia, akhir dunia, semuanya adalah hal yang tidak memiliki arti. Jika kamu juga ingin melangkah di jalan menuju kebenaran, aku tidak keberatan menjadi pembimbingmu... seperti dulu kita pernah."
  },
  Voice_5567_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5567_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5568_AwakerVoiceContent = {
    Text = "Kalian mungkin bisa menghentikanku, tapi akhir tidak dapat dihindari... Aku akan meninggalkan sekolah ini, dan juga dirimu, hingga detik terakhir. Kita akan berdiri di atas menara, mandi dalam senja waktu, menyaksikan runtuhnya peradaban... Bagaimana? Dengan melakukan ini, aku tidak mengecewakan ikatan kita, kan?"
  },
  Voice_5568_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5568_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5569_AwakerVoiceContent = {Text = "Baiklah."},
  Voice_5569_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5570_AwakerVoiceContent = {
    Text = "Menghilanglah."
  },
  Voice_5570_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_5571_AwakerVoiceContent = {
    Text = "Semoga doaku menjadi lonceng pagi yang membangunkan tanah airku…"
  },
  Voice_5571_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5572_AwakerVoiceContent = {
    Text = "Aku tidak pernah membayangkan bahwa ada orang selain Tinct yang mau menerima aku. Aku sangat bersyukur bisa bertemu denganmu, Penjaga. Aku akan berusaha sepenuhnya untuk belajar mengendalikan Kekuatan, jadi ketika aku memelukmu, aku tidak akan menghisap habis kehidupanmu… Itu adalah pelukan, kan? Cara manusia mengekspresikan rasa terima kasih?"
  },
  Voice_5572_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5572_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5573_AwakerVoiceContent = {
    Text = "Aku tetap di sini, tidak perlu membayar apa pun, kan? Aku bisa membantu meningkatkan statusmu di sini. Cukup ancam akan menghisap habis hidup mereka, sangat mudah, seperti dulu aku membantu Tinct… Ah! Ini, jangan beritahu siapa pun tentang ini!"
  },
  Voice_5573_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5573_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5574_AwakerVoiceContent = {
    Text = "Maaf, aku berbeda dari yang lainnya, aku produk yang inferior..."
  },
  Voice_5574_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5574_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5575_AwakerVoiceContent = {
    Text = "Seorang pelayan yang cakap dapat menambah banyak warna pada salon, tetapi pelayan berwarna biru kehijauan... izinkan saya mempertimbangkannya kembali..."
  },
  Voice_5575_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Karen"
  },
  Voice_5575_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Karen\", akan terbuka."
  },
  Voice_5576_AwakerVoiceContent = {
    Text = [[
Tinct adalah adik kembar saya. Berbeda dari saya, dia selalu bersinar terang... 
 Jika tidak ada saya yang menahannya, dia pasti akan memiliki masa depan yang lebih baik, suaranya bisa bergema di seluruh galaksi...]]
  },
  Voice_5576_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5576_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5577_AwakerVoiceContent = {
    Text = "Boks bayi sangat sempit, tidak ada cara untuk meregangkan tubuh… Tapi Tinct berkata, demi keamanan semua orang, dia memintaku untuk tidak meninggalkan boks bayi… Karena dia berharap begitu, aku akan mendengarkannya."
  },
  Voice_5577_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5577_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5578_AwakerVoiceContent = {
    Text = "Sering kali saya merasa berada di antara celah hidup dan mati. Di mana pun saya berada, kesedihan menyebar seperti gelombang, tragedi datang silih berganti. Meski begitu, apakah kamu masih bersedia membiarkan aku menulis puisi untukmu? Hmm… mungkin, kamu pantas mendapatkan yang paling manis…"
  },
  Voice_5578_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5578_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5579_AwakerVoiceContent = {
    Text = "\"Mawar belum mekar, tetapi fajar sudah akan tiba.\""
  },
  Voice_5579_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5579_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5580_AwakerVoiceContent = {
    Text = "Apa yang kau dambakan? Apakah keindahan kata-kata yang memikat, kemasyhuran yang terkenal di seluruh negeri, atau mungkin ketulusan menyayat hati di balik kalimat-kalimat itu?"
  },
  Voice_5580_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5580_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5581_AwakerVoiceContent = {
    Text = "Dengan tinta yang tak terlihat, mengukir kuncup bunga yang cacat... dahan mawar yang hantu ini, yang begitu samar, ternyata bisa membangkitkan inspirasi..."
  },
  Voice_5581_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5581_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_55825_AwakerVoiceContent = {
    Text = "Dengarkan Tuhanku."
  },
  Voice_55825_AwakerVoiceTitle = {
    Text = "Membangkitkan·Dua"
  },
  Voice_55826_AwakerVoiceContent = {
    Text = "Mengorbankan diri! Membentuk kembali Ranah dewa——"
  },
  Voice_55826_AwakerVoiceTitle = {
    Text = "Membangkitkan·Tiga"
  },
  Voice_5582_AwakerVoiceContent = {
    Text = "Jika kau bersikeras, aku akan melangkah kembali ke bawah sinar matahari... sinar matahari yang sama seperti hari itu saat aku meninggalkan Cité…"
  },
  Voice_5582_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5582_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5583_AwakerVoiceContent = {
    Text = "Hehe, apakah kamu ingin melihat alam semesta yang mengalami kehancuran? Eh, sekarang menyesal sudah terlambat!"
  },
  Voice_5583_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5583_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5584_AwakerVoiceContent = {
    Text = "Minumlah, kematian yang manis."
  },
  Voice_5584_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5585_AwakerVoiceContent = {
    Text = "Minumlah, kematian yang manis."
  },
  Voice_5585_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5586_AwakerVoiceContent = {
    Text = "Sampai di sini!"
  },
  Voice_5586_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5587_AwakerVoiceContent = {Text = "Jangan..."},
  Voice_5587_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5588_AwakerVoiceContent = {
    Text = "Saksikanlah keagungan Yu."
  },
  Voice_5588_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5589_AwakerVoiceContent = {
    Text = "Udara di universitas pada pukul 4 pagi sangat segar, senang Anda bersedia berolahraga bersama saya. Patut diakui, membuat patung adalah pekerjaan yang membutuhkan tenaga."
  },
  Voice_5589_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Pagi"
  },
  Voice_5590_AwakerVoiceContent = {
    Text = "Kekuatan ini, saat digunakan, cukup baik."
  },
  Voice_5590_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5590_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5591_AwakerVoiceContent = {
    Text = "Saya benci orang yang belanja tapi tidak membayar. Selama toko buka cukup lama, pasti akan ada masalah seperti ini, kan? Tak apa, saya hanya bisa turun tangan sendiri untuk menagih tagihan itu kembali~"
  },
  Voice_5591_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5592_AwakerVoiceContent = {
    Text = "Menyiksa secara perlahan."
  },
  Voice_5592_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5593_AwakerVoiceContent = {
    Text = "Menyiksa secara perlahan."
  },
  Voice_5593_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5594_AwakerVoiceContent = {Text = "Memuat."},
  Voice_5594_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5595_AwakerVoiceContent = {Text = "Mulai."},
  Voice_5595_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5596_AwakerVoiceContent = {
    Text = "Mari kita jadikan tempat ini lautan keriuhan untuk semua orang!"
  },
  Voice_5596_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5597_AwakerVoiceContent = {
    Text = "Apa, kau berharap aku akan berterima kasih padamu?"
  },
  Voice_5597_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5598_AwakerVoiceContent = {
    Text = "Sebagai persembahan, ini benar-benar tidak memenuhi syarat... Namun, karena kau begitu tulus, aku akan menerimanya dengan berat hati."
  },
  Voice_5598_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5599_AwakerVoiceContent = {
    Text = "Apakah kau pikir aku akan menuruti perintahmu hanya karena ini?"
  },
  Voice_5599_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5600_AwakerVoiceContent = {Text = "Haa!"},
  Voice_5600_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5601_AwakerVoiceContent = {Text = "Maju!"},
  Voice_5601_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5602_AwakerVoiceContent = {
    Text = "Makhluk yang tidak tahu balas budi, pembunuh bayaran, pembunuh, apakah mereka juga memiliki nilai yang kau akui? Orang aneh."
  },
  Voice_5602_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5602_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5603_AwakerVoiceContent = {
    Text = "Tak peduli berapa banyak bantalan lembut yang ditumpuk, singgasana lazurit tetap tak bisa dibandingkan dengan ranjang berbulu. Dari sudut pandang ini, tempat ini masih memiliki beberapa hal yang layak dihargai."
  },
  Voice_5603_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5604_AwakerVoiceContent = {
    Text = "Hukuman kecil."
  },
  Voice_5604_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5605_AwakerVoiceContent = {
    Text = "Aku benci kesendirian, benci merasa cemas akan perasaan seseorang di tengah kegelapan yang tak berujung… Jadi, tolong jangan tinggalkan aku, oke?"
  },
  Voice_5605_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5606_AwakerVoiceContent = {
    Text = "Jika aku jadi kamu, aku akan mengurung semua Pembangun di dalam kandang! Setelah anjing gila keluar dari kandang, mereka selalu menggigit tuannya terlebih dahulu."
  },
  Voice_5606_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5606_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5607_AwakerVoiceContent = {
    Text = "Aku terlambat satu jam untuk pertemuan ini — semua karena para pengacau yang ingin menghapuskan perbudakan, sekarang tidak ada yang menyisir rambutku!"
  },
  Voice_5607_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5607_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5608_AwakerVoiceContent = {
    Text = "Sulit dipercaya, Rumah-ku benar-benar musnah begitu saja… Itu adalah Roma yang hebat! Tidak mungkin kau belum pernah mendengarnya!"
  },
  Voice_5608_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5608_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5609_AwakerVoiceContent = {
    Text = "Ayo, raih kemenangan pertama!"
  },
  Voice_5609_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5610_AwakerVoiceContent = {
    Text = "Ini adalah berkat dari Tuan-ku."
  },
  Voice_5610_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5611_AwakerVoiceContent = {
    Text = "Tahan tatapan kasihanmu. Aku tidak suka, juga tidak butuh belas kasihan. Jika kau terus menatapku seperti ini, aku tidak akan tahan untuk menyiksamu dengan kejam... Kau juga tidak ingin semuanya menjadi tak terkendali, kan? Jadi, jadilah penurut, dengarkan aku, dan jadilah gladiatorku yang patuh..."
  },
  Voice_5611_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5611_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5612_AwakerVoiceContent = {
    Text = "Jangan *dibisukan* tanya lagi. Aku lalai, ceroboh, membiarkan gladiator melarikan diri, hingga seluruh keluargaku mati! Seperti Kekaisaran Romawi sekarang, dibakar sampai tidak tersisa abunya!"
  },
  Voice_5612_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5612_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5613_AwakerVoiceContent = {
    Text = [[
Dibandingkan dengan semua orang yang memiliki bakat masing-masing, Nymphaea hanyalah seorang manusia biasa yang tidak pernah mencatatkan prestasi apa pun atau menciptakan nilai apa pun. 
Mungkin yang membuatku terbangun adalah beberapa keinginan kecil dan sederhana...]]
  },
  Voice_5613_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5614_AwakerVoiceContent = {
    Text = "Hari ini saya kembali melanggar peraturan sekolah, terlambat lima menit untuk kelas… Oleh karena itu, saya memohon hukuman yang paling berat. Jika Penjaga yang menjalankan hukuman, akan lebih baik."
  },
  Voice_5614_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5615_AwakerVoiceContent = {
    Text = "Peralatan juga perlu dirawat, lho. Satu set alat yang nyaman adalah jiwa seorang montir."
  },
  Voice_5615_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5615_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5616_AwakerVoiceContent = {
    Text = "(Menahan diri dengan nada meremehkan)"
  },
  Voice_5616_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5617_AwakerVoiceContent = {
    Text = "Jika ada lain kali, saya akan mengajukan hukuman skorsing untukmu."
  },
  Voice_5617_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5618_AwakerVoiceContent = {
    Text = "Selain pertempuran, tentu saja saya memiliki pekerjaan lain yang harus diselesaikan. Bahkan di zaman Arkeozoikum, saya tidak benar-benar menganggur… Hei, jangan-jangan kamu menganggapku sebagai orang kasar yang hanya bisa berkelahi!"
  },
  Voice_5618_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Pekerjaan"
  },
  Voice_5619_AwakerVoiceContent = {
    Text = "Setiap kali orang mendekati saya, mereka selalu teringat pada pengalaman paling menyedihkan dalam hidup mereka, sehingga tanpa sadar meneteskan air mata. Apakah saya, yang seperti ini, juga bisa berkembang?"
  },
  Voice_5619_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5619_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5620_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5621_AwakerVoiceContent = {Text = "Begitu ya?"},
  Voice_5621_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5622_AwakerVoiceContent = {
    Text = "Di sini jauh lebih baik daripada Penjara Xinmen yang kotor dan bau! Baik berbaring di sofa maupun duduk di sudut dinding, semuanya terasa nyaman, bukan?"
  },
  Voice_5622_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5623_AwakerVoiceContent = {
    Text = "Cokelat…!"
  },
  Voice_5623_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5624_AwakerVoiceContent = {
    Text = "Rumah siput, ke mana perginya…"
  },
  Voice_5624_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5625_AwakerVoiceContent = {Text = "Licik!"},
  Voice_5625_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5626_AwakerVoiceContent = {
    Text = "Kemana perginya rumah siput!"
  },
  Voice_5626_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5627_AwakerVoiceContent = {
    Text = "Galaksi yang mengalir..."
  },
  Voice_5627_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5628_AwakerVoiceContent = {
    Text = "Aurita tidak suka teman yang tiba-tiba pergi… tapi, jika dia akan kembali, Aurita akan memaafkannya!"
  },
  Voice_5628_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5629_AwakerVoiceContent = {
    Text = "Wanita yang berlayar sendirian menyeberangi lautan bisa jadi dewi, bisa juga wanita gila. Saat itu, menganggap Miryam sebagai dewi adalah kesalahan besar."
  },
  Voice_5629_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Miryam"
  },
  Voice_5629_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Miryam\", akan terbuka."
  },
  Voice_5630_AwakerVoiceContent = {Text = "Ya!"},
  Voice_5630_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  },
  Voice_56313_AwakerVoiceContent = {
    Text = "Saya diam-diam pergi melihat pertunjukan sulap Nyonya Casiah. Penampilannya membawa banyak kebahagiaan kepada penonton, tapi saya selalu membawa kesedihan kepada semua orang... Apakah menurutmu air mata dan senyuman adalah hal yang sama berharganya? Mungkin..."
  },
  Voice_56313_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Casiah"
  },
  Voice_56313_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Casiah\", akan terbuka."
  },
  Voice_56314_AwakerVoiceContent = {
    Text = "Puisi, api, dan kesedihan adalah hal yang serupa. Mereka akan menelanmu tanpa terasa... Saat tersadar, kau sudah tenggelam dalam dunia puisi..."
  },
  Voice_56314_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_56315_AwakerVoiceContent = {
    Text = "Biarkan syair dari masa lalu membangun taman yang tersembunyi di dasar hati."
  },
  Voice_56315_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_56316_AwakerVoiceContent = {
    Text = "Puisi dan bunga, mungkin adalah hal yang sama, bukan? Sama-sama singkat, penuh makna. Di dunia tanpa batas ini, hanya dengan sebagian kecil tempat, sudah bisa menampung momen-momen yang paling mendalam... Saya pikir, semua orang pernah terdiam karena sebuah puisi, sama seperti mereka berhenti sejenak untuk mekarnya sebuah bunga."
  },
  Voice_56316_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Puisi"
  },
  Voice_56317_AwakerVoiceContent = {
    Text = "Saya hampir lupa... bunga apa yang akan mekar di Cité pada musim ini?"
  },
  Voice_56317_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Cité"
  },
  Voice_56318_AwakerVoiceContent = {
    Text = "Anda membuat tinta di bawah kuas saya berkumpul kembali menjadi aliran kecil, dan saya juga akan menulis puisi untuk melanjutkan cerita Anda."
  },
  Voice_56318_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Penjaga 1"
  },
  Voice_56319_AwakerVoiceContent = {
    Text = "Betapa indahnya mekarnya bunga, betapa menyedihkan ketika bunga itu layu. Namun, tidak peduli berapa kali aku merasa sedih, aku selalu tak bisa menahan diri untuk berhenti dan berduka atas bunga-bunga itu. Jika aku mengabaikannya karena takut akan penderitaan, betapa sedihnya bunga-bunga itu akan merasa..."
  },
  Voice_56319_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penderitaan"
  },
  Voice_5631_AwakerVoiceContent = {
    Text = [[
Untuk melakukan penelitian terhadap struktur internal tubuh ini saat Erica "tidur", Kerang meminta saya untuk berhibernasi di kantornya pada malam hari. 
Apakah perlu memberi tahu bahwa Erica masih memiliki sebagian kesadaran saat hibernasi?]]
  },
  Voice_5631_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Kerang"
  },
  Voice_5631_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Kerang\", akan terbuka."
  },
  Voice_56320_AwakerVoiceContent = {
    Text = "Nyonya Merah itu sungguh cantik. Kekuatannya dan rasa percaya dirinya, senyumannya yang anggun menghadapi takdir, serta vitalitas hidupnya yang membara dan teguh seperti mawar merah, semua membuatku sangat iri…"
  },
  Voice_56320_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Sorel"
  },
  Voice_56320_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Sorel\", akan terbuka."
  },
  Voice_56321_AwakerVoiceContent = {
    Text = "Saya menulis sebuah puisi kemarin, belum pernah menunjukkannya kepada orang lain. Meskipun mungkin tidak bagus, tapi... Penjaga, apakah kamu bersedia melihatnya?"
  },
  Voice_56321_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Penjaga 2"
  },
  Voice_56322_AwakerVoiceContent = {
    Text = "Para peserta pertemuan puisi mahasiswa berharap saya menjadi pembimbing mereka... Saya tidak bisa menyetujui permintaan mereka. Saya tidak ingin mematahkan semangat kaum muda, tetapi saya hanya akan membawa kekecewaan dan kemurungan bagi mereka."
  },
  Voice_56322_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_56323_AwakerVoiceContent = {
    Text = "Di dunia ini, tidak ada hal yang dibenci. Masa keemasan patut dirayakan, sedangkan kemunduran akibat usia tua layak dikasihani; pakaian indah masa muda membangkitkan kekaguman, sedangkan kain lusuh yang lapuk menimbulkan rasa nostalgia."
  },
  Voice_56323_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_56324_AwakerVoiceContent = {
    Text = "Setiap kali melihat Nymphaea, saya selalu teringat pada lukisan bunga teratai itu. Di tubuhnya, ada kepahitan dan keharuman yang tenang seperti bunga teratai… Entah seperti apa dunia di matanya."
  },
  Voice_56324_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Nymphaea"
  },
  Voice_56324_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Nymphaea\", akan terbuka."
  },
  Voice_56325_AwakerVoiceContent = {
    Text = "Sejak dulu, saya bisa merasakan keberadaan \"hantu\" di sekitar saya, seperti semacam kerasukan yang sulit dijelaskan atau fenomena kesurupan. Itu membuat saya perlahan kehilangan harapan terhadap dunia. Namun, jika itu hantu, bagaimana mungkin menjelaskan susu dan air bersih yang tiba-tiba menghilang begitu saja……"
  },
  Voice_56325_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Hantu"
  },
  Voice_56326_AwakerVoiceContent = {
    Text = "Tubuhku tidak terkena pelarutan, cairan hitam itu hanyalah tinta pekat. Namun, meskipun tanpa pelarutan, keberadaan segala sesuatu akan berubah menjadi ilusi, bukan?"
  },
  Voice_56326_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_56327_AwakerVoiceContent = {
    Text = "Di batu nisan Kunci, saya melihat nama Penjaga... Memori dari kehidupan sebelumnya menyakitkan, tetapi saya tak pernah berniat melupakannya. Bagi Penjaga, memori yang hilang itu pasti juga sangat berharga, bukan?"
  },
  Voice_56327_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Memori"
  },
  Voice_56328_AwakerVoiceContent = {
    Text = "Jika puisi ada untuk memuji keindahan, maka keberadaannya bagaikan puisi itu sendiri. Ketika dia mulai bernyanyi, aku tiba-tiba mengerti apa yang para pendahulu gambarkan sebagai suara merdu bak burung malam…"
  },
  Voice_56328_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Tinct"
  },
  Voice_56328_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Tinct\", akan terbuka."
  },
  Voice_56329_AwakerVoiceContent = {
    Text = "Penari cantik itu... Api hijau zamrud di tubuhnya membuat orang tak kuasa menahan diri untuk menyentuhnya, meskipun harus terbakar habis pun tak masalah..."
  },
  Voice_56329_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Liz"
  },
  Voice_56329_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Liz\", akan terbuka."
  },
  Voice_5632_AwakerVoiceContent = {
    Text = "Menggantikan penyerapan Primal dengan cara ini?"
  },
  Voice_5632_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5633_AwakerVoiceContent = {
    Text = "Lezat, sangat lezat."
  },
  Voice_5633_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5634_AwakerVoiceContent = {
    Text = "Tamu, imbalan seperti apa yang Anda inginkan?"
  },
  Voice_5634_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5635_AwakerVoiceContent = {
    Text = "Ayo cepat selesaikan, jangan berlama-lama di jalanan."
  },
  Voice_5635_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5636_AwakerVoiceContent = {
    Text = "Pengorbanan yang tak terelakkan."
  },
  Voice_5636_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5637_AwakerVoiceContent = {
    Text = "(Bertahan dengan desahan tertahan)"
  },
  Voice_5637_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_56386_AwakerVoiceContent = {
    Text = "Input arus selesai. Arus dilepaskan."
  },
  Voice_56386_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_56387_AwakerVoiceContent = {
    Text = "Jangan meremehkan pencuri nomor satu di jalanan!"
  },
  Voice_56387_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_56388_AwakerVoiceContent = {
    Text = "Persembahkan pujian pembukaan!"
  },
  Voice_56388_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_56389_AwakerVoiceContent = {
    Text = "Seribu bayangan yang muncul di sini!"
  },
  Voice_56389_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_5638_AwakerVoiceContent = {
    Text = "Semakin dekat lagi..."
  },
  Voice_5638_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5638_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_56390_AwakerVoiceContent = {
    Text = "Tenggelamlah, terbakarlah! Tarian kehancuran!"
  },
  Voice_56390_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_56391_AwakerVoiceContent = {
    Text = "Inilah kota yang hilang, tempat ribuan jiwa yang telah meninggal berkeliaran tanpa tujuan."
  },
  Voice_56391_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_56392_AwakerVoiceContent = {
    Text = "Maka izinkan aku memberikannya padamu, sisa energi migrasi yang kumiliki…!"
  },
  Voice_56392_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_56393_AwakerVoiceContent = {
    Text = "Jangan meremehkan pencuri nomor satu di jalanan!"
  },
  Voice_56393_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_5639_AwakerVoiceContent = {
    Text = [[
Apakah itu musuh? Berikan saya perintah untuk menyerang. 
 Lendir hitam adalah musuh... Apakah Lily juga musuh?]]
  },
  Voice_5639_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5640_AwakerVoiceContent = {
    Text = "Automaton Erica, nomor rangka EA307881, nomor motor MF311028. Senang bisa melayani Anda."
  },
  Voice_5640_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5641_AwakerVoiceContent = {
    Text = "Sebelum musuh sepenuhnya hancur, bertarunglah dengan segenap tenaga!"
  },
  Voice_5641_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5642_AwakerVoiceContent = {
    Text = "Halo, saya adalah... Bisakah kamu memberitahu saya nama saya?"
  },
  Voice_5642_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5643_AwakerVoiceContent = {
    Text = "Setelah tiba di sekolah, aku baru memahami penyakit yang disebut Pelarutan yang telah menginfeksi diriku. Semasa hidup, orang tua selalu berharap agar aku menjauhi lautan, dan sekarang tampaknya infeksi ini mungkin memang ada hubungannya dengan kebiasaanku yang sering mendekati laut…"
  },
  Voice_5643_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5644_AwakerVoiceContent = {
    Text = "Baiklah, aku tidak akan mengecewakanmu."
  },
  Voice_5644_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5645_AwakerVoiceContent = {
    Text = "Nafas yang membakar ini——"
  },
  Voice_5645_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5646_AwakerVoiceContent = {Text = "Pergilah."},
  Voice_5646_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5647_AwakerVoiceContent = {
    Text = "Berputarlah."
  },
  Voice_5647_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_5648_AwakerVoiceContent = {Text = "Eh!"},
  Voice_5648_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5650_AwakerVoiceContent = {
    Text = "Hari itu akhirnya tiba..."
  },
  Voice_5650_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5651_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5651_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5652_AwakerVoiceContent = {
    Text = "Aku masih belum puas... Bagaimana kalau kau bangkit lagi, biar aku bisa membunuhmu sekali lagi?"
  },
  Voice_5652_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5654_AwakerVoiceContent = {
    Text = "Penjaga, aku harus berbicara denganmu. Sebelum kita mencapai kemenangan akhir, ada beberapa orang yang tidak seharusnya begitu boros dan berfoya-foya. Ketahuilah, aku tidak berjuang demi kehidupan bangsawan seperti itu."
  },
  Voice_5654_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Sorel"
  },
  Voice_5654_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Sorel\", akan terbuka."
  },
  Voice_5655_AwakerVoiceContent = {
    Text = "Jika aku dibawa sebagai tawanan perang, nasib kejam macam apa yang akan menantiku?"
  },
  Voice_5655_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5656_AwakerVoiceContent = {
    Text = "Lihat jurus ini!"
  },
  Voice_5656_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5657_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5657_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5658_AwakerVoiceContent = {
    Text = "Hu—— sangat mengantuk. Sebelum beristirahat, apakah kalian sudah menyiapkan camilan dan teh untuk bersantai?"
  },
  Voice_5658_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5659_AwakerVoiceContent = {
    Text = "Ibu, apakah kamu ingin menyentuhnya? Katanya sangat lembut."
  },
  Voice_5659_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5659_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5660_AwakerVoiceContent = {
    Text = "Hmmm, lalala~ membersihkan, aku suka membersihkan, suasana hatiku sangat baik~"
  },
  Voice_5660_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Pekerjaan"
  },
  Voice_5661_AwakerVoiceContent = {
    Text = "(Rintihan kesakitan yang tak tertahankan)"
  },
  Voice_5661_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5662_AwakerVoiceContent = {
    Text = "Hmm… bagus."
  },
  Voice_5662_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5663_AwakerVoiceContent = {
    Text = "(Rintihan kesakitan yang tak tertahankan)"
  },
  Voice_5663_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5664_AwakerVoiceContent = {
    Text = "(Rintihan kesakitan yang tak tertahankan)"
  },
  Voice_5664_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5665_AwakerVoiceContent = {
    Text = "Api kemarahan berkobar!"
  },
  Voice_5665_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  },
  Voice_5666_AwakerVoiceContent = {
    Text = "Saya melihat banyak orang menjadi gila karena Pelarutan. Jujur, saya sudah cukup gila, jadi Pelarutan seharusnya tidak berpengaruh banyak pada saya."
  },
  Voice_5666_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5667_AwakerVoiceContent = {Text = "He~hahaha!"},
  Voice_5667_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5668_AwakerVoiceContent = {
    Text = "Alat yang baik adalah separuh dari kesuksesan!"
  },
  Voice_5668_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5669_AwakerVoiceContent = {
    Text = "Rasanya seperti mendapatkan kehidupan kembali."
  },
  Voice_5669_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5670_AwakerVoiceContent = {
    Text = "Tidak buruk."
  },
  Voice_5670_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5671_AwakerVoiceContent = {
    Text = "Bisa mengayunkan pedang yang lebih kuat."
  },
  Voice_5671_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5672_AwakerVoiceContent = {
    Text = "Harus menjaga tingkat kehadiran, mempertahankan kemajuan Penelitian, dan masih ada tugas pengajaran yang perlu diselesaikan. Sepertinya, eksperimen kompresi waktu terbalik harus segera dimulai."
  },
  Voice_5672_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5672_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5673_AwakerVoiceContent = {
    Text = "Selangkah lebih dekat menuju petualangan sebenarnya."
  },
  Voice_5673_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5674_AwakerVoiceContent = {
    Text = "Jangan biarkan orang mendekati air, lho, api cinta kamu bisa padam, loh?"
  },
  Voice_5674_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5675_AwakerVoiceContent = {
    Text = "Pertempuran sampai akhir!"
  },
  Voice_5675_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5676_AwakerVoiceContent = {
    Text = "Kamu benar-benar penuh keberanian. Lihatlah tentakel-tentakel ini, apakah kamu tidak takut dimakan oleh kegilaan?"
  },
  Voice_5676_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5676_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5677_AwakerVoiceContent = {Text = "Aduh!"},
  Voice_5677_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5678_AwakerVoiceContent = {Text = "Sakit..."},
  Voice_5678_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5679_AwakerVoiceContent = {
    Text = "Tolong hentikan!"
  },
  Voice_5679_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5680_AwakerVoiceContent = {
    Text = "Ingin menyentuhnya? Jantungku berdetak karena kehadiran Anda."
  },
  Voice_5680_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5680_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5681_AwakerVoiceContent = {
    Text = "Mereka berbincang-bincang dengan riang. Terima kasih, Tuan."
  },
  Voice_5681_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5681_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5682_AwakerVoiceContent = {
    Text = [[
Ada sesuatu yang mulai bangkit di dada... hangat sekali, air mata Lily hampir... 
Ibu, mari kita rayakan bersama.]]
  },
  Voice_5682_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5682_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5683_AwakerVoiceContent = {
    Text = "Bersama ibu, akan muncul perasaan bahagia."
  },
  Voice_5683_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5683_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5684_AwakerVoiceContent = {
    Text = [[
Sudah tidak bisa makan lagi... perut kenyang. 
 Setelah ritual selesai, apakah Lily akan menjadi lebih kuat?]]
  },
  Voice_5684_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5684_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5685_AwakerVoiceContent = {
    Text = "Apakah menyukai lautan itu ironis? Karena semua yang kumiliki telah tenggelam ke dalam Aequor…"
  },
  Voice_5685_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5686_AwakerVoiceContent = {Text = "Hati-hati!"},
  Voice_5686_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5687_AwakerVoiceContent = {
    Text = "Hal yang dibenci...? Tidak ada. Apakah Anda akan membenci sebutir debu atau selembar daun?"
  },
  Voice_5687_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5688_AwakerVoiceContent = {
    Text = "Saya beberapa kali menolak undangan pesta dari Nona Pelayan. Dia tampak sedikit kecewa… Namun, dibandingkan dengan bersenang-senang, keselamatan Tuan jauh lebih penting!"
  },
  Voice_5688_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Karen"
  },
  Voice_5688_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Karen\", akan terbuka."
  },
  Voice_5689_AwakerVoiceContent = {
    Text = "Tuanku adalah alasan keberadaan seorang ksatria, jadi silakan perintahkan saya sesuka hati!"
  },
  Voice_5689_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5690_AwakerVoiceContent = {
    Text = "...Ini mungkin memerlukan kunci torsi... Hmm, maaf, apakah kamu baru saja memanggilku?"
  },
  Voice_5690_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5691_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5692_AwakerVoiceContent = {Text = "Berani!"},
  Voice_5692_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5693_AwakerVoiceContent = {
    Text = "(Humming dengan anggun)"
  },
  Voice_5693_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5694_AwakerVoiceContent = {
    Text = "(Bertahan dengan desahan tertahan)"
  },
  Voice_5694_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5695_AwakerVoiceContent = {
    Text = "Cukup sudah."
  },
  Voice_5695_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5696_AwakerVoiceContent = {
    Text = "Lebih lembut."
  },
  Voice_5696_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5697_AwakerVoiceContent = {
    Text = "Ternyata masih sulit untuk berkonsentrasi dalam Roh…"
  },
  Voice_5697_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5698_AwakerVoiceContent = {
    Text = "Dia sering berada di dekatku saat malam hari. Apakah kepalaku ini terlalu mencolok?"
  },
  Voice_5698_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Kerang"
  },
  Voice_5698_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Kerang\", akan terbuka."
  },
  Voice_5699_AwakerVoiceContent = {
    Text = "Saya selalu menunggu kedatangan kehancuran, namun tak pernah terpikir olehku bahwa ada pilihan \"melawan\"... Apakah Anda bersedia membawa jiwa saya yang begitu dangkal melewati kehancuran ini? Di dunia yang penuh dengan pelarian dari kematian, tetap berikan saya keselamatan..."
  },
  Voice_5699_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5699_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5700_AwakerVoiceContent = {
    Text = "Karena aku telah di-Bangun sebagai rasulmu, maka selain kedamaian dan kebahagiaanmu, aku tidak menginginkan apa pun. Ini adalah harapanku… Ugh… Ah… Memang, bertahan hidup, bertahan hidup, bertahan hidup, bertahan hidup, tetap hidup…"
  },
  Voice_5700_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5700_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5701_AwakerVoiceContent = {
    Text = "Tidakkah Anda ingin mencoba untuk tidak tenggelam dalam cinta saya? Bukankah Anda membangunkan saya hanya untuk kehangatan di pelukan saya?"
  },
  Voice_5701_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5701_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5702_AwakerVoiceContent = {
    Text = "Tidak ingin terlibat dengan wanita yang tidak jelas asal-usulnya, baiklah, baiklah. Raja yang kehilangan negaranya di Nineveh, orang Shinar yang berniat mencapai langit, gadis muda yang kehendaknya dirampas di bawah Pohon Suci Euphrates… dari mana Anda ingin mulai mendengarnya?"
  },
  Voice_5702_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5702_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5703_AwakerVoiceContent = {
    Text = "Kenapa kamu selalu menghindariku? Apakah karena malu? Sungguh menggemaskan, ekspresi takutmu untuk menghadapi Keinginan ini..."
  },
  Voice_5703_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5703_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5704_AwakerVoiceContent = {
    Text = "Mengerikan, tempat ini benar-benar mengerikan! Bagaimana bisa kalian membiarkan seorang putri minum teh sore di meja yang sama dengan orang lain! … Rasanya kue kering buatan tangan lumayan enak juga, bawakan sedikit ke kamarku setelah makan malam."
  },
  Voice_5704_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5705_AwakerVoiceContent = {Text = "Hey!"},
  Voice_5705_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5706_AwakerVoiceContent = {
    Text = "Lihat jurus ini!"
  },
  Voice_5706_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_5707_AwakerVoiceContent = {
    Text = "Pelarutan… Di rumah, ada catatan terkait di akademi, tapi Karen benci membaca buku, jadi dia sudah melupakannya semua!"
  },
  Voice_5707_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5708_AwakerVoiceContent = {
    Text = "Apakah Anda ingin saya berlayar lagi? Jika Anda tidak keberatan dengan kelalaian saya sebelumnya, saya akan mencoba melakukannya."
  },
  Voice_5708_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5708_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5709_AwakerVoiceContent = {
    Text = "Hal yang menyebalkan? Terlalu banyak — bos yang memaksa pekerja lembur hingga larut malam, biarawati yang merasa dirinya paling benar, perut yang terus-menerus berbunyi, roti hitam dengan serpihan kaca tertancap di dalamnya..."
  },
  Voice_5709_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5710_AwakerVoiceContent = {
    Text = "Ini semua salah Aigis, semuanya... ini semua kesalahanku…"
  },
  Voice_5710_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5711_AwakerVoiceContent = {
    Text = "Selesaikan ini!"
  },
  Voice_5711_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5712_AwakerVoiceContent = {
    Text = "Berkat perhatian dari Nona Hanna, saya mengikuti latihan paduan suara. Nyanyian paduan suara sangat berbeda dengan nyanyian perahu, selama melindungi kapal, saya belum pernah mendengar melodi yang begitu unik…"
  },
  Voice_5712_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5713_AwakerVoiceContent = {
    Text = "Bagaimana dengan serangan ini!"
  },
  Voice_5713_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5714_AwakerVoiceContent = {
    Text = "Bagaimana dengan serangan ini!"
  },
  Voice_5714_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5715_AwakerVoiceContent = {
    Text = "Sangat menakutkan~"
  },
  Voice_5715_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5716_AwakerVoiceContent = {Text = "Ugh......"},
  Voice_5716_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5717_AwakerVoiceContent = {
    Text = "Halo, Tuan baru saya! Hidangan hari ini ada puding bekicot, sup kodok, dan anggur api hijau. Tuan bisa memilih sesuka hati~"
  },
  Voice_5717_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5718_AwakerVoiceContent = {
    Text = "Apakah itu bentuk aslinya dari Genesis… Tidak, agak berbeda dari yang kubayangkan. Namun, kalau aku juga bisa berubah menjadi seperti itu, akan sangat bagus."
  },
  Voice_5718_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Aequor"
  },
  Voice_5718_UnlockDesc = {
    Text = "Setelah mendapatkan salah satu Pembangun \"Tulu\"\"Murphy\"\"Miryam\"\"Goliath\", akan terbuka."
  },
  Voice_5719_AwakerVoiceContent = {
    Text = "Menunggu saat yang tepat."
  },
  Voice_5719_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5720_AwakerVoiceContent = {
    Text = "Lihat jurus ini!"
  },
  Voice_5720_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5721_AwakerVoiceContent = {
    Text = "Anak domba, kasih sayang Tuhan akan menebus kalian."
  },
  Voice_5721_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5722_AwakerVoiceContent = {
    Text = "Anak domba, kasih sayang Tuhan akan menebus kalian."
  },
  Voice_5722_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5723_AwakerVoiceContent = {Text = "Mati!"},
  Voice_5723_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5724_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5724_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5725_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5725_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5726_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5726_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5727_AwakerVoiceContent = {
    Text = "Dia juga seorang yang malang, pada akhirnya akan dihancurkan oleh takdir. Karena, saat Dia benar-benar dilahirkan, itulah saat aku akan memberikan kematian kepadanya."
  },
  Voice_5727_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Miryam"
  },
  Voice_5727_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Miryam\", akan terbuka."
  },
  Voice_5728_AwakerVoiceContent = {
    Text = "Bermandikan darah!"
  },
  Voice_5728_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5729_AwakerVoiceContent = {
    Text = "Balas dendam…!"
  },
  Voice_5729_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5730_AwakerVoiceContent = {
    Text = "Sakit sekali..."
  },
  Voice_5730_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5731_AwakerVoiceContent = {
    Text = "(Rintihan kesakitan yang terpendam)"
  },
  Voice_5731_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5732_AwakerVoiceContent = {
    Text = "(Rintihan kesakitan yang terpendam)"
  },
  Voice_5732_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5733_AwakerVoiceContent = {Text = "Sakit..."},
  Voice_5733_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5734_AwakerVoiceContent = {
    Text = "Apakah kamu ingin tenggelam bersamaku?"
  },
  Voice_5734_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5735_AwakerVoiceContent = {Text = "Enyahlah!"},
  Voice_5735_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5736_AwakerVoiceContent = {
    Text = "Hal yang menjengkelkan... meja yang penuh dengan barang tak teratur, lemari yang berantakan, ambang jendela berdebu — ya, aku sedang menggambarkan kamarmu. Sebelum pukul tujuh pagi besok, aku ingin melihatnya kembali seperti sebelum kamu menempatinya."
  },
  Voice_5736_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5737_AwakerVoiceContent = {
    Text = "(Humming dengan penuh minat)"
  },
  Voice_5737_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5738_AwakerVoiceContent = {Text = "Menarik!"},
  Voice_5738_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5739_AwakerVoiceContent = {
    Text = "(Tertawa dengan nada meremehkan)"
  },
  Voice_5739_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5740_AwakerVoiceContent = {
    Text = "Jika diperlukan, aku bisa meninggalkan ayunan..."
  },
  Voice_5740_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5741_AwakerVoiceContent = {Text = "Mau?"},
  Voice_5741_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_5742_AwakerVoiceContent = {
    Text = "Lihat~ jurus!"
  },
  Voice_5742_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5743_AwakerVoiceContent = {
    Text = "Double.double.double!"
  },
  Voice_5743_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5744_AwakerVoiceContent = {
    Text = "Ini mengingatkanku pada sepasang sepatu dansa merah pertama yang kuterima saat berusia delapan tahun. Aku sangat menyukainya, terima kasih banyak, Penjaga."
  },
  Voice_5744_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5744_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5745_AwakerVoiceContent = {
    Text = "Teman... apakah ini Tuan? Atau Ibu?"
  },
  Voice_5745_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5746_AwakerVoiceContent = {
    Text = "Perlindunganku, kadang-kadang juga bisa gagal…"
  },
  Voice_5746_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5747_AwakerVoiceContent = {
    Text = "(Mengerang tertahan)"
  },
  Voice_5747_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5748_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_5748_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5749_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_5749_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5750_AwakerVoiceContent = {
    Text = "Apa yang disukai? Di medan perang Peloponnesia, ada juga yang menanyakan hal ini padaku… Sudah terlambat, aku telah lama meninggalkan preferensi pribadi seperti itu."
  },
  Voice_5750_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5751_AwakerVoiceContent = {
    Text = "Shh... tentang aku yang menjadi lebih kuat, tolong jangan biarkan \"mereka\" mengetahuinya."
  },
  Voice_5751_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5752_AwakerVoiceContent = {
    Text = "\"Mereka\" berkata… sangat berterima kasih."
  },
  Voice_5752_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5753_AwakerVoiceContent = {
    Text = "Eh... Apa ini?"
  },
  Voice_5753_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5754_AwakerVoiceContent = {
    Text = "Ini hanya akan membuatku semakin dekat dengan Jurang."
  },
  Voice_5754_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5754_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5755_AwakerVoiceContent = {
    Text = "Kamu adalah pelayan kesayanganku. Aku tahu, kalian menyebut ini sebagai teman, sahabat, kawan... tidak masalah, terserah apa yang membuatmu senang."
  },
  Voice_5755_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5756_AwakerVoiceContent = {
    Text = "Aku mendapatkan jawabannya... meskipun itu bukan jawaban yang kuharapkan, namun aku tetap mendapatkannya."
  },
  Voice_5756_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5756_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5757_AwakerVoiceContent = {
    Text = "Apakah itu \"ketakutan\"? Atau \"kesedihan\"? Wajahmu yang lesu sungguh memikat."
  },
  Voice_5757_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5757_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5758_AwakerVoiceContent = {
    Text = "Bau kematian dan kehancuran, begitu jelas."
  },
  Voice_5758_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5758_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5759_AwakerVoiceContent = {
    Text = "Bagaimana kehidupan di sini? Lumayan, lumayan baik. Selama aku memberikan beberapa pengetahuan tentang ilmu mekanik dan penelitian roh kepada Nyonya Boneka, dia mengizinkanku untuk terus menyalakan lampu."
  },
  Voice_5759_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5760_AwakerVoiceContent = {
    Text = "Semoga Jenkin dan Cokelat menikmati waktu mereka di akademi. Kancing lengan ayah tidak ada artinya dibandingkan dengan kenyamanannya, dan saya yakin dia masih memiliki satu kotak penuh cadangan."
  },
  Voice_5760_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Jenkin"
  },
  Voice_5760_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Jenkin\", akan terbuka."
  },
  Voice_5761_AwakerVoiceContent = {
    Text = "Tidak bisa pergi..."
  },
  Voice_5761_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5762_AwakerVoiceContent = {
    Text = "Setelah terbebas dari ras rendahan, aku sama sekali tidak takut dengan pengaruh ini. Meskipun Tubuh yang menjadi wadah hancur, darah bangsawan tidak akan pernah musnah."
  },
  Voice_5762_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5763_AwakerVoiceContent = {
    Text = "Benci orang yang tersenyum palsu! Tidak ada emosi yang bisa dicuri dari mereka!"
  },
  Voice_5763_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5764_AwakerVoiceContent = {
    Text = "Hmm? Kenapa semua orang diam? Karen benci suasana yang sunyi, aku akan menceritakan sebuah cerita kepada kalian. Dahulu kala, ada sebuah gunung..."
  },
  Voice_5764_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5765_AwakerVoiceContent = {
    Text = "Lily akan meraih masa depan… Tokuli—Li!"
  },
  Voice_5765_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5766_AwakerVoiceContent = {
    Text = "Lily akan meraih masa depan… Tokuli—Li!"
  },
  Voice_5766_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5767_AwakerVoiceContent = {
    Text = "Jika kau melakukannya untuk merasakan keberadaan-Nya, maka untuk sementara aku akan memaafkan ketidaksopananmu."
  },
  Voice_5767_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5768_AwakerVoiceContent = {
    Text = "Tidak mau melakukannya..."
  },
  Voice_5768_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5769_AwakerVoiceContent = {
    Text = "Jangan mendekat!"
  },
  Voice_5769_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5770_AwakerVoiceContent = {
    Text = "Perlahan. Perlahan bisa mengikuti ritme komando Anda!"
  },
  Voice_5770_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5771_AwakerVoiceContent = {
    Text = "Semakin dekat untuk menjadi ksatria resmi!"
  },
  Voice_5771_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5772_AwakerVoiceContent = {
    Text = "Terima kasih atas angkatannya, sangat terhormat"
  },
  Voice_5772_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5773_AwakerVoiceContent = {
    Text = "Pemandian adalah tempat yang bagus untuk menghabiskan waktu. Tidak hanya makanannya enak, tetapi juga menawarkan layanan relaksasi otot. Tertarik? Kalau begitu, bangun satu di sekolah segera!"
  },
  Voice_5773_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5774_AwakerVoiceContent = {
    Text = "Tidak, jangan pergi!"
  },
  Voice_5774_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5775_AwakerVoiceContent = {
    Text = "Sudah siap."
  },
  Voice_5775_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5776_AwakerVoiceContent = {
    Text = "(Gemuruh kesakitan)"
  },
  Voice_5776_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5777_AwakerVoiceContent = {
