  },
  Voice_5780_AwakerVoiceContent = {
    Text = "Serahkan saja padaku."
  },
  Voice_5780_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_57818_AwakerVoiceContent = {
    Text = "Semua orang yang menghina saya harus membayar harganya!"
  },
  Voice_57818_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_57819_AwakerVoiceContent = {
