  },
  Voice_57835_AwakerVoiceContent = {
    Text = "Segala sesuatu adalah bagian dari rencana-Nya."
  },
  Voice_57835_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_57836_AwakerVoiceContent = {
    Text = "Dari entitas yang datang dari antara bintang-bintang, kami menyampaikan undangan kepada Anda."
