  },
  Voice_57849_AwakerVoiceContent = {
    Text = "Jangan bergerak! Jangan bergerak! Jangan bergerak!"
  },
  Voice_57849_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_5784_AwakerVoiceContent = {Text = "Hehe."},
  Voice_5784_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_57850_AwakerVoiceContent = {
    Text = "Saksikanlah, inilah kekuatan yang menjadi andalan Perishite!"
  },
  Voice_57850_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_57851_AwakerVoiceContent = {
    Text = "Saksikanlah, inilah kekuatan yang menjadi andalan Perishite!"
  },
  Voice_57851_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_5785_AwakerVoiceContent = {
    Text = "Terlalu lemah."
  },
  Voice_5785_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5786_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5786_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5787_AwakerVoiceContent = {
    Text = "Hmm... tampaknya tuan sedang tidak dalam suasana hati yang baik? Karen akan membuat wajah lucu, hi——ha! \n Bagaimana, apakah sekarang kamu merasa lebih baik?"
  },
  Voice_5787_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5788_AwakerVoiceContent = {
    Text = "Dengan kebijaksanaan manusia... ungkap esensi dunia!"
  },
  Voice_5788_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5789_AwakerVoiceContent = {
    Text = "Saya menemui beberapa orang yang membuat saya merasa tidak nyaman di koridor. Mungkin karena situasi yang memaksa, Anda harus berjuang bersama mereka, tetapi tetap waspada. Tidak ada yang lebih kejam dari perang kecuali hati manusia; penghianatan yang paling mengerikan sering berasal dari dalam."
  },
  Voice_5789_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang @2"
  },
  Voice_5789_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Helot\" atau \"Lily\", akan dibuka."
  },
  Voice_5790_AwakerVoiceContent = {
    Text = [[
Apakah kamu sudah menyelesaikan pekerjaan rumahmu? Bisakah kamu menemaniku ke pusat kota Londinium... Eh? Kamu belum menyelesaikan pekerjaan rumah matematikamu?! 
Ah, ah... Maaf, aku tidak menyangka ada orang yang tidak mengerti kalkulus... Biar aku membantu kamu, ya?]]
  },
  Voice_5790_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Belajar"
  },
  Voice_5791_AwakerVoiceContent = {
    Text = "Saya bersumpah kepada Anda, pemilik toko itu pasti pernah muncul di salon Fontainebleau… Jadi begitu, sejak saat itu dia sudah seperti ini? Aku tidak tahu berapa banyak rahasia yang bisa kudapatkan darinya…"
  },
  Voice_5791_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Daffdell"
  },
  Voice_5791_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Narsis\", akan terbuka."
  },
  Voice_5792_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_5792_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5793_AwakerVoiceContent = {
    Text = "Jangan sampai pecah."
  },
  Voice_5793_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5794_AwakerVoiceContent = {
    Text = "Aurita suka bermain dengan semua orang! Apakah kamu juga mau ikut? Anak ini bernama Jelly, yang itu adalah Hela, dan yang di sana juga bernama Jelly… Eh?"
  },
  Voice_5794_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5795_AwakerVoiceContent = {
    Text = "Rasa malu, bersihkan dengan cara ini!"
  },
  Voice_5795_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5796_AwakerVoiceContent = {
    Text = "Toko kecil Narsis sudah buka, anak-anak yang belum siap sebaiknya jangan masuk sembarangan, ya?"
  },
  Voice_5796_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5796_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5797_AwakerVoiceContent = {
    Text = "Jangan sentuh leherku... Tidak terlihat bukan berarti tidak ada."
  },
  Voice_5797_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5798_AwakerVoiceContent = {
    Text = "Saya suka orang yang memiliki keyakinan, baik itu hewan, Pembangun, maupun manusia. Jika mereka juga memiliki keahlian bela diri yang luar biasa, itu lebih bagus lagi."
  },
  Voice_5798_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5799_AwakerVoiceContent = {Text = "Pergilah."},
  Voice_5799_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5800_AwakerVoiceContent = {
    Text = "Jangan khawatir!"
  },
  Voice_5800_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5801_AwakerVoiceContent = {
    Text = "Ramona membenci kehilangan... maaf, maksud saya, aku tidak suka perpisahan, ini terlalu menyedihkan."
  },
  Voice_5801_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5802_AwakerVoiceContent = {
    Text = "Saya tidak terlalu pandai bergaul dengan para pemuka agama. Mereka membosankan dan kaku, serta menyerahkan ikat pinggang mereka kepada \"Tuhan\" yang mereka hormati. Sungguh disayangkan, Padahal Tuan Salvador memiliki aroma yang begitu manis…"
  },
  Voice_5802_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Salvador"
  },
  Voice_5802_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Salvador\", akan terbuka."
  },
  Voice_5803_AwakerVoiceContent = {
    Text = "Kemenangan dalam pertarungan yang mendebarkan melampaui segalanya, termasuk hasil akhir menang atau kalah."
  },
  Voice_5803_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5804_AwakerVoiceContent = {
    Text = "Siapa yang tidak suka kasur yang empuk dan ruangan dengan sistem pembuangan air yang tidak bocor… seperti itu."
  },
  Voice_5804_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5805_AwakerVoiceContent = {
    Text = "... jangan biarkan aku mengingatnya ... hari-hari ketika aku terkurung di Elworth ..."
  },
  Voice_5805_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5806_AwakerVoiceContent = {
    Text = "Bakar habis semuanya!"
  },
  Voice_5806_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5807_AwakerVoiceContent = {
    Text = "Bakar habis semuanya!"
  },
  Voice_5807_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5808_AwakerVoiceContent = {
    Text = "Aku mengikuti aroma darah dan menemukan tempat ini. Permisi… apakah di sini menyediakan kantong darah segar?"
  },
  Voice_5808_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5809_AwakerVoiceContent = {
    Text = "Hmm… Agrippa juga punya banyak teman, tapi semua orang terlihat takut padanya. Mungkinkah, dia suka mengambil makanan dari teman-temannya?"
  },
  Voice_5809_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Agrippa"
  },
  Voice_5809_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Agrippa\", akan terbuka."
  },
  Voice_5810_AwakerVoiceContent = {
    Text = "Hidupku hanya dipenuhi dengan tarian. Bahkan jika aku belajar pengetahuan lain, sulit bagiku untuk berkembang. Namun, semua orang di sini adalah orang-orang baik. Mereka tidak akan menjualku demi kebanggaan atau uang. Aku bisa merasakannya."
  },
  Voice_5810_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5811_AwakerVoiceContent = {
    Text = "Pengecut! Meskipun kau memiliki kekuatan yang mirip denganku, kau menekan dirimu seperti ini. Apa bedanya dengan memasang kalung di leher secara sukarela!"
  },
  Voice_5811_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Lily"
  },
  Voice_5811_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Lily\", akan terbuka."
  },
  Voice_5812_AwakerVoiceContent = {
    Text = "Tidak cukup... kekuatan masih belum cukup..."
  },
  Voice_5812_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5813_AwakerVoiceContent = {
    Text = "Kembali saja."
  },
  Voice_5813_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5814_AwakerVoiceContent = {Text = "Ya!"},
  Voice_5814_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5815_AwakerVoiceContent = {
    Text = "Topi tinggi, topi bowler, topi berburu rusa, topi beret... harus kukatakan, upaya kalian para pria dari kalangan atas untuk menutupi kebotakan tampak sangat menggelikan."
  },
  Voice_5815_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Etika"
  },
  Voice_5816_AwakerVoiceContent = {
    Text = "Saya sangat mengagumi orang itu, putih dan anggun seperti Dewa pelayaran bunga lili... Apakah Anda mengatakan bahwa dia, yang begitu luar biasa, juga tidak bisa mengendalikan nasibnya sendiri dan akhirnya tenggelam di dasar laut? Ini benar-benar sulit dibayangkan..."
  },
  Voice_5816_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Celeste"
  },
  Voice_5816_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Celeste\", akan dibuka."
  },
  Voice_5817_AwakerVoiceContent = {
    Text = "Tidak ada yang dapat menandingi kekuatan raksasa di dunia ini!"
  },
  Voice_5817_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5818_AwakerVoiceContent = {
    Text = "Tidak ada yang dapat menandingi kekuatan raksasa di dunia ini!"
  },
  Voice_5818_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5819_AwakerVoiceContent = {
    Text = "Sial, sial...! Kekuatan hanya akan mengurungku di dalam tubuhku..."
  },
  Voice_5819_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5819_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5820_AwakerVoiceContent = {
    Text = "Ingin sekali tinggal di tempat yang selalu terang benderang… Ya, kutub. Di planet ini, hanya kutub saja."
  },
  Voice_5820_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5820_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5821_AwakerVoiceContent = {
    Text = "Aku... aku tidak bisa menanggung tanggung jawab besar apa pun, aku hanya bisa mengejar cahaya. Jadi, tolong jangan berhenti berkedip…"
  },
  Voice_5821_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5821_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5822_AwakerVoiceContent = {
    Text = "Jika masih bisa berpindah, aku ingin menjadi sebuah bintang..."
  },
  Voice_5822_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5822_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5823_AwakerVoiceContent = {
    Text = "Berapa pun perhitungannya, rumus untuk mentransfer kesadaran tetap tidak terpecahkan…"
  },
  Voice_5823_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5823_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5824_AwakerVoiceContent = {
    Text = "Selamat datang, mari bersama-sama berpesta!"
  },
  Voice_5824_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5825_AwakerVoiceContent = {
    Text = "Ini Pesananmu!"
  },
  Voice_5825_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5826_AwakerVoiceContent = {
    Text = "Huuu—ini Aurita! Satu, dua, tiga… Wah! Selamat datang, selamat datang! Anggota baru bertambah! Hmm? Apakah aku yang menjadi anggota baru bagi kalian? Bisa dibilang begitu juga!"
  },
  Voice_5826_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5827_AwakerVoiceContent = {
    Text = "Kalian menyebut mainan kecil ini sebagai pistol? Hanya berani menyerang lawan dari bayangan, memang senjata pengecut."
  },
  Voice_5827_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5828_AwakerVoiceContent = {
    Text = "Tidak ada artinya. Melakukan ini benar-benar tidak ada artinya."
  },
  Voice_5828_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5829_AwakerVoiceContent = {
    Text = "Kamu benar-benar tidak mengerti apa pun."
  },
  Voice_5829_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5830_AwakerVoiceContent = {
    Text = "Masih berharap aku menjadi \"penyelamat\" pendukung?"
  },
  Voice_5830_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5831_AwakerVoiceContent = {
    Text = "Maaf, apakah kamu melihat sekrup saya? Sungguh aneh, setiap kali anak dengan telinga tikus itu ada di sekitar, sepertinya saya lebih mudah lupa ke mana saya meletakkan barang-barang saya…"
  },
  Voice_5831_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Jenkin"
  },
  Voice_5831_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Jenkin\", akan terbuka."
  },
  Voice_5832_AwakerVoiceContent = {
    Text = "Aku tidak akan melupakan segala sesuatu yang kau persembahkan untuk pertemuan kembali antara aku dan Tuhanku…"
  },
  Voice_5832_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5833_AwakerVoiceContent = {
    Text = "Seperti ukiran dalam lagu!"
  },
  Voice_5833_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5834_AwakerVoiceContent = {
    Text = "Apakah kamu sudah mengabulkan keinginanku?"
  },
  Voice_5834_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5835_AwakerVoiceContent = {
    Text = "Mudah-mudahan kepemimpinanmu tidak akan mengecewakan."
  },
  Voice_5835_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5836_AwakerVoiceContent = {
    Text = "Apakah yang meningkat adalah tubuh ini atau kesadaran saya? Topik yang menarik."
  },
  Voice_5836_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5836_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5837_AwakerVoiceContent = {Text = "Mundur."},
  Voice_5837_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5838_AwakerVoiceContent = {Text = "Minggir."},
  Voice_5838_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5839_AwakerVoiceContent = {
    Text = "Di dalam pembuluh darahku mengalir keinginan untuk bertahan hidup, itu berteriak, mendorongku untuk meneteskan darah di setiap inci tanah Planet ini… Ah, maafkan aku karena banyak mengeluh, sungguh memalukan. Aku Thais, kau memanggilku, apakah kau sudah siap untuk menyatu denganku?"
  },
  Voice_5839_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5840_AwakerVoiceContent = {
    Text = "Jika saja Aigis bisa menanggung cairan hitam ini untuk semua orang… Lagipula, Aigis tidak pernah ada, itu seharusnya hal yang baik bagi dunia ini, kan?"
  },
  Voice_5840_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5841_AwakerVoiceContent = {
    Text = "Hobi saya adalah Konjektur Riemann — itu adalah ungkapan favorit si burung merak, bukan milik saya. Sebagai perbandingan, saya lebih tertarik pada penelitian tentang standar atom."
  },
  Voice_5841_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5842_AwakerVoiceContent = {
    Text = "Rasanya diusir dari rumah dan mengembara di laut... sekali saja sudah cukup."
  },
  Voice_5842_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5844_AwakerVoiceContent = {
    Text = "Lihat baik-baik!"
  },
  Voice_5844_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5845_AwakerVoiceContent = {
    Text = "Lihat baik-baik!"
  },
  Voice_5845_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5846_AwakerVoiceContent = {
    Text = "Selama kau bisa mempertahankan keadilan ini, aku akan terus menjalankan tugas sebagai pedang yang tajam."
  },
  Voice_5846_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5847_AwakerVoiceContent = {
    Text = "Apakah Anda tahu bahwa ada legenda tentang \"Sang Pelukis\" yang beredar di sini? Dari gaya grafiti ekspresionis itu, saya mencium sedikit aroma yang familiar……"
  },
  Voice_5847_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5848_AwakerVoiceContent = {
    Text = "Sakit sekali, sangat bersemangat——"
  },
  Voice_5848_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5849_AwakerVoiceContent = {
    Text = "Rasakan amarahku!"
  },
  Voice_5849_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5850_AwakerVoiceContent = {
    Text = "Mari kita catat kemenangan ini dalam bentuk syair."
  },
  Voice_5850_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5851_AwakerVoiceContent = {
    Text = "Tumbuhlah——"
  },
  Voice_5851_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5852_AwakerVoiceContent = {
    Text = "Lihat jurus ini!"
  },
  Voice_5852_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5853_AwakerVoiceContent = {Text = "Eh!"},
  Voice_5853_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5854_AwakerVoiceContent = {
    Text = "Mungkin setelah dewasa, aku bisa mengendalikan diri agar tidak menghisap habis kehidupan orang lain… sedikit saja sudah cukup untuk bertahan hidup."
  },
  Voice_5854_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5854_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5855_AwakerVoiceContent = {
    Text = "Sepertinya menjadi lebih berat, apakah ayunan masih bisa menahan beban saya?"
  },
  Voice_5855_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5855_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5856_AwakerVoiceContent = {
    Text = "Kekuatan hampir meluap, punggung terasa gatal. Apakah ini pertanda akan tumbuh dewasa?"
  },
  Voice_5856_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_5856_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_5857_AwakerVoiceContent = {
    Text = "Meskipun masih memiliki penampilan seperti anak kecil, aku sekarang... sudah memiliki kekuatan untuk melindungimu."
  },
  Voice_5857_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5857_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5858_AwakerVoiceContent = {
    Text = "Aku akan berusaha untuk tumbuh dewasa."
  },
  Voice_5858_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_5858_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_5859_AwakerVoiceContent = {
    Text = "Tidak tahu diri, kenapa begitu ngotot untuk membangunku?"
  },
  Voice_5859_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5860_AwakerVoiceContent = {
    Text = "Aku akan menjadi Ibu dari para Dewa!"
  },
  Voice_5860_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5861_AwakerVoiceContent = {
    Text = "Ini sudah pemanggilan yang keberapa kalinya… Manusia, sebaiknya kau sudah menyiapkan cukup \"makanan\" untukku, jika tidak, aku tidak bisa menjamin apa pun."
  },
  Voice_5861_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5862_AwakerVoiceContent = {
    Text = "Di luar Pintu!"
  },
  Voice_5862_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5863_AwakerVoiceContent = {Text = "Bodoh."},
  Voice_5863_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5864_AwakerVoiceContent = {Text = "Haha"},
  Voice_5864_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5865_AwakerVoiceContent = {
    Text = "Hmph, tidak buruk. Di pertarungan berikutnya, aku akan menggunakan semua kemampuanku."
  },
  Voice_5865_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5866_AwakerVoiceContent = {
    Text = "Orang yang kasar!"
  },
  Voice_5866_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_5867_AwakerVoiceContent = {
    Text = "Terkadang, keindahan seni adalah keindahan kehancuran. Dan kegagalan Anda… jelas tidak termasuk dalam kategori itu."
  },
  Voice_5867_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5868_AwakerVoiceContent = {
    Text = "Anda adalah pendengar paling penting bagi saya. Kapan pun, saya akan selalu siap untuk menyanyikan lagu dan memberikan segalanya untuk Anda."
  },
  Voice_5868_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5869_AwakerVoiceContent = {
    Text = "Hal yang disukai? Rumput air, gerombolan ikan, tiang koridor, labirin... Tentu saja aku pernah melihatnya! Semua ada di buku Paman Oen!"
  },
  Voice_5869_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5870_AwakerVoiceContent = {
    Text = "Apakah ini persiapan untuk misi Penyelidikan? Saya mengerti."
  },
  Voice_5870_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5870_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5871_AwakerVoiceContent = {
    Text = "Nama saya Celeste. Selama kamu masih membutuhkanku, aku akan tetap ada di sini."
  },
  Voice_5871_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5872_AwakerVoiceContent = {
    Text = "Rasakan hukuman ini!"
  },
  Voice_5872_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5873_AwakerVoiceContent = {
    Text = "Hormati yang lebih tua, pemuda. Di militer, ada tatanan senioritas dan ketaatan pada perintah. Perilaku seperti ini akan dihukum."
  },
  Voice_5873_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5874_AwakerVoiceContent = {
    Text = "Saya sebenarnya bersedia memberikan layanan purna jual untuk \"mainan kecil\"itu, masalahnya adalah, apakah kalian berani menerima layanan saya?"
  },
  Voice_5874_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penemuan"
  },
  Voice_5875_AwakerVoiceContent = {
    Text = "Anda adalah tuan rumah di sini, tetapi juga tamu di salon saya. Saya akan menyiapkan penyambutan terbaik untuk kunjungan Anda — apakah Anda lebih menyukai balutan rok berwarna merah cerah, atau piyama berwarna putih mawar?"
  },
  Voice_5875_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5876_AwakerVoiceContent = {
    Text = "Maaf, sinar matahari di sini agak menyilaukan... Tikus dari gua yang gelap belum bisa beradaptasi untuk sementara waktu."
  },
  Voice_5876_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5877_AwakerVoiceContent = {
    Text = "Bisa mengikis segalanya, menghapus semuanya… itu adalah senjata yang luar biasa. Jika saja aku tahu saat itu… hah."
  },
  Voice_5877_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5878_AwakerVoiceContent = {
    Text = "Ada rumor yang mengatakan bahwa tubuh manusia yang berkejang di dalam api menyala tampak seperti sedang menari."
  },
  Voice_5878_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Api"
  },
  Voice_5880_AwakerVoiceContent = {
    Text = "Jangan keluar di malam hari, bahkan dengan sumber cahaya 2000 lumens pun tidak sepenuhnya aman... Begitu melangkah ke dalam kegelapan, iblis-iblis yang bersembunyi di luar pandangan akan mengejarmu, melahapmu, mengejarmu, melahapmu… sampai tidak ada yang tersisa."
  },
  Voice_5880_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Malam"
  },
  Voice_5881_AwakerVoiceContent = {
    Text = "Menangislah."
  },
  Voice_5881_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5882_AwakerVoiceContent = {Text = "Diterima."},
  Voice_5882_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5883_AwakerVoiceContent = {
    Text = "Itu adalah kerinduan akan hidup, yang mendorong angsa untuk berjuang demi kembali ke langit yang jauh."
  },
  Voice_5883_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5883_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5884_AwakerVoiceContent = {
    Text = "Mulai berubah!"
  },
  Voice_5884_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5885_AwakerVoiceContent = {Text = "Tolong!"},
  Voice_5885_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5886_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_5886_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_5887_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_5887_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5888_AwakerVoiceContent = {Text = "Ah"},
  Voice_5888_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5889_AwakerVoiceContent = {
    Text = [[
Ah, Cokelat berlari melewati! A-aku... sebaiknya aku menghindar saja... 
 Meskipun aku ingin menjadi temannya, tak disangka akhirnya aku malah menjadi mimpi buruknya... Dia pasti tidak ingin melihatku lagi...]]
  },
  Voice_5889_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Jenkin"
  },
  Voice_5889_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Jenkin\", akan terbuka."
  },
  Voice_5890_AwakerVoiceContent = {
    Text = "Kapel? Terima kasih banyak, tapi sebenarnya aku tidak terlalu konservatif. Selama aku selalu mengingat ajaran Tuhan yang penuh kasih dan melaksanakan kehendak-Nya setiap saat, jiwa saya tidak akan pernah jauh dari kemuliaan-Nya."
  },
  Voice_5890_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Kapel"
  },
  Voice_5891_AwakerVoiceContent = {
    Text = "Nama saya Ogier. Sesuai dengan Kontrak bersama Anda, saya akan mempersembahkan kesetiaan seorang ksatria untuk melindungi keselamatan Anda dan menghilangkan ancaman musuh-musuh Anda. Sumpah hari ini tidak akan pernah dilupakan."
  },
  Voice_5891_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5892_AwakerVoiceContent = {
    Text = "Wanita berkerut dengan mata ganda itu, baunya sama persis dengan kutu busuk dari Sparta."
  },
  Voice_5892_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Agrippa"
  },
  Voice_5892_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Agrippa\", akan terbuka."
  },
  Voice_5893_AwakerVoiceContent = {
    Text = "Apa yang disukai? Tentu saja keberuntungan yang baik. Setiap hari sebelum keluar rumah, selalu mencari tanda-tanda keberuntungan."
  },
  Voice_5893_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5894_AwakerVoiceContent = {
    Text = "Tolong, tolong jangan beritahu Nona Hannah bahwa aku bersembunyi di sini. Aku belum siap…"
  },
  Voice_5894_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Hanna"
  },
  Voice_5895_AwakerVoiceContent = {
    Text = "Bagaimana dengan ini?"
  },
  Voice_5895_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5896_AwakerVoiceContent = {
    Text = "Anda adalah tamu terhormat saya. Ketahuilah, saya hanya bisa mengizinkan Anda berhutang. Lagipula, sudah bertahun-tahun saya tidak melihat kepala seorang pun yang begitu sempurna seperti ini…"
  },
  Voice_5896_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5897_AwakerVoiceContent = {Text = "Aduh!"},
  Voice_5897_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5898_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_5898_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5899_AwakerVoiceContent = {Text = "Aduh!"},
  Voice_5899_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5900_AwakerVoiceContent = {
    Text = "Hal yang disukai… seorang raja tidak seharusnya memiliki sifat seperti itu, tetapi jika bisa terbebas dari laporan dan doa yang menjemukan, berbaring di atas ranjang yang empuk, tentu saja aku akan menikmati ketenangan ini."
  },
  Voice_5900_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5901_AwakerVoiceContent = {
    Text = "Aku akan menganggap tindakan tidak hormat kalian sebagai permintaan untuk tidur panjang."
  },
  Voice_5901_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5902_AwakerVoiceContent = {
    Text = "Benci? Aku benci takdir yang tidak bisa dihindari dan tragedi yang pasti terjadi."
  },
  Voice_5902_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5903_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5903_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5904_AwakerVoiceContent = {
    Text = "(Humming yang tertahan)"
  },
  Voice_5904_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5905_AwakerVoiceContent = {
    Text = "Jangan mendekat!"
  },
  Voice_5905_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5906_AwakerVoiceContent = {
    Text = "Oh, ingin tahu rahasia saya? Nama ini, tubuh ini, wajah ini, suara ini, semuanya berasal dari pemilik sebuah kepala di San Pedro. Dia melakukan transaksi dengan saya... setelah dia meninggal, saya menjadi dia. Adapun keberadaannya... itu adalah koleksi terindah saya, lho?"
  },
  Voice_5906_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5906_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5907_AwakerVoiceContent = {
    Text = "Anda adalah tamu yang sangat menyenangkan, bahkan saya pun terpesona oleh kepala unik Anda ini… Jika Anda berniat untuk mentransfernya, pastikan untuk mengunjungi toko kecil saya. Hehe… hanya bercanda dengan Anda."
  },
  Voice_5907_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5907_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5908_AwakerVoiceContent = {
    Text = "Mencari tahu identitas asli saya? Masih terlalu dini untuk itu. Yang perlu Anda percayai hanyalah ini: setiap anak yang tersesat bisa menemukan tempat berlabuh di tokoku. Termasuk Anda juga, kan?"
  },
  Voice_5908_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5908_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5909_AwakerVoiceContent = {
    Text = "Tidak ada yang akan menerima kerusakan."
  },
  Voice_5909_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5910_AwakerVoiceContent = {
    Text = "Belum selesai!"
  },
  Voice_5910_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5911_AwakerVoiceContent = {
    Text = [[
Melihat usaha keras Anda, saya merasa sedikit tidak enak untuk segera meminta bayaran. Jadi, kepala Anda untuk sementara bisa tetap di tempatnya.
Namun, jangan lupa, kepala itu sudah menjadi milik pribadi saya, kan?]]
  },
  Voice_5911_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5911_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5912_AwakerVoiceContent = {
    Text = "Dulu aku tidak seperti ini, dia yang memberiku hidup baru. Jadi, kau juga adalah orang yang memberiku hidup kedua, dan aku akan dengan baik menjaga kepalamu."
  },
  Voice_5912_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5912_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5913_AwakerVoiceContent = {
    Text = "Benar-benar melarikan diri dari kegelapan."
  },
  Voice_5913_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5914_AwakerVoiceContent = {
    Text = "Ternyata petualangan itu sangat berbahaya..."
  },
  Voice_5914_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_5915_AwakerVoiceContent = {
    Text = "Kenapa gadis bodoh itu langsung lari begitu melihatku? Lain kali aku akan menginjak benang wolnya, lihat ke mana dia bisa lari."
  },
  Voice_5915_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Aigis"
  },
  Voice_5915_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Aigis\", akan terbuka."
  },
  Voice_5916_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_5916_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5917_AwakerVoiceContent = {Text = "Hm~hahaha!"},
  Voice_5917_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5918_AwakerVoiceContent = {Text = "Hahahaha!"},
  Voice_5918_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5919_AwakerVoiceContent = {
    Text = "Anak itu sangat cerdas, kebijaksanaan seperti itulah yang dibutuhkan untuk bertahan hidup di jalanan. Jika aku masih menyelidiki kasus di luar, aku pasti akan menjalin hubungan baik dengannya."
  },
  Voice_5919_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Jenkin"
  },
  Voice_5919_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Jenkin\", akan terbuka."
  },
  Voice_5920_AwakerVoiceContent = {
    Text = "Ayah Suci itu tidak bisa menyelamatkan semua orang. Mungkin dia bisa membantu satu orang yang malang, tapi tidak bisa menarik semua orang keluar dari lumpur... Aku sangat menantikannya, menantikan runtuhnya keyakinannya."
  },
  Voice_5920_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Salvador"
  },
  Voice_5920_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Salvador\", akan terbuka."
  },
  Voice_5921_AwakerVoiceContent = {
    Text = "Anda bisa menemukan semua yang Anda butuhkan di saluran air bawah tanah Londinium: salmon, sabun, wiski yang diminum setengahnya… \n Apa? Anda bertanya mengapa saya begitu tahu? Saya pernah menyeret mayat kakak saya, merangkak sejauh lima li di dalam sana…"
  },
  Voice_5921_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Saluran Pembuangan"
  },
  Voice_5922_AwakerVoiceContent = {
    Text = "Berlututlah di hadapanku!"
  },
  Voice_5922_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5923_AwakerVoiceContent = {
    Text = "Berlututlah di hadapanku."
  },
  Voice_5923_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5924_AwakerVoiceContent = {
    Text = "Setelah melihat dunia nyata di luar pertempuran, saya sempat meragukan nilai dari apa yang disebut \"pahlawan\". Namun, untungnya saya bertemu denganmu, seseorang yang jujur, berani, dan tanpa cela. Saya akan berada di bawah komandomu, berjuang sepenuh hati demi perdamaian dan stabilitas dunia. Kali ini, saya pasti bisa menyelesaikan penebusan dosa saya."
  },
  Voice_5924_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5924_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5925_AwakerVoiceContent = {
    Text = "Yaa! Buruk sekali…"
  },
  Voice_5925_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5926_AwakerVoiceContent = {
    Text = "Tidak suci, kotor, kekacauan — inilah kekuatan kita."
  },
  Voice_5926_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5927_AwakerVoiceContent = {
    Text = "Aku benci sikap kalian yang berpura-pura. Kalian pikir aku gila, aku kasihan, ya? Di mataku, kalian seperti Icarus yang terbakar karena matahari, kalian yang sebenarnya menyedihkan."
  },
  Voice_5927_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5928_AwakerVoiceContent = {
    Text = "Biarkan aku menjadi yang pertama menyerang!"
  },
  Voice_5928_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_5929_AwakerVoiceContent = {
    Text = "Aura mereka terasa asing, mereka bukan kehidupan yang lahir secara alami dari planet ini, kan."
  },
  Voice_5929_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Orang-orang dari Luar Bintang"
  },
  Voice_5929_UnlockDesc = {
    Text = "Setelah mendapatkan salah satu Pembangun \"Kerang\", \"Tinct\", \"Pingsan\", atau \"Wanda\", akan dibuka."
  },
  Voice_5931_AwakerVoiceContent = {
    Text = "(Mengerang tertahan)"
  },
  Voice_5931_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_5932_AwakerVoiceContent = {Text = "Hilanglah!"},
  Voice_5932_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  },
  Voice_5933_AwakerVoiceContent = {
    Text = "Mohon jangan..."
  },
  Voice_5933_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5934_AwakerVoiceContent = {
    Text = "Meskipun menjadi monster juga tidak apa-apa, yang aku inginkan sejak awal hanyalah kekuatan untuk balas dendam."
  },
  Voice_5934_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5934_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5935_AwakerVoiceContent = {
    Text = "Selain menghilangkan lawan, apakah ada hal lain yang kamu inginkan? Sebagai imbalan, aku akan mengabulkan keinginanmu… tentu saja, selama masih dalam batas Kemampuan."
  },
  Voice_5935_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_5935_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_5936_AwakerVoiceContent = {
    Text = "(Mengerang tertahan)"
  },
  Voice_5936_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_5937_AwakerVoiceContent = {
    Text = "Teman? ...Aku akan mempertimbangkannya. Sebelum aku memutuskan, jangan mati begitu saja."
  },
  Voice_5937_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_5937_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_5938_AwakerVoiceContent = {
    Text = "Sejak pertama kali dicatat secara eksplisit, Fenomena-d telah memengaruhi kehidupan lebih dari satu juta orang. Tindakan kita menentukan kelangsungan hidup seluruh umat manusia."
  },
  Voice_5938_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5939_AwakerVoiceContent = {
    Text = "Tenaga penuh!"
  },
  Voice_5939_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5940_AwakerVoiceContent = {
    Text = "Hati-hati terhadap keganasan laut."
  },
  Voice_5940_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5941_AwakerVoiceContent = {
    Text = "Hati-hati terhadap keganasan laut."
  },
  Voice_5941_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5942_AwakerVoiceContent = {Text = "Hei!"},
  Voice_5942_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5943_AwakerVoiceContent = {
    Text = "Aku adalah putri-Nya, juga ibu-Nya. Adapun kamu, di hadapan-Nya hanyalah semut yang tak berarti."
  },
  Voice_5943_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5944_AwakerVoiceContent = {
    Text = "Semuanya berjalan dengan baik, mari kita naikkan layar kemenangan."
  },
  Voice_5944_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_5945_AwakerVoiceContent = {
    Text = "Jangan mendekatiku. Apakah kau ingin menjadi mainan Putri, atau korban persembahan dewa?"
  },
  Voice_5945_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5945_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_59463_AwakerVoiceContent = {
    Text = "Dengan santai, kemenangan besar!"
  },
  Voice_59463_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_59464_AwakerVoiceContent = {
    Text = "Dengan santai, kemenangan besar!"
  },
  Voice_59464_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_5946_AwakerVoiceContent = {
    Text = "Aku mengizinkanmu menjadi saksi, menyaksikan momen cemerlang yang memutarbalikkan etika."
  },
  Voice_5946_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5946_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5947_AwakerVoiceContent = {
    Text = "Kongsi kosong? Kembali ke eksterior juga sering membuat celah seperti ini! Apakah celah yang dibuat Casiah juga menghubungkan ke dimensi yang lain, apakah pelarutan juga begitu?"
  },
  Voice_5947_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_5948_AwakerVoiceContent = {
    Text = "Penjaga, aku akan menggunakan kekuasaan dari Ibu Dewa, di sisi Takhta Aequor menyediakan sebuah tempat untukmu. Kau akan menyaksikan era kebangkitan setelah Kehancuran. Rasakanlah rasa syukur yang mendalam, ini adalah janji dari Ibu Dewa!"
  },
  Voice_5948_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5948_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5949_AwakerVoiceContent = {
    Text = "Melihat kesopananmu yang begitu tulus, aku akan memberikanmu satu jawaban sebagai hadiah. Pada awalnya, tentu saja ada perjuangan. Namun sekarang aku telah memahami bahwa kemewahan hidupku berasal dari-Nya. Kematian bukanlah akhir, Dia akan membangkitkanku kembali, dan melalui siklus sakit ini, aku akan menikmati keabadian…"
  },
  Voice_5949_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5949_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5950_AwakerVoiceContent = {
    Text = "Keinginan wanita itu sungguh menggelikan. Tidak ada yang dapat bertahan hidup setelah lenyap, bahkan \"dewa\" pun sama."
  },
  Voice_5950_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Thais"
  },
  Voice_5950_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Thais\", akan terbuka."
  },
  Voice_5951_AwakerVoiceContent = {
    Text = "Aku adalah seorang praktisi spiritisme, bukan seseorang yang serba bisa, tentu saja aku bisa membuat kesalahan. Tindakan wanita itu yang menyeret semua orang ke dalam masalah saat ini adalah akibat dari kelalaian tanpa sengaja dariku… Oleh karena itu, aku membutuhkan bantuanmu. Untuk dapat segera merespons panggilanku kapanpun, kamu diizinkan untuk meletakkan tempat tidur di istana tidurku."
  },
  Voice_5951_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5951_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5952_AwakerVoiceContent = {
    Text = "Kau memiliki tugas untuk menghadapi Clades, sungguh beban yang berat untuk seusiamu… Jika, sejak awal kau sudah tahu bahwa kau tidak bisa mengubah masa depan, apakah kau masih akan setia menjalankan misimu? Jangan terburu-buru menjawab, renungkan saat kau beristirahat, aku sangat penasaran dengan jawabanmu."
  },
  Voice_5952_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5952_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5953_AwakerVoiceContent = {
    Text = "Sudah beberapa waktu sejak aku dibangun, tidak ada apa pun yang ingin kau minta dariku? Wahyu dari Dewa, ramalan yang pasti terjadi, bahkan harta karun benua tenggelam—kau benar-benar tidak ingin tahu? \n Hmph… orang aneh."
  },
  Voice_5953_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5953_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5954_AwakerVoiceContent = {
    Text = "Aku tak pernah meminta siapa pun untuk menyembahku. Tindakan bodoh yang angkuh hanya membuatku semakin merasa lelah… Pergilah, sudah waktunya untuk beristirahat."
  },
  Voice_5954_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5954_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5955_AwakerVoiceContent = {
    Text = "Pada dirimu, Yu tidak melihat kualitas apa pun yang mirip dengan para pengikutnya... Yah, mungkin ini adalah hal yang baik. Memikirkan wanita itu membuat Yu merasa lelah."
  },
  Voice_5955_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5955_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5956_AwakerVoiceContent = {
    Text = "Tuhan, berlaku adil kepada semua."
  },
  Voice_5956_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5957_AwakerVoiceContent = {
    Text = "Aku tahu, kau adalah penonton yang istimewa, tidak bisa begitu saja melemparmu ke dimensi lain, kalau tidak akan ada masalah besar. Eh, apa pernah melakukan ini pada orang lain? Aduh, jangan tanya, itu Rahasia!"
  },
  Voice_5957_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_5958_AwakerVoiceContent = {
    Text = "Haiyah, apakah kamu tertarik pada penampilan ini? Sepertinya setiap kehilangan pasti ada perolehan. Mungkin ini juga salah satu keberuntunganku, Ryker?"
  },
  Voice_5958_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_5959_AwakerVoiceContent = {
    Text = "Mythag adalah tempat di mana saya memiliki paling banyak memori, dan juga merupakan… rumah terhangat saya."
  },
  Voice_5959_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_5960_AwakerVoiceContent = {
    Text = "Serahkan padaku."
  },
  Voice_5960_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5961_AwakerVoiceContent = {
    Text = "Terlalu polos!"
  },
  Voice_5961_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5962_AwakerVoiceContent = {
    Text = "Nyanyian Suci Aequor!"
  },
  Voice_5962_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5963_AwakerVoiceContent = {
    Text = "Apa yang telah kuterima——"
  },
  Voice_5963_AwakerVoiceTitle = {
    Text = "Keterampilan·satu·Lautan Tenang"
  },
  Voice_5964_AwakerVoiceContent = {
    Text = "Jika kamu bersedia mengakui bahwa aku masih \"Ramona\", silakan terus panggil aku seperti itu."
  },
  Voice_5964_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5965_AwakerVoiceContent = {
    Text = "Apa, kau juga ingin memanfaatkan kemarahanku?"
  },
  Voice_5965_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_5965_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_5966_AwakerVoiceContent = {
    Text = "Kebenaran… diungkapkan di sini."
  },
  Voice_5966_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_5967_AwakerVoiceContent = {
    Text = "Makanan yang didapat harus segera dimakan, itulah aturan di jalanan."
  },
  Voice_5967_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_5968_AwakerVoiceContent = {
    Text = "Rasanya seperti sudah kenyang."
  },
  Voice_5968_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_5969_AwakerVoiceContent = {
    Text = "Hmm… gatal, Cokelat, tolong garuk punggungku."
  },
  Voice_5969_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_5970_AwakerVoiceContent = {
    Text = "Komponen mekanis yang baru akan sangat membantu operasi tubuh saya — bukankah ini bisa dianggap sebagai rasa suka? Maaf, sepertinya saya tidak mengerti pertanyaanmu. Rasa suka tidak memiliki arti bagi boneka mekanis."
  },
  Voice_5970_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_5971_AwakerVoiceContent = {
    Text = "Lihat jurus ini."
  },
  Voice_5971_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5972_AwakerVoiceContent = {
    Text = "Lihat jurus ini!"
  },
  Voice_5972_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5974_AwakerVoiceContent = {
    Text = "Pertimbangkan dengan matang."
  },
  Voice_5974_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_5975_AwakerVoiceContent = {
    Text = "Berpikir dengan tenang."
  },
  Voice_5975_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_5976_AwakerVoiceContent = {
    Text = "Nyonya Kerang dan saya sama-sama memiliki rumah yang tidak berada di planet ini... Selain Tinct, tidak ada apa pun di rumah saya yang membuat saya merindukannya. Entah apa perasaan Nyonya Kerang terhadap rumahnya?"
  },
  Voice_5976_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Kerang"
  },
  Voice_5976_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Kerang\", akan terbuka."
  },
  Voice_5977_AwakerVoiceContent = {
    Text = "Jangan mendekati saya dari belakang, kecuali kau ingin lehermu dipatahkan."
  },
  Voice_5977_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_5977_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_5978_AwakerVoiceContent = {
    Text = "Hah—kenapa kalian membiarkan kucing liar berkeliaran di sekolah?! Kalau makhluk kecil yang tidak terdidik itu mencakar seseorang, bagaimana kalau terjadi sesuatu!"
  },
  Voice_5978_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5979_AwakerVoiceContent = {
    Text = "Apakah tatapan saya membuatmu merasa tidak nyaman? Ya, memang begitu. Justru karena keganasan inilah saya bisa bertahan hidup di neraka."
  },
  Voice_5979_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_5979_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_5980_AwakerVoiceContent = {
    Text = "Percuma berkata-kata yang terdengar muluk-muluk, apa sebenarnya yang kau inginkan dariku? Kau menghabiskan tenaga untuk menjaga rasionalitasku, pasti ada tujuanmu kan."
  },
  Voice_5980_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_5980_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_5981_AwakerVoiceContent = {
    Text = "Target balas dendamku selalu hanya Spartan, tapi sekarang, bahkan kota negara ini sudah tidak ada lagi… Baiklah, menjadi pedangmu juga bukan masalah. Aku mengakui engkau sebagai partnerku, namun jika berani melakukan penghianatan, aku akan mencabut jantungmu."
  },
  Voice_5981_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_5981_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_5982_AwakerVoiceContent = {
    Text = "Kedua tangan saya berlumuran darah. Kaum saya yang lemah tidak mengakui balas dendam saya; mereka membicarakan kekejaman saya, ketidakpatuhan saya, dan ketidaktahuan saya di belakang… Balas dendam, sejak awal, hanya untuk diri saya sendiri, tidak ada hubungannya dengan siapa pun."
  },
  Voice_5982_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_5982_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_5983_AwakerVoiceContent = {
    Text = "Sudah saatnya menggunakan lebih banyak baja."
  },
  Voice_5983_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5984_AwakerVoiceContent = {
    Text = "Sudah saatnya menggunakan lebih banyak baja."
  },
  Voice_5984_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5985_AwakerVoiceContent = {Text = "Mati."},
  Voice_5985_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_5986_AwakerVoiceContent = {
    Text = "Saya... lebih baik panggil saya Kerang, semua orang memanggil saya begitu. Ya, panggil saya seperti itu, sama seperti mereka..."
  },
  Voice_5986_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5987_AwakerVoiceContent = {
    Text = "Tubuh ini adalah perisai bagi Tuan!"
  },
  Voice_5987_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5988_AwakerVoiceContent = {
    Text = "Tubuh ini adalah perisai bagi Tuan!"
  },
  Voice_5988_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_5989_AwakerVoiceContent = {
    Text = "\"The Nutcracker\" awalnya adalah dongeng romantis penuh fantasi untuk anak perempuan, namun mereka yang berwajah bengis hanya melihat dalamnya anggota tubuh yang bergerak indah dan keinginan fisik yang vulgar... sungguh memuakkan."
  },
  Voice_5989_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_5990_AwakerVoiceContent = {
    Text = "Harus... harus dihapus...!"
  },
  Voice_5990_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_5991_AwakerVoiceContent = {
    Text = "Pandia...... apakah dia menyebut ini sebagai pelatihan? Haha...... izinkan aku tertawa sebentar. Manusia pada akhirnya masih terlalu lembut hatinya, apa pun yang mereka lakukan terlihat seperti bermain rumah-rumahan."
  },
  Voice_5991_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Pandia"
  },
  Voice_5991_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Pandia\", akan terbuka."
  },
  Voice_5992_AwakerVoiceContent = {
    Text = "Jangan mendekat!"
  },
  Voice_5992_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5993_AwakerVoiceContent = {
    Text = [[
Harus memperkenalkan diri lagi? Benar-benar tidak ada obat untukmu. Aku Jenkin, dan anak ini Brown. "Cicit!"
Jangan lupa! Jika kamu salah mengingat nama kami, bersiap-siaplah untuk aku pukul *sensor* dengan lampu lentera! "Cicit?!"]]
  },
  Voice_5993_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_5994_AwakerVoiceContent = {
    Text = "Lompatlah, lompatlah!"
  },
  Voice_5994_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_5995_AwakerVoiceContent = {
    Text = "Lompatlah, lompatlah!"
  },
  Voice_5995_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_5996_AwakerVoiceContent = {
    Text = "Persembahkan pujian pembukaan!"
  },
  Voice_5996_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_5997_AwakerVoiceContent = {Text = "Hmph."},
  Voice_5997_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_5998_AwakerVoiceContent = {
    Text = "Hanya butuh sedikit batu, dua pahat ukir, dan tiga tangkai bunga iris yang tumbuh menghadap matahari... aku bisa menciptakan segalanya untukmu."
  },
  Voice_5998_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_5998_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_5999_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_5999_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6000_AwakerVoiceContent = {
    Text = "Hanya sebatas ini?"
  },
  Voice_6000_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_6001_AwakerVoiceContent = {Text = "Hm."},
  Voice_6001_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_6002_AwakerVoiceContent = {
    Text = "Pertarungan yang tak berguna ini..."
  },
  Voice_6002_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_6003_AwakerVoiceContent = {
    Text = "(Mengerang tertahan)"
  },
  Voice_6003_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6004_AwakerVoiceContent = {
    Text = "Setelah kematian Tiberius, rakyat Roma akhirnya berhasil mewujudkan keinginan mereka selama bertahun-tahun — melemparkannya ke Sungai Tiber untuk memberi makan ikan. Tentu saja, mereka harus membayar sedikit harga untuk itu: dilemparkan ke arena oleh Caligula untuk hiburan saya."
  },
  Voice_6004_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6005_AwakerVoiceContent = {
    Text = "(Mengerang tertahan)"
  },
  Voice_6005_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_6006_AwakerVoiceContent = {
    Text = "Saya bisa merasakan bahwa gadis kecil itu memiliki kekuatan yang mirip denganku. Dia belum sepenuhnya memahami betapa besar kekuatan ini. Demi dirimu, aku akan melatihnya dengan tepat."
  },
  Voice_6006_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Lily"
  },
  Voice_6006_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Lily\", akan terbuka."
  },
  Voice_6007_AwakerVoiceContent = {
    Text = "Sialan, kalian masih meremehkanku, ya?!"
  },
  Voice_6007_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6008_AwakerVoiceContent = {
    Text = "Bukti keberadaan."
  },
  Voice_6008_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_6009_AwakerVoiceContent = {
    Text = "Bukti keberadaan."
  },
  Voice_6009_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6010_AwakerVoiceContent = {
    Text = "Saya percaya bahwa segala sesuatu terjadi karena suatu alasan, tetapi... kekerasan yang tak berarti, prasangka yang membuat saudara-saudara saling bermusuhan dan saling membenci, sungguh membuat saya sulit menutupi kesedihan. Jika ada hal yang membuat saya muak, mungkin itulah penyebabnya."
  },
  Voice_6010_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_6011_AwakerVoiceContent = {
    Text = "Benar-benar tidak ingin menggunakan kekuatan ini."
  },
  Voice_6011_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6012_AwakerVoiceContent = {
    Text = "Jangan ceroboh."
  },
  Voice_6012_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6013_AwakerVoiceContent = {Text = "Hm"},
  Voice_6013_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_6014_AwakerVoiceContent = {Text = "Berhenti!"},
  Voice_6014_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6015_AwakerVoiceContent = {Text = "Berhenti!"},
  Voice_6015_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_6016_AwakerVoiceContent = {
    Text = "Casiah hebat sekali! Dia bisa mengeluarkan seekor kelinci kecil dalam sekejap ——!"
  },
  Voice_6016_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Casiah"
  },
  Voice_6016_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Casiah\", akan terbuka."
  },
  Voice_6017_AwakerVoiceContent = {
    Text = "Sihir, sudah siap!"
  },
  Voice_6017_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6018_AwakerVoiceContent = {
    Text = "Pelarutan… harus diakui, memang ada hal-hal di dunia ini yang tidak dapat dikendalikan oleh kekuasaan."
  },
  Voice_6018_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_6019_AwakerVoiceContent = {Text = "Aah——"},
  Voice_6019_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6020_AwakerVoiceContent = {
    Text = "Mari menari di tengah api hijau yang menyala."
  },
  Voice_6020_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6021_AwakerVoiceContent = {
    Text = "Tidak perlu bersedih, bekas luka adalah lambang kehormatan seorang pejuang."
  },
  Voice_6021_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6022_AwakerVoiceContent = {
    Text = "Gemetarlah karena otot ini...... ia selalu siap untuk memenggal kepalamu."
  },
  Voice_6022_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_6024_AwakerVoiceContent = {
    Text = "Waktu makan? Atau waktu aktivitas?"
  },
  Voice_6024_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_6024_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_6025_AwakerVoiceContent = {
    Text = "Umm! Kalau begitu, teman-teman Aurita tidak akan hilang!"
  },
  Voice_6025_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_6025_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_6026_AwakerVoiceContent = {
    Text = "Guru Sylvia berkata, saat menerima sesuatu, kita harus mengucapkan terima kasih… terima kasih, terima kasih, terima kasih!"
  },
  Voice_6026_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_6026_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_6027_AwakerVoiceContent = {
    Text = "Kali ini giliran Aurita menjadi hantu! Hanya 5 detik untuk bersembunyi, ya! 5, 4—"
  },
  Voice_6027_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_6027_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_6028_AwakerVoiceContent = {
    Text = "Setelah semua orang mulai bermain petak umpet dan menghilang, kali ini Aurita pasti akan menemukan mereka semua!"
  },
  Voice_6028_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_6028_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_6029_AwakerVoiceContent = {
    Text = [[
Karena tulang Yu ditemukan di dasar laut, diyakini bahwa Yu menyukai air, dan mereka ingin membangun kolam di luar kamar tidur Yu? 
 Ha... terserah kalian, jangan ganggu Yu dengan hal-hal sepele seperti ini.]]
  },
  Voice_6029_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_6030_AwakerVoiceContent = {
    Text = "Setetes kecil di lautan, pengikut dangkal yang fana, Miryam... memberi salam padamu."
  },
  Voice_6030_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6031_AwakerVoiceContent = {
    Text = "Sekarang giliranku untuk bertindak."
  },
  Voice_6031_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6032_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6032_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6033_AwakerVoiceContent = {
    Text = "Benar-benar menakjubkan... Sebuah kalimat santai dari Anda berhasil memecahkan kesulitan kreatif yang menghantui saya selama berbulan-bulan."
  },
  Voice_6033_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6033_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6034_AwakerVoiceContent = {
    Text = "Dibandingkan dengan para gadis bangsawan di pesta anggur, temperamen Murphy bisa dianggap menggemaskan."
  },
  Voice_6034_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Murphy"
  },
  Voice_6034_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Murphy\", akan terbuka."
  },
  Voice_6035_AwakerVoiceContent = {
    Text = "Master penyembuhan psikologis? Anak-anak itu terlalu memujiku. Aku hanya berusaha mendengarkan sebaik mungkin untuk mengurangi beban di hati mereka — seperti yang selalu kulakukan."
  },
  Voice_6035_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_6036_AwakerVoiceContent = {
    Text = "Jangan meremehkanku lagi!"
  },
  Voice_6036_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6037_AwakerVoiceContent = {
    Text = "Jangan meremehkanku lagi!"
  },
  Voice_6037_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_6038_AwakerVoiceContent = {
    Text = "Merasa haus? Sumber air bersih adalah sesuatu yang sangat langka di penjara."
  },
  Voice_6038_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_6038_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_6039_AwakerVoiceContent = {
    Text = "Anak baik, anak penurut~ jangan menyerah di tengah jalan ya~"
  },
  Voice_6039_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_6039_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_6040_AwakerVoiceContent = {
    Text = "Kamu pasti sudah terperangkap dalam jebakan manis milikku, kan?"
  },
  Voice_6040_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_6040_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_6041_AwakerVoiceContent = {
    Text = "Berusaha, sedikit lagi~ Segera akan mencapai puncak kebahagiaan tertinggi itu~"
  },
  Voice_6041_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_6041_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_6042_AwakerVoiceContent = {
    Text = "Saat berusia empat belas tahun, saya masuk sekolah. Jika saya bisa lulus dengan lancar pada waktu itu, sekarang kamu seharusnya memanggil saya \"Kepala Sekolah\"."
  },
  Voice_6042_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_6043_AwakerVoiceContent = {
    Text = "Otakmu yang lemah sepertinya tidak bisa mengingat apa pun."
  },
  Voice_6043_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_6044_AwakerVoiceContent = {
    Text = [[
Apa kau bertanya apa keinginanku? Melindungi pelayaran, keluar masuk dengan selamat, bukankah itu bisa dihitung? 
 Yang lainnya, aku belum pernah memikirkannya... tapi aku akan mempertimbangkannya dengan baik, lalu memberitahumu nanti.]]
  },
  Voice_6044_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6044_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6045_AwakerVoiceContent = {
    Text = "\"Yang aku dambakan adalah rahasia langit dan bumi, aku ingin tahu kekuatan apa yang menguasai diriku.\" Meskipun aku tidak terlalu puas dengan alur cerita novel ini, dan ilmu fiksi di dalamnya terasa begitu naif hingga membuatku tertawa, setelah membacanya, kamu seharusnya bisa memahamiku... Eh, apa kamu belum pernah membaca buku ini?"
  },
  Voice_6045_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6045_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6046_AwakerVoiceContent = {
    Text = "Misi dan takdir adalah hal yang serupa. Tidak bisa dengan mudah dilepaskan, dan tidak perlu untuk dilepaskan."
  },
  Voice_6046_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_6046_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_6047_AwakerVoiceContent = {
    Text = "Apakah aku terlihat selalu sibuk? Ya, sesekali asisten bisa membantu meringankan beban kerja, tetapi dalam beberapa penelitian, aku tidak tergantikan. Kamu ingin membantu? Datanglah sesekali untuk memastikan bahwa aku masih hidup."
  },
  Voice_6047_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6047_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6048_AwakerVoiceContent = {
    Text = "Kau pikir aku marah? Tahu berapa banyak otot yang digunakan untuk tersenyum? Aku pernah mengajarkan pengetahuan ini di kelas, jelas, itu meluncur begitu saja dari permukaan kepalamu yang licin. Jawabannya adalah setidaknya tujuh belas, dan aku tidak punya alasan untuk marah padamu."
  },
  Voice_6048_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6048_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6049_AwakerVoiceContent = {
    Text = "Nyonya Ramona berkata, aku tidak perlu menuruti semua orang, apa kamu mengerti apa artinya? … Apakah ini berarti aku tidak lagi membutuhkan perlindunganmu?"
  },
  Voice_6049_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6049_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6050_AwakerVoiceContent = {
    Text = "Ada tiga belas laporan yang menunggu persetujuan, enam komunikator rusak yang perlu diperbaiki, dan saya juga harus mengamati hasil dari lima eksperimen ekstraksi Perak yang berbeda… Jadi, alih-alih mengganggu saya dengan waktu yang terbatas, lebih baik kamu mencari cara untuk melatih materi putih otakmu yang lemah itu."
  },
  Voice_6050_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_6050_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_6051_AwakerVoiceContent = {
    Text = "Semoga lain kali, tanah airku dapat merespons panggilanku."
  },
  Voice_6051_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_6052_AwakerVoiceContent = {
    Text = "Kunci telah dibuka."
  },
  Voice_6052_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6054_AwakerVoiceContent = {
    Text = "Saya sangat senang... Anda begitu memihak dan berat sebelah kepada saya."
  },
  Voice_6054_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_6054_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_6055_AwakerVoiceContent = {
    Text = "Orang lain mungkin akan marah karena sikap berat sebelah Anda, lho."
  },
  Voice_6055_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_6055_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_6056_AwakerVoiceContent = {
    Text = "Apakah Anda juga menginginkan saya?"
  },
  Voice_6056_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_6056_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_6057_AwakerVoiceContent = {
    Text = "Akhirnya selesai, akhirnya tidak perlu lagi melihat yang hitam, lengket-lengket itu…"
  },
  Voice_6057_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_6058_AwakerVoiceContent = {
    Text = "Karena telah memberikan begitu banyak untukku, cinta Anda telah sepenuhnya menyatu dengan diriku…"
  },
  Voice_6058_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_6058_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_6059_AwakerVoiceContent = {Text = "Hei!"},
  Voice_6059_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_6060_AwakerVoiceContent = {
    Text = "Sangat berbahaya."
  },
  Voice_6060_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6061_AwakerVoiceContent = {
    Text = "Setelah berusaha begitu banyak, bukankah sudah waktunya kamu menikmati hasilnya? Mendekatlah, aku tidak akan mengecewakanmu~"
  },
  Voice_6061_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_6061_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_6062_AwakerVoiceContent = {
    Text = "Saya, saya mengerti, niatmu... meskipun masih sangat canggung, Aigis akan berjuang sekuat tenaga untukmu!"
  },
  Voice_6062_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_6062_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_6063_AwakerVoiceContent = {
    Text = "Pandanganmu membakar saya... Apakah Aigis memberi Anda masalah?"
  },
  Voice_6063_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_6063_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_6064_AwakerVoiceContent = {
    Text = "Aigis sangat cemas... tidak tahu apakah bisa memenuhi harapan Anda..."
  },
  Voice_6064_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_6064_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_6065_AwakerVoiceContent = {
    Text = "Anda, Anda menatap saya seperti ini, Aigis merasa tidak nyaman... Apakah Anda tidak takut terhadap kutukan?"
  },
  Voice_6065_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_6065_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_6066_AwakerVoiceContent = {
    Text = "Tolong, tolong jangan lihat mataku... Aigis takut akan melukaimu... Bagaimanapun, aku adalah sosok seperti monster..."
  },
  Voice_6066_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_6066_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_6067_AwakerVoiceContent = {
    Text = "Indra penciuman binatang buas seperti itu hanyalah keberuntungan belaka. Jangan salah lihat, ya?"
  },
  Voice_6067_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6067_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6068_AwakerVoiceContent = {
    Text = "Aku masih tidak bisa berhenti..."
  },
  Voice_6068_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6069_AwakerVoiceContent = {
    Text = "Kekuatan, terus mengalir!"
  },
  Voice_6069_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_6070_AwakerVoiceContent = {
    Text = "Kekuatan, terus mengalir."
  },
  Voice_6070_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6071_AwakerVoiceContent = {
    Text = "Apakah Anda menyukai laut? Apapun yang terjadi, saya sangat mencintai laut. Saya masih ingat, bertahun-tahun yang lalu pada hari itu, laut begitu lembut membawa kematian yang sudah lama kutunggu kepada diriku yang malang."
  },
  Voice_6071_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6073_AwakerVoiceContent = {
    Text = "Entah mengapa, muncul perasaan kenikmatan yang belum pernah dirasakan sebelumnya…"
  },
  Voice_6073_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6074_AwakerVoiceContent = {
    Text = "Arus gelap ini akan merobek musuh."
  },
  Voice_6074_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6075_AwakerVoiceContent = {
    Text = "Arus gelap ini akan merobek musuh."
  },
  Voice_6075_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_6076_AwakerVoiceContent = {
    Text = "Saya selalu menunggu seseorang, seseorang yang dapat mengajari saya tentang cinta yang sebenarnya, rasa sakit, dan keinginan. Apakah Anda bisa memenuhi harapan saya? Bisakah Anda menyelamatkan saya dari penjara kegelapan ini?"
  },
  Voice_6076_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6076_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6077_AwakerVoiceContent = {
    Text = "Apakah kamu ingin mengetahui kebenarannya? Aku benci penjara, benci kegelapan, bencinya sampai rasanya ingin mati. Aku ingin diperhatikan, ingin dibakar..."
  },
  Voice_6077_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6077_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6078_AwakerVoiceContent = {
    Text = "Semuanya demi kesejahteraan abadi di masa depan."
  },
  Voice_6078_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6079_AwakerVoiceContent = {
    Text = "Ingin menikmatiku? Jadilah budakku. Akan kubuatmu panas hingga meleleh~"
  },
  Voice_6079_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_6079_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_6080_AwakerVoiceContent = {
    Text = "Anggap saja ini sebagai persembahan dari seorang bawahan."
  },
  Voice_6080_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6081_AwakerVoiceContent = {
    Text = "Sudah bosan, sudah bosan. Dibandingkan dengan tahanan besar yang penuh ketakutan, ini benar-benar seperti bermain rumah-rumahan. Lebih baik kamu menemaniku~"
  },
  Voice_6081_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6081_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6082_AwakerVoiceContent = {
    Text = "Ingin lebih banyak budak, ingin mendengar mereka mengerang dan memohon ampun ya——\nPergi bawakan lebih banyak budak untukku~ Tolong ya~"
  },
  Voice_6082_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6082_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6083_AwakerVoiceContent = {
    Text = "Maaf, aku tenggelam dalam kenangan lagi. Tolong jangan tunjukkan Ekspresi sedih. Giliranmu untuk menceritakan Ceritamu padaku. Apakah kamu pernah merasa ingin menulis puisi? Petualanganmu, pengalamanmu, kebahagiaanmu, kesedihanmu, apakah mereka akan menjadi Arus mengapung yang mengalir dari pikiran ke ujung jarimu?"
  },
  Voice_6083_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6083_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6084_AwakerVoiceContent = {
    Text = "Aku semula hanyalah noda air yang kelak akan memudar di atas gulungan perkamen, namun karena takdir membawaku bertemu denganmu, aku terhenti di saat ini. Mungkin ini adalah suatu keajaiban. Aku akan sangat menghargai keajaiban ini dan menciptakan syair abadi untukmu."
  },
  Voice_6084_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6084_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6085_AwakerVoiceContent = {
    Text = "Seseorang pernah berkata kepadaku, puisi diciptakan untuk dibaca dan dihargai... bisakah kau berbagi pemikiranmu denganku?"
  },
  Voice_6085_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_6085_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_6086_AwakerVoiceContent = {
    Text = "Pernahkah Anda mengalami hal seperti ini? Menghadapi penghinaan orang lain dengan sikap pemaaf, namun pada akhirnya tidak mendapatkan hasil yang diharapkan. Memberikan mawar kepada orang lain, tetapi di tangan tidak tersisa aroma harum, hanya luka dari duri tajam yang tertinggal."
  },
  Voice_6086_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6086_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6087_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6088_AwakerVoiceContent = {
    Text = "Pena dan tintaku..."
  },
  Voice_6088_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_6089_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_6089_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6090_AwakerVoiceContent = {Text = "Salah..."},
  Voice_6090_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_6091_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_6091_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_6092_AwakerVoiceContent = {
    Text = "Ini adalah anugerah dari sesuatu yang agung!"
  },
  Voice_6092_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6093_AwakerVoiceContent = {
    Text = "Perlindungan dari Keagungan Pucat."
  },
  Voice_6093_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_6094_AwakerVoiceContent = {
    Text = "Saya tidak punya waktu untuk beristirahat, Fenomena-d sudah membawa kehancuran pada dua tubuh saya. Sebelum dikejar oleh kesudahan, ada terlalu banyak hal yang ingin saya pahami… Bantu saya, mulai dari menyiapkan bahan percobaan. Saya percaya kamu tidak akan bodoh sampai salah menghitung keseimbangan, kan?"
  },
  Voice_6094_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6094_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6095_AwakerVoiceContent = {
    Text = "Saya suka jendela kaca patri di Fontainebleau, yang mewarnai wajah orang-orang dengan warna berbeda: ungu putus asa, biru penuh sanjungan, dan tentu saja, merah ambisi favorit saya…"
  },
  Voice_6095_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6096_AwakerVoiceContent = {
    Text = "Di sini, aku kerap merasakan kehadiran Tuanku, tapi mungkin aku belum siap menghadap-Nya…… Bagaimanapun, terima kasih telah menyediakan tempat bernaung untukku."
  },
  Voice_6096_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_6097_AwakerVoiceContent = {
    Text = "Penghianatan dapat membuat seseorang menjadi monster, baik bagi pihak mana pun. Oleh karena itu, aku membenci para pengkhianat."
  },
  Voice_6097_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_60985_AwakerVoiceContent = {
    Text = "Hameln, siap untuk melayani Anda."
  },
  Voice_60985_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_60986_AwakerVoiceContent = {
    Text = [[
Saya pernah melihat seseorang yang memiliki pemahaman hampir naluriah terhadap musik. Konser dan simfoni yang dihasilkan oleh orang itu sungguh tak terlupakan. 
Itu adalah bakat sejati.]]
  },
  Voice_60986_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Orang-orang Terdahulu"
  },
  Voice_60987_AwakerVoiceContent = {
    Text = "Saya tidak suka menghabiskan waktu untuk strategi. Dibandingkan dengan musik, nilai seni dari strategi hampir tidak ada. Namun, untuk membersihkan rintangan di jalan, itu adalah alat yang diperlukan. Untuk mencapai puncak tertinggi musik, saya tidak keberatan menggunakannya."
  },
  Voice_60987_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Mengenai Strategi"
  },
  Voice_60988_AwakerVoiceContent = {
    Text = "Tidak sopan."
  },
  Voice_60988_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_60989_AwakerVoiceContent = {
    Text = "Lagi, melodi macam apa ini sebenarnya? Sejak terakhir kali mendengarnya, ia terus terngiang di pikiranku, tak mau pergi, tak mau berhenti."
  },
  Voice_60989_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_60989_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_6098_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_6098_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_60990_AwakerVoiceContent = {
    Text = "Secara teknis, perencanaan strategi tidak berbeda dengan mengarahkan musik. Kemanusiaan, emosi, keinginan… semuanya tersusun jelas dan patuh seperti not-not pada partitur musik, terpapar di depan mataku, menari mengikuti jejak tongkat dirigen. Dengan memahami musik, segalanya dapat dimengerti."
  },
  Voice_60990_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Kesamaan"
  },
  Voice_60991_AwakerVoiceContent = {
    Text = "Hanya sedikit lagi, hanya sedikit... Aku harus menyelesaikannya, aku harus mendengarnya!"
  },
  Voice_60991_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_60991_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_60992_AwakerVoiceContent = {Text = "Hmm."},
  Voice_60992_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_60993_AwakerVoiceContent = {
    Text = "Tidak sopan."
  },
  Voice_60993_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_60994_AwakerVoiceContent = {Text = "Hmm."},
  Voice_60994_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_60995_AwakerVoiceContent = {
    Text = "Musik melampaui bahasa, melampaui kata-kata, melampaui segalanya. Jika ini bukan kesempurnaan, saya tidak tahu apa itu."
  },
  Voice_60995_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_60995_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_60996_AwakerVoiceContent = {
    Text = "Perhatikan ritme."
  },
  Voice_60996_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_60997_AwakerVoiceContent = {
    Text = "Penyetelan selesai."
  },
  Voice_60997_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_60998_AwakerVoiceContent = {
    Text = "Senang sekali kamu juga memahami pentingnya pelatihan."
  },
  Voice_60998_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_60999_AwakerVoiceContent = {
    Text = "Saya akan menyuguhkan pertunjukan yang sempurna."
  },
  Voice_60999_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6099_AwakerVoiceContent = {
    Text = "Iri? Sisik keras ini adalah bukti dari garis keturunan yang mulia."
  },
  Voice_6099_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_61000_AwakerVoiceContent = {
    Text = [[
Aku juga pernah dipuji oleh orang lain, namun... itu bukanlah bakat sejati. 
 Karyaku hanyalah tiruan dari karya para pendahulu.]]
  },
  Voice_61000_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Karya"
  },
  Voice_61001_AwakerVoiceContent = {
    Text = "Musik tiup, musik gesek... saling bersilangan naik lalu bersilangan lagi, motif kembali muncul... Aku ingat sekarang, ini adalah Requiem yang kubuat, untuk sang jenius yang mati muda, untuk bintang yang telah gugur."
  },
  Voice_61001_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_61001_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_61002_AwakerVoiceContent = {
    Text = "Hmm? Apakah kamu memiliki lagu baru untuk ditunjukkan kepadaku?"
  },
  Voice_61002_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_61003_AwakerVoiceContent = {
    Text = "Dengan lagu ini, kami memperingati jiwa-jiwa yang telah pergi."
  },
  Voice_61003_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_61004_AwakerVoiceContent = {
    Text = [[
Penari hijau itu memiliki postur yang cukup anggun untuk menjadi pemimpin balet istana. 
 Jika memungkinkan, aku sangat berharap bisa bekerja sama dengannya.]]
  },
  Voice_61004_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Liz"
  },
  Voice_61004_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Liz\", akan terbuka."
  },
  Voice_61005_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_61006_AwakerVoiceContent = {
    Text = "Dalam orkestra, akan ada pemain utama, tetapi seorang pemain utama saja tidak bisa membentuk sebuah orkestra yang lengkap. Orkestra saya tidak membutuhkan orang-orang yang hanya fokus pada menampilkan diri mereka sendiri."
  },
  Voice_61006_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_61007_AwakerVoiceContent = {
    Text = "Sepertinya aku mendengar sebuah melodi. Apakah ada yang sedang berlatih di sekitar sini?"
  },
  Voice_61007_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_61007_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_61008_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_61009_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6100_AwakerVoiceContent = {Text = "Mati saja!"},
  Voice_6100_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_61010_AwakerVoiceContent = {
    Text = "Benar, benar, inilah akhirnya, inilah misa terakhir, requiem yang dipersembahkan untuk musik itu sendiri!"
  },
  Voice_61010_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_61010_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_61011_AwakerVoiceContent = {
    Text = "Ah, Penjaga, kamu datang tepat pada waktunya. Beritahu aku, bagaimana menurutmu cara memproses melodi ini?"
  },
  Voice_61011_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_61012_AwakerVoiceContent = {
    Text = "Musik gesek, mulai."
  },
  Voice_61012_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_61013_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_61014_AwakerVoiceContent = {
    Text = "Itu menjadi jelas, melodi yang berliku-liku dan menyedihkan seperti ratapan Jiwa... Saya yakin saya pernah mendengarnya di suatu tempat."
  },
  Voice_61014_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_61014_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_61015_AwakerVoiceContent = {
    Text = "Rasionalitas, ketertiban, dengan ini aku membangun tangga, melangkah ke atas, dan pada akhirnya, membuka pintu besar istana itu. Namun, di balik pintu tersebut, rasionalitas dan ketertiban tidak lagi ada — musik yang benar-benar abadi akan melampaui rasionalitas."
  },
  Voice_61015_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Rasionalitas dan Ketertiban"
  },
  Voice_61016_AwakerVoiceContent = {
    Text = "Lihat tangan saya, satu, dua, tiga."
  },
  Voice_61016_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_61017_AwakerVoiceContent = {
    Text = "Saya sudah mendengar penampilan orkestra kalian itu, penuh dengan kesalahan. Namun, tidak masalah. Saya telah menyusun rencana yang sangat rinci dan yakin bisa menyiapkan pertunjukan yang sempurna sebelum Festival Perak Frost."
  },
  Voice_61017_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Mythag"
  },
  Voice_61018_AwakerVoiceContent = {
    Text = "Sampai sekarang, aku masih tidak bisa melupakan hari ketika pertama kali mendengar melodi yang berasal dari kedalaman kesadaran. Di antara not-not dan akor-akor tersebut, segala sesuatu di dunia nyata menghilang, hanya tersisa musik, musik yang murni dan luhur."
  },
  Voice_61018_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_61019_AwakerVoiceContent = {
    Text = "Sangat disayangkan, sepertinya perlu memperkuat latihan."
  },
  Voice_61019_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6101_AwakerVoiceContent = {
    Text = "Ini adalah perintah."
  },
  Voice_6101_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_61020_AwakerVoiceContent = {
    Text = "Saya biasanya tidak akan mengeluarkan undangan seperti ini, tapi... apakah kamu ingin mencobanya? Pegang tongkat konduktor dan berikan hidup baru pada musik ini?"
  },
  Voice_61020_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_61020_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_61021_AwakerVoiceContent = {
    Text = "Dibandingkan dengan ekspresi verbal, aku lebih suka menyampaikan diriku melalui musik. Namun, proses berkomunikasi denganmu seperti memimpin orkestra yang telah berlatih ribuan kali — lancar, bahkan seringkali memberikan kejutan. \n Baik untuk musik itu sendiri maupun bagiku, kau adalah sosok yang istimewa."
  },
  Voice_61021_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_61021_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_61022_AwakerVoiceContent = {
    Text = [[
Dalam simfoni, kerja sama antar instrumen sangat penting. Bagaimana setiap suara masuk dan keluar akan memberikan pengalaman berbeda pada musik. 
 Yang ingin aku katakan adalah, jika memimpin pertunjukan Pembangun adalah sebuah penampilan, kau melakukannya dengan baik.]]
  },
  Voice_61022_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_61022_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_61023_AwakerVoiceContent = {
    Text = "Apakah kamu juga menyukai komposisi ini? Hanya dengan empat birama, motifnya sudah tersaji secara utuh. Musik tiup mendorong melodi naik hingga mencapai tema, dan desain seperti ini telah memengaruhi banyak orang di masa setelahnya... Maaf, apakah aku berbicara terlalu banyak?"
  },
  Voice_61023_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_61023_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_61024_AwakerVoiceContent = {
    Text = "Penampilan yang sempurna."
  },
  Voice_61024_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_61025_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_61026_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_61027_AwakerVoiceContent = {
    Text = "Di dalam hati masing-masing dari kita, tersembunyi sebuah melodi yang menjadi milik kita sendiri. Melodi itu terjebak di antara akal dan tubuh, dan hanya bisa mekar sepenuhnya dalam kegilaan."
  },
  Voice_61027_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_61028_AwakerVoiceContent = {
    Text = "Hanya musik yang layak dipuji."
  },
  Voice_61028_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_61029_AwakerVoiceContent = {
    Text = "Hanya musik yang layak dipuji."
  },
  Voice_61029_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_6102_AwakerVoiceContent = {Text = "Pergilah."},
  Voice_6102_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_61030_AwakerVoiceContent = {
    Text = "Dengarlah, inilah requiem terakhir!"
  },
  Voice_61030_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_6103_AwakerVoiceContent = {
    Text = "\"Mohon ampun!\""
  },
  Voice_6103_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_61049_AwakerVoiceContent = {
    Text = "Dengarlah, inilah requiem terakhir!"
  },
  Voice_61049_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_6104_AwakerVoiceContent = {
    Text = "(Mengerang tertahan)"
  },
  Voice_6104_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6105_AwakerVoiceContent = {
    Text = "Apakah Anda juga ingin binasa dalam api hijau?"
  },
  Voice_6105_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_6107_AwakerVoiceContent = {
    Text = "Berani melamun?"
  },
  Voice_6107_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6108_AwakerVoiceContent = {Text = "Fokuslah!"},
  Voice_6108_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_6109_AwakerVoiceContent = {
    Text = [[
Di universitas masih ada anak semanis ini ya~ Aku baru saja bertanya padanya, "Maukah kau menjadi budakku?", lalu dia langsung memerah dan bergumam dengan gagap sesuatu seperti "Aku sudah menjadi Ksatria Penjaga"... 
 Padahal sebenarnya itu tidak saling bertentangan sama sekali~]]
  },
  Voice_6109_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Ogier"
  },
  Voice_6109_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Ogier\", akan terbuka."
  },
  Voice_6110_AwakerVoiceContent = {
    Text = "Jangan berani mendekati Putri."
  },
  Voice_6110_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu·Ombak Bergelora"
  },
  Voice_6111_AwakerVoiceContent = {
    Text = "Terima takdirmu."
  },
  Voice_6111_AwakerVoiceTitle = {
    Text = "Keterampilan·satu·Arus Tinggi"
  },
  Voice_6112_AwakerVoiceContent = {
    Text = "Gerbang tanah airku semakin menjauh... Tidak... Jangan sekali lagi..."
  },
  Voice_6112_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6113_AwakerVoiceContent = {
    Text = "Jangan menghalangi jalan!"
  },
  Voice_6113_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6114_AwakerVoiceContent = {
    Text = "Jangan menghalangi jalan!"
  },
  Voice_6114_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_6115_AwakerVoiceContent = {
    Text = "Membayar harga atas tindakan kalian."
  },
  Voice_6115_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6116_AwakerVoiceContent = {Text = "Mau mati?"},
  Voice_6116_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_6117_AwakerVoiceContent = {
    Text = "Saya merasa saya terkena pelarutan lagi… hati saya telah terlarut! Hanya butuh beberapa tablet aspirin, ditambah cemeti dan sedikit rasa sakit, seharusnya bisa sembuh…"
  },
  Voice_6117_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_6118_AwakerVoiceContent = {
    Text = "Bahkan kamu tidak bisa mengatasi masalah aneh ini? Lalu kamu masih mengejar Pelarutan, sungguh tidak memedulikan nyawa."
  },
  Voice_6118_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_6119_AwakerVoiceContent = {
    Text = "Saya adalah prajurit Roma terakhir——Uvhash!"
  },
  Voice_6119_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6120_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_6120_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6121_AwakerVoiceContent = {
    Text = "Saya adalah prajurit Roma terakhir——Uvhash!"
  },
  Voice_6121_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_6122_AwakerVoiceContent = {
    Text = "Pelarutan…? Tentu saja aku tahu, bukankah itu berarti pemutusan hubungan tuan dan pelayan? Apa yang sulit tentang ini."
  },
  Voice_6122_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_6123_AwakerVoiceContent = {
    Text = "Aku telah menerima panggilan ilahi, batas antara dewa dan orang bodoh telah menjadi kabur."
  },
  Voice_6123_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6123_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6124_AwakerVoiceContent = {
    Text = "Hmm......tekanan cukup, teknik pijatnya bagus~"
  },
  Voice_6124_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_6125_AwakerVoiceContent = {
    Text = "Apakah dekorasi di sini terlalu kuno? Suasananya suram, sepertinya ada hantu."
  },
  Voice_6125_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_6126_AwakerVoiceContent = {
    Text = "Di sini terdapat rerumputan dan pepohonan yang rimbun, udara yang tenang, serta mampu menyembuhkan penyakit Kakak. Bagi kami berdua, ini adalah rumah baru yang paling indah."
  },
  Voice_6126_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_6127_AwakerVoiceContent = {
    Text = "Tak disangka bisa bertemu lagi di sini… Aku tidak tahu bagaimana kehidupan Kakak setelah itu. Tidak peduli bagaimana aku bertanya, dia hanya mengatakan bahwa semuanya baik-baik saja… Maaf, aku juga harus berterima kasih padamu karena telah mempersatukan kami berdua."
  },
  Voice_6127_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Pingsan"
  },
  Voice_6127_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Pingsan\", akan terbuka."
  },
  Voice_6128_AwakerVoiceContent = {
    Text = "Persembahan kepada Tuhanku."
  },
  Voice_6128_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_6129_AwakerVoiceContent = {
    Text = "Persembahan kepada Tuhanku."
  },
  Voice_6129_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6130_AwakerVoiceContent = {
    Text = "Tenang, tenang, tenang..."
  },
  Voice_6130_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6131_AwakerVoiceContent = {
    Text = "Di dalam tubuhku ada banyak \"aku\", yang bahagia, sedih, marah... Mereka suka sponge cake, mereka benci hari-hari hujan di Londinium, mereka semua dipanggil \"24\", dan mereka semua sangat menghormati Anda."
  },
  Voice_6131_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6131_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6132_AwakerVoiceContent = {
    Text = [[
Dulu, saya bekerja setiap hari hingga tengah malam, menenun, mencuci, membersihkan, menjadi pengasuh, bahkan penyapu jalan... saya melakukan apa saja asalkan bisa mendapatkan uang. Pada waktu itu, hidup hanya berarti bertahan hidup.
Sekarang, kami memiliki makanan segar, tempat tidur yang hangat, dan orang baik hati seperti Anda... sungguh hal yang tak pernah terbayangkan.]]
  },
  Voice_6132_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6132_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6133_AwakerVoiceContent = {
    Text = "Bagaimanapun, kita berbagi sepotong steak dan sebuah tempat tidur, serta tidak akan merepotkan Anda."
  },
  Voice_6133_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6133_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6134_AwakerVoiceContent = {
    Text = [[
Hehe, wanita itu takut aku keluar, malam pun dia tidak berani tidur. Santai saja, demi Hadiah, aku tidak akan membunuhmu. 
Siapa aku? Tentu saja "24", hahahaha!]]
  },
  Voice_6134_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6134_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6135_AwakerVoiceContent = {
    Text = "Saya sekarang merasa sangat baik. Apa? Anda mengatakan bahwa pikiran saya telah direbut oleh sesuatu yang lain? Hu, hu... omong kosong... uh..."
  },
  Voice_6135_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_6135_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_6136_AwakerVoiceContent = {
    Text = "Sebagai seorang bawahan, kau cukup memahami situasi. Sebelum menyambut tidur panjang berikutnya, Yu akan merendahkan diri dan tinggal di sini untuk sementara waktu."
  },
  Voice_6136_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_6137_AwakerVoiceContent = {
    Text = "Hmm, air laut malam ini terasa cukup hangat…"
  },
  Voice_6137_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6138_AwakerVoiceContent = {
    Text = "Burung putih yang berputar-putar dalam Mimpi, Kedatangan."
  },
  Voice_6138_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6139_AwakerVoiceContent = {
    Text = "Seperti yang kamu inginkan, keberadaanku menjadi lebih nyata."
  },
  Voice_6139_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6140_AwakerVoiceContent = {
    Text = "Begitu puas! Begitu puas!"
  },
  Voice_6140_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_6141_AwakerVoiceContent = {
    Text = "Senang sekali!"
  },
  Voice_6141_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6142_AwakerVoiceContent = {
    Text = "Serahkan padaku!"
  },
  Voice_6142_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_6143_AwakerVoiceContent = {
    Text = "Serahkan padaku!"
  },
  Voice_6143_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6144_AwakerVoiceContent = {
    Text = "Selamat datang di — pesta kami!"
  },
  Voice_6144_AwakerVoiceTitle = {
    Text = "Muliakan·Aliemus"
  },
  Voice_6145_AwakerVoiceContent = {
    Text = "Gadis ini tanpa diragukan lagi mengalir darah dari garis keturunan Yu… Tidak, Yu masih terlalu muda untuk memiliki keturunan. Namun, kekuatannya memang berasal dari garis yang sama dengan Yu."
  },
  Voice_6145_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Darah Dewa"
  },
  Voice_6145_UnlockDesc = {
    Text = "Setelah mendapatkan salah satu Pembangun \"Aigis\" atau \"Murphy\", fitur ini akan terbuka."
  },
  Voice_6146_AwakerVoiceContent = {
    Text = "Kebaikan Tuan, Karen tidak berani melupakan sedetik pun!"
  },
  Voice_6146_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6147_AwakerVoiceContent = {
    Text = "——Manis sekali, sangat enak!"
  },
  Voice_6147_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6148_AwakerVoiceContent = {
    Text = "Karen baru-baru ini sedang diet, jadi dia tidak bisa makan terlalu banyak~"
  },
  Voice_6148_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6149_AwakerVoiceContent = {
    Text = "Untuk dijadikan lawanku, orang-orang ini masih belum layak."
  },
  Voice_6149_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_6150_AwakerVoiceContent = {
    Text = "Menjelaskan seni sama konyolnya dengan menjelaskan saham kereta api — tolong jangan menyusahkan seniman yang malang."
  },
  Voice_6150_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_6151_AwakerVoiceContent = {
    Text = "Aigis... Apakah dia melakukan kesalahan?"
  },
  Voice_6151_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_6152_AwakerVoiceContent = {
    Text = "Doamu, aku telah mendengarnya."
  },
  Voice_6152_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_6153_AwakerVoiceContent = {
    Text = "Doamu, aku telah mendengarnya."
  },
  Voice_6153_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6154_AwakerVoiceContent = {
    Text = "Hmph, orang yang tidak sopan."
  },
  Voice_6154_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6155_AwakerVoiceContent = {
    Text = "Ah, apakah orang yang lewat tadi adalah Tuan itu? Tidak, tidak apa-apa. Saat terakhir kali aku menyapanya, dia bahkan tidak mengenalku... Padahal aku selalu menunggunya di penjara untuk membawaku pergi, tapi sampai kerusuhan itu pun dia tak kunjung datang..."
  },
  Voice_6155_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang \"N\""
  },
  Voice_6155_UnlockDesc = {
    Text = "Setelah menyelesaikan Bab 7 dari \"Operasi\", akan terbuka"
  },
  Voice_6156_AwakerVoiceContent = {
    Text = "Menanggapi panggilan Bangun manusia, menjalin kerja sama adalah untuk menyelesaikan tugas yang belum selesai — jika kamu bisa berkembang hingga mampu bertarung denganku, itu akan menjadi yang terbaik."
  },
  Voice_6156_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_6157_AwakerVoiceContent = {
    Text = [[
Kakak, Cokelat, dan pengecut dari panti asuhan, sudah cukup bagiku memiliki mereka sebagai teman. Hmm... baiklah, kau juga termasuk. Cokelat, berikan satu permen kepada Penjaga. 
"Cicit?!"]]
  },
  Voice_6157_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6157_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6158_AwakerVoiceContent = {
    Text = "Kumuh Timur tidak cocok untuk anak-anak bertahan hidup. Mandor tua yang licik akan dengan berbagai cara mengurangi upah para penjual koran, serta terus-menerus mempermasalahkan kecepatan para pekerja pengantar susu... mencari-cari kesalahan! Singkatnya, untuk bertahan di jalanan, hanya bisa mengandalkan diri sendiri. Tidak ada yang bisa diandalkan, tidak ada yang bisa dipercaya."
  },
  Voice_6158_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6158_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6159_AwakerVoiceContent = {
    Text = "Kebiasaan burukku tidak bisa hilang begitu saja dalam waktu singkat, kau pasti bisa memahaminya, kan? Tidur di bawah jembatan dan saluran air hujan, bertahan hidup dengan makan sampah... Hidup saja sudah cukup sulit... Kau tidak bisa memintaku langsung terbiasa membuat tempat tidur setelah bangun! Setidaknya butuh waktu dua minggu untuk beradaptasi, kan!"
  },
  Voice_6159_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6159_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6160_AwakerVoiceContent = {
    Text = [[
Rasanya tidak enak tersesat di dalam ruang. Karena kamu sudah menolongku keluar dari sana, jika ada apa-apa yang ingin kamu katakan, langsung saja, tapi aku tidak bisa menjanjikan apakah bisa membantu atau tidak. 
Lagipula, aku masih kecil, kamu tidak akan menyulitkan seorang anak kan~]]
  },
  Voice_6160_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6160_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6161_AwakerVoiceContent = {
    Text = "Hei, orang Barat! Apakah kamu melihat Cokelat? Sialan rakus itu entah mencium bau apa dan pergi ke sana lagi."
  },
  Voice_6161_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_6161_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_6162_AwakerVoiceContent = {
    Text = "\"Mereka yang memiliki kekuatan tidak boleh menindas orang lain dengan kekuatan mereka sendiri, karena kalian semua memiliki darahku.\" — Aku selalu mengingat ajaran dewa kasih sayang ini dan akan menggunakan kekuatan ini untuk melindungi orang-orang di sekitarku."
  },
  Voice_6162_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6162_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6163_AwakerVoiceContent = {
    Text = "Penasaran apa yang kulihat di awal mula alam semesta? Aku bisa memberitahumu, di sana tidak ada apa-apa."
  },
  Voice_6163_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_6163_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_6164_AwakerVoiceContent = {
    Text = "Lebih terang."
  },
  Voice_6164_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6165_AwakerVoiceContent = {
    Text = "Cahaya lampu yang menyala terus-menerus..."
  },
  Voice_6165_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6166_AwakerVoiceContent = {
    Text = "Koneksi dengan tanah air menjadi lebih kuat."
  },
  Voice_6166_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6167_AwakerVoiceContent = {
    Text = "Jika bisa membuat orang terbebas dari penderitaan, aku akan merasa puas."
  },
  Voice_6167_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6168_AwakerVoiceContent = {
    Text = "Berikan aku lebih banyak perintah, wahai utusan pucat. Semoga api-Mu menuntunku ke arah yang benar."
  },
  Voice_6168_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6169_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_6169_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_6170_AwakerVoiceContent = {
    Text = "Penggemblengan seseorang tidak hanya pada tubuh, tetapi juga pada hati."
  },
  Voice_6170_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6171_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_6171_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_6172_AwakerVoiceContent = {
    Text = "Aduh, sakit!"
  },
  Voice_6172_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6173_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_6173_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_6174_AwakerVoiceContent = {
    Text = "Hmm! Suhu Anda masih sedikit terlalu tinggi untuk Sanga. Namun... itu hangat dan membara. Saya sangat menyukainya."
  },
  Voice_6174_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_6175_AwakerVoiceContent = {
    Text = "Ah... Apa ada keperluan? Kalau bisa, mari kita bicara di belakang panggung..."
  },
  Voice_6175_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_6176_AwakerVoiceContent = {
    Text = "Tak pernah mekar, sudah layu, seperti bunga teratai yang ditelan oleh air… Dalam arus dingin yang mengamuk, lemah mencari ketenangan, tak berani mengejar kebahagiaan yang seharusnya menjadi miliknya sendiri… Itulah aku, Penjaga."
  },
  Voice_6176_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6176_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6177_AwakerVoiceContent = {
    Text = "Saya pernah terjebak dalam kebingungan seperti ini: apakah penderitaan lebih panjang daripada hidup itu sendiri? Jika demikian, apakah tidur panjang yang damai lebih membahagiakan daripada kesadaran yang menyiksa? Setelah bangun, saya sempat tenggelam dalam pikiran itu, sampai Anda memberi saya tempat berlindung dari badai ini…"
  },
  Voice_6177_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6177_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6178_AwakerVoiceContent = {
    Text = "Saat berada di sanatorium, saya pernah mencoba untuk berteman, tetapi tidak banyak orang yang mau mendekati saya... Apakah ini karena \"racun\" yang menggerogoti tulang ini? Intinya, Anda harus berhati-hati saat mendekati saya."
  },
  Voice_6178_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_6178_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_6179_AwakerVoiceContent = {
    Text = "Suara lonceng yang dibawa oleh angin malam terasa menenangkan. Apakah Anda ingin duduk sejenak di kursi batu untuk mendengarkannya? Saya akan menggunakan selendang untuk mempersiapkan tempat duduk Anda."
  },
  Voice_6179_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6179_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6180_AwakerVoiceContent = {
    Text = "Pernahkah Anda mendengar tentang \"pemakaman laut\"? Di kampung halaman saya semasa hidup, ada sebuah adat di mana penduduk akan menenggelamkan jenazah ke dalam laut, sehingga laut menjadi tempat peristirahatan terakhir bagi semua orang. Sedangkan saya, adalah salah satu yang lebih awal kembali ke pelukan laut..."
  },
  Voice_6180_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6180_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6181_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_6181_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_6182_AwakerVoiceContent = {Text = "Ah"},
  Voice_6182_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6183_AwakerVoiceContent = {Text = "Ya!"},
  Voice_6183_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_6184_AwakerVoiceContent = {Text = "Ah"},
  Voice_6184_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_6185_AwakerVoiceContent = {
    Text = "Log operasi telah diarsipkan. Terima kasih atas kerja kerasnya, Penjaga."
  },
  Voice_6185_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_6186_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_6186_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_6187_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_6187_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6188_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_6188_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_6189_AwakerVoiceContent = {
    Text = "Masih bisa dilanjutkan."
  },
  Voice_6189_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_6190_AwakerVoiceContent = {
    Text = "Para tamu yang mengunjungi salon akan mendapatkan sambutan terbaik... Sebagai tiket masuk, apakah para tamu telah menyiapkan rahasia yang sepadan dengan kemegahan pesta ini?"
  },
  Voice_6190_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6191_AwakerVoiceContent = {
    Text = "Saya menyukai hal-hal yang segar. Selama perjalanan ribuan tahun, saya telah menyaksikan banyak inovasi dan penemuan menarik, seperti genre puisi, gambar dalam film. Manusia sungguh makhluk yang sangat menarik."
  },
  Voice_6191_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6192_AwakerVoiceContent = {
    Text = "Hmm, Lily mengenalnya. Ketika ibunya tidak ada, Lily tinggal di rumahnya."
  },
  Voice_6192_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Daffdell"
  },
  Voice_6192_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Narsis\", akan terbuka."
  },
  Voice_6195_AwakerVoiceContent = {
    Text = "Apakah kau yang mengganggu tidur panjangku?"
  },
  Voice_6195_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6196_AwakerVoiceContent = {
    Text = "Dewa? Hanya orang bodoh yang akan menyerahkan nyawa mereka pada keberadaan yang samar dan tak berwujud seperti itu. Alih-alih bertaruh pada dewa, lebih baik pikirkan cara untuk menjadi lebih kuat."
  },
  Voice_6196_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_6197_AwakerVoiceContent = {
    Text = "Apa tuan gladiator, tidak lebih dari serangga rendahan belaka."
  },
  Voice_6197_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Agrippa"
  },
  Voice_6197_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Agrippa\", akan terbuka."
  },
  Voice_6198_AwakerVoiceContent = {
    Text = "Setelah kemenangan, izinkan aku mengambil bahan-bahan yang diperlukan untuk memperbanyak keturunan."
  },
  Voice_6198_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6199_AwakerVoiceContent = {
    Text = "Teman besar! Teman! Hu hu, harus selalu menjadi sahabat baik dengan Aurita selamanya!"
  },
  Voice_6199_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_6200_AwakerVoiceContent = {
    Text = "Saya sangat bersemangat sekarang... Jika tidak ingin mati, lebih baik menjauh dari saya."
  },
  Voice_6200_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6201_AwakerVoiceContent = {
    Text = "Orang itu... apakah sikapnya terhadap orang lain benar-benar tidak masalah? Nyonya Sarah berkata, anak kecil tidak boleh sembarangan marah-marah..."
  },
  Voice_6201_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Murphy"
  },
  Voice_6201_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Murphy\", akan terbuka."
  },
  Voice_6202_AwakerVoiceContent = {
    Text = "Kejayaan kemenangan adalah milik Anda"
  },
  Voice_6202_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_6203_AwakerVoiceContent = {
    Text = "Makan, sudah tidak bisa makan lagi~"
  },
  Voice_6203_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6204_AwakerVoiceContent = {
    Text = "Kekosongan di dalam hati, sudah terisi penuh~"
  },
  Voice_6204_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6205_AwakerVoiceContent = {
    Text = "Sedikit lebih panas~"
  },
  Voice_6205_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6206_AwakerVoiceContent = {
    Text = "Aku tahu anak itu, dia sesekali berdiri jauh di luar arena untuk menonton pertunjukan. Lebih baik dia tidak mendekat, kalau tidak, para penonton kecil ini pasti akan \"kelelahan fisik dan mental\"!"
  },
  Voice_6206_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Pingsan"
  },
  Voice_6206_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Pingsan\", akan terbuka."
  },
  Voice_6207_AwakerVoiceContent = {
    Text = "Tinct pernah berkata, \"Orang harus tahu berterima kasih.\" Jadi, selama masih dalam kemampuanku, aku akan membantu…"
  },
  Voice_6207_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_6208_AwakerVoiceContent = {
    Text = "Halo, Penjaga, apakah ada yang bisa saya bantu?"
  },
  Voice_6208_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_6209_AwakerVoiceContent = {
    Text = "Suatu hari nanti, aku akan kembali ke medan perang sebagai pemimpin yang memimpin di garis depan."
  },
  Voice_6209_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_6209_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_6210_AwakerVoiceContent = {
    Text = "Apa kamu bisa mempercayainya? Aku merasa tulang kaki yang patah sedang sembuh."
  },
  Voice_6210_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_6210_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_6211_AwakerVoiceContent = {
    Text = "Terima kasih yang tulus atas kepercayaanmu, hingga membimbingku mencapai level seperti ini. Tampaknya kau juga seseorang yang mengejar keadilan, maka aku pasti akan melanjutkan kejayaan militer di sini."
  },
  Voice_6211_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_6211_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_6212_AwakerVoiceContent = {
    Text = "Hari keberangkatan segera tiba, darah yang membara bergelora di dalam dada."
  },
  Voice_6212_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_6212_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_6213_AwakerVoiceContent = {
    Text = "Sebagai kehormatan seorang pejuang, sedang dipulihkan."
  },
  Voice_6213_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_6213_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_6214_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_6214_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_6215_AwakerVoiceContent = {
    Text = "Aduh! Aduh!"
  },
  Voice_6215_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_6216_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_6216_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6217_AwakerVoiceContent = {
    Text = "Bermuka tebal!"
  },
  Voice_6217_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_6218_AwakerVoiceContent = {
    Text = "Aduh, maaf ya, lain kali pasti bisa!"
  },
  Voice_6218_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6219_AwakerVoiceContent = {
    Text = "Saya mendengar seseorang meneriakkan nama saya, Agrippa, Agrippa, Agrippina…"
  },
  Voice_6219_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_6219_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_6220_AwakerVoiceContent = {
    Text = "Aku melihat... Dia memanjat dari kegelapan di bawah sumur, tak terhitung banyaknya mata muncul dari telur daging itu. Mereka menatapku, memanggilku... Dewa Labirin."
  },
  Voice_6220_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_6220_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_6221_AwakerVoiceContent = {
    Text = "Saya memiliki dorongan yang sangat kuat untuk menyaksikan duel… Jika lokasinya berada di Labirin, itu akan lebih menakjubkan."
  },
  Voice_6221_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_6221_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_6222_AwakerVoiceContent = {
    Text = "Kontrak… ya, aku akan membuat kontrak denganmu, sebuah kontrak tuan-hamba yang tidak pernah kedaluwarsa…"
  },
  Voice_6222_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_6222_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_6223_AwakerVoiceContent = {
    Text = "Hm… lumayan, sedikit lagi. Aku harus memberi makan perut anak-anak laba-laba ini."
  },
  Voice_6223_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_6223_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_6224_AwakerVoiceContent = {
    Text = "Betapa kotor dan menjijikkan! Ahh—jangan bicarakan lagi! Kumohon! Jangan biarkan aku melihatnya, dan jangan, jangan sebutkan itu di telingaku…"
  },
  Voice_6224_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_6225_AwakerVoiceContent = {
    Text = "Masa laluku berjalan sesuai rencana, seperti wilayah perairan di sekitar khatulistiwa yang tenang, tak ada yang perlu disebutkan."
  },
  Voice_6225_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6225_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6226_AwakerVoiceContent = {
    Text = "Hmm...? Ibu, peluk... Hmm, sangat hangat..."
  },
  Voice_6226_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_6227_AwakerVoiceContent = {
    Text = "Debu bintang..."
  },
  Voice_6227_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_6228_AwakerVoiceContent = {
    Text = "Aduh, apakah kamu tersesat?"
  },
  Voice_6228_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6229_AwakerVoiceContent = {
    Text = "Tidak ada gunanya."
  },
  Voice_6229_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_6230_AwakerVoiceContent = {
    Text = "Setiap kali saya mengingat kembali adegan para pengkhianat itu berlutut di tanah sambil menangis memohon ampun, saya merasa lega, dan api dalam hati saya juga tampaknya mereda banyak."
  },
  Voice_6230_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6231_AwakerVoiceContent = {
    Text = "Pemilik kapal membawaku dari rumah dan memberiku misi sebagai Santa Perahu. Sejak saat itu, makna hidupku tidak lagi berada di bawah kendaliku sendiri. Seseorang mengatakan padaku bahwa setidaknya dalam kehidupan keduaku sebagai Pembangun, aku harus hidup untuk keinginanku sendiri… Apakah kamu akan membantuku? Bantu aku menjadi lebih egois, bantu aku menemukan keinginanku."
  },
  Voice_6231_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6231_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6232_AwakerVoiceContent = {
    Text = "Agrippa. Aku tidak punya apa-apa untuk dibicarakan denganmu — kecuali jika kamu cukup berani untuk menjadi gladiator di bawahku, maka itu akan menjadi cerita yang berbeda."
  },
  Voice_6232_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6233_AwakerVoiceContent = {
    Text = "Tawil... jauh lebih berbahaya daripada yang kita bayangkan. Jika suatu hari aku tidak ada, kau harus sangat berhati-hati terhadapnya."
  },
  Voice_6233_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Tawil"
  },
  Voice_6235_AwakerVoiceContent = {
    Text = "Dengan metode deduksi ini... memaknai dunia!"
  },
  Voice_6235_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6236_AwakerVoiceContent = {
    Text = "Dengan metode deduksi ini... memaknai dunia!"
  },
  Voice_6236_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_6237_AwakerVoiceContent = {
    Text = "Bersinar dengan bebas!"
  },
  Voice_6237_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6238_AwakerVoiceContent = {
    Text = "Sesuai kemampuan saya."
  },
  Voice_6238_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6239_AwakerVoiceContent = {
    Text = "Sesuai kemampuan saya."
  },
  Voice_6239_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_6240_AwakerVoiceContent = {
    Text = "Begitu saja Pembusukan."
  },
  Voice_6240_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6241_AwakerVoiceContent = {
    Text = "Begitu saja Pembusukan."
  },
  Voice_6241_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_6242_AwakerVoiceContent = {
    Text = "Senyuman dan etika adalah lapisan pelindung yang membantu saya menjaga jarak dengan orang lain, menghindari gangguan yang membosankan. Adapun sisi asli saya... saya tidak keberatan untuk menampilkannya kepada Anda."
  },
  Voice_6242_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6242_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6243_AwakerVoiceContent = {
    Text = "Pikiran menumpuk menjadi kalsium karbonat putih, kemudian terkikis menjadi terumbu karang yang indah. Mereka menyatu dengan diriku, di dalamnya berdetak denyut nadiku... Apakah Anda bersedia mendengarkannya?"
  },
  Voice_6243_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6243_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6244_AwakerVoiceContent = {
    Text = "Inspirasi seperti busa yang terus-menerus naik dari air laut: dengan sedikit sentuhan, ia menghilang tanpa jejak. Apakah Anda juga seperti itu?"
  },
  Voice_6244_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6244_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6245_AwakerVoiceContent = {
    Text = "Perang, penjarahan, ketenaran, dan keuntungan semuanya adalah keinginan manusia. Pemahat yang rendah hati tidak tertarik pada hal-hal yang dikejar oleh manusia. Dia hanya ingin menjadi budak keindahan."
  },
  Voice_6245_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6245_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6246_AwakerVoiceContent = {
    Text = "Hidup yang indah terletak pada kecanduan. Terkadang, kamu tidak boleh terlalu keras pada dirimu sendiri."
  },
  Voice_6246_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_6246_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_6247_AwakerVoiceContent = {
    Text = "Luka kecil saja..."
  },
  Voice_6247_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_6249_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_6249_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6250_AwakerVoiceContent = {Text = "Sial!"},
  Voice_6250_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_6251_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_6251_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_6252_AwakerVoiceContent = {
    Text = "Fenomena-d akan membawa berbagai gangguan dan bencana. Mungkin, negaraku menjadi korban bencana ini, sehingga tenggelam ke dalam Aequor…"
  },
  Voice_6252_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_6253_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6253_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6254_AwakerVoiceContent = {Text = "Ya~!"},
  Voice_6254_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  },
  Voice_6255_AwakerVoiceContent = {
    Text = "Kemegahan raksasa."
  },
  Voice_6255_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  },
  Voice_6256_AwakerVoiceContent = {Text = "Coba ini!"},
  Voice_6256_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6257_AwakerVoiceContent = {
    Text = "Pengorbanan yang tak terelakkan."
  },
  Voice_6257_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6258_AwakerVoiceContent = {
    Text = "Cukup bagus, inilah kehormatan seorang pejuang."
  },
  Voice_6258_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_6259_AwakerVoiceContent = {
    Text = "Kamu ini, bagaimana bisa membiarkan wanita seperti itu masuk! Tetapkan area terlarang untukku! Jangan biarkan dia mendekati dalam radius lima puluh langkah dari tempatku!"
  },
  Voice_6259_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Miryam"
  },
  Voice_6259_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Miryam\", akan terbuka."
  },
  Voice_6260_AwakerVoiceContent = {
    Text = "Mengapa ingin menjadi kuat? Di suku saya, yang lemah akan ditelanjangi, rambutnya dicukur, dan menghadapi penghinaan paling kotor yang bisa kamu bayangkan — itulah harga menjadi lemah, dan tidak semua orang mampu menanggungnya."
  },
  Voice_6260_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_6260_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_6261_AwakerVoiceContent = {
    Text = "Dewi Keberuntungan, berikan aku Berkati!"
  },
  Voice_6261_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6262_AwakerVoiceContent = {
    Text = "Ternyata... kekuatan manusia, apakah ada batasnya..."
  },
  Voice_6262_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6263_AwakerVoiceContent = {
    Text = "Otot dan tulangnya sedikit lebih rileks."
  },
  Voice_6263_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6263_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6264_AwakerVoiceContent = {
    Text = "Apakah ini adalah manifestasi dari keinginanmu yang membuat cintaku semakin mendalam?"
  },
  Voice_6264_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_6264_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_6265_AwakerVoiceContent = {
    Text = "Bertindak sesukamu!"
  },
  Voice_6265_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6266_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_6266_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6267_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_6267_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_6268_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_6268_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_6269_AwakerVoiceContent = {
    Text = "Ah, tidak termaafkan..."
  },
  Voice_6269_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6270_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_6271_AwakerVoiceContent = {
    Text = "Lebih berani sedikit!"
  },
  Voice_6271_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6272_AwakerVoiceContent = {Text = "Biu——"},
  Voice_6272_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_6273_AwakerVoiceContent = {
    Text = "Teruskan, nilai akhirmu layak untuk dinantikan."
  },
  Voice_6273_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_6274_AwakerVoiceContent = {
    Text = "Katanya ada pencuri dari kawasan kumuh yang datang, dan dia membawa seekor tikus gemuk? Hohoho... Lihat aku yang akan menegakkan keadilan untuk Tuan, menghilangkan bencana ini!"
  },
  Voice_6274_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Jenkin"
  },
  Voice_6274_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Jenkin\", akan terbuka."
  },
  Voice_6275_AwakerVoiceContent = {
    Text = "Ayo, tarik napas dalam-dalam——"
  },
  Voice_6275_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6276_AwakerVoiceContent = {
    Text = "Menarik, kecepatan pertumbuhanmu dalam pertempuran jauh melampaui imajinasiku. Jika diberi waktu, mungkin suatu hari kau bisa menjadi yang berikutnya… Sungguh aneh… Meski telah melintasi waktu, aku masih memiliki harapan terhadap makhluk selemah dirimu."
  },
  Voice_6276_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6276_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6277_AwakerVoiceContent = {
    Text = "Mungkin inilah saat yang tepat untuk mengatakannya, dengarkan baik-baik. \nRaksasa Bintang Lotan secara resmi mengundangmu untuk pertarungan terakhir… Tentu saja, sampai kamu mencapai puncak kekuatanmu, aku akan melindungi keselamatanmu. Kehilangan lawan yang diakui, hal seperti itu tidak akan kubiarkan terjadi untuk kedua kalinya."
  },
  Voice_6277_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6277_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6278_AwakerVoiceContent = {
    Text = "Hmph… benar-benar tidak mengerti, bagaimana Ramona bisa mengakui kamu sebagai pasangannya. Aku akui kau memiliki aroma seorang yang kuat, tapi untuk menjadi lawanku, masih jauh dari cukup."
  },
  Voice_6278_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6278_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6279_AwakerVoiceContent = {
    Text = "Benar, seperti inilah seharusnya kalian memandangku dengan mata penuh kekaguman. Aku adalah Relik tertua di Planet ini, pantas mendapatkan rasa hormat dari yang lebih kecil—aku telah menjadi Penjaga Planet ini selama jutaan tahun, meminta pertarungan yang memuaskan sebagai imbalan, ini tidak berlebihan kan?"
  },
  Voice_6279_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6279_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6280_AwakerVoiceContent = {
    Text = "Hah, aku tidak punya tenaga untuk bermain pura-pura dengan anak kecil. Kalau kau mengerti situasinya, carilah sudut dan duduklah dengan tenang di sana."
  },
  Voice_6280_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_6280_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_6281_AwakerVoiceContent = {
    Text = "Jiwa yang tidak mendapatkan perlindungan, aku akan memberikan kalian ketenangan terakhir."
  },
  Voice_6281_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6282_AwakerVoiceContent = {Text = "Waspada."},
  Voice_6282_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6283_AwakerVoiceContent = {
    Text = "Peringatan."
  },
  Voice_6283_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_6284_AwakerVoiceContent = {
    Text = "Ada sesuatu yang meratap di dalam pikiranku..."
  },
  Voice_6284_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_6284_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_6285_AwakerVoiceContent = {
    Text = "Sepertinya ada selubung kabut putih yang menyelimuti pikiranku."
  },
  Voice_6285_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_6285_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_6286_AwakerVoiceContent = {
    Text = "Suara semakin keras, kasa putih semakin tebal."
  },
  Voice_6286_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_6286_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_6287_AwakerVoiceContent = {
    Text = "Apakah itu suara jarum jam yang berputar?"
  },
  Voice_6287_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_6287_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_6288_AwakerVoiceContent = {
    Text = "Ketika bel berbunyi, apakah aku masih akan berada di sini?"
  },
  Voice_6288_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_6288_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_6289_AwakerVoiceContent = {
    Text = "Cara yang begitu kikuk... Hmph, orang yang tidak tahu diri. Bagaimana mungkin aku bisa begitu mudah terikat olehmu?"
  },
  Voice_6289_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6290_AwakerVoiceContent = {
    Text = "Permisi... apakah kalian pernah melihat adik perempuanku, Jenkin? Dia adalah gadis yang membawa tikus dan agak galak... aku yakin tidak mungkin salah."
  },
  Voice_6290_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Jenkin"
  },
  Voice_6290_UnlockDesc = {
    Text = "Setelah menyelesaikan Bab 2 dari \"Operasi\""
  },
  Voice_6292_AwakerVoiceContent = {
    Text = "Terima kasih atas cinta dan perhatian Anda."
  },
  Voice_6292_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6293_AwakerVoiceContent = {
    Text = "Sudah siap."
  },
  Voice_6293_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_6294_AwakerVoiceContent = {
    Text = "Silakan nantikan."
  },
  Voice_6294_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6295_AwakerVoiceContent = {
    Text = "Untukmu, aku menyanyikan lagu."
  },
  Voice_6295_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6296_AwakerVoiceContent = {
    Text = "Penjaga baru? Tunjukkan kemampuan terbaikmu, biar aku lihat apakah kamu layak menjadi lawanku."
  },
  Voice_6296_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6297_AwakerVoiceContent = {
    Text = "Meskipun aku seorang pasifis, tampaknya \"mereka\" tidak berpikir demikian…"
  },
  Voice_6297_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6298_AwakerVoiceContent = {Text = "Ha!"},
  Voice_6298_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6299_AwakerVoiceContent = {Text = "Mundur!"},
  Voice_6299_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6300_AwakerVoiceContent = {
    Text = "Berani sekali mempermalukan saya seperti ini..."
  },
  Voice_6300_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6301_AwakerVoiceContent = {
    Text = "Apakah kamu sudah siap? Pertunjukan sulap Casiah akan segera dimulai! Jangan alihkan pandanganmu, jangan lewatkan momen yang menakjubkan. It's showtime!"
  },
  Voice_6301_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6302_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6303_AwakerVoiceContent = {Text = "Ha!"},
  Voice_6303_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_6304_AwakerVoiceContent = {
    Text = [[
Aku mendapatkan jadwalmu dari Sylvia, ini terlalu ketat bagi pendatang baru. Aku mengerti bahwa kalian melakukan hal yang benar, tetapi membebani para prajurit baru bisa menciptakan masalah yang tidak perlu bagi tim. 
Kamu bilang kamu bukan pendatang baru? Tidak, aku bisa melihat dari matamu, ada banyak hal yang belum kamu alami.]]
  },
  Voice_6304_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6304_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6305_AwakerVoiceContent = {
    Text = "Saya benci diri saya yang lalai... Ah! Anda tidak perlu menghibur saya! Masa lalu itu telah menjadi dorongan untuk pertumbuhan saya, dan saya sudah menjadi kekuatan bagi Anda, bukan begitu?"
  },
  Voice_6305_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_6306_AwakerVoiceContent = {
    Text = "Aku dan pria itu tidak bisa berkomunikasi dengan baik. Hidup ini tidak selalu penuh dosa atau hukuman, menikmati saat ini jauh lebih penting, bukan?"
  },
  Voice_6306_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Salvador"
  },
  Voice_6306_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Salvador\", akan terbuka."
  },
  Voice_6307_AwakerVoiceContent = {
    Text = "Waktu hampir habis, ayo berangkat."
  },
  Voice_6307_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6308_AwakerVoiceContent = {
    Text = "Benci lilin yang mudah padam, benci roti hitam, benci benang di ujung rok… Tidak ada alasan khusus, bukankah membenci hal-hal ini sudah wajar?"
  },
  Voice_6308_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_6309_AwakerVoiceContent = {
    Text = "Jika kalian menyebutku sebagai Perawan Suci, maka kalian semua harus tunduk!"
  },
  Voice_6309_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6310_AwakerVoiceContent = {
    Text = "Jika kalian menyebutku sebagai Perawan Suci, maka kalian semua harus tunduk!"
  },
  Voice_6310_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_6311_AwakerVoiceContent = {
    Text = "Bernyanyilah."
  },
  Voice_6311_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6312_AwakerVoiceContent = {
    Text = "\"Lemari Pakaian Wanita\",\"Panduan Pekerjaan Wanita\" adalah bacaan yang sangat bagus... meskipun tidak mampu membelinya, melihat gaun-gaun yang indah tetap merupakan pengalaman yang menyenangkan."
  },
  Voice_6312_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6313_AwakerVoiceContent = {
    Text = "Aneh sekali, saya selalu kesulitan mengingat hal lain, tetapi mengingatmu hanya butuh beberapa hari... Apa? Sudah tiga bulan? Maaf, saya sudah melupakan lagi."
  },
  Voice_6313_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_6314_AwakerVoiceContent = {Text = "Cobalah."},
  Voice_6314_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_6316_AwakerVoiceContent = {
    Text = "Terus tingkatkan sikap Anda."
  },
  Voice_6316_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6317_AwakerVoiceContent = {
    Text = "Latih lagi gerakan memutar cambuk sebanyak dua puluh kali."
  },
  Voice_6317_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6318_AwakerVoiceContent = {
    Text = "Apakah gerakan saya cukup tepat?"
  },
  Voice_6318_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6319_AwakerVoiceContent = {Text = "Silakan!"},
  Voice_6319_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_6320_AwakerVoiceContent = {
    Text = "Cepat bawa Cokelat pergi!"
  },
  Voice_6320_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6321_AwakerVoiceContent = {
    Text = "Berlutut di hadapan singgasana."
  },
  Voice_6321_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6322_AwakerVoiceContent = {
    Text = "Berlutut di hadapan singgasana."
  },
  Voice_6322_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_6323_AwakerVoiceContent = {
    Text = "Ekspresi manusia dalam menghadapi berbagai macam keinginan selalu membuatku terkejut. Sayangnya, manusia masih terlalu rapuh, terlalu kecil… Hanya ini yang membuatku merasa seperti ada kucing mencakar di dada setiap kali memikirkannya."
  },
  Voice_6323_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_6324_AwakerVoiceContent = {
    Text = "Dari memori-nya, aku melihat banyak hal tentang masa lalu \"Pelarutan\"… Namun, setiap kali aku ingin memberitahumu, kesadaranku selalu terputus. Aku yakin ini juga ulahnya."
  },
  Voice_6324_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_6325_AwakerVoiceContent = {
    Text = "Bukankah lebih baik jika semuanya lenyap begitu saja?"
  },
  Voice_6325_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6326_AwakerVoiceContent = {
    Text = "Seorang pelayan yang memenuhi syarat harus lemah lembut, otak kosong——aku suka domba yang penurut."
  },
  Voice_6326_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6327_AwakerVoiceContent = {
    Text = "Kita bisa bertemu seperti ini, pasti ini adalah janji Tuhan kepada mereka yang menderita — kau adalah api pucat yang menghilangkan bencana, dan aku akan menjadi lenganmu, mendampingimu di sisimu."
  },
  Voice_6327_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6328_AwakerVoiceContent = {
    Text = "Sampai di sini!"
  },
  Voice_6328_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6329_AwakerVoiceContent = {
    Text = "Pernah mencoba menyuntikkan D-lendir langsung ke tubuh? Lendir hitam itu seperti ular kobra, melilit jantungmu sepanjang jalan, lalu... bang! Tubuhmu akan meledak menjadi segumpal cairan hangat. Menjijikkan, tapi sangat efektif."
  },
  Voice_6329_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_6330_AwakerVoiceContent = {
    Text = "Hmph, tempat para lemah saling berbagi kehangatan."
  },
  Voice_6330_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_6331_AwakerVoiceContent = {
    Text = "Setiap beberapa waktu, gadis kecil yang mengendarai motor itu selalu membantu saya merawat prostesis. Namun, akhir-akhir ini frekuensi perawatannya tampaknya sedikit terlalu sering, bukan?"
  },
  Voice_6331_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Nautila"
  },
  Voice_6331_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Nautila\", akan terbuka."
  },
  Voice_6332_AwakerVoiceContent = {
    Text = "Hubungan di antara kita? Masih perlu bertanya? Itu adalah hubungan seperti yang kamu bayangkan, lho?"
  },
  Voice_6332_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_6333_AwakerVoiceContent = {
    Text = "Bukan genre yang saya kuasai, tapi jika kamu bersikeras."
  },
  Voice_6333_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6334_AwakerVoiceContent = {
    Text = "Lingkaran hitam di bawah matamu semakin jelas...... Kenapa harus begitu lelah? Kamu perlu belajar menikmati waktu luang seperti aku."
  },
  Voice_6334_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_6334_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_6335_AwakerVoiceContent = {
    Text = "Tunggu, tanpa izin dariku..."
  },
  Voice_6335_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6335_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6336_AwakerVoiceContent = {
    Text = "Bagus... Mulai mendekati bentuk aslinya."
  },
  Voice_6336_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_6336_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_6337_AwakerVoiceContent = {
    Text = "Ini adalah kekuatan yang cukup untuk menyaingi \"Korupsi Hijau\"... kamu telah menyentuh sesuatu yang seharusnya tidak disentuh. Adapun aku, aku tidak akan pernah membiarkanmu pergi lagi."
  },
  Voice_6337_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_6337_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_6338_AwakerVoiceContent = {
    Text = "Shh... Cahaya pagi di lembah sungai, pasti ini pertama kalinya kamu melihatnya, kan? Ini adalah hadiah atas kesetiaanmu."
  },
  Voice_6338_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_6338_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_6339_AwakerVoiceContent = {
    Text = "Buku \"@1@2 Wahyu\" ini diberikan kepadamu. Mungkin dapat membantu dalam mencerahkan pikiran, atau membuatmu cepat tertidur."
  },
  Voice_6339_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_6339_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_6340_AwakerVoiceContent = {
    Text = "Dunia masih terlalu bising. Jika kau bisa menemukan sudut yang tenang untukku di akademi, itu akan sangat baik... Tidak, aku tidak membutuhkan perapian. Hanya melalui asketisme, doaku dapat didengar oleh para dewa..."
  },
  Voice_6340_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_6341_AwakerVoiceContent = {
    Text = "Apakah yang menetes dari tubuh ini adalah lilin atau madu? Jika kamu menjilatnya sedikit, bukankah kamu akan tahu?"
  },
  Voice_6341_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6341_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6342_AwakerVoiceContent = {
    Text = "Pertama kali bertemu. Nama saya Aigis... Mohon, anggap saja saya tidak ada!"
  },
  Voice_6342_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6343_AwakerVoiceContent = {
    Text = "Selama aku masih menjadi \"Ramona\", kita tetap rekan, kan?"
  },
  Voice_6343_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_6344_AwakerVoiceContent = {
    Text = "Nona dengan lingkaran hitam tebal di matanya itu pernah berkonsultasi padaku tentang cara 'hidup selamanya di bawah sinar matahari'…… Memang benar, cukup berpindah bolak-balik antara dua dunia saja. Tapi, dia sama sekali tidak mau melangkah ke terowongan dimensi…… Sungguh membingungkan."
  },
  Voice_6344_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Kerang"
  },
  Voice_6344_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Kerang\", akan terbuka."
  },
  Voice_6345_AwakerVoiceContent = {
    Text = "Selamat datang di taman bermainku! Apakah kamu sudah siap menerima hukuman cemeti?"
  },
  Voice_6345_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6346_AwakerVoiceContent = {
    Text = "Karena Dia telah mengakui kamu, aku tidak akan memperlakukanmu sebagai musuh."
  },
  Voice_6346_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_6347_AwakerVoiceContent = {
    Text = "Apa maksudmu aku yang mengambilnya, jangan fitnah orang baik! Saat baut-baut rusaknya hilang, aku... Cokelat! Hehe, anggap saja kau tidak melihat apa-apa, oke?"
  },
  Voice_6347_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Nautila"
  },
  Voice_6347_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Nautila\", akan terbuka."
  },
  Voice_6348_AwakerVoiceContent = {
    Text = "Petualangan memang semenarik yang dikatakan dalam Cerita! Cerita itu… apa ya?"
  },
  Voice_6348_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_6349_AwakerVoiceContent = {
    Text = "... Sendawa. Ah, maaf, tanpa sengaja menyerap terlalu banyak energi lagi."
  },
  Voice_6349_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_6350_AwakerVoiceContent = {
    Text = "Setelah memasuki tubuh manusia, aku kehilangan kontak dengan semua rekan-rekanku. Aku takut yang lainnya tidak bisa melarikan diri dari kejaran iblis, dan aku khawatir bahwa aku mungkin sudah menjadi yang terakhir dari ras kami… Tolong selamatkan aku, Penjaga, biarkan aku tetap di sisimu, jangan tinggalkan aku dalam kegelapan…"
  },
  Voice_6350_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6350_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6351_AwakerVoiceContent = {
    Text = "Pada saat kehancuran Planet, aku meninggalkan Tubuhku dan memindahkan kesadaranku ke dalam tubuh manusia... tapi iblis hitam mengejarku, mengikat erat Rohku sehingga aku tak bisa lepas! Dia ingin menyeret seluruh dunia ke dalam rawa lumpur yang gelap!"
  },
  Voice_6351_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6351_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6352_AwakerVoiceContent = {
    Text = "Tolong, Penjaga... Asalkan aku bisa tetap berada di lokator tanpa meninggalkannya, selain masuk ke dalam kegelapan dan menghadapi itu. Yang hitam... Aku bisa melakukan apa saja! Aku tidak bisa meninggalkan lokator, sebentar lagi, sebentar lagi aku akan bisa melacak reruntuhan planet induk! Tinggal dua belas miliar perhitungan lagi!"
  },
  Voice_6352_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6352_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6353_AwakerVoiceContent = {
    Text = "Bisakah kamu membantu aku mengajukan dua paket suplemen kafein dari jatahmu? … Aku tidak bisa tidur, kenapa harus tidur? Jangan sampai tidur! Setelah menutup mata, semuanya menjadi gelap, gelap…"
  },
  Voice_6353_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6353_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6354_AwakerVoiceContent = {
    Text = "Wow! Jangan mendekatiku! Pertama-tama, buktikan dulu bahwa kamu bukan antek kegelapan! Ya, antek. Jika kamu melepas pakaianmu dan memperlihatkan padaku apakah ada cairan hitam menjijikkan di tubuhmu, aku bisa memastikan apakah kamu iblis atau bukan…"
  },
  Voice_6354_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_6354_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_6355_AwakerVoiceContent = {
    Text = "Jangan tanya lagi, jangan tanya lagi…! Kau tahu dengan jelas apa yang paling kubenci dan takuti! Kegelapan, kegelapan tanpa akhir!"
  },
  Voice_6355_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_6356_AwakerVoiceContent = {
    Text = "Cara menyembuhkan Pelarutan? Hal semacam itu tidak ada di mana pun. \n Kamu bertanya bagaimana aku tidak terinfeksi? Hehe… asalkan \"tidak terlihat\" saja sudah cukup."
  },
  Voice_6356_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_6357_AwakerVoiceContent = {
    Text = "Terima kasih, Pemilik."
  },
  Voice_6357_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6358_AwakerVoiceContent = {
    Text = "Mereka juga tampak sangat bahagia."
  },
  Voice_6358_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6359_AwakerVoiceContent = {
    Text = "Lily, sudah dewasa."
  },
  Voice_6359_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6360_AwakerVoiceContent = {
    Text = "Mau dihancurkan?"
  },
  Voice_6360_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6361_AwakerVoiceContent = {
    Text = "Bagaimana bisa kamu memanggilnya! Kutu tidur yang tak berguna itu! Menyerah pada kehancuran, tidak berusaha maju… sia-sia aku pernah menaruh harapan besar padanya! Ayo pergi! Aku tidak mau melihat orang ini!"
  },
  Voice_6361_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Tulu"
  },
  Voice_6361_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Tulu\", akan terbuka."
  },
  Voice_6362_AwakerVoiceContent = {
    Text = "Menjijikkan!"
  },
  Voice_6362_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_6363_AwakerVoiceContent = {
    Text = "Mengganggu!"
  },
  Voice_6363_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6364_AwakerVoiceContent = {
    Text = "Lain kali, mari kita pergi melihat laut bersama. Pergi ke Febvre juga boleh, saya bisa menjadi pemandu Anda; pergi ke tempat lain pun tidak masalah, bahkan sampai ujung dunia sekalipun, saya ingin melihatnya bersama Anda."
  },
  Voice_6364_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_6364_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_6365_AwakerVoiceContent = {
    Text = [[
Laut memiliki bahasanya sendiri.
... Seperti ini, sesekali saya bisa berbincang dengan ikan-ikan kecil di kolam tentang kampung halaman mereka. Jika Anda penasaran, apakah saya bisa membantu menerjemahkannya untuk Anda?]]
  },
  Voice_6365_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_6365_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_6366_AwakerVoiceContent = {
    Text = "Bisa diselamatkan oleh Anda, saya sering kali merasa bahagia hingga takut... Tolong beritahu saya, ini bukan Mimpi, dan Anda juga tidak akan menghilang begitu saja di lautan, kan?"
  },
  Voice_6366_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_6366_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_6367_AwakerVoiceContent = {
    Text = "Apakah perasaan seperti ini bisa disebut sebagai \"kebahagiaan\"? Aku sebelumnya... tak pernah berharap untuk hal semacam ini."
  },
  Voice_6367_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_6367_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_6368_AwakerVoiceContent = {
    Text = "Tubuh terasa hangat, seolah-olah dikelilingi oleh air laut yang lembut, sungguh luar biasa."
  },
  Voice_6368_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_6368_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_6369_AwakerVoiceContent = {
    Text = "Apakah itu irisan milik-Nya? Tidak buruk, sungguh memiliki keagungan seorang raja."
  },
  Voice_6369_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Tulu"
  },
  Voice_6369_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Tulu\", akan terbuka."
  },
  Voice_6370_AwakerVoiceContent = {
    Text = "Jangan, jangan lanjutkan... Itu akan menemukanku. Itu akan menemukanku!"
  },
  Voice_6370_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6371_AwakerVoiceContent = {
    Text = "Dengan begitu, aku bisa terus menjaga kesadaran, kan?"
  },
  Voice_6371_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6372_AwakerVoiceContent = {
    Text = "Selesai, selesai, selesai, pasti akan ketahuan seperti ini…"
  },
  Voice_6372_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6373_AwakerVoiceContent = {
    Text = "Kita menang, apakah kamu senang? \"Senang\" itu perasaan seperti apa?"
  },
  Voice_6373_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_6374_AwakerVoiceContent = {
    Text = "Hal yang disukai? Aku suka lagu pengantar tidur Tinct… Tentu saja, suaramu juga sangat merdu!"
  },
  Voice_6374_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6375_AwakerVoiceContent = {
    Text = "Dia adalah pejuang yang andal, dulu aku menganggapnya sebagai \"kawan\"... apa? Kau bilang, cara aku mendefinisikan \"kawan\" bermasalah? Aku ingin mendengar penjelasanmu."
  },
  Voice_6375_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Goliath"
  },
  Voice_6375_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Goliath\", akan terbuka."
  },
  Voice_6378_AwakerVoiceContent = {Text = "Meteor..."},
  Voice_6378_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6379_AwakerVoiceContent = {Text = "Aah——"},
  Voice_6379_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6380_AwakerVoiceContent = {
    Text = "Kekuatan yang terus-menerus mengalir, memenuhi seluruh tubuh…"
  },
  Voice_6380_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6381_AwakerVoiceContent = {
    Text = "Terbanglah!"
  },
  Voice_6381_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6382_AwakerVoiceContent = {
    Text = "Tidak buruk, kamu lebih berguna daripada yang terlihat."
  },
  Voice_6382_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6383_AwakerVoiceContent = {
    Text = "Dua puluh, dua puluh satu, dua puluh empat... Eh, tunggu, aku menghitung sampai berapa tadi? Satu, dua, tiga..."
  },
  Voice_6383_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_6383_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_6384_AwakerVoiceContent = {
    Text = "Aku akhirnya tahu berapa banyak bahan yang ada sebelumnya, jadi aku bisa menyelesaikan perbaikan lebih cepat — Eh, dari mana lagi semua ini?"
  },
  Voice_6384_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_6384_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_6385_AwakerVoiceContent = {
    Text = "Efisiensi perbaikan akhir-akhir ini tampaknya meningkat, berkat bantuanmu. Dengan begini, kita akan segera bisa memulai petualangan."
  },
  Voice_6385_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_6385_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_6386_AwakerVoiceContent = {
    Text = "Saya mulai ingat sedikit-sedikit… Kemarin, apa kamu memberiku kunci pas nomor 7?"
  },
  Voice_6386_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_6386_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_6387_AwakerVoiceContent = {
    Text = "Perbaiki, tambal, selesaikan! Petualangan yang tak diketahui, dunia yang misterius, aku datang!"
  },
  Voice_6387_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_6387_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_6388_AwakerVoiceContent = {Text = "BOOM——"},
  Voice_6388_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_6389_AwakerVoiceContent = {
    Text = "Jangan menipu diri sendiri, belenggu Roh tetaplah belenggu, tidak bisa disebut adil."
  },
  Voice_6389_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_6390_AwakerVoiceContent = {
    Text = "Dengan begini, batas antara aku dan Pembangun menjadi semakin kabur. Kau harus benar-benar mengawasiku."
  },
  Voice_6390_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_6390_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_6391_AwakerVoiceContent = {
    Text = "Ayo, pergi dan selamatkan dunia."
  },
  Voice_6391_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_6391_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_6392_AwakerVoiceContent = {
    Text = "Rasanya segar seperti membaca \"Asal Usul Spesies\" dalam satu tarikan napas."
  },
  Voice_6392_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_6392_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_6393_AwakerVoiceContent = {
    Text = "Menjadi lebih kuat, coba biarkan aku menjalankan misi sendiri lain kali?"
  },
  Voice_6393_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_6393_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_6394_AwakerVoiceContent = {
    Text = "Selain kemampuan pertempuran, sepertinya tidak ada peningkatan signifikan dalam memori dan kemampuan logika. Memang, masih harus mengandalkan pemikiran sendiri."
  },
  Voice_6394_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_6394_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_6395_AwakerVoiceContent = {
    Text = "Aku akan membuat mereka merasakan sendiri bagaimana rasanya kehidupan terbalik, kehilangan segalanya, dan diinjak-injak oleh puluhan ribu orang."
  },
  Voice_6395_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_6395_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_6396_AwakerVoiceContent = {
    Text = "Segala penghinaan yang kuterima, segala sesuatu yang telah hilang dariku... Aku akan membuat mereka membayar. Aku akan membuat mereka semua membayar."
  },
  Voice_6396_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_6396_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_6397_AwakerVoiceContent = {
    Text = "Betapa manisnya kebencian, bila disertai dengan darah musuh, pasti akan menjadi hidangan terlezat di dunia."
  },
  Voice_6397_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_6397_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_6398_AwakerVoiceContent = {
    Text = "Ah! Jangan tiba-tiba mendekat dari belakang seperti itu!"
  },
  Voice_6398_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_6399_AwakerVoiceContent = {
    Text = "Api yang menyala-nyala membakar di dalam dadaku... Ya, aku tak pernah melupakan, dan juga tidak mungkin bisa melupakannya."
  },
  Voice_6399_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_6399_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_6400_AwakerVoiceContent = {
    Text = "Terbakarlah, jiwa puisi."
  },
  Voice_6400_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6401_AwakerVoiceContent = {
    Text = "(Mendengus pelan)"
  },
  Voice_6401_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_6402_AwakerVoiceContent = {
    Text = "(Mendengus pelan)"
  },
  Voice_6402_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6403_AwakerVoiceContent = {
    Text = "(Mendengus pelan)"
  },
  Voice_6403_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_6404_AwakerVoiceContent = {
    Text = "(Mendengus pelan)"
  },
  Voice_6404_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_6405_AwakerVoiceContent = {
    Text = "Gatal sekali! Sama seperti pelayan yang menggelitik telapak kaki dengan bulu, kamu *disensor* bukan sengaja kan."
  },
  Voice_6405_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6405_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6406_AwakerVoiceContent = {
    Text = "Semoga kamu bermimpi indah."
  },
  Voice_6406_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_6407_AwakerVoiceContent = {
    Text = "Semoga kamu bermimpi indah."
  },
  Voice_6407_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6408_AwakerVoiceContent = {
    Text = "Berikan ketenangan…!"
  },
  Voice_6408_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_6409_AwakerVoiceContent = {
    Text = "Bertindaklah dengan anggun."
  },
  Voice_6409_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6410_AwakerVoiceContent = {
    Text = "Bisakah kamu mendengarnya? Suaraku."
  },
  Voice_6410_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_6411_AwakerVoiceContent = {
    Text = "Bisakah kamu mendengarnya? Suaraku."
  },
  Voice_6411_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6412_AwakerVoiceContent = {
    Text = "Hujan turun. Air hujan akan membersihkan segalanya, makanan yang sudah rusak, kotoran yang membandel, dan juga orang-orang seperti saya... yang tidak diperlukan..."
  },
  Voice_6412_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_6413_AwakerVoiceContent = {
    Text = "Gelombang balas dendam tak pernah berhenti."
  },
  Voice_6413_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6414_AwakerVoiceContent = {
    Text = "Darah, membasahi seluruh tubuh!"
  },
  Voice_6414_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6415_AwakerVoiceContent = {Text = "Ya!"},
  Voice_6415_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6416_AwakerVoiceContent = {
    Text = "Lihat ke sini!"
  },
  Voice_6416_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6417_AwakerVoiceContent = {
    Text = "Aku sama sekali tidak takut."
  },
  Voice_6417_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_6418_AwakerVoiceContent = {Text = "Hati-hati!"},
  Voice_6418_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6419_AwakerVoiceContent = {
    Text = "Tidak pernah mengalami penderitaan, tidak pernah tercemar oleh kesedihan, tidak pernah disiksa oleh penyakit, tidak pernah dirasuki oleh penderitaan hitam — mungkin ini adalah ilusi yang tak akan pernah terwujud, tetapi ini adalah ideal yang kukejar sepanjang hidupku."
  },
  Voice_6419_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6420_AwakerVoiceContent = {
    Text = "Tunduklah pada keindahan Kerajaan Abadi!"
  },
  Voice_6420_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_6421_AwakerVoiceContent = {
    Text = "Tunduklah pada keindahan Kerajaan Abadi!"
  },
  Voice_6421_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6422_AwakerVoiceContent = {
    Text = "Datang lagi untuk memberikan persembahan dengan patuh? Benar-benar penurut."
  },
  Voice_6422_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6422_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6423_AwakerVoiceContent = {
    Text = "Apakah sakit?"
  },
  Voice_6423_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_6424_AwakerVoiceContent = {Text = "Fokuslah."},
  Voice_6424_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6425_AwakerVoiceContent = {
    Text = "Ribuan tahun berlalu membuatku sedikit ceroboh."
  },
  Voice_6425_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6426_AwakerVoiceContent = {
    Text = "Pada hari itu, lautan api kebencian menjalar, seperti mawar berwarna darah yang mekar dengan liar… semua puisi pun hancur menjadi abu di antara lidah api berwarna merah darah…"
  },
  Voice_6426_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6426_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6427_AwakerVoiceContent = {
    Text = "Memahami teknik baru, ya!"
  },
  Voice_6427_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6428_AwakerVoiceContent = {
    Text = "Hati-hati ya."
  },
  Voice_6428_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6429_AwakerVoiceContent = {
    Text = "Tongkat sihir ingin menari!"
  },
  Voice_6429_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6430_AwakerVoiceContent = {
    Text = "Hmm, perasaan hampa yang sudah tidak asing lagi!"
  },
  Voice_6430_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6431_AwakerVoiceContent = {
    Text = "Gerakan pada sendi menjadi lebih halus."
  },
  Voice_6431_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6432_AwakerVoiceContent = {
    Text = "Warna hitam yang tidak menyenangkan itu tampak mirip dengan pedang dan perisai amorfik saya… Ah! Mohon Tuan tenang! Pedang pelindung saya pasti tidak akan memberikan kerusakan pada Anda!"
  },
  Voice_6432_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_6433_AwakerVoiceContent = {Text = "Mari."},
  Voice_6433_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6434_AwakerVoiceContent = {
    Text = "Bisa dibilang lolos dengan susah payah."
  },
  Voice_6434_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6435_AwakerVoiceContent = {
    Text = "Aku akan melakukan yang terbaik."
  },
  Voice_6435_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6436_AwakerVoiceContent = {
    Text = "Apa kamu bermain di sini hari ini?"
  },
  Voice_6436_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6437_AwakerVoiceContent = {
    Text = "Di basement ada banyak air, lembut dan dingin. Jadi, tubuhku selalu dikelilingi oleh uap air… seakan-akan di antara langit dan bumi, aku adalah satu-satunya makhluk berdaging. Terkadang, aku benar-benar ingin melebur ke dalam air. \nNamun, jika aku melakukan itu, aku tidak akan ada lagi, dan aku juga tidak akan pernah bertemu denganmu."
  },
  Voice_6437_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6437_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6438_AwakerVoiceContent = {
    Text = [[
Aku akan memberitahumu sebuah rahasia... sebenarnya aku benci darah. Aku benci warnanya, aku benci rasanya. Tapi aku tidak bisa hidup tanpanya. 
... Aku menelan darah itu ke dalam kerongkonganku, lalu memuntahkannya semua... Aku membenci diriku sendiri.]]
  },
  Voice_6438_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6438_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6439_AwakerVoiceContent = {
    Text = "Hmm! Darahmu... ada aroma mirip mead. Aku pikir aku adalah satu-satunya yang mengetahui rahasia ini, benar kan?"
  },
  Voice_6439_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_6439_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_6440_AwakerVoiceContent = {
    Text = "Dalam khayalanku, seorang ksatria yang gagah berani akan menarikku keluar dari kegelapan, lalu mengikatku dengan rantai. Dia bisa memukuliku, memarahiku, melakukan apa saja padaku — rasa sakit adalah bukti bahwa aku masih hidup. \nMaukah Anda menjadi ksatriaku?"
  },
  Voice_6440_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6440_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6441_AwakerVoiceContent = {
    Text = "Darah mengalir seperti sungai. Aku adalah milikmu — perasaan ini belum pernah begitu kuat."
  },
  Voice_6441_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6441_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6442_AwakerVoiceContent = {
    Text = "Inilah kehendak dari Tiga Dewi Pembalasan!"
  },
  Voice_6442_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6443_AwakerVoiceContent = {
    Text = "Pedang tercabut."
  },
  Voice_6443_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_6444_AwakerVoiceContent = {
    Text = "Tidak bisa!"
  },
  Voice_6444_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6445_AwakerVoiceContent = {
    Text = "Sangat kotor, sangat kotor!"
  },
  Voice_6445_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_6446_AwakerVoiceContent = {
    Text = "...Aigis, terlihat!"
  },
  Voice_6446_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_6447_AwakerVoiceContent = {
    Text = "...Aigis, terlihat!"
  },
  Voice_6447_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6448_AwakerVoiceContent = {
    Text = "Tip, tentu saja tip. Lihat saja pelayan-pelayan yang lamban di kantin sekolah! Mereka bahkan tidak menyiapkan kursi malas terlebih dahulu, dan masih berharap mendapatkan imbalan tambahan? Mimpi!"
  },
  Voice_6448_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_6449_AwakerVoiceContent = {Text = "Hitam."},
  Voice_6449_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_6450_AwakerVoiceContent = {
    Text = "Biarkan aku keluar!"
  },
  Voice_6450_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu·Gelisah"
  },
  Voice_6451_AwakerVoiceContent = {
    Text = "Jangan seperti ini......"
  },
  Voice_6451_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu·Depresi"
  },
  Voice_6452_AwakerVoiceContent = {
    Text = "Tidak perlu begitu sopan, utusan pucat. Tidak seharusnya ada jarak di antara kita, karena kita semua adalah Relik ciptaan Tuhan, dan bersama-sama melangkah di jalan yang penuh lumpur dan ujian ini."
  },
  Voice_6452_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_6452_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_6453_AwakerVoiceContent = {
    Text = "Tentu saja, aku tidak takut kepada mereka, para makhluk malang yang menderita akibat kutukan penyusutan. Aku hanya merasa iba kepada mereka. Aku tahu bahwa aku tidak bisa mengambil alih penderitaan mereka, tetapi aku bisa memberikan apa pun yang mampu aku berikan, asalkan itu dapat memberi mereka sedikit ketenangan."
  },
  Voice_6453_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6453_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6454_AwakerVoiceContent = {
    Text = "Mau berdoa bersamaku, Api Pucat? Berdoa untuk mereka yang menderita dan tewas dalam Pertempuran kita hari ini. Meskipun mereka jatuh ke dalam Kegilaan karena kutukan penghancuran, mereka tetap merupakan Relik dari dewa kasih, saudara dan saudari kita. Semoga mereka menemukan ketenangan yang layak mereka dapatkan."
  },
  Voice_6454_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6454_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6455_AwakerVoiceContent = {
    Text = "Meskipun api merah membuatku tegang, aku akan melangkah ke atas panggung kayu yang terbakar sekali lagi untukmu. Tidak perlu merasa bersalah, Api pucat-ku. Di hadapan berkah yang bisa kau bawa, pengorbanan seorang diriku tidak ada artinya."
  },
  Voice_6455_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6455_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6456_AwakerVoiceContent = {
    Text = "Menyesal? Tidak, tentu saja tidak. Kematianku mengurangi penderitaan mereka dan memberi lebih banyak waktu, itu sudah cukup. Tapi... kamu sangat terbuka padaku, jadi aku juga tidak akan menyembunyikan apa pun darimu: hukuman bakar pada hari itu tetap meninggalkan luka di hatiku."
  },
  Voice_6456_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6456_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6457_AwakerVoiceContent = {
    Text = "Bisakah kita membuat perjanjian? Hmm... Kita berjanji, apa pun yang terjadi, kau akan selalu mengingat \"Ramona\", bagaimana?"
  },
  Voice_6457_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6457_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6458_AwakerVoiceContent = {
    Text = "Saya tidak menyesal memilih untuk menjadi seperti ini. Jika diberi kesempatan lagi, saya akan tetap melakukannya. Namun, Penjaga, saya sangat takut… takut bahwa \"Ramona\"tidak akan meninggalkan jejak apa pun di dunia ini."
  },
  Voice_6458_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6458_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6459_AwakerVoiceContent = {
    Text = "Tidak perlu khawatir, penutup mata ini tidak mengganggu penglihatanku. Bahkan, dengan begini aku bisa menyaring apa yang kulihat dan tidak terbebani oleh segala sesuatu di sekitarku."
  },
  Voice_6459_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_6459_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_6460_AwakerVoiceContent = {
    Text = "Ekspresi saya terlihat asing? Saya sudah berusaha mengendalikannya… Tampaknya, keberadaannya semakin kuat."
  },
  Voice_6460_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6460_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6461_AwakerVoiceContent = {
    Text = "Misteri yang belum terpecahkan, orang-orang yang harus diselamatkan terlalu banyak. Aku tidak tahu berapa lama lagi aku bisa terus bertindak, dan aku juga tidak mampu melindungi semua orang... Ini benar-benar sulit."
  },
  Voice_6461_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6461_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6462_AwakerVoiceContent = {
    Text = "Masih ingin bertaruh lebih banyak padaku? Tampaknya, hidup sesuai keinginan tidak semudah itu. Tenanglah, aku akan tetap membantumu menyelesaikan masalah sambil mencuri waktu untuk bersantai."
  },
  Voice_6462_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_6462_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_6463_AwakerVoiceContent = {
    Text = "Sudah sampai pada titik ini, aku harus menunjukkan kemampuan sebenarnya, kan? Di mana lokasi tempat kejadian? Meskipun harus mengorbankan semua keberuntunganku, aku pasti akan membawa tersangka kembali sebelum batas waktu!"
  },
  Voice_6463_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_6463_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_6464_AwakerVoiceContent = {
    Text = "Aduh, menerima begitu banyak keuntungan darimu, aku tidak bisa tidak memberitahumu beberapa rahasia: sebenarnya, aku mungkin orang yang paling sial di dunia ini."
  },
  Voice_6464_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_6464_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_6465_AwakerVoiceContent = {
    Text = "Sepertinya kau tidak terlalu memperhatikan apa yang kukatakan... ah, sudahlah. Aku tetap akan membantu merobek musuhmu. Toh, cakar dan taring ini juga kudapatkan secara kebetulan, kan?"
  },
  Voice_6465_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_6465_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_6466_AwakerVoiceContent = {
    Text = "Keberuntunganku belum tentu bisa disampaikan kepada teman. Kamu pasti pernah mendengar ungkapan itu, kan? \"Kaki kelinci yang membawa keberuntungan tidak ada manfaatnya bagi kelinci itu sendiri.\""
  },
  Voice_6466_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_6466_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_6467_AwakerVoiceContent = {
    Text = "Apakah kamu ingin menorehkan jejak Yu di dalam jiwamu?"
  },
  Voice_6467_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6468_AwakerVoiceContent = {
    Text = "Begitu menginginkan kekuatanku, ya?"
  },
  Voice_6468_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6469_AwakerVoiceContent = {
    Text = "Jangan lihat penampilanku seperti ini, aku dulunya adalah seorang wanita anggun... Aku bisa menyulam, membaca Tennyson... Oh iya, aku juga bisa bernyanyi: Dia seperti sungai yang tak pernah berhenti, mengalir di dalam darahku~"
  },
  Voice_6469_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6470_AwakerVoiceContent = {
    Text = "Pickman dan saya sedang berkolaborasi dalam beberapa karya seni instalasi yang menarik, membahas bagaimana merekonstruksi abstraksi ekspresionisme melalui dekonstruksi primitivisme visual... Eh, kenapa Aurita pingsan?"
  },
  Voice_6470_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Aurita"
  },
  Voice_6470_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Aurita\", akan terbuka."
  },
  Voice_6471_AwakerVoiceContent = {
    Text = [[
Apakah kamu ingin aku tersenyum?
Lily, apakah kamu sedang tersenyum?]]
  },
  Voice_6471_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Senyuman"
  },
  Voice_6472_AwakerVoiceContent = {
    Text = [[
Benar-benar mengejutkan, aku ternyata mendapatkan persahabatan yang setara.
Namun... aku ingin tetap mempertahankan hak untuk mengarahkanmu, sebagai sedikit keintiman di antara kita. Datanglah ke kamarku malam ini, masih banyak hal tentang perasaan manusia yang perlu kupelajari...]]
  },
  Voice_6472_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6472_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6473_AwakerVoiceContent = {
    Text = "Tahukah kamu bagian paling menggemaskan dari dirimu ada di mana? Itu adalah saat kamu berkata \"tidak\" padaku. Hidungmu akan berkerut, alismu sedikit terangkat... ya, persis seperti sekarang ini."
  },
  Voice_6473_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6473_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6474_AwakerVoiceContent = {
    Text = "Aku sangat menyayangi pelayan-pelayanku. Makhluk-makhluk kecil yang tampan ini, gemetar ketakutan akibat Pelarutan, bersembunyi di belakangku dengan cara yang begitu menggemaskan. Air mata seorang wanita selalu memikat hati. Bagaimana denganmu, apakah kamu takut pada Pelarutan?"
  },
  Voice_6474_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6474_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6475_AwakerVoiceContent = {
    Text = "Penjaga, apakah ada orang yang kamu benci? Sebagai balasannya, aku bisa membantu mendisiplinkan mereka. Dalam waktu kurang dari seminggu, aku akan membuatnya berubah sepenuhnya dan dengan patuh mencium ujung kakimu."
  },
  Voice_6475_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6475_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6476_AwakerVoiceContent = {
    Text = [[
Hmm... meskipun kamu agak lamban, setidaknya kamu tidak menjengkelkan. Mulai besok, kamu akan melayani aku.
Kamu tidak mau...? Ini bukan permintaan, ini perintah.]]
  },
  Voice_6476_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_6476_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_6477_AwakerVoiceContent = {
    Text = "Sudah lama tidak merasakan suasana hati seperti ini. Saya akan naik ke panggung dengan penampilan terbaik, menyuguhkan gelombang suara yang menggelegar melintasi alam semesta untuk Anda."
  },
  Voice_6477_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_6477_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_6478_AwakerVoiceContent = {
    Text = "Kamu harus tahu, ini tidak ada artinya."
  },
  Voice_6478_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6478_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6479_AwakerVoiceContent = {
    Text = "Setelah memetik bunga kemenangan, saya ingin meminta sedikit imbalan…"
  },
  Voice_6479_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6480_AwakerVoiceContent = {Text = "Ah"},
  Voice_6480_AwakerVoiceTitle = {
    Text = "Serangan·Depresi·Tiga"
  },
  Voice_6481_AwakerVoiceContent = {
    Text = "Kapal udara itu sempit dan pengap, seperti peti mati logam yang melayang di angkasa. Saya sedang menunggu bintang fajar saya, hingga Anda datang."
  },
  Voice_6481_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_6481_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_6482_AwakerVoiceContent = {
    Text = "Bagaimana bisa?!"
  },
  Voice_6482_AwakerVoiceTitle = {
    Text = "Serangan·Gelisah·Satu"
  },
  Voice_6483_AwakerVoiceContent = {Text = "Ngh..."},
  Voice_6483_AwakerVoiceTitle = {
    Text = "Terpukul·Depresi·Satu"
  },
  Voice_6484_AwakerVoiceContent = {Text = "Sakit..."},
  Voice_6484_AwakerVoiceTitle = {
    Text = "Tertekan·Depresi·Dua"
  },
  Voice_6485_AwakerVoiceContent = {
    Text = "Hukuman Langit!"
  },
  Voice_6485_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_6486_AwakerVoiceContent = {
    Text = "Hukuman Langit!"
  },
  Voice_6486_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6487_AwakerVoiceContent = {
    Text = "Membosankan."
  },
  Voice_6487_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_6488_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_6488_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_6489_AwakerVoiceContent = {
    Text = "Masih bisa bertahan."
  },
  Voice_6489_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_6490_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_6490_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_6491_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_6491_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6492_AwakerVoiceContent = {
    Text = "Orang yang tidak hormat, larutlah dalam ketenangan api yang membakar."
  },
  Voice_6492_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_6493_AwakerVoiceContent = {
    Text = "Hati-hati, jika kamu memasukkan tangan ke Dimensi lain, kamu tidak akan bisa menariknya kembali!"
  },
  Voice_6493_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_6494_AwakerVoiceContent = {
    Text = "Sekelompok sampah, jika tidak mau dijadikan daging cincang kalengan, lain kali harus lebih berhati-hati."
  },
  Voice_6494_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6495_AwakerVoiceContent = {
    Text = "Aduh, apa kau sedang manja padaku? \nSulit sekali, kalau begini terus, aku mungkin tidak bisa menunggu sampai Penjaga sepenuhnya dewasa ya…"
  },
  Voice_6495_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_6496_AwakerVoiceContent = {
    Text = "Menyelam jauh ke dalam kehendak bebas!"
  },
  Voice_6496_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6497_AwakerVoiceContent = {
    Text = "Hal yang menjijikkan… seperti dugaanku, dia memang orang yang selalu menyerah di tengah jalan. Begitu teringat orang seperti itu, aku merasa ingin muntah saat mengingat makan malam kemarin."
  },
  Voice_6497_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_6498_AwakerVoiceContent = {
    Text = "Kepala yang tak berujung, lihatlah wajahmu di sini!"
  },
  Voice_6498_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6499_AwakerVoiceContent = {
    Text = "Kepala yang tak berujung, lihatlah wajahmu di sini!"
  },
  Voice_6499_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_6500_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6500_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6501_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6501_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6502_AwakerVoiceContent = {
    Text = "Begitu mempercayaiku?"
  },
  Voice_6502_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6502_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6503_AwakerVoiceContent = {Text = "Kembali."},
  Voice_6503_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6504_AwakerVoiceContent = {Text = "Baik!"},
  Voice_6504_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_6505_AwakerVoiceContent = {
    Text = "Tentu saja aku tahu, itu sisi lain dari diriku. Tapi mengapa dia harus melawan? Menerima takdir sebagai yang terpilih, bukankah apa yang diinginkan akan mudah diraih?"
  },
  Voice_6505_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang \"Murphy\""
  },
  Voice_6505_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Murphy\", akan terbuka."
  },
  Voice_6506_AwakerVoiceContent = {
    Text = [[
Halo, nama saya Narsis. Saya pernah melakukan pertukaran dengan seorang tamu, dan orang itu meminta saya untuk membantu Anda. Jadi, ceritakanlah kebutuhan Anda. 
 Astaga... Apa yang Anda harapkan ternyata harganya tidak murah, ya?]]
  },
  Voice_6506_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6507_AwakerVoiceContent = {
    Text = "*Suara mati* Apa yang kamu lakukan! Percaya atau tidak, aku akan memotong tanganmu!"
  },
  Voice_6507_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_6508_AwakerVoiceContent = {Text = "Hahahaha!"},
  Voice_6508_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6509_AwakerVoiceContent = {Text = "Hahahaha!"},
  Voice_6509_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_6510_AwakerVoiceContent = {
    Text = "Duri mawar melukai jari, mengalir menjadi puisi."
  },
  Voice_6510_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6511_AwakerVoiceContent = {
    Text = "Tertunduk dalam kesedihan yang pekat ini, menjadi nyanyian duka..."
  },
  Voice_6511_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_6512_AwakerVoiceContent = {
    Text = "Lihat aku…!"
  },
  Voice_6512_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6513_AwakerVoiceContent = {Text = "Hmm…!"},
  Voice_6513_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6514_AwakerVoiceContent = {
    Text = "Clades Kedatangan!"
  },
  Voice_6514_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6515_AwakerVoiceContent = {
    Text = "Berikan itu padaku."
  },
  Voice_6515_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_6516_AwakerVoiceContent = {
    Text = [[
...Nama, uh, aku tidak bisa mengingatnya. 
Ah, "24", begitu mereka memanggilku... Tidak! Jangan keluar! Kau tidak boleh, sekarang tidak...]]
  },
  Voice_6516_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6517_AwakerVoiceContent = {
    Text = "Jejak tinta..."
  },
  Voice_6517_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_6518_AwakerVoiceContent = {Text = "Muncul..."},
  Voice_6518_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6519_AwakerVoiceContent = {
    Text = "Saya tidak pantas mendapatkan gelar seperti Suara Surgawi... yang terpenting adalah Anda menikmati nyanyian saya."
  },
  Voice_6519_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Bernyanyi"
  },
  Voice_6520_AwakerVoiceContent = {
    Text = "Pakaian yang kotor harus diganti sebelum acara salon berikutnya."
  },
  Voice_6520_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_6521_AwakerVoiceContent = {
    Text = "Itu akan segera menyusulku, kegelapan abadi, tak ada yang bisa melarikan diri…"
  },
  Voice_6521_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6522_AwakerVoiceContent = {
    Text = "Setiap kali melihatmu, aku teringat pada belenggu tak terlihat yang kau pasang padaku. Membiarkanmu tetap hidup sudah merupakan bentuk kesabaran terbesarku."
  },
  Voice_6522_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_6523_AwakerVoiceContent = {
    Text = "Berapa kali pun harus diulang, aku akan tetap maju bersamamu."
  },
  Voice_6523_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6524_AwakerVoiceContent = {
    Text = "Semoga kasih sayang Tuhan menghangatkan jiwamu."
  },
  Voice_6524_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_6525_AwakerVoiceContent = {
    Text = "Saya suka berkelana tanpa tujuan. Berkelana tanpa arah yang jelas. Rawa-rawa, pemakaman, ruang perawatan, kastil yang ditinggalkan... Di tempat-tempat seperti itu, saya selalu menemukan kejutan tak terduga."
  },
  Voice_6525_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6526_AwakerVoiceContent = {
    Text = "Merasa terhormatlah, gerbang Kerajaan Abadi ada di sini."
  },
  Voice_6526_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6527_AwakerVoiceContent = {
    Text = "Gak gak —— geli banget! Aurita juga mau balas menggelitik!"
  },
  Voice_6527_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_6528_AwakerVoiceContent = {
    Text = "\"Kematian Angsa\"，sebuah pertunjukan yang menggambarkan keinginan dan perjuangan hidup melalui bahasa tubuh penari. Bukankah sosok yang terbelit dalam api itu juga demikian?"
  },
  Voice_6528_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6529_AwakerVoiceContent = {
    Text = "Potong, potong, robek. Sama seperti yang mereka lakukan padaku di masa lalu… hehe…… hahaha!!"
  },
  Voice_6529_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_6530_AwakerVoiceContent = {
    Text = "Sebaiknya jangan terlalu dekat dengan Nona Thais... Bukan, aku tidak cemburu, aku hanya takut ada orang yang akan tertipu oleh wanita."
  },
  Voice_6530_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Thais"
  },
  Voice_6530_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Thais\", akan terbuka."
  },
  Voice_6531_AwakerVoiceContent = {
    Text = "...Terima kasih banyak."
  },
  Voice_6531_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6531_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6532_AwakerVoiceContent = {
    Text = "Bagus sekali... kamu memiliki mata yang tajam untuk mengenali orang."
  },
  Voice_6532_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6532_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6533_AwakerVoiceContent = {
    Text = "Rumah Karen sangat indah! Kota batu yang terletak di tengah danau.\nSetiap bulan purnama, kami akan menari tanpa suara di dalam api, melakukan ritual…...\nJujur, saat Karen baru datang ke universitas, setiap malam dia merindukan rumah dan diam-diam menangis di bawah selimut. Tapi sekarang, Karen telah memiliki rumah baru, keluarga baru, semuanya menjadi lebih baik!"
  },
  Voice_6533_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6533_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6534_AwakerVoiceContent = {
    Text = "Yah~ Masih belum puas? Ayo, biar aku melatihmu sebentar~"
  },
  Voice_6534_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_6535_AwakerVoiceContent = {
    Text = "Otot lemah, wajah kuyu, hanya mata ini yang seperti mata orang mati masih memiliki sedikit nilai — mencungkilnya untuk memberi makan laba-laba akan sangat sesuai."
  },
  Voice_6535_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_6536_AwakerVoiceContent = {
    Text = "Te-terima kasih banyak atas semua yang telah Anda lakukan untuk Aigis. Aigis akan berusaha semaksimal mungkin, tidak akan mengecewakan Anda."
  },
  Voice_6536_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6537_AwakerVoiceContent = {
    Text = "(Teriakan ketakutan)"
  },
  Voice_6537_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_6538_AwakerVoiceContent = {Text = "Jangan!"},
  Voice_6538_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_6539_AwakerVoiceContent = {
    Text = "Lepaskan aku..."
  },
  Voice_6539_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_6540_AwakerVoiceContent = {
    Text = "(Teriakan ketakutan)"
  },
  Voice_6540_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6541_AwakerVoiceContent = {
    Text = "Teknik pedang Milady Ramona sangat berbeda dari keterampilan yang aku kuasai. Jika tuanku mengizinkan, aku sangat ingin bertukar ilmu dengannya… Te-tentu saja! Ini hanya untuk meningkatkan diri!"
  },
  Voice_6541_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6541_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6542_AwakerVoiceContent = {
    Text = "Anda bertanya, mengapa saya tidak bermain dengan anak-anak lain? Sangat sulit untuk diungkapkan... Saya tidak memiliki banyak kesempatan untuk bermain saat masih hidup. Satu-satunya teman bermain saya adalah seorang putri yang pernah saya layani... Ah! Saya bahkan menyebut penguasa lain di hadapan tuanku. Mohon maafkan kelancangan saya..."
  },
  Voice_6542_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6542_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6543_AwakerVoiceContent = {
    Text = "Kamu adalah Penjaga yang diakui oleh Universitas Mythag, oleh karena itu, saya akan memberikan akses fungsi yang sesuai untukmu."
  },
  Voice_6543_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang \"Karakter Utama\""
  },
  Voice_6544_AwakerVoiceContent = {
    Text = "Apakah Tuan tertarik dengan \"Tujuh Keterampilan Ksatria\" yang saya pelajari? Luar biasa! Ah... eh... maafkan kelancanganku tadi. Maksudku, jika Anda bersedia berlatih memanah sambil berkuda, akan menjadi suatu kehormatan bagiku untuk menjadi rekan latihan Anda!"
  },
  Voice_6544_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6544_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6545_AwakerVoiceContent = {
    Text = "Saya bukan seorang ksatria yang pantas. Baik dari wabah jahat itu maupun dari musuh yang menyerang, saya tidak mampu melindungi tuanku terdahulu. Kini, Anda bersedia memberikan kepercayaan kepada seseorang sepertiku, ini adalah kehormatan besar bagiku... Dengan kemuliaan seorang ksatria dan nyawa yang tak berarti ini, aku bersumpah akan selalu melindungi jalanmu ke depan."
  },
  Voice_6545_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6545_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6546_AwakerVoiceContent = {
    Text = "Jangan sampai ada kerusakan."
  },
  Voice_6546_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6547_AwakerVoiceContent = {Text = "Jangan~"},
  Voice_6547_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6548_AwakerVoiceContent = {Text = "Tak!"},
  Voice_6548_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_6549_AwakerVoiceContent = {
    Text = "Jangan membunuh."
  },
  Voice_6549_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_6550_AwakerVoiceContent = {
    Text = "Nyaman sekali~!"
  },
  Voice_6550_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_6551_AwakerVoiceContent = {
    Text = "Sekarang, kita hanyalah air dan minyak yang tidak bisa menyatu."
  },
  Voice_6551_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_6552_AwakerVoiceContent = {
    Text = "Saya tidak punya hal yang benar-benar saya sukai. Jika harus memilih, rasanya cukup menyenangkan saat menjalankan misi di luar."
  },
  Voice_6552_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6553_AwakerVoiceContent = {
    Text = "Kenapa, kenapa kau mengurungku di sini? Haha... aku tidak akan membiarkanmu berhasil. Biar aku yang merobek semua belenggu ini, merobek seluruh penjara ini... menjadi fragmen!"
  },
  Voice_6553_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_6554_AwakerVoiceContent = {
    Text = "Melindungi semua orang."
  },
  Voice_6554_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6555_AwakerVoiceContent = {
    Text = "Kalian ini, setiap kali datang untuk melihat pertunjukan sulap, tidak bosan ya? Duduklah dengan baik, oke? Kalau kalian lari ke atas panggung lagi, aku akan melempar kalian ke dimensi lain!"
  },
  Voice_6555_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Anak-anak"
  },
  Voice_6555_UnlockDesc = {
    Text = "Setelah mendapatkan salah satu Pembangun \"Aigis\"\"Jenkin\"\"Lily\"\"Murphy\"\"Karen\"\"Aurita\", akan terbuka."
  },
  Voice_6556_AwakerVoiceContent = {
    Text = "Hadiah dari Anda, saya terima dengan penuh hormat."
  },
  Voice_6556_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6557_AwakerVoiceContent = {
    Text = "Hadiah balasan seperti apa yang dapat sepadan dengan dedikasi Anda?"
  },
  Voice_6557_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6558_AwakerVoiceContent = {
    Text = "Betapa memukau..."
  },
  Voice_6558_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6559_AwakerVoiceContent = {
    Text = "Mendeteksi arus listrik yang kuat, pemeliharaan mesin akan segera dilakukan… Koreksi, mengapa tidak terjadi overheating?"
  },
  Voice_6559_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_6559_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_6560_AwakerVoiceContent = {
    Text = "Sejak upacara Mencerahkan terakhir, saya melihat gambar-gambar yang rusak saat berada dalam Negara tidur. Di dalamnya, saya memiliki tubuh Caro seperti dirimu, dan juga bisa meneteskan air mata. Apakah ini sebuah mimpi?"
  },
  Voice_6560_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_6560_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_6561_AwakerVoiceContent = {
    Text = "Setelah setiap ritual, bagian dada selalu mendeteksi panas tinggi, tetapi tidak ada komponen terkait energi di sana. Apakah kamu tahu mengapa?"
  },
  Voice_6561_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_6561_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_6562_AwakerVoiceContent = {
    Text = "Aku melihatnya, semuanya <Del:harus mati dalam arus abadi> maafkan aku, modul tampaknya——peringatan, peringatan, aktivitas kesadaran non-Erica meningkat, hancurkan hancurkan hancurkan… halo, ada yang bisa aku bantu?"
  },
  Voice_6562_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_6562_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_6563_AwakerVoiceContent = {
    Text = "Setelah dianalisis secara cermat, saya menyimpulkan bahwa apa yang saya lihat saat berada dalam keadaan tidur bukanlah Mimpi dalam arti tradisional, melainkan <Del:Tubuh Caro saya yang menyedihkan seharusnya dihancurkan> Memori saya. Adapun panas yang membakar seperti kelebihan beban, mungkin itu adalah perasaan yang disebut \"ketidakrelaan\"."
  },
  Voice_6563_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_6563_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_6564_AwakerVoiceContent = {
    Text = "Jika ingin menonton pertunjukan, duduklah dengan tenang di kursi penonton!"
  },
  Voice_6564_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6564_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6565_AwakerVoiceContent = {
    Text = "Api kebencian berkobar dengan hebat, tak pernah padam."
  },
  Voice_6565_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6567_AwakerVoiceContent = {
    Text = "Kehendak yang menyatu denganku adalah sosok yang sangat berisik. Semakin kuat ia meningkat, suara \"Dia\" menjadi semakin jelas... seperti suara angsa di Hyde Park, cukup mengganggu."
  },
  Voice_6567_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_6567_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_6568_AwakerVoiceContent = {
    Text = "Saya akan menggunakan kekuatan ini untuk melahap para penghianat."
  },
  Voice_6568_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6569_AwakerVoiceContent = {
    Text = "...Terima kasih banyak."
  },
  Voice_6569_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6570_AwakerVoiceContent = {
    Text = "Penjaga? Lucu sekali. Mimpi yang tidak realistis ini sudah waktunya untuk bangun."
  },
  Voice_6570_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6571_AwakerVoiceContent = {
    Text = "Darah balas dendam sedang mendidih…"
  },
  Voice_6571_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6572_AwakerVoiceContent = {
    Text = "Bergeraklah, pelayan!"
  },
  Voice_6572_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6573_AwakerVoiceContent = {
    Text = "Jangan tenggelam!"
  },
  Voice_6573_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6574_AwakerVoiceContent = {
    Text = "Swish swish!"
  },
  Voice_6574_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6575_AwakerVoiceContent = {
    Text = "Jebakan tikus di belakang kantin sudah aku buang, terlalu berbahaya! Bagaimana kalau Cokelat yang ceroboh itu menginjaknya!"
  },
  Voice_6575_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_6576_AwakerVoiceContent = {
    Text = "Ini terasa sangat aneh... Apakah aku akan mati? Tidak, tolong selamatkan aku! Jangan!!!"
  },
  Voice_6576_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6576_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6579_AwakerVoiceContent = {
    Text = "Saya ingin sebuah lampu yang tidak akan padam; dia bahkan bilang, untuk bertukar dengan \"spesimen hidra tanpa sayap yang bisa terbang\". Di mana saya bisa menemukan spesies aneh seperti itu!"
  },
  Voice_6579_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Daffdell"
  },
  Voice_6579_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Narsis\", akan terbuka."
  },
  Voice_6582_AwakerVoiceContent = {Text = "Bahaya."},
  Voice_6582_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6583_AwakerVoiceContent = {
    Text = "Peringatan."
  },
  Voice_6583_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_6584_AwakerVoiceContent = {
    Text = "Terkena pukulan."
  },
  Voice_6584_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_6585_AwakerVoiceContent = {
    Text = "Harta yang berkilauan seperti kertas permen... Aigis akan menyimpannya dengan baik."
  },
  Voice_6585_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6586_AwakerVoiceContent = {
    Text = "Menerima kerusakan."
  },
  Voice_6586_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_6587_AwakerVoiceContent = {
    Text = "Toko kecilku bisa berada di dimensi mana pun, di posisi mana pun di alam semesta, tentu saja juga bisa berada di sini. Lagipula, aku sangat menyukai anak-anak Mythag yang kurang berhati-hati itu, lho?"
  },
  Voice_6587_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_6588_AwakerVoiceContent = {
    Text = "Benci... paprika hijau rasanya tidak enak."
  },
  Voice_6588_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_6589_AwakerVoiceContent = {
    Text = "Hubungan antara saya dan Anda seperti hubungan antara layar dan kapal. Tanpa kapal, layar tidak akan ada; tanpa layar, kapal sulit berlayar jauh. Bukankah begitu?"
  },
  Voice_6589_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_6590_AwakerVoiceContent = {
    Text = "Orang yang setia pada tarian mati, orang yang menista seni juga mati, mati dalam api yang menyala dengan bau ter pahit. Kematian bukanlah akhir, melainkan awal, karena yang mati hanyalah manusia, sedangkan tarian dan seni adalah abadi."
  },
  Voice_6590_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6590_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6591_AwakerVoiceContent = {
    Text = "Terima kasih atas pengertiannya, mungkin sekarang adalah saatnya untuk berdamai dengan diri sendiri di masa lalu… Saya percaya bahwa apa yang saya lakukan adalah benar, dan saya tidak pernah mencemarkan nama baik keluarga dalam seni tari. Saya akan naik ke panggung yang Anda persiapkan, dan seperti yang Anda harapkan, saya akan bersinar terang."
  },
  Voice_6591_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6591_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6592_AwakerVoiceContent = {
    Text = "Hati-hati ya."
  },
  Voice_6592_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6593_AwakerVoiceContent = {
    Text = [[
Apakah kau ingin aku naik ke panggung, bersinar di atasnya?
Itu sudah tidak mungkin lagi. Mata ini telah ditelan oleh kebencian. Selain membakar segalanya, aku tidak bisa melakukan apa pun.]]
  },
  Voice_6593_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_6593_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_6594_AwakerVoiceContent = {
    Text = "Apakah kamu mengerti perasaan itu? Berputar, berputar, berputar, tanpa henti. Lutut yang kaku terasa lemas, dan jejak darah hitam merembes dari ujung kaki, membasahi sepatu balet, namun tak berhenti sedetik pun. Semua ini karena aku menolak takdir untuk menjadi mainan..."
  },
  Voice_6594_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6594_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6595_AwakerVoiceContent = {
    Text = "Yang aku bakar bukanlah penari istana yang mahir, bukan pemimpin anggun dari kuil balet, bukan bangsawan yang mengerti untuk menghargai kemuliaan dan keindahan, melainkan orang biasa yang menjual tubuh mereka, makelar yang berusaha menyenangkan dengan mengabaikan orang lain, makhluk kotor yang terbenam dalam nafsu duniawi… Kamu akan mengerti aku, kan?"
  },
  Voice_6595_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6595_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6596_AwakerVoiceContent = {
    Text = "Aku tidak suka orang-orang dengan tentakel lengket, juga tidak suka dasar laut… Jangan tunjukkan ekspresi seolah kau sudah mengerti! Aku bukan anak kecil yang takut pada orang tua!"
  },
  Voice_6596_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6596_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6597_AwakerVoiceContent = {
    Text = "Anda begitu murah hati, saya sangat berterima kasih…"
  },
  Voice_6597_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6598_AwakerVoiceContent = {
    Text = "Menghilanglah!"
  },
  Voice_6598_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6599_AwakerVoiceContent = {
    Text = "Menghilanglah!"
  },
  Voice_6599_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_6600_AwakerVoiceContent = {
    Text = "Cepat bawa Cokelat pergi!"
  },
  Voice_6600_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6601_AwakerVoiceContent = {Text = "Jangan..."},
  Voice_6601_AwakerVoiceTitle = {
    Text = "Pertahanan·Depresi"
  },
  Voice_6602_AwakerVoiceContent = {Text = "Pergi!"},
  Voice_6602_AwakerVoiceTitle = {
    Text = "Pertahanan·Manik"
  },
  Voice_6603_AwakerVoiceContent = {
    Text = "Siapa Leigh? Oh, wanita yang meminta saya untuk memukulnya. Haha, cukup menarik... tampaknya di sini tidak terlalu membosankan juga."
  },
  Voice_6603_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Leigh"
  },
  Voice_6603_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Leigh\", akan terbuka."
  },
  Voice_6604_AwakerVoiceContent = {
    Text = "Matahari terbenam di bukit kecil sering kali membuatku teringat pada hari-hariku di Cleveland… Cleveland, aku masih bisa mengingat nama itu, tempat yang meninggalkan bekas luka ini…"
  },
  Voice_6604_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Senja"
  },
  Voice_6605_AwakerVoiceContent = {
    Text = "Ah……bintang-bintang……telah jatuh……"
  },
  Voice_6605_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6606_AwakerVoiceContent = {
    Text = "Tidak diragukan lagi, itu manusia. Apakah ada makhluk yang lebih kotor daripada manusia?"
  },
  Voice_6606_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_6607_AwakerVoiceContent = {Text = "Sekarang!"},
  Voice_6607_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6608_AwakerVoiceContent = {Text = "Hei!"},
  Voice_6608_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_6609_AwakerVoiceContent = {
    Text = "Pelarutan? Hmm… ya! Es krim memang bisa meleleh! Tapi jika kita semua berbagi bersama, kita bisa memakannya sebelum sepenuhnya berubah menjadi krim!"
  },
  Voice_6609_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_6610_AwakerVoiceContent = {
    Text = "Saya akan menggunakan kekuatan ini untuk melindungi Anda."
  },
  Voice_6610_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_6610_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_6611_AwakerVoiceContent = {
    Text = "Astaga, barang yang sudah dibeli di toko ini tidak dapat dikembalikan, ya? Memang benar kalau ingin menyelam ke Aequor, kamu membutuhkan kapal selam, kan?"
  },
  Voice_6611_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Caecus"
  },
  Voice_6611_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Caecus\", akan terbuka."
  },
  Voice_6612_AwakerVoiceContent = {
    Text = "Panggung terbaik! Semua guru dan siswa di Universitas Mythag dapat memahami bahwa pertunjukanku adalah sihir sejati! Inilah yang disebut sebagai jiwa seorang pesulap, bukan?"
  },
  Voice_6612_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_6613_AwakerVoiceContent = {
    Text = "Tatanan alam semesta berubah di sini; masa depan kehancuran adalah keyakinan para penyihir!"
  },
  Voice_6613_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_6613_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_6614_AwakerVoiceContent = {
    Text = "Bolehkah Aigis tetap di sini sebentar lagi? Aku akan tetap tenang dan tidak mengeluarkan suara apa pun, berusaha untuk tidak mengganggu Anda…"
  },
  Voice_6614_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6614_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6615_AwakerVoiceContent = {
    Text = "Dengan kebijaksanaan manusia... ungkap esensi dunia!"
  },
  Voice_6615_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6616_AwakerVoiceContent = {
    Text = "Dalam mimpi saya, sering terdengar suara ombak. Suara itu semakin jauh, semakin jauh. Saya tahu, mungkin saya akan selamanya tinggal di sini, manusia."
  },
  Voice_6616_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Aequor"
  },
  Voice_6617_AwakerVoiceContent = {
    Text = "Lebih banyak memori, lebih banyak emosi, lebih banyak impian——"
  },
  Voice_6617_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_6617_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_6618_AwakerVoiceContent = {
    Text = "Mulai berubah!"
  },
  Voice_6618_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6619_AwakerVoiceContent = {
    Text = "Jangan berkedip, ya!"
  },
  Voice_6619_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_6620_AwakerVoiceContent = {
    Text = "Setelah Dia dilahirkan... aku tidak perlu lagi menanggung penghinaan seperti ini..."
  },
  Voice_6620_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6621_AwakerVoiceContent = {
    Text = "Pilih aku, pilih aku! Di mana ada pesta, di situ ada Karen!"
  },
  Voice_6621_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6622_AwakerVoiceContent = {
    Text = "Hmm? Tertarik padaku? Sepertinya... kamu sudah siap membayar harganya, kan?"
  },
  Voice_6622_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_6623_AwakerVoiceContent = {
    Text = "Tidak akan memaafkan, tidak akan memaafkan…!"
  },
  Voice_6623_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6624_AwakerVoiceContent = {
    Text = "Masih memuji, warna yang berasal dari bintang-bintang."
  },
  Voice_6624_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6625_AwakerVoiceContent = {
    Text = "Bernyanyilah, bernyanyilah!"
  },
  Voice_6625_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_6626_AwakerVoiceContent = {Text = "Suka Ibu!"},
  Voice_6626_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6627_AwakerVoiceContent = {Text = "Mari."},
  Voice_6627_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6628_AwakerVoiceContent = {
    Text = "Hati-hati ya."
  },
  Voice_6628_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_6629_AwakerVoiceContent = {
    Text = "Pembangun mungkin akan makan karena rasa ingin tahu, tetapi makanan bukanlah kebutuhan untuk mempertahankan keberadaan kami. Jadi, tidak perlu memanggilku setiap kali ada teh sore. Mengonsumsi gula hanya akan mempercepat penuaan sendi bola Tubuh ini."
  },
  Voice_6629_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Teh Sore"
  },
  Voice_6632_AwakerVoiceContent = {
    Text = "Tolong, kalian harus membebaskan Tuan, Karen... Karen terserah kalian!"
  },
  Voice_6632_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6633_AwakerVoiceContent = {
    Text = "Apakah semua ini bisa dimakan oleh Lily?"
  },
  Voice_6633_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6633_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6634_AwakerVoiceContent = {
    Text = "Benci? Bolehkah aku mengatakannya, Aigis paling benci pada diriku yang selalu merasa tidak berdaya... Tapi begitu aku mengatakannya, Jenkin akan menjadi sangat marah... sangat marah..."
  },
  Voice_6634_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_6635_AwakerVoiceContent = {
    Text = "Menjadi abu."
  },
  Voice_6635_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_6636_AwakerVoiceContent = {
    Text = "Menjadi abu."
  },
  Voice_6636_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6637_AwakerVoiceContent = {
    Text = "Bagus sekali, Penjaga. Katakanlah, siapa yang harus kubunuh untukmu kali ini?"
  },
  Voice_6637_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_6637_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_6638_AwakerVoiceContent = {
    Text = "Pelarutan adalah alasan berdirinya akademi ini, juga alasan kita bertemu. Untuk menyelamatkan api umat manusia dari Pelarutan, berjuanglah, rekan."
  },
  Voice_6638_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_6639_AwakerVoiceContent = {
    Text = "Saya bisa merasakan permusuhan dari wanita itu, mungkin cinta saya pada Anda telah memicu rasa iri… Lihatlah, mulut paus bunga itu pun terbuka karena iri."
  },
  Voice_6639_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Lotan"
  },
  Voice_6639_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Lotan\", akan terbuka."
  },
  Voice_6640_AwakerVoiceContent = {
    Text = "Tuan! Tuan! Hari ini Karen melihat bros cameo yang super——cantik di Harol Department Store! Bisakah Tuan membelikannya untuk Karen? Ini adalah permintaan seumur hidupku!"
  },
  Voice_6640_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6641_AwakerVoiceContent = {
    Text = "Aku akan menjadi penunjuk arahmu dalam kegelapan malam, namun batas waktu ini tidak berlangsung selamanya."
  },
  Voice_6641_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_6642_AwakerVoiceContent = {
    Text = "Ibu, sangat sakit, Ibu…"
  },
  Voice_6642_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6643_AwakerVoiceContent = {
    Text = "Menyerahlah! Kemenangan sudah menjadi milik saya!"
  },
  Voice_6643_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_6644_AwakerVoiceContent = {
    Text = "Menyerahlah! Kemenangan sudah menjadi milik saya!"
  },
  Voice_6644_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6645_AwakerVoiceContent = {
    Text = "Pelarutan... kapasitas otakku terbatas, aku tidak bisa memahami penyakit yang begitu rumit... kalau ada mesin yang perlu diperbaiki, cari aku lagi!"
  },
  Voice_6645_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_6646_AwakerVoiceContent = {
    Text = "Ya! Aurita sudah ditemukan! Sebagai hukuman karena kalah, kamu bisa mengajukan satu permintaan kepada Aurita, oh—tapi tolong jangan suruh Aurita untuk pergi ke kelas, ya—mohon-mohon—"
  },
  Voice_6646_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_6647_AwakerVoiceContent = {
    Text = "Untuk menyapu rintangan bagi kedatangan-Nya kembali..."
  },
  Voice_6647_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6648_AwakerVoiceContent = {
    Text = "Suatu hari nanti, Paman Oen akan menyambutku kembali ke rumah kami di dasar laut. Sebelum itu, aku bisa dengan terpaksa menjadi temanmu."
  },
  Voice_6648_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6648_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6649_AwakerVoiceContent = {
    Text = [[
"Di dalam keluarga kami mengalir darah yang luar biasa, mereka yang terpilih akan menikmati kedamaian abadi di Aequor."
Tak disangka, setelah meninggalkan lautan dan datang ke akademi, barulah aku merasakan kedamaian itu. Kau berbeda dengan mereka yang mempermalukanku, jadi, aku juga tidak akan membiarkan orang lain mempermalukanmu."]]
  },
  Voice_6649_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6649_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6650_AwakerVoiceContent = {
    Text = "Bahan super keras yang dibuat khusus!"
  },
  Voice_6650_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6651_AwakerVoiceContent = {
    Text = "Terjebak dalam cangkang yang bercampur dengan elemen manusia ini benar-benar membuatku jijik. Setelah susah payah melepaskan diri dari masa lalu, sekarang malah harus mengingatnya lagi…"
  },
  Voice_6651_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_6651_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_6652_AwakerVoiceContent = {
    Text = "Aku tahu, pewaris darah mulia kembali menjadi anjing peliharaan manusia. Namun, jangan harap kau bisa sembarangan mengendalikanku."
  },
  Voice_6652_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6652_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6653_AwakerVoiceContent = {
    Text = "Hmph, manusia lemah sepertimu ternyata memiliki bakat dalam hal memimpin. Namun, tubuh yang buruk ini membuatku tidak bisa memberikan kemampuan terbaikku."
  },
  Voice_6653_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6653_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6654_AwakerVoiceContent = {
    Text = "Tubuh semakin panas."
  },
  Voice_6654_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6655_AwakerVoiceContent = {
    Text = "Lari... harus lari! Harus melarikan diri dari sini!"
  },
  Voice_6655_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6656_AwakerVoiceContent = {
    Text = "Lari... harus lari! Harus melarikan diri dari sini!"
  },
  Voice_6656_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_6657_AwakerVoiceContent = {
    Text = "Terima kasih atas usaha Anda, jadi izinkan saya memberikan hadiah yang sesuai kepada Anda."
  },
  Voice_6657_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6658_AwakerVoiceContent = {
    Text = "Tidak apa-apa."
  },
  Voice_6658_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_6659_AwakerVoiceContent = {
    Text = "(Gemuruh kesakitan)"
  },
  Voice_6659_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_6660_AwakerVoiceContent = {
    Text = "Manusia, meskipun kau lemah, keyakinanmu telah menyentuh hatiku. Aku bersedia menjadi senjatamu, mari kita berbuat keributan besar bersama!"
  },
  Voice_6660_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6660_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6662_AwakerVoiceContent = {
    Text = "Ini adalah salon saya."
  },
  Voice_6662_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6664_AwakerVoiceContent = {
    Text = "Akademi yang mengusung kesetaraan semua orang… entah harapan bodoh apa yang kalian miliki. Meskipun kamu tidak melakukan kesalahan apa pun, mereka tetap akan menginjakmu. Aku tahu bagaimana rasanya."
  },
  Voice_6664_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_6665_AwakerVoiceContent = {
    Text = "Ini adalah akar dari semua kekotoran…"
  },
  Voice_6665_AwakerVoiceTitle = {
    Text = "Muliakan·Depresi"
  },
  Voice_6666_AwakerVoiceContent = {
    Text = "Saya pernah dihukum karena gagal melindungi awak kapal. Mereka berkata, karena kelalaian saya, awak kapal yang hilang tidak akan pernah bisa berkumpul kembali dengan keluarga mereka… Apakah ini yang dimaksud dengan pelarutan?"
  },
  Voice_6666_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_6667_AwakerVoiceContent = {
    Text = "Lebih dekat dengan Tuhanku..."
  },
  Voice_6667_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6668_AwakerVoiceContent = {
    Text = "Kenapa? Kenapa kamu… tidak mau bangun?"
  },
  Voice_6668_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6669_AwakerVoiceContent = {
    Text = "Saya adalah Horla dari Cité, nama pena... Saya pernah berjanji kepada seseorang untuk tidak mengungkapkan nama pena saya kepada siapa pun. Maafkan saya, tetapi tolong panggil saya Horla saja."
  },
  Voice_6669_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6670_AwakerVoiceContent = {
    Text = "Saya menolak segala tindakan yang tidak adil, dan yang paling serius di antaranya adalah penghianatan. Di dalam militer, jika seseorang tidak bisa atau tidak berani mempercayakan punggungnya kepada rekan satu tim, seluruh pasukan akan menjadi tidak kompak."
  },
  Voice_6670_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_6671_AwakerVoiceContent = {
    Text = "Kenapa kau terlihat begitu gelap, namun juga begitu terang? …… Tidak, tidak apa-apa, anggap saja aku sedang berbicara omong kosong."
  },
  Voice_6671_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_6672_AwakerVoiceContent = {
    Text = "(Erangan kesakitan)"
  },
  Voice_6672_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_6673_AwakerVoiceContent = {
    Text = "(Desahan tegar)"
  },
  Voice_6673_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6674_AwakerVoiceContent = {Text = "Apa?!"},
  Voice_6674_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_6675_AwakerVoiceContent = {
    Text = "Saya menyukai kehidupan, menyukai cahaya. Saya ingin membuat Pingsan keluar dari cangkangnya yang terisolasi, menggunakan matanya sendiri untuk mendengar dan melihat dunia ini."
  },
  Voice_6675_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6676_AwakerVoiceContent = {
    Text = "Tidak terlihat!"
  },
  Voice_6676_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6677_AwakerVoiceContent = {
    Text = "Apakah pekerjaan pemeliharaan masih perlu dilanjutkan?"
  },
  Voice_6677_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6678_AwakerVoiceContent = {
    Text = "Persiapan komponen telah selesai."
  },
  Voice_6678_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6679_AwakerVoiceContent = {
    Text = "Manusia bisa memiliki niat penghianatan, tetapi alat tidak. Selama digunakan dengan tepat, pelarutan juga bisa menjadi alat untuk balas dendam."
  },
  Voice_6679_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_6680_AwakerVoiceContent = {
    Text = "Setelah bersembunyi selama ribuan tahun, saat ini akhirnya tiba... Aku adalah satu-satunya penguasa Perishite!"
  },
  Voice_6680_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_6680_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_6681_AwakerVoiceContent = {
    Text = "Baru saja lewat, apakah itu hibrida dari Aequor? Hmm... lihatlah tulang punggungnya yang tegak ini, malam ini aku akan melihat dia dalam posisi berlutut di tanah."
  },
  Voice_6681_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Caecus"
  },
  Voice_6681_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Caecus\", akan terbuka."
  },
  Voice_6682_AwakerVoiceContent = {
    Text = "Kekuatan perlahan kembali ke tangan... Langkah berikutnya, merebut hakku atas kekuasaan!"
  },
  Voice_6682_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_6682_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_6683_AwakerVoiceContent = {
    Text = "Tidak buruk, semakin dekat untuk menarik kerudung palsu wanita itu."
  },
  Voice_6683_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_6683_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_6684_AwakerVoiceContent = {
    Text = "Tenang, tenang, tenang..."
  },
  Voice_6684_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_6685_AwakerVoiceContent = {
    Text = "Tidak perlu ragu. Batas toleransi rasa sakit saya mungkin jauh melampaui imajinasi kalian."
  },
  Voice_6685_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6685_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6686_AwakerVoiceContent = {
    Text = "Menurutku, hal-hal indah yang bodoh adalah yang terbaik. Sayangnya, di sini dipenuhi dengan banyak otak yang cerdas namun tidak berguna."
  },
  Voice_6686_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_6687_AwakerVoiceContent = {
    Text = "Dengan memanfaatkan reaksi fusi nuklir dari bintang raksasa merah sebagai sumber energi, serta menambahkan energi yang dilepaskan saat bintang runtuh, mesin gerak abadi dapat diaktifkan untuk menyalakan lampu yang menyala selamanya... Eh? Kamu bilang, di sini tidak ada kondisi untuk membuat mesin gerak abadi, dan juga tidak ada bintang raksasa merah? Hmm..."
  },
  Voice_6687_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6688_AwakerVoiceContent = {
    Text = "Darah musuh belum habis."
  },
  Voice_6688_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_6689_AwakerVoiceContent = {
    Text = "Serahkan mereka… semua padaku!"
  },
  Voice_6689_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6690_AwakerVoiceContent = {
    Text = "Serahkan mereka… semua padaku!"
  },
  Voice_6690_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6691_AwakerVoiceContent = {
    Text = "Saatnya menuju medan perang."
  },
  Voice_6691_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6692_AwakerVoiceContent = {
    Text = "Sudah waktunya!"
  },
  Voice_6692_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_6693_AwakerVoiceContent = {
    Text = "Saat Yu tertidur, mimpi yang meluap akan memanggil makhluk untuk mendidih. Jadi, jangan mendekat saat Yu tidur nyenyak, dan jangan sembarangan Bangun Yu."
  },
  Voice_6693_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Tidur Panjang"
  },
  Voice_6694_AwakerVoiceContent = {
    Text = "Sudah waktunya!"
  },
  Voice_6694_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6695_AwakerVoiceContent = {
    Text = "Meskipun Herbert adalah orang yang sangat menakutkan, kucingnya sangat jinak... Eh, tunggu dulu, tepatnya, bukankah itu dua ekor kucing?"
  },
  Voice_6695_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Herbert"
  },
  Voice_6695_UnlockDesc = {
    Text = "Setelah menyelesaikan Bab 2 dari \"Operasi\""
  },
  Voice_6696_AwakerVoiceContent = {
    Text = [[
Wanita itu, Murphy, berpakaian terlalu mencolok... Tidak, Karen tidak boleh kalah darinya! 
 Atau, lebih baik membunuhnya saja...]]
  },
  Voice_6696_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Murphy"
  },
  Voice_6696_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Murphy\", akan terbuka."
  },
  Voice_6697_AwakerVoiceContent = {Text = "Ya~"},
  Voice_6697_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6698_AwakerVoiceContent = {Text = "Nyaman?"},
  Voice_6698_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6699_AwakerVoiceContent = {
    Text = "Ketika mencapai kerja sama dengan Universitas Mythag, jelas-jelas disepakati bahwa aku tidak akan dikirim untuk pertempuran…"
  },
  Voice_6699_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6699_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6700_AwakerVoiceContent = {
    Text = "Jangan terlalu berbangga diri. Terkadang, jarak antara kemuliaan dan kehinaan hanyalah satu langkah."
  },
  Voice_6700_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_6700_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_6701_AwakerVoiceContent = {
    Text = "Faros mengucapkan salam padamu. Memanggilmu ke sini, aku yakin kamu sudah siap untuk berlayar, bukan?"
  },
  Voice_6701_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_6702_AwakerVoiceContent = {
    Text = "Yahuu——sangat lelah, bolehkah aku pergi bermain sekarang!"
  },
  Voice_6702_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_6703_AwakerVoiceContent = {
    Text = "Ah ah… cahayanya begitu menyilaukan dan mempesona, tak terabaikan, kegilaan fanatik yang menutupi indra-indraku… Tidak, aku tidak bisa mencari alasan apapun untuk kebodohanku…"
  },
  Voice_6703_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Tulu"
  },
  Voice_6703_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Tulu\", akan terbuka."
  },
  Voice_6705_AwakerVoiceContent = {
    Text = "Bintang-bintang dalam mimpi yang terlelap, pergi ke tempat seharusnya, menunjuk ke arah Ranah Dewa!"
  },
  Voice_6705_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6706_AwakerVoiceContent = {
    Text = "Bukankah menurutmu, mendorong segala sesuatu menuju akhir dan menghentikan hukum dunia dari berputar adalah hal yang sangat menarik?"
  },
  Voice_6706_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6707_AwakerVoiceContent = {Text = "Minumlah!"},
  Voice_6707_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6708_AwakerVoiceContent = {Text = "Mantap!"},
  Voice_6708_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_6709_AwakerVoiceContent = {
    Text = "Silakan masukkan perintah pertempuran."
  },
  Voice_6709_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6710_AwakerVoiceContent = {
    Text = "Selama aku hanyut di antara bintang-bintang, aku telah bermimpi tentang hari ini berkali-kali… Terima kasih, karena telah mempersatukan aku kembali dengan Tinct."
  },
  Voice_6710_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Tinct"
  },
  Voice_6710_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Tinct\", akan terbuka."
  },
  Voice_6711_AwakerVoiceContent = {
    Text = "Universitas Mythag adalah tempat yang bagus, terutama kasino bawah tanah yang buka setiap minggu… \n Eh, Anda tidak tahu? Ups, apakah aku bicara terlalu banyak…"
  },
  Voice_6711_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_6712_AwakerVoiceContent = {
    Text = "\"Menghadapi krisis pelarutan,\" ha, kepuasan diri manusia benar-benar menggelikan."
  },
  Voice_6712_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Universitas Mythag"
  },
  Voice_6713_AwakerVoiceContent = {
    Text = "Pada akhirnya, manusia hanyalah makhluk yang dangkal. Hanya dengan beberapa kata dan sedikit insinuasi, mereka bisa memicu pertikaian di antara sesama… Hmm, tingkat seperti ini tidak cukup untuk membuat seseorang bersemangat."
  },
  Voice_6713_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Manusia"
  },
  Voice_6714_AwakerVoiceContent = {
    Text = "Mungkin, menganggapmu sebagai manusia biasa adalah pandanganku yang sempit dan prasangka awal. Aku sangat penasaran, bagaimana kamu, seorang tanpa keyakinan, bisa tetap menjaga bentengmu sendiri? Ini bukanlah pertanyaan dari Bunda Laut, melainkan kebingungan Miryam. Bisakah kamu menjawab pertanyaan ini untukku…?"
  },
  Voice_6714_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6714_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6715_AwakerVoiceContent = {
    Text = "Dirimu yang begitu istimewa, tidakkah engkau merasa jemu dengan hiruk-pikuk duniawi yang dangkal ini? Aku sungguh percaya bahwa Ranah Abadi adalah tempatmu pulang. Engkau akan melangkah di tanah para dewa, berenang di kolam roh suci, dan berakar di tanah subur yang luas… Bergabunglah dalam perjalanan suciku, bersamaku melampaui dunia fana ini. Pada saat itu, engkau dan aku akan berdiri berdampingan di sisi Takhta, menikmati kebahagiaan membangun kembali Ranah Dewa…"
  },
  Voice_6715_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_6715_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_6716_AwakerVoiceContent = {
    Text = "Kamu dan aku hanyalah orang-orang lemah yang merangkak di dunia ini, namun orang suci itu tidak sama. Dia adalah pelaksana kehendak, wujud dewa di antara manusia. Nasihatnya bagaikan kata-kata pencerahan dari para dewa, yang menuntun peradaban menuju keabadian… Aku tidak berharap kamu bisa memahami keyakinan terhadapnya sekarang, tetapi suatu hari nanti, kamu akan tunduk di bawah Takhtanya."
  },
  Voice_6716_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6716_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_6717_AwakerVoiceContent = {
    Text = "Para yang dipanggil adalah orang-orang yang berbahagia, tidakkah kau rasa demikian? Mereka memperoleh kekuatan ilahi dan memiliki umur yang lebih panjang. Ketika kerajaan Tuhan kembali turun, dan kehendak-Nya ditegakkan kembali di bumi, mereka akan menjadi pengikut yang mulia. Bukankah ini merupakan kebahagiaan dan keberuntungan yang besar bagi manusia yang lemah?"
  },
  Voice_6717_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6717_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6718_AwakerVoiceContent = {
    Text = "Kegembiraan yang disucikan oleh cahaya ilahi, orang-orang tanpa iman seperti dirimu tidak akan mampu memahaminya... Semoga dewa-dewaku mengampunimu, mengampuni ketidaktahuan dan ketidaksopananmu."
  },
  Voice_6718_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_6718_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_6719_AwakerVoiceContent = {
    Text = "Cepat selesaikan, Penjaga."
  },
  Voice_6719_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6720_AwakerVoiceContent = {
    Text = "Eh he——"
  },
  Voice_6720_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_6720_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_6721_AwakerVoiceContent = {
    Text = "Mati kau, serangga busuk Sparta."
  },
  Voice_6721_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6722_AwakerVoiceContent = {
    Text = "Boneka berkata, aku bisa sementara menghindari Pelarutan dengan cara meninggalkan tubuhku seperti dia… Tidak bisa, tidak bisa, tidak bisa. Saat operasi, aku akan kehilangan kesadaran, dan kegelapan akan masuk…"
  },
  Voice_6722_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Boneka"
  },
  Voice_6722_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Boneka\", akan terbuka."
  },
  Voice_6723_AwakerVoiceContent = {
    Text = "Hmph... apa? Mencari takdir kehancuran, ya?"
  },
  Voice_6723_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_6724_AwakerVoiceContent = {
    Text = "Apakah Tuan masih terganggu oleh insomnia? Karen telah menyiapkan obat penenang Dobie untukmu~! Meskipun dosisnya sedikit melebihi batas, tidur yang berkualitas tetap menjadi prioritas utama!"
  },
  Voice_6724_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_6724_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_6725_AwakerVoiceContent = {
    Text = "Saat itu kami sedang minum anggur kecil, bernyanyi, tiba-tiba berubah menjadi monster! Tapi tidak apa-apa, kulit hijau lumut juga cukup menarik!"
  },
  Voice_6725_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_6725_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_6726_AwakerVoiceContent = {
    Text = "Impian Karen? Hmm... membeli kalung mutiara yang indah, lalu memakainya untuk menghadiri pesta dansa, dan menjadi bintang yang paling bersinar!"
  },
  Voice_6726_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_6726_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_67276_AwakerVoiceContent = {
    Text = "Tifrelle Soder, yang menjadi wujud keinginan, juga telah menemukan cara untuk mempertahankan keberadaannya. Di hadapan hal-hal yang tidak diketahui, tak seorang pun mampu menilai apakah suatu metode itu mulia atau rendah."
  },
  Voice_67276_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Esensi Keinginan"
  },
  Voice_67276_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Thais\", akan terbuka."
  },
  Voice_67277_AwakerVoiceContent = {
    Text = "Menembus Pintu Kunci Perak, mencapai Takhta-Nya."
  },
  Voice_67277_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_67278_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_67279_AwakerVoiceContent = {
    Text = "Jangan menyia-nyiakan ilmu dan Memori-Nya."
  },
  Voice_67279_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6727_AwakerVoiceContent = {
    Text = "Gosok kiri, gosok kanan, debu dan kekhawatiran hilang semua——"
  },
  Voice_6727_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_6727_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_67280_AwakerVoiceContent = {
    Text = "Saya tidak berada di sini."
  },
  Voice_67280_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_67281_AwakerVoiceContent = {
    Text = "Sebuah fragmen dari kontinum ruang-waktu yang tak terbatas tiba di kesadaranku."
  },
  Voice_67281_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_67282_AwakerVoiceContent = {
    Text = "Saya sudah mengetahui keseluruhan."
  },
  Voice_67282_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_67283_AwakerVoiceContent = {
    Text = "Segalanya berada dalam kehampaan."
  },
  Voice_67283_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_67284_AwakerVoiceContent = {
    Text = "Kamu sudah melangkah sangat jauh dan dalam. Segera, kamu akan menyentuh keajaiban luar biasa itu. Semoga pada saat itu, kamu masih bisa mempertahankan ketenangan dan kewarasanmu seperti sekarang."
  },
  Voice_67284_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_67284_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_67285_AwakerVoiceContent = {
    Text = "\"Tidak tahu\". Bukan, secara tidak henti-hentinya mengejar pada dasarnya bukanlah ketidaktahuan. Orang yang benar-benar tidak tahu hidup dalam kekaburan, bahkan tidak menyadari apa yang tidak mereka ketahui."
  },
  Voice_67285_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_67286_AwakerVoiceContent = {
    Text = "Aku akan menunjukkan mimpiku kepadamu. Segala sesuatu yang aneh dan kacau yang kau lihat dalam mimpi lebih mendekati esensi dunia daripada realitas yang kau kenal."
  },
  Voice_67286_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_67286_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_67287_AwakerVoiceContent = {
    Text = "Ini adalah nasihat untukmu: jangan terburu-buru. Ketika kamu merasa lelah, segera hentikan berpikir, simpan tenaga dan energimu. Jika tidak, kamu akan tersesat selamanya dalam Mimpi."
  },
  Voice_67287_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_67287_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_67288_AwakerVoiceContent = {
    Text = "Siklus alam semesta terus berlangsung tanpa henti."
  },
  Voice_67288_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_67289_AwakerVoiceContent = {
    Text = "Sinkronisasi di antara kita seharusnya tidak memerlukan penyesuaian yang begitu lama. Namun, demi melindungi kesadaranmu dari bahaya ilusi, aku akan melakukannya secara bertahap."
  },
  Voice_67289_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_67289_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_6728_AwakerVoiceContent = {
    Text = "Pelarutan... kebetulan aku juga pernah menangani kasus yang terkait dengannya, tapi bagaimana ya, aku pikir menghilang adalah hal yang sangat alami. Pada akhirnya, setiap orang akan menghilang."
  },
  Voice_6728_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_67290_AwakerVoiceContent = {
    Text = "Gerbang Pertama. Alam semesta tak terbatas dilahirkan dari sebuah titik."
  },
  Voice_67290_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_67290_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_67291_AwakerVoiceContent = {
    Text = "Pintu kedua. Titik-titik membentuk garis yang terus berlanjut, mengarah ke dua kutub tanpa akhir."
  },
  Voice_67291_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_67291_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_67292_AwakerVoiceContent = {
    Text = "Pintu Keempat. Prototipe abadi terkunci di suatu ruang dalam Dimensi."
  },
  Voice_67292_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_67292_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_67293_AwakerVoiceContent = {
    Text = "Pintu ketiga. Bidangnya adalah kata ganti yang bersifat lokal dan sebagian."
  },
  Voice_67293_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_67293_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_67294_AwakerVoiceContent = {
    Text = "Gerbang Ekstrem. Tautan dari ribuan alam semesta menuju kehampaan akhir, menembus Gerbang Ekstrem, rahasia terdalam dunia akan terbuka untukmu."
  },
  Voice_67294_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_67294_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_67295_AwakerVoiceContent = {
    Text = "Pintu Kelima. Perubahan waktu hanyalah ilusi Anda, di dunia ini tidak pernah ada awal, dan tentu saja juga tidak ada akhir."
  },
  Voice_67295_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_67295_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_67296_AwakerVoiceContent = {
    Text = "Aku seharusnya hanya menjadi pemberi petunjukmu, membimbingmu untuk memulai perjalanan ini lalu tenggelam dalam kolam ilusi itu. Sekarang kau adalah Tautanku, hubungan antara kita berdua begitu rumit dan tak terpisahkan… sulit untuk diputuskan…"
  },
  Voice_67296_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_67297_AwakerVoiceContent = {
    Text = "Apa yang ingin kau konfirmasi? Sayangnya, indera dan pikiran Tubuh ini dibatasi dan diikat oleh banyak hal. Jika kau dan aku bertemu di Jurang, aku bisa membawamu melihat lebih banyak lagi…"
  },
  Voice_67297_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_67298_AwakerVoiceContent = {
    Text = "Dia juga merupakan salah satu Fragmen saya, berasal dari Dimensi lain, sebuah dunia yang telah musnah selamanya. Sungguh disayangkan, meskipun dia telah menguasai cara untuk memundurkan waktu, dia tidak dapat memahami hakikat di balik batas ruang dan waktu, sehingga hanya terperangkap dalam penderitaan berulang kali. Ini adalah kesalahan saya."
  },
  Voice_67298_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Ramona yang Berkeliling"
  },
  Voice_67298_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Ramona-loop\", akan terbuka."
  },
  Voice_67299_AwakerVoiceContent = {Text = "Saya tahu."},
  Voice_67299_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_6729_AwakerVoiceContent = {
    Text = "Apakah kamu sangat memperhatikan penampilan Tubuh ini? Jangan berpikir yang tidak-tidak, saat aku dilahirkan, aku memiliki wajah manusia."
  },
  Voice_6729_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_67300_AwakerVoiceContent = {
    Text = "Saya mengerti."
  },
  Voice_67300_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_67301_AwakerVoiceContent = {
    Text = "Begitu kecil."
  },
  Voice_67301_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_67302_AwakerVoiceContent = {
    Text = "Tetap tenang."
  },
  Voice_67302_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_67303_AwakerVoiceContent = {
    Text = "Tautan langsung dengan plasma akan merusak jiwa dan akal pikiranmu… Namun, karena kau bersikeras, aku pasti akan datang sebagai jawaban atas panggilanmu."
  },
  Voice_67303_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_67304_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_67305_AwakerVoiceContent = {
    Text = "Anak itu, karena fragmen kesadaran saya, telah menanggung terlalu banyak hal yang seharusnya tidak ia tanggung. Untungnya, jiwanya masih seperti perak mengalir, begitu jernih…"
  },
  Voice_67305_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Ramona"
  },
  Voice_67305_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Ramona\", akan terbuka."
  },
  Voice_67306_AwakerVoiceContent = {
    Text = "Mengunjungi Mimpi-Nya, mengintip rahasia tabu alam semesta."
  },
  Voice_67306_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_67307_AwakerVoiceContent = {Text = "Hmm."},
  Voice_67307_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_67308_AwakerVoiceContent = {
    Text = "Pintu kehampaan terbuka untukmu. Sambutlah dunia yang sunyi di balik pintu itu."
  },
  Voice_67308_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_67308_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_67309_AwakerVoiceContent = {
    Text = "Tujuan saya mendirikan sekolah ini bersama mereka adalah untuk \"menyimpan\". Kalian telah mencapai lebih dari yang saya perkirakan."
  },
  Voice_67309_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Mythag"
  },
  Voice_6730_AwakerVoiceContent = {
    Text = "Pelarutan adalah anugerah dari dewa. Rasa sakit yang dibawanya tidak berlebihan, cukup untuk membuat saraf kita mengalami kelumpuhan, membiarkan kita sepenuhnya menikmati makanan lezat, anggur merah, lalu bersama-sama berpesta pora menuju kehancuran."
  },
  Voice_6730_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Pelarutan"
  },
  Voice_67310_AwakerVoiceContent = {
    Text = "Masa lalu, sekarang, dan masa depan, miliaran cahaya bersinar terpusat di sini!"
  },
  Voice_67310_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_67311_AwakerVoiceContent = {
    Text = "Masa lalu, sekarang, dan masa depan, miliaran cahaya bersinar terpusat di sini!"
  },
  Voice_67311_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_67312_AwakerVoiceContent = {
    Text = "Gerbang Puncak telah terbuka. Di sini, segala sesuatu menjadi satu!"
  },
  Voice_67312_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_67313_AwakerVoiceContent = {
    Text = "Gerbang Puncak telah terbuka. Di sini, segala sesuatu menjadi satu!"
  },
  Voice_67313_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_67314_AwakerVoiceContent = {
    Text = "Mendengarkan suara kebijaksanaan."
  },
  Voice_67314_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Dua"
  },
  Voice_67315_AwakerVoiceContent = {
    Text = "Tak terbatas, tanpa akhir, tak terhingga, tanpa batas."
  },
  Voice_67315_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Tiga"
  },
  Voice_67316_AwakerVoiceContent = {
    Text = "Itu adalah kehendak-Nya... tidak, lebih tepatnya bukan kehendak, melainkan ketidaksadaran. Pandangan-Nya yang tanpa sadar akan menyerap segala sesuatu ke dalam napas-Nya."
  },
  Voice_67316_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Krisis"
  },
  Voice_67317_AwakerVoiceContent = {
    Text = "Tidak bisa menyelidiki secara rinci... jejak-jejak kecil..."
  },
  Voice_67317_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_67318_AwakerVoiceContent = {
    Text = "Aku akan menampilkan kebenaran."
  },
  Voice_67318_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_67319_AwakerVoiceContent = {
    Text = "\"Jawaban\". Aku menjaga pintu ini karena rasa suka, dan juga karena rasa suka itu aku menyerahkan kunci pintu ke tanganmu."
  },
  Voice_67319_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6731_AwakerVoiceContent = {
    Text = "Harus... kembali..."
  },
  Voice_6731_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_6732_AwakerVoiceContent = {
    Text = "Segala sesuatu di langit dan bumi, hukum sebab-akibat dalam siklus kehidupan!"
  },
  Voice_6732_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6733_AwakerVoiceContent = {
    Text = "Segala sesuatu di langit dan bumi, hukum sebab-akibat dalam siklus kehidupan!"
  },
  Voice_6733_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6734_AwakerVoiceContent = {
    Text = "Mata pisaunya belum pudar."
  },
  Voice_6734_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6735_AwakerVoiceContent = {
    Text = "Latihan juga tidak boleh dilalaikan."
  },
  Voice_6735_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6736_AwakerVoiceContent = {
    Text = "Lebih fleksibel."
  },
  Voice_6736_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6737_AwakerVoiceContent = {
    Text = "Hal yang tak berwujud akan berada di bawah kendali Anda."
  },
  Voice_6737_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_6737_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_6738_AwakerVoiceContent = {
    Text = "Rasakan napas yang membakar ini——"
  },
  Voice_6738_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6739_AwakerVoiceContent = {
    Text = "Kita semua akan menjadi... bagian dari Api Hijau..."
  },
  Voice_6739_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_6740_AwakerVoiceContent = {
    Text = "Perisai saya akan bersinar demi Anda, Tuan."
  },
  Voice_6740_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_6740_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_6741_AwakerVoiceContent = {
    Text = "Lagi-lagi ada kemajuan sedikit, sangat berterima kasih!"
  },
  Voice_6741_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_6741_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_6743_AwakerVoiceContent = {Text = "Hmph"},
  Voice_6743_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_6744_AwakerVoiceContent = {
    Text = "(Menahan diri dengan nada meremehkan)"
  },
  Voice_6744_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6745_AwakerVoiceContent = {
    Text = "(Menahan diri dengan nada meremehkan)"
  },
  Voice_6745_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_6746_AwakerVoiceContent = {
    Text = "(Menahan diri dengan nada meremehkan)"
  },
  Voice_6746_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_6747_AwakerVoiceContent = {
    Text = "Waktu yang dihabiskan bersama semua orang selalu terasa santai…"
  },
  Voice_6747_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_6748_AwakerVoiceContent = {
    Text = "Helot pembunuhan, utusan Tisiphone, mata penuh kebencian... mereka yang memberiku gelar-gelar itu. Tentu saja, aku tidak keberatan menjadi seperti itu."
  },
  Voice_6748_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Diri Sendiri"
  },
  Voice_6749_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_6749_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_6750_AwakerVoiceContent = {
    Text = "Tenaga penuh!"
  },
  Voice_6750_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_6751_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_6751_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_6752_AwakerVoiceContent = {Text = "(Terkejut)"},
  Voice_6752_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_6753_AwakerVoiceContent = {
    Text = "Bisakah kita pergi lebih jauh untuk bermain? Ayo pergi ke pantai!"
  },
  Voice_6753_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_6754_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_6755_AwakerVoiceContent = {
    Text = "Wow——terima kasih, teman~"
  },
  Voice_6755_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_6756_AwakerVoiceContent = {
    Text = "Teman~ lebih banyak teman~"
  },
  Voice_6756_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_6757_AwakerVoiceContent = {
    Text = "Uvhash… Dia memang istimewa. Kau kira dari mana keluargaku bisa hidup makmur? Semua berkat dia yang membunuh seperti anjing gila di arena. Dialah sumber pendapatan terbesar bagi keluargaku."
  },
  Voice_6757_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Uvhash"
  },
  Voice_6757_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Uvhash\", akan terbuka."
  },
  Voice_6758_AwakerVoiceContent = {Text = "Bodoh!"},
  Voice_6758_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_6759_AwakerVoiceContent = {Text = "Heh."},
  Voice_6759_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_6760_AwakerVoiceContent = {
    Text = "Maju! Berikan perintah pertempuran!"
  },
  Voice_6760_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_6761_AwakerVoiceContent = {
    Text = "Di dalam Jurang… akan ada cahaya keadilan."
  },
  Voice_6761_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_6762_AwakerVoiceContent = {
    Text = "Cahaya Keadilan menyala di sini!"
  },
  Voice_6762_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6763_AwakerVoiceContent = {
    Text = "Perasaan manusia adalah sesuatu yang rapuh seperti bunga, dan juga berharga seperti bunga…"
  },
  Voice_6763_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Colette"
  },
  Voice_6764_AwakerVoiceContent = {
    Text = "Hit, Stand, Black·Jack!"
  },
  Voice_6764_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_6765_AwakerVoiceContent = {
    Text = "Hit, Stand, Black·Jack!"
  },
  Voice_6765_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_67754_AwakerVoiceContent = {
    Text = "Jangan melawan, jangan menangis, jangan bertahan hidup!"
  },
  Voice_67754_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_67756_AwakerVoiceContent = {
    Text = "Jangan melawan, jangan menangis, jangan bertahan hidup!"
  },
  Voice_67756_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_67772_AwakerVoiceContent = {
    Text = "Pintu, bukalah."
  },
  Voice_67772_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  },
  Voice_79297_AwakerVoiceContent = {Text = "Oh."},
  Voice_79297_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_79298_AwakerVoiceContent = {Text = "Eh…?"},
  Voice_79298_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_80092_AwakerVoiceContent = {
    Text = "Terapis air, terapi listrik, terapi pengikatan, semua ini bukan penyembuhan tetapi penyiksaan, jadi selama masa pelayanan, aku akan menyembuhkan pasien rumah sakit jiwa dengan caraku sendiri, pada akhirnya mereka semua sembuh, menemukan kebebasan sejati."
  },
  Voice_80092_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_80092_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_80093_AwakerVoiceContent = {
    Text = "Malang White, karena panti di sekitar sudah penuh, dia dikurung keluarganya di kandang babi untuk dipelihara. Aku melakukan pengobatan secara gratis untuknya, setelah itu, dia akhirnya mengerti bahwa dia adalah manusia, bukan ternak, dan dengan tangannya sendiri mendapatkan kembali martabatnya sebagai manusia."
  },
  Voice_80093_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_80093_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_80094_AwakerVoiceContent = {
    Text = "Pekerja tekstil, pengacara, baron... Aku sama sekali tidak akan menolak pasien karena biaya, bagi saya, mereka semua hanyalah pasien yang perlu disembuhkan."
  },
  Voice_80094_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_80094_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_80095_AwakerVoiceContent = {
    Text = "Saya mengakui saya memang meremehkanmu, keberadaanmu adalah penderitaan itu sendiri. Kali ini tidak perlu perawatan lanjutan, saya ingin tinggal di sampingmu, melihat sendiri akhir yang tiba."
  },
  Voice_80095_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_80095_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_80096_AwakerVoiceContent = {
    Text = "Para pasien ini telah memberikanku kenangan indah. Sekarang, giliranmu, Penjaga, aku sudah menyiapkan akhir untukmu. Itu akan menjadi konsultasi yang paling berharga untuk ku ulang-ulang sepanjang karierku."
  },
  Voice_80096_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_80096_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_81138_AwakerVoiceContent = {
    Text = "Menolak bantuan dokter tidak baik untuk Anda. Mungkin lain kali, kita perlu mencoba hipnosis mendalam."
  },
  Voice_81138_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_81139_AwakerVoiceContent = {
    Text = "Kamar gelap, sendirian, ditambah dengan bisikan penuh rasa sakit yang terus-menerus berulang di benak, inilah cara terbaik untuk menikmati waktu."
  },
  Voice_81139_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_81140_AwakerVoiceContent = {
    Text = "Meskipun mengatakan hal ini agak tidak sopan, tetapi berbicara dengan anak itu hanya akan membuatku merasa bosan—kamu hanya bisa melihat satu ekspresi, yaitu senyum."
  },
  Voice_81140_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Aurita"
  },
  Voice_81140_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Aurita\", akan terbuka."
  },
  Voice_81141_AwakerVoiceContent = {
    Text = "Maafkan saya yang datang tanpa diundang, saya hanya merasakan energi psikologis rendahmu dan datang untuk memperhatikan. Sekarang, Penjaga, apakah kamu ingin memulai perjalanan jiwa?"
  },
  Voice_81141_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_81143_AwakerVoiceContent = {
    Text = "Metode penyembuhan dokter jiwa adalah dengan mengebor tengkorak pasien dengan karbit—tenanglah, itu sudah lama sekali, sekarang kami memiliki banyak cara untuk mengukur dan menyelami jiwa pasien."
  },
  Voice_81143_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_81143_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_81144_AwakerVoiceContent = {
    Text = "Untuk saling memahami, satu-satunya cara adalah membuka hati—sentuh di sini, hati perak saya akan terbuka untukmu."
  },
  Voice_81144_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_81145_AwakerVoiceContent = {
    Text = "Jika kamu ingin mendengarkan pendapat saya, maka mungkin kamu akan kecewa. Daripada curhat, saya lebih baik mendengarkan."
  },
  Voice_81145_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_81146_AwakerVoiceContent = {
    Text = "Ah, saya mendengar suaranya, bisikan itu, setiap suku kata dipenuhi dengan rasa sakit yang paling ekstrem!"
  },
  Voice_81146_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_81147_AwakerVoiceContent = {
    Text = "Saya akan mengingat rasa sakit dari saat ini, dan mengingatnya kembali untuk menikmati..."
  },
  Voice_81147_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_81148_AwakerVoiceContent = {
    Text = "Sebagai pecahan dari keberadaan tersebut, kamu memiliki aroma-Nya, aroma penuh rasa sakit itu, yang membuat setiap ingatanmu terasa sangat lezat."
  },
  Voice_81148_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_81149_AwakerVoiceContent = {
    Text = "Ingat ketakutan itu, deskripsikan dengan detail perasaan sakit yang saya alami, esensi terapi dampak emosional adalah menghadapi rasa sakit, mengatasi rasa sakit. Ayo, hapus air mata, ceritakan ingatan itu perlahan dan detail kepada saya..."
  },
  Voice_81149_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_81149_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_81150_AwakerVoiceContent = {
    Text = "Selamat, kamu sudah pulih—ya, halusinasi dan penglihatan adalah fenomena yang normal, itu adalah bukti bahwa kamu telah sembuh."
  },
  Voice_81150_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_81150_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_81151_AwakerVoiceContent = {
    Text = "Pikiranmu pasti penuh dengan pemandangan yang aneh dan fantastis, tidak apa-apa, itu semua normal. Gambarkan mereka, bawah sadar dan nalurimu akan mengungkapkan segalanya."
  },
  Voice_81151_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_81151_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_81152_AwakerVoiceContent = {
    Text = "Selanjutnya adalah terapi moral Philippe Pinel. Anda perlu mengungkapkan keinginan dan ketakutan terdalam, ini adalah proses yang diperlukan untuk melepaskan belenggu jiwa dan mengembalikan kemanusiaan yang tertidur."
  },
  Voice_81152_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_81152_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_81153_AwakerVoiceContent = {
    Text = "Penjaga, bisakah kamu membantuku menyelesaikan tes kecil? Hanya tes bercak Rorschach, dengan itu, aku bisa melihat kedalaman dalam dirimu yang tak seorang pun tahu, menjadi Pembangun yang satu-satunya mengungkap rahasia batin Penjaga."
  },
  Voice_81153_AwakerVoiceTitle = {
    Text = "Percakapan Santai·Analisis Psikologis"
  },
  Voice_81154_AwakerVoiceContent = {
    Text = "Pertama, mari kita dengarkan sebuah musik. Apakah kamu mendengarnya, musik yang lembut dan menenangkan. Sekarang, biarkan tubuh dan pikiranmu bergetar dengan musik, memasuki relaksasi jiwa..."
  },
  Voice_81154_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_81154_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_81155_AwakerVoiceContent = {
    Text = "Mengamati bandul, matanya mengikuti larut.…"
  },
  Voice_81155_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_81156_AwakerVoiceContent = {
    Text = "Ssshh—diam, lalu menuju akhir yang saya tunjukkan."
  },
  Voice_81156_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_81157_AwakerVoiceContent = {
    Text = "Jiwa yang mati tidak akan menarik perhatian saya sedikit pun. Jiwa mereka telah mati, tidak peduli seberapa besar penggodaannya, tidak akan ada riak sedikit pun."
  },
  Voice_81157_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_81158_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_81159_AwakerVoiceContent = {
    Text = "Saya mendengarkan, silakan lanjutkan."
  },
  Voice_81159_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_81160_AwakerVoiceContent = {
    Text = "Tolong tetap tenang."
  },
  Voice_81160_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_81161_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_81162_AwakerVoiceContent = {
    Text = "Percayalah padaku sedikit lebih lagi."
  },
  Voice_81162_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_81163_AwakerVoiceContent = {
    Text = "Tunjukkan lebih banyak rasa sakit!"
  },
  Voice_81163_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_81164_AwakerVoiceContent = {
    Text = "Tak perlu menyembunyikan, tak perlu malu, aku adalah pendengar yang paling kamu percayai. Ayo, curahkan rasa sakit terberatmu padaku..."
  },
  Voice_81164_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_81165_AwakerVoiceContent = {
    Text = "Aigis sekarang tampak jauh lebih ceria. Tentu saja, jika tamu kecil saya membutuhkan bantuan, saya bersedia menawarkan bantuan. Maksud saya, bantuan yang nyata."
  },
  Voice_81165_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Aigis"
  },
  Voice_81165_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Aigis\", akan terbuka."
  },
  Voice_81166_AwakerVoiceContent = {
    Text = "Tunjukkan sisi terhinamu padaku."
  },
  Voice_81166_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_81168_AwakerVoiceContent = {
    Text = "Saya akan menikmati rasa sakit manis ini dengan baik."
  },
  Voice_81168_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_81169_AwakerVoiceContent = {
    Text = "Tak perlu menyembunyikan, tak perlu malu, aku adalah pendengar yang paling kamu percayai. Ayo, curahkan rasa sakit terberatmu padaku..."
  },
  Voice_81169_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_81170_AwakerVoiceContent = {
    Text = "Penyakit mental bukanlah eksklusif zaman ini, ia melampaui waktu dan ruang, demikian juga pelarutan. Keduanya melampaui batas pemahaman manusia, bukan?"
  },
  Voice_81170_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Krisis"
  },
  Voice_81171_AwakerVoiceContent = {
    Text = "Ssshh—diam, lalu menuju akhir yang saya tunjukkan."
  },
  Voice_81171_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_81172_AwakerVoiceContent = {
    Text = "Ini penuh dengan jejak sejarah, dan dalam beberapa hal, sejarah mewakili kenangan—kenangan menyakitkan dari yang telah pergi."
  },
  Voice_81172_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Mythag"
  },
  Voice_81173_AwakerVoiceContent = {
    Text = "Tarik napas dalam-dalam……"
  },
  Voice_81173_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_81174_AwakerVoiceContent = {
    Text = "Sakit, keputusasaan, kematian... ingatan-inyatan ini terasa seperti pencuci mulut setelah makan."
  },
  Voice_81174_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_81175_AwakerVoiceContent = {
    Text = "Tidak perlu begitu tegang, ini hanya konsultasi psikologis biasa."
  },
  Voice_81175_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_81176_AwakerVoiceContent = {
    Text = "Dengarkan petunjuk dari saya."
  },
  Voice_81176_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_84185_AwakerVoiceContent = {
    Text = "Upacara mengalami kejadian tak terduga. Harap maafkan saya karena harus memukul lengan Anda dengan bendera, saya harus membuat Anda tetap terjaga."
  },
  Voice_84185_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_84185_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_84186_AwakerVoiceContent = {
    Text = "Di sini kamu bisa melihat model kapal yang berbeda, menyentuh peralatan navigasi yang lebih canggih, saya sangat menyukainya, yang terpenting adalah, saya pikir kapal ini berjalan di jalur sejarah manusia yang benar."
  },
  Voice_84186_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Mythag"
  },
  Voice_84187_AwakerVoiceContent = {
    Text = "Upacara berlangsung dengan sukses, terima kasih atas kerjasama Anda. Lain kali saya akan menciptakan beberapa sinyal khusus untuk membantu kami menyelesaikan upacara dengan lebih aman dan lancar."
  },
  Voice_84187_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_84187_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_84188_AwakerVoiceContent = {
    Text = "Saya tidak tahu mengapa itu ada, saya hanya tahu satu hal: saya harus berhasil sebagai navigator dan membawa pulang semua pelaut dan penumpang yang pergi ke laut dengan aman."
  },
  Voice_84188_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Krisis"
  },
  Voice_84189_AwakerVoiceContent = {
    Text = "Tenanglah, saya akan menggunakan Kekuatan ini untuk menuntun keselamatan pelayaran kapal ini, tidak akan menyalahgunakannya."
  },
  Voice_84189_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_84190_AwakerVoiceContent = {
    Text = "Silahkan berhenti melawan."
  },
  Voice_84190_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_84191_AwakerVoiceContent = {
    Text = "Saya hanya memiliki rasa hormat untuk Anda, dan akan berjanji untuk menyelesaikan semua perintah yang Anda berikan dengan sekuat tenaga."
  },
  Voice_84191_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_84192_AwakerVoiceContent = {
    Text = "Maaf, saya tidak mengerti orang, hanya mengerti kapal, maafkan saya menggunakan perumpamaan ini: Lambung kapalmu bukanlah kayu atau besi, tetapi baja, kuat dan tegas, sangat mengagumkan."
  },
  Voice_84192_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_84192_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_84193_AwakerVoiceContent = {
    Text = "Menyerah saja."
  },
  Voice_84193_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_84194_AwakerVoiceContent = {
    Text = "Daripada menyukai, saya lebih memilih menggunakan kata \"Bertarak\". Ketika menghadapi Dewa tak bernama itu, otak saya kehilangan rasionalitas dan jatuh ke dalam kegembiraan, ya, saya seharusnya takut pada-Nya, tetapi saya tidak bisa mengendalikan diri saya."
  },
  Voice_84194_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_84195_AwakerVoiceContent = {
    Text = "Saya tidak akan kalah terhadap badai."
  },
  Voice_84195_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_84196_AwakerVoiceContent = {
    Text = "Tanpa tatanan, apa yang tersisa di dunia ini? Hanya kekacauan dan kekacauan belaka."
  },
  Voice_84196_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_84197_AwakerVoiceContent = {
    Text = "Di pelayaran berikutnya, saya ingin naik kapal sebagai sesuatu selain seorang navigator. Itu... maksud saya, saya bersedia dan menerima untuk bertindak di bawah petunjuk Anda. Anda pantas mendapatkan kepercayaan penuh saya."
  },
  Voice_84197_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_84197_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_84198_AwakerVoiceContent = {
    Text = "Saya hanya menjalankan tugas saya sebagai navigator, tidak perlu memberi laporan pujian."
  },
  Voice_84198_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_84199_AwakerVoiceContent = {
    Text = "Sistem mercusuar dapat sangat mengurangi tekanan navigasi, dan cahayanya sangat terang, saya sangat senang berlayar bersama Faros."
  },
  Voice_84199_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Faros"
  },
  Voice_84199_UnlockDesc = {
    Text = "Terkunci setelah mendapatkan Pembangun \"Pallos\""
  },
  Voice_84200_AwakerVoiceContent = {
    Text = "Para pelaut, ikutilah panduan saya dan kita pasti akan tiba dengan selamat di pelabuhan."
  },
  Voice_84200_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_84201_AwakerVoiceContent = {
    Text = "Tautan roh berhasil, aku merasakan kesadaran Anda...... Ini adalah pertama kalinya aku mengarahkan di ruang hampa, jika ada masalah arah, mohon koreksi segera."
  },
  Voice_84201_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_84201_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_84202_AwakerVoiceContent = {
    Text = "Telah diamati awan lenticular dan tingkat air raksa barometer terus menurun, harap semua perhatian, kapal akan menghadapi badai."
  },
  Voice_84202_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_84203_AwakerVoiceContent = {
    Text = "Kekacauan ini semua karena kesalahan dalam merencanakan rute, saya bersedia menerima hukuman sesuai aturannya."
  },
  Voice_84203_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_84204_AwakerVoiceContent = {
    Text = "Mengukur sudut ketinggian benda langit."
  },
  Voice_84204_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_84205_AwakerVoiceContent = {
    Text = "Pusing ini mirip seperti mabuk kapal. Silakan tutup mata, pegang tangan saya, bersandar di sisi saya, ini akan lebih baik."
  },
  Voice_84205_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_84205_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_84206_AwakerVoiceContent = {
    Text = "Tarik layar depan, miring ke kiri, juru kemudi menyesuaikan jalur sesuai perhitunganku."
  },
  Voice_84206_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_84207_AwakerVoiceContent = {
    Text = "Pengalaman ini sangat berharga, saya akan mencatatnya dengan rinci dalam jurnal pelayaran, membaginya kepada pelaut yang datang kemudian."
  },
  Voice_84207_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_84208_AwakerVoiceContent = {
    Text = "Ritual untuk memperdalam tautan memiliki risiko dan hasil yang tidak diketahui, tetapi jangan khawatir, aku akan memandu kamu, agar ritual dapat selesai dengan sukses."
  },
  Voice_84208_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_84208_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_84209_AwakerVoiceContent = {
    Text = "Menyesuaikan kembali pusat gravitasi."
  },
  Voice_84209_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_84210_AwakerVoiceContent = {
    Text = "Perhatikan dan lindungi perahu."
  },
  Voice_84210_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_84211_AwakerVoiceContent = {
    Text = "Beberapa orang adalah kapal uap, respons lambat tetapi dapat beroperasi dengan kecepatan tinggi, beberapa adalah kapal diesel, cepat memulai tetapi daya terbatas. Bagaimana dengan Anda, Penjaga?"
  },
  Voice_84211_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_84211_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_84212_AwakerVoiceContent = {
    Text = "Saya sangat percaya pada hukum dasar bahwa kerja keras akan mendapatkan imbalan, dan di masa depan saya akan lebih berusaha."
  },
  Voice_84212_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_84213_AwakerVoiceContent = {
    Text = "Dalam banyak aksi tugas, Anda telah membuktikan diri Anda. Saya pikir Anda adalah pelaut yang hebat seperti saya, tidak, mungkin Anda bahkan jauh lebih hebat dari saya."
  },
  Voice_84213_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_84213_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_84214_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_84215_AwakerVoiceContent = {
    Text = "Selama kamu membutuhkan, Keper Sanga siap sedia."
  },
  Voice_84215_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_84215_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_84216_AwakerVoiceContent = {
    Text = "Para pelaut, ikutilah panduan saya dan kita pasti akan tiba dengan selamat di pelabuhan."
  },
  Voice_84216_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_84217_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_84218_AwakerVoiceContent = {
    Text = "Mengarungi perlahan, Kapten Kupert datang melapor! Bendera sudah siap, kondisi pribadi baik, silakan Penjaga memberikan perintah berlayar."
  },
  Voice_84218_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_84219_AwakerVoiceContent = {
    Text = "Saya pasti akan mengarahkan kapal ke arah yang benar."
  },
  Voice_84219_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_84220_AwakerVoiceContent = {
    Text = "Apakah topinya miring? Maaf, saya tidak terlalu memahami niat Anda melakukan ini, mohon beri saya instruksi yang jelas."
  },
  Voice_84220_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_84221_AwakerVoiceContent = {
    Text = "Bendera adalah bahasa panduan, juga nisan panduan. Saat kapal tenggelam, penyelamat akan membaca pesan terakhir yang aku tinggalkan dari sisa-sisa bendera."
  },
  Voice_84221_AwakerVoiceTitle = {
    Text = "Percakapan Santai·Tentang Bendera"
  },
  Voice_84222_AwakerVoiceContent = {
    Text = "Mendapatkan titik keseimbangan kapal."
  },
  Voice_84222_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_84223_AwakerVoiceContent = {
    Text = "Tarik layar depan, miring ke kiri, juru kemudi menyesuaikan jalur sesuai perhitunganku."
  },
  Voice_84223_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_84224_AwakerVoiceContent = {
    Text = "E bendera menyampaikan instruksi."
  },
  Voice_84224_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_84225_AwakerVoiceContent = {
    Text = "Pada saat yang diperlukan, navigator yang telah mempelajari kolaborasi ruang mesin juga dapat berfungsi sebagai juru mudi, tetapi demi keamanan kapal, saya masih berharap untuk memberikan tugas ini kepada orang yang ahli."
  },
  Voice_84225_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Celeste"
  },
  Voice_84225_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Celeste\", akan dibuka."
  },
  Voice_84226_AwakerVoiceContent = {
    Text = "Perasaan kehilangan berat muncul, diikuti oleh goyangan seperti kapal bergetar hebat. Ikuti gerakan saya untuk merasakan pusat tubuh, jaga keseimbangan."
  },
  Voice_84226_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_84226_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_84406_AwakerVoiceContent = {
    Text = "Memulai koreksi carta laut."
  },
  Voice_84406_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  },
  Voice_84407_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Tiga"
  },
  Voice_84408_AwakerVoiceContent = {
    Text = "Perintah respon bendera C."
  },
  Voice_84408_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Dua"
  },
  Voice_84409_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Tiga"
  },
  Voice_90333_AwakerVoiceContent = {
    Text = "Jangan bermimpi melewatiku."
  },
  Voice_90333_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_90334_AwakerVoiceContent = {
    Text = "Bagaimana seharusnya teman berinteraksi? Polydeuces suka memberi perintah banyak hal padaku, meskipun dia bisa melakukannya sendiri. Dan saya juga bersedia membantunya melakukan hal-hal tersebut, itu adalah bentuk komunikasi di antara kita. Jika Anda mau, saya juga akan melakukan sesuatu untuk Anda."
  },
  Voice_90334_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_90334_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_90335_AwakerVoiceContent = {
    Text = "Dengan tubuh yang abadi ini, menahan segala clades!"
  },
  Voice_90335_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_90336_AwakerVoiceContent = {
    Text = "Bahkan sebelum melihat buku itu, kami juga tidak pernah tidak penasaran dengan dunia luar, penasaran dengan pemandangan di luar pulau isolasi di danau, dinding merah tua. Namun saat Polydeukes disiksa, saya tidak pernah berpikir untuk melawan, dibandingkan dengan Polydeukes, saya jauh lebih lemah dan canggung."
  },
  Voice_90336_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_90336_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_90337_AwakerVoiceContent = {
    Text = "Apakah saya seperti orang bodoh? Maafkan saya atas ketidaktahuan saya, selain dari lampu yang mengajarkan tentang Tuhan, saya tahu sangat sedikit tentang segala hal lainnya. Saya akan belajar lebih cepat, tolong beri tahu saya apa yang Anda sukai, apa yang Anda benci, saya pasti akan mengingatnya."
  },
  Voice_90337_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_90337_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_90338_AwakerVoiceContent = {
    Text = "Saksikanlah, kehendak untuk mengejar kebebasan ini."
  },
  Voice_90338_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_90339_AwakerVoiceContent = {
    Text = "Toko yang dapat memenuhi keinginan apa pun, dengan barang-barang yang melimpah, sungguh membuat orang menjauh...tidak, saya tidak mempertanyakan kekuatan wanita itu, tetapi, \"untuk memiliki sesuatu, Anda harus membayar harga yang setimpal\", alasan ini telah kami, saya dan Poluksus rasakan terlalu sering."
  },
  Voice_90339_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Daffdell"
  },
  Voice_90339_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Narsis\", akan terbuka."
  },
  Voice_90340_AwakerVoiceContent = {
    Text = "Apakah sayap yang terkutuk ini juga bisa terbang tinggi di angkasa?"
  },
  Voice_90340_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_90341_AwakerVoiceContent = {
    Text = "Kalian tidak bisa menghancurkanku!"
  },
  Voice_90341_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_90342_AwakerVoiceContent = {
    Text = "Apakah Anda ingin menyentuh bulu-bulu ini? Silahkan, haruskah saya mengembangkan sayap sedikit?"
  },
  Voice_90342_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_90343_AwakerVoiceContent = {
    Text = "Saat menerima bantuan dari orang lain, sering kali saya berpikir, apakah ada harga lain di balik perawatan khusus, buku berharga yang Anda berikan, dan batu permata yang indah dari meteor tersebut? Maaf, saya tidak seharusnya menduga seperti ini."
  },
  Voice_90343_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_90343_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_90344_AwakerVoiceContent = {
    Text = "Burung akhirnya akan terbang di atas langit yang tinggi."
  },
  Voice_90344_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_90345_AwakerVoiceContent = {
    Text = "Menjadi master memasak hidangan lezat... pengetahuan membuat makanan memang sangat penting, meskipun saya tidak terlalu menuntut tentang makan, tetapi Polydeuces sangat pemilih. Sepertinya saya harus mencari waktu untuk belajar dengan serius... Jangan pergi? Mengapa, tetapi makanan yang dibuat oleh pria itu terlihat sangat lezat?"
  },
  Voice_90345_AwakerVoiceTitle = {
    Text = "Obrolan·Tentang Dullesai"
  },
  Voice_90345_UnlockDesc = {
    Text = "Mendapatkan Pembangun \"Dullesain\" untuk membuka kunci"
  },
  Voice_90346_AwakerVoiceContent = {
    Text = "Memikirkan kembali, para pelayan perempuan pada saat Pengangkut Cahaya sebenarnya tidak berbeda banyak dengan saya dan Polydeuces, kita semua hidup dengan rantai tetapi mereka terus tunduk dan Bertahan. Namun, pelayan perempuan berwarna hijau itu tampaknya berbeda, dia... sangat bersemangat, seolah-olah dilahirkan untuk menyukai melakukan hal-hal ini, mungkin dia sudah memiliki kebebasan yang paling berharga."
  },
  Voice_90346_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Karen"
  },
  Voice_90346_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Karen\", akan terbuka."
  },
  Voice_90347_AwakerVoiceContent = {
    Text = "Kalian tidak bisa menghancurkanku!"
  },
  Voice_90347_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_90348_AwakerVoiceContent = {
    Text = "Masih belum...bisa keluar terbang?"
  },
  Voice_90348_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_90349_AwakerVoiceContent = {
    Text = "Biarlah angin menyebarkannya!"
  },
  Voice_90349_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Dua"
  },
  Voice_90350_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_90351_AwakerVoiceContent = {
    Text = "Salam hormat, senang bertemu, saya adalah Castor...apakah perlu mengatakan sesuatu yang lain? Maaf, saya kurang pandai berbicara, jika ada yang perlu Anda ketahui tentang saya, silakan panggil saya kapan saja."
  },
  Voice_90351_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_90352_AwakerVoiceContent = {
    Text = "Hanya begini saja..."
  },
  Voice_90352_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_90353_AwakerVoiceContent = {Text = "Jatuhlah!"},
  Voice_90353_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_90354_AwakerVoiceContent = {
    Text = "Ada banyak hal yang belum saya lihat, banyak yang belum saya lakukan, air danau hijau yang gersang itu dan kabut pekat tidak akan menahan kami lagi. Laut, kota besar, lahan pertanian pedesaan, tempat-tempat yang disebutkan dalam buku catatan, aku ingin melihatnya semua, bersama dengan Polydeukes dan Anda."
  },
  Voice_90354_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_90354_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_90355_AwakerVoiceContent = {
    Text = "Ketika kamu mendengar daun-daun di pohon bergemerisik, kamu tahu aku sudah di sampingmu."
  },
  Voice_90355_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_90355_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_90356_AwakerVoiceContent = {
    Text = "Bulu-bulu gelap ini menjadi semakin mendalam."
  },
  Voice_90356_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_90357_AwakerVoiceContent = {
    Text = "Sebenarnya yang paling saya iri adalah cara Anda dan rekan-rekan Anda saling mempercayai tanpa kecurigaan, perasaan dilupakan dan dikhianati... sungguh menyakitkan."
  },
  Voice_90357_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_90358_AwakerVoiceContent = {
    Text = "Pencuri ulung tersebut memberitahuku bahwa dia bisa mengajarkanku keterampilan bertahan hidup paling hebat di jalanan, hanya dengan membayarnya lima ratus Leobang... Apakah aku tertipu? Tidak, aku rasa ini sangat berharga untuk dipelajari, ini adalah yang aku dan Pollux kurang... Masalah uang? Aku mengerti, lalu, aku akan mencari cara untuk berdiskusi dengannya, bagaimana jika aku membayarnya empat ratus lima puluh Leobang?"
  },
  Voice_90358_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Tentang Jenkin"
  },
  Voice_90358_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Jenkin\", akan terbuka."
  },
  Voice_90359_AwakerVoiceContent = {
    Text = "Saya masih bisa menahan..."
  },
  Voice_90359_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_90360_AwakerVoiceContent = {
    Text = "Saat kecil, kontrol lentera terhadap kami tidak begitu ketat. Kadang-kadang Polydeukes entah bagaimana berhasil mendapatkan permen. Rasanya mencicipi permen itu... seperti sekarang ini."
  },
  Voice_90360_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_90360_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_90361_AwakerVoiceContent = {
    Text = "Dengan tubuh yang abadi ini, menahan segala clades!"
  },
  Voice_90361_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_90362_AwakerVoiceContent = {
    Text = "Bolehkah Anda ajarkan saya, tentang pengetahuan perdagangan dengan orang-orang? Bagaimana bertukar barang, bagaimana mengelola mata uang yang didapat, sungguh sebuah ilmu yang mendalam. Mendapat kebebasan hanyalah awal, untuk hidup mandiri, saya dan Polydeukes masih banyak yang harus belajar, dan ke depan mohon bantuannya."
  },
  Voice_90362_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_90363_AwakerVoiceContent = {
    Text = "Biarlah angin menyebarkannya!"
  },
  Voice_90363_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  },
  Voice_90364_AwakerVoiceContent = {
    Text = "Angin, bawa dia menuju mulut kematian!"
  },
  Voice_90364_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_90365_AwakerVoiceContent = {
    Text = "Polydeuces... meskipun dipenuhi banyak pikiran buruk dari Pengangkut Cahaya, tetapi hatinya tidak buruk. Dia hanya sangat menginginkan pengakuan dari Pengangkut Cahaya, dari umat, sehingga dia terlalu memperhatikan kebutuhan mereka. Daripada mengatakan dia terlalu egois, lebih baik mengatakan bahwa dia selalu takut kehilangan \"diri\"."
  },
  Voice_90365_AwakerVoiceTitle = {
    Text = "Kisah·Tentang Pollux"
  },
  Voice_90365_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Pollux\", akan terbuka."
  },
  Voice_90366_AwakerVoiceContent = {
    Text = "Maaf, saya tidak sengaja melamun... Anda bertanya apa ini? Ini adalah... hal yang paling penting baginya, juga yang paling penting bagi saya. Indah, bukan?"
  },
  Voice_90366_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_90367_AwakerVoiceContent = {
    Text = "Saat itu kami belajar teologi setiap hari di bawah bimbingan Albino atau penjaga lampu, dan keinginanku yang terbesar saat itu adalah bahwa suatu hari teks-teks dapat direvisi ulang menjadi lebih pendek dan lebih sedikit. Dengan begitu, aku tidak akan pusing karena hapalan dan mendapat teguran dari penjaga lampu yang ketat."
  },
  Voice_90367_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_90367_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_90368_AwakerVoiceContent = {
    Text = "Terima kasih, memberi saya kunci untuk menguasai kebebasan."
  },
  Voice_90368_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_90369_AwakerVoiceContent = {
    Text = "Sayap ini akhirnya tumbuh menjadi paling kuat, begitu kokoh dan kuat. Sekarang saya bisa membawa Anda dan Poluksus sekaligus, ketika Anda ingin terbang ke langit, panggil saya dengan lantang."
  },
  Voice_90369_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_90369_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_90370_AwakerVoiceContent = {
    Text = "Sembunyilah di belakang sayap!"
  },
  Voice_90370_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_90371_AwakerVoiceContent = {
    Text = "Akhirnya... melihat langit penuh bintang yang disebutkan dalam buku itu."
  },
  Voice_90371_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_90372_AwakerVoiceContent = {
    Text = "Dulu, Pemimpin Tertinggi... Juliette juga sering menunjukkan momen-momen kehangatan kepada kita, dia selalu tersenyum ramah kepada semua orang, membuat orang tidak tega mengecewakan harapannya. Selama dia tersenyum dan menepuk kepala Anda, kata-kata penolak tidak akan dapat diucapkan. Hmm, sekarang tidak lagi, Anda dapat dengan bebas menyentuh kepala saya."
  },
  Voice_90372_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_90372_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_90373_AwakerVoiceContent = {
    Text = "Saya telah terendam dalam lendir hitam itu lama sekali, lama sekali sampai saya lupa waktu, lama sampai... bahkan Polydeukes melupakan saya. Itu tidak membawa rasa sakit fisik, tetapi semacam teror jiwa saat melihat diri sendiri menghilang."
  },
  Voice_90373_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Krisis"
  },
  Voice_90374_AwakerVoiceContent = {
    Text = "Sejak kecil kami tidak diizinkan terlalu banyak berinteraksi dengan orang lain, kata 'teman' baru kami ketahui lama setelah itu. Saya dan Polydeukes, tidak memiliki apa-apa selain satu sama lain, saudara, teman, narapidana di penjara yang sama, itulah kami, hanya kami. Sekarang, saatnya untuk mencari teman baru."
  },
  Voice_90374_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_90374_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_90375_AwakerVoiceContent = {Text = "Mundur!"},
  Voice_90375_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_90376_AwakerVoiceContent = {
    Text = "Sebuah sekolah di mana semua orang bisa berkomunikasi dengan bebas dan berteman sesuka hati? Kamu bilang di sini tidak mempelajari teologi, tapi bisa memilih berbagai macam pelajaran... bahkan bisa bolos? Hmm, benar-benar tempat yang indah."
  },
  Voice_90376_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Mythag"
  },
  Voice_90377_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_90378_AwakerVoiceContent = {Text = "Minggir!"},
  Voice_90378_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_95050_AwakerVoiceContent = {
    Text = "Orang yang tidak menghormati... pasti akan ada hukuman..."
  },
  Voice_95050_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_95051_AwakerVoiceContent = {
    Text = "Jiwaku bersinar!"
  },
  Voice_95051_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_95052_AwakerVoiceContent = {
    Text = "Benda yang tercemar."
  },
  Voice_95052_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_95053_AwakerVoiceContent = {
    Text = "Seorang pengikut yang terlalu fanatik, mungkin di mata dunia hanyalah orang gila yang tidak bisa dimengerti, meski dia pernah tersesat, tetapi tekadnya untuk mengorbankan segalanya demi Dewa adalah keteguhan yang tak mampu dilakukan oleh kebanyakan orang biasa, untuk dia... saya hanya merasakan kesedihan bertemu sesama."
  },
  Voice_95053_AwakerVoiceTitle = {
    Text = "Ngobrol: Tentang Miryam"
  },
  Voice_95053_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Miryam\", akan terbuka."
  },
  Voice_95054_AwakerVoiceContent = {
    Text = "Saya akan membawa bimbingan dan penghakiman, cahaya malam putih akan mengusir kejahatan kalian!"
  },
  Voice_95054_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_95055_AwakerVoiceContent = {
    Text = "Hah… Selama ini, dia tetap tidak berubah. Diri saya yang kecil mungkin tidak pernah berpikir, suatu hari saya akan menyakiti dan berhutang budi kepada kakak saya begitu banyak, hingga membuatku merasa malu, meskipun nasib tragis ini bukan di bawah kendali kita. Kita sudah mengalami banyak perpisahan, tetapi, sekarang saya sudah kembali, tidak ada yang dapat memisahkan kita lagi, bahkan kematian sekalipun."
  },
  Voice_95055_AwakerVoiceTitle = {
    Text = "Gosip: Tentang Castor"
  },
  Voice_95055_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Kastor\", akan terbuka."
  },
  Voice_95056_AwakerVoiceContent = {
    Text = "Dulu aku membenci banyak hal. Pelayan yang tidak tahu sopan santun, pelayan yang mengabaikan tingkatan, penyembah berhala yang menghina dewa…… tetapi sekarang, hanya lampu saja, hanya lampu！ Juliette dan sekte-nya memberi kami dan kakakku luka yang tak terobati. Demi nama Sang Anak, aku bersumpah, luka ini tidak akan kuizinkan muncul di tubuh orang lain！"
  },
  Voice_95056_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_95057_AwakerVoiceContent = {
    Text = "Saya akan mengikuti jalan yang terang, sampai menghabiskan hidup saya."
  },
  Voice_95057_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_95058_AwakerVoiceContent = {
    Text = "Cahaya Pemegang Lampu pada akhirnya akan menerangi malam yang panjang!"
  },
  Voice_95058_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_95059_AwakerVoiceContent = {
    Text = "Anda selalu begitu dermawan dan penyayang, saya akan sangat menghargai suhu terang ini."
  },
  Voice_95059_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_95060_AwakerVoiceContent = {
    Text = "Utusan Pemegang Lampu, lahir dari malam yang putih, pengusir kegelapan, Putra Hati Suci, aku, Polyx, datang atas panggilanmu, memberikan kekuatanku yang gelap dan jiwa cahayaku."
  },
  Voice_95060_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_95061_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_95062_AwakerVoiceContent = {
    Text = "Bersihkan dosamu!"
  },
  Voice_95062_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_95063_AwakerVoiceContent = {
    Text = "Dulunya semua orang memberitahu saya, bahwa warna hitam yang dalam ini adalah keyakinan saya, yang akan saya bawa sebagai berkat bagi para pengikut. Kini, kegelapan ini telah menggerogoti saya dan menyatu dengan saya... tetapi hati yang berdegup dalam tubuh berdosa ini adalah tempat yang tidak akan pernah tergerogoti. Jangan khawatir, saya pasti akan menggunakan kemampuan yang diberikan oleh warna hitam ini untuk memberikan kesejahteraan yang sejati kepada umat manusia!"
  },
  Voice_95063_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Krisis"
  },
  Voice_95064_AwakerVoiceContent = {
    Text = "Saya akan menyebarkan nama besar Anda, semua yang kotor dan tidak bersih, pada akhirnya akan dibersihkan oleh cahaya."
  },
  Voice_95064_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_95065_AwakerVoiceContent = {
    Text = "Segala dosa yang telah lalu telah dilakukan, aku tidak seharusnya menghindarinya lagi. Aku harus memperbaiki kesalahan lampu yang menyala, dan mengarahkan orang-orang yang tersesat ke jalan yang benar. Biarkan aku memikul dosaku. Kemudian, aku akan menjawab cahaya ini, menjawab panggilanmu, dan menapaki jalan yang sejati, yang menjadi milik Anak Suci."
  },
  Voice_95065_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_95065_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_95066_AwakerVoiceContent = {
    Text = "Betapa penuh belas kasihnya hati yang membuat Anda bersedia memaafkan seseorang yang penuh dosa, saya bisa merasakan, sinar murni dalam jiwa Anda yang lebih cerah dari cahaya, mungkin Anda bisa membimbing hati saya yang tersesat..."
  },
  Voice_95066_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_95066_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_95067_AwakerVoiceContent = {
    Text = "Kegelapan itu, kegelapan yang menyebar dari mantra Juliette, terus membayangi pikiranku... tapi sekarang, di dalam kegelapan itu, tiba-tiba ada cahaya! Titik cahaya yang lemah itu, apakah ingin memberitahuku sesuatu?"
  },
  Voice_95067_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_95067_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_95068_AwakerVoiceContent = {
    Text = "Kabarnya dia pernah menjadi seorang perawan suci, tetapi, sikapnya yang kasar dan tindakan yang seenaknya... Apa? Dia bahkan tidak bisa menghafal satu ayat doa? Sikap yang sama sekali tidak khusyuk seperti itu, membuat saya merasa malu bagi dewa-dewanya."
  },
  Voice_95068_AwakerVoiceTitle = {
    Text = "Gosip: Tentang Murphy"
  },
  Voice_95068_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Murphy\", akan terbuka."
  },
  Voice_95069_AwakerVoiceContent = {
    Text = "Orang yang dapat memimpin semua orang keluar dari kabut adalah pemegang lampu yang terbuat dari perak murni. Tanah suci tak bersalah yang disebut Juliette ternyata dibangun dari tumpukan mayat para pengikut. Sebagai anak suci, aku akan menyebarkan Injil baru kepada semua orang beriman yang layak diselamatkan."
  },
  Voice_95069_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Mythag"
  },
  Voice_95070_AwakerVoiceContent = {
    Text = "Wahai yang memandu dan memberi terang padaku, dulunya aku selalu terjebak dalam makna yang salah, kini di bawah petunjukmu, aku telah menemukan kembali misiku yang sebenarnya—mengubah pengikut yang bodoh dan menyimpang, untuk membawa cahaya yang abadi ke dunia. Aku tahu tentang ketidakberdayaanmu, kau tidak perlu kesalehan dan persembahanku, biarkan aku mengikuti Anda, mencatat setiap firman dan perbuatanmu yang suci, untuk menerangi jalanku di malam yang gelap."
  },
  Voice_95070_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_95070_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_95071_AwakerVoiceContent = {
    Text = "Dengan belenggu, berenang dalam kegelapan, menuju cahaya itu, dengan tekad yang tak tergoyahkan … apakah ini yang ingin kamu katakan padaku?"
  },
  Voice_95071_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_95071_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_95072_AwakerVoiceContent = {
    Text = "Seorang pelayan terang kehilangan nyalanya, rasa sakit buta ini sungguh membuatku gelisah, aku dengan tulus memohon padamu untuk menyelamatkan jiwa yang tersesat ini, tolong pegang tanganku, dekati hati suci ini, tolong berikan aku panduan menuju cahaya…"
  },
  Voice_95072_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_95072_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_95073_AwakerVoiceContent = {
    Text = "Anak malang, tetapi karena dia telah terjun ke dalam mengikuti jalan-Mu, dia pasti akan mendapatkan penebusan akhir. Namun, mengapa teman monyetnya juga mendapatkan rahmat-Mu? Anak jahat itu bahkan mencuri artefak doaku! Pasti di dalam jiwanya terpendam dosa yang mengalir seperti banjir, benar-benar tidak menghormati! Tidak menghormati!"
  },
  Voice_95073_AwakerVoiceTitle = {
    Text = "Ngobrol: Tentang Aigis dan Jenki"
  },
  Voice_95073_UnlockDesc = {
    Text = "Mendapatkan badan bangun \"Aigis\", badan bangun \"Jenkin\" setelah dibuka kuncinya"
  },
  Voice_95074_AwakerVoiceContent = {
    Text = "Segera pergi."
  },
  Voice_95074_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_95075_AwakerVoiceContent = {
    Text = "Cahaya Pemegang Lampu pada akhirnya akan menerangi malam yang panjang!"
  },
  Voice_95075_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_95076_AwakerVoiceContent = {
    Text = "Ah… saya telah melihatnya, kekuatan agung yang dahsyat, kebenaran dunia… saya telah mengetahui kesalahan jalan saya di masa lalu, Anda adalah pemegang cahaya yang sejati! Mohon izinkan saya menjadi rasul setia Anda, hati ini yang lahir untuk pemegang cahaya, akan terus bergetar bersukacita dan tunduk kepada Anda…"
  },
  Voice_95076_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_95076_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_95077_AwakerVoiceContent = {
    Text = "Keselamatan buta dari pastor itu benar-benar tindakan bodoh yang tidak dapat diterima, Injil Tuhan seharusnya hanya diberikan kepada orang-orang yang benar-benar taat. Jika bahkan rasul Tuhan tidak memiliki mata tajam untuk menilai, sehingga memberikan penghargaan kepada para penjahat yang tidak bertobat dan penuh dosa, merusak kemurnian kerajaan Tuhan, bukankah ini merupakan penghianatan terhadap Dewa dan orang-orang saleh itu?"
  },
  Voice_95077_AwakerVoiceTitle = {
    Text = "Ngobrol: Tentang Salvador"
  },
  Voice_95077_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Salvador\", akan terbuka."
  },
  Voice_95078_AwakerVoiceContent = {
    Text = "Jiwaku bersinar!"
  },
  Voice_95078_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_95079_AwakerVoiceContent = {Text = "Hah!"},
  Voice_95079_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_95080_AwakerVoiceContent = {
    Text = "Ketika aku masih kecil, aku ingin terbang keluar dari sangkar, saat itu aku selalu menganggap tempat yang hanya membawa rasa sakit ini tidak layak untuk dikenang. Namun setelah mengalami dua kehidupan, aku menyadari bahwa kebebasan bukanlah satu-satunya hal yang aku idamkan; melihat wajah-wajah para pengikut saat mereka mengetahui akan mendapatkan penebusan, penuh dengan ketulusan, harapan, dan rasa terima kasih, itulah arti sebenarnya dari identitas ini."
  },
  Voice_95080_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_95081_AwakerVoiceContent = {
    Text = "Selama mengikuti Juliette, aku telah melakukan banyak kesalahan, aku seharusnya tidak mendapatkan kepercayaan seperti ini lagi. Tapi kamu tetap memilihku... tenang saja, aku akan mencarikan kembali keyakinanku yang seharusnya. Anak Suci tidak akan mengecewakan rakyatnya, dan juga tidak akan mengecewakanmu."
  },
  Voice_95081_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_95081_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_95082_AwakerVoiceContent = {
    Text = "Berkat yang Anda berikan, akan saya gunakan dengan penuh rasa syukur."
  },
  Voice_95082_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_95083_AwakerVoiceContent = {
    Text = "Tidak sopan!"
  },
  Voice_95083_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_95084_AwakerVoiceContent = {Text = "Sial."},
  Voice_95084_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_95085_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_95086_AwakerVoiceContent = {
    Text = "Demi namaku！"
  },
  Voice_95086_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_95087_AwakerVoiceContent = {
    Text = "Saya melihatnya! Cahaya itu, cahaya yang bersinar di kedalaman kesadaran, semakin lama semakin terang! Ia memanggil saya …"
  },
  Voice_95087_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_95087_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_95088_AwakerVoiceContent = {
    Text = "Di masa kanak-kanak, Castor dan aku menjabat sebagai Putra Suci. Saat itu, aku selalu berpikir dia terlalu kaku dan canggung, perlu dipandu olehku untuk menentukan arah masa depan. Kini, setelah memahami jalan yang telah kamu lalui, aku baru mengerti bahwa fondasi dunia dibangun dan dipelopori oleh orang-orang sepertimu dan dia yang setia dan penuh integritas."
  },
  Voice_95088_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_95088_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_95089_AwakerVoiceContent = {
    Text = "Lampu penerang saya, sejak mendapatkan petunjuk dari Anda, saya rasa saya telah menempuh jalan yang benar. Kini, pengikut Anda yang bodoh masih memiliki satu keraguan, apakah tanah suci yang disebut tidak bersalah juga berada di bawah kekuasaan Anda? Tidak ada hal seperti itu? Apakah maksud Anda … tanah suci yang tidak bersalah ada di tengah manusia, di dalam hati orang-orang yang benar-benar suci?"
  },
  Voice_95089_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_95090_AwakerVoiceContent = {
    Text = "Jantung yang mendengar kehendak Tuhan ini, kini semakin dekat dengan Anda."
  },
  Voice_95090_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_95091_AwakerVoiceContent = {
    Text = "Anda... apakah Anda memiliki perintah yang ingin disampaikan kepada saya? Utusan Anda selalu siap mendengarkan ajaran Anda."
  },
  Voice_95091_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_95092_AwakerVoiceContent = {
    Text = "Terangi saya, pemandu yang tersesat! Dengan cintamu, saya telah melihat segala yang perlu saya lihat... Saya akan menggunakan tubuh terkutuk ini untuk membersihkan semua yang berlalu, dan biarkan segala sesuatu di masa depan terberkati dalam cahaya ini!"
  },
  Voice_95092_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_95092_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_95093_AwakerVoiceContent = {
    Text = "Menghymn cahaya!"
  },
  Voice_95093_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_95391_AwakerVoiceContent = {
    Text = "Apakah mengejar penyelamatan di dunia yang brutal? Ayo semangat, anak kecil yang penuh harapan."
  },
  Voice_95391_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_95391_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_95392_AwakerVoiceContent = {
    Text = [[
Ayo, ini ambil dan mainkan, katanya ini adalah barang terlarang yang digali dari reruntuhan. Saya tidak tertarik dengan barang-barang yang terkontaminasi oleh auras mereka, saya ingin langsung membakarnya, tapi memikirkan mungkin itu berguna bagimu, jadi saya membawanya. 
Kamu bertanya bagaimana saya mendapatkannya? Tentu saja, diberikan oleh beberapa orang yang "sukarela", jangan khawatir, jalan keluarnya dijamin "bersih".]]
  },
  Voice_95392_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_95392_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_95393_AwakerVoiceContent = {
    Text = "Perburuan selesai, bayaran cukup menggunakan senyuman bocah kecil itu."
  },
  Voice_95393_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_95394_AwakerVoiceContent = {
    Text = [[
Tahukah kamu, nak? Di antara dua pistol ini, yang ditembakkan bukan peluru, melainkan kumpulan keinginan dan niat jahat.
Kekacauan yang tidak teratur ini membentuk api seperti daging, pada suara tembakan ketujuh di ujung sana, ini akan menyeret semuanya ke dalam neraka untuk dibakar.]]
  },
  Voice_95394_AwakerVoiceTitle = {
    Text = "Ngobrol: Tentang Senjata"
  },
  Voice_95395_AwakerVoiceContent = {
    Text = "Tidak perlu memaksa diri terlalu keras, Penjagaku. Meskipun saya tahu ini adalah jalan yang tidak bisa ditunda dan berliku, sedikit kesalahan dapat menyebabkan kerusakan abadi. Tetapi jika terus seperti ini, suatu hari kamu akan jatuh karena kelelahan. Jika perlu, bicaralah padaku, sebagai keluarga."
  },
  Voice_95395_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_95395_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_95396_AwakerVoiceContent = {
    Text = "Bakar, kehancuran, teriakkanlah!"
  },
  Voice_95396_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_95397_AwakerVoiceContent = {
    Text = "Menghilanglah."
  },
  Voice_95397_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_95398_AwakerVoiceContent = {
    Text = "Visi saya semakin jelas, saya melihat sesuatu yang tersembunyi di dalam jurang... Untuk kalian, saya harus memiliki kekuatan yang lebih besar..."
  },
  Voice_95398_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_95398_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_95399_AwakerVoiceContent = {
    Text = "Ayo Penjaga, duduklah, saat ini terasa sangat canggung.\nTahukah kamu, ketika pertama kali melihatmu, saya tidak pernah berpikir bahwa suatu hari saya bisa melepas cangkang yang disebut kejam dan dingin ini di hadapanmu. Terasa konyol, bukan? Sang penguasa yang terkenal kejam, namun ingin memiliki seseorang untuk mencurahkan isi hati.\nBuatlah janji, jika pada hari itu kamu tidak tahan lagi…… panggil saja namaku di dalam hatimu, Aku akan membawamu bersamaku, menuju kerajaan-ku. Meskipun ini hanya akan menunda kedatangan segalanya, setidaknya di momen terakhir, kamu bisa beristirahat dengan baik di pelukanku."
  },
  Voice_95399_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_95399_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_95400_AwakerVoiceContent = {
    Text = "Sambutlah akhir!"
  },
  Voice_95400_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_95401_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_95401_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_95402_AwakerVoiceContent = {
    Text = "Di tengah berjuta keinginan dan niat jahat, bakarlah!"
  },
  Voice_95402_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_95403_AwakerVoiceContent = {
    Text = "Setelah berburu berhasil, selalu perlu diadakan pesta perayaan, ayo, cobalah daging unta yang saya panggang dan tequila yang baru saya dapatkan. Tunggu, kecil, sepertinya kamu tidak bisa minum alkohol... Kalau begitu, minum jus khusus saya!"
  },
  Voice_95403_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_95403_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_95404_AwakerVoiceContent = {
    Text = "Ada apa, anak kecil? Apakah kamu ingin pelukan? Ayo, dada saya yang panas ini selalu terbuka untukmu... Haha, jangan malu, sebagai kakak sangat wajar memperhatikan adik kecil, bukankah?"
  },
  Voice_95404_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_95406_AwakerVoiceContent = {Text = "Sial."},
  Voice_95406_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_95407_AwakerVoiceContent = {
    Text = "Sambutlah kematian berwarna amber!"
  },
  Voice_95407_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_95408_AwakerVoiceContent = {
    Text = "Mari mundur, aku akan menutup jalan... Tenang, aku akan kembali hidup-hidup."
  },
  Voice_95408_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_95409_AwakerVoiceContent = {
    Text = "Ayo, mari kita bakar segalanya hingga menjadi abu!"
  },
  Voice_95409_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_95410_AwakerVoiceContent = {
    Text = "Api Ledakan, hidup kembali di sini!"
  },
  Voice_95410_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_95411_AwakerVoiceContent = {
    Text = "Api semakin berkobar, apakah kamu ingin melihat kembang api yang megah?"
  },
  Voice_95411_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_95412_AwakerVoiceContent = {
    Text = "Orang-orang yang menginjak-injak kemanusiaan, bersembunyi di bayangan, melakukan pengorbanan dan penelitian kotor menggunakan @1 sebagai bahan... suatu saat nanti, saya akan membunuh semuanya."
  },
  Voice_95412_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_95413_AwakerVoiceContent = {Text = "Dentang!"},
  Voice_95413_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_95414_AwakerVoiceContent = {
    Text = [[
Saya akan menemukan dia, tidak peduli di sudut mana dari alam semesta dia bersembunyi, saya pasti akan menemukannya.
Saya akan membuat tikus kotor ini membayar segala sesuatu sebagai harga, begitu saya menemukan dia, semua kegembiraan dan kebahagiaan di dunia akan terbakar dalam neraka.
Jangan khawatir, pada saat itu saya akan menyisihkan tempat khusus di pemakamannya untukmu, agar kita bersama-sama, menikmati jeritan terakhirnya.]]
  },
  Voice_95414_AwakerVoiceTitle = {
    Text = "Gosip: Tentang N"
  },
  Voice_95415_AwakerVoiceContent = {
    Text = "Dengarkan, jeritan bintang-bintang yang meleleh."
  },
  Voice_95415_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_95415_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_95416_AwakerVoiceContent = {
    Text = "Sambutlah akhir!"
  },
  Voice_95416_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_95417_AwakerVoiceContent = {
    Text = "Kamu adalah keluargaku yang membuatku bangga, percayalah, Penjagaku! Apa pun yang terjadi, aku adalah dukungan terkuatmu."
  },
  Voice_95417_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_95418_AwakerVoiceContent = {
    Text = "Makhluk-makhluk yang tidak dapat dijelaskan itu sedang menggerogoti dunia ini, dan kamu tidak akan bisa menghindari untuk menjadi musuh mereka. Tetapi tidak masalah, karena saya akan ada di belakangmu."
  },
  Voice_95418_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_95418_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_95420_AwakerVoiceContent = {
    Text = "Bakar, kehancuran, teriakkanlah!"
  },
  Voice_95420_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_95421_AwakerVoiceContent = {
    Text = "Tetap tenang."
  },
  Voice_95421_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_95422_AwakerVoiceContent = {Text = "Mundur."},
  Voice_95422_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_95423_AwakerVoiceContent = {
    Text = "Kau bertanya padaku bagaimana pandanganku tentang Pelarutan? Ini seperti bertanya kepada seekor tikus kecil yang berkeliaran di saluran pembuangan bagaimana ia memandang tuan besar yang tinggi. Jawabanku hanya satu: rasa jijik yang datang dari insting tubuh. Jika bisa, aku akan menikmati susu unta yang lezat sambil menyaksikan teriakan gagak mereka saat mati di bawah senjataku."
  },
  Voice_95423_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Krisis"
  },
  Voice_95424_AwakerVoiceContent = {
    Text = "Ingin api lebih menyala lagi?"
  },
  Voice_95424_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_95424_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_95425_AwakerVoiceContent = {
    Text = "Saya hanya akan datang ke sini saat menerima misi, jika si kecil ingin menemui saya, gunakan mantra ini. Ayo, ikuti saya:……………… Ia! KathiguRa!"
  },
  Voice_95425_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Mythag"
  },
  Voice_95426_AwakerVoiceContent = {
    Text = "Dahulu kala, kami bertahan hidup di kota usang itu dengan keberanian dan kelicikan. Bahkan setelah menjadi yang disebut \"kekuatan besar\", ketika menghadapi tuan, regu penjaga, dan \"Tuan Kesatria\" yang enggan mundur dari panggung sejarah, kami harus bersemangat sepenuhnya. Tapi sekarang berbeda, semua orang telah menjadi \"kaumku\", tidak perlu lagi melihat muka orang lain. Yah, meskipun masih ada satu anak kecil yang tersesat di luar, saya percaya anak itu pasti akan aman, karena setiap kali saya sibuk di luar, dia yang merawat orang lain."
  },
  Voice_95426_AwakerVoiceTitle = {
    Text = "Gosip: Tentang Keluarga"
  },
  Voice_95427_AwakerVoiceContent = {
    Text = "Ini adalah musuh si bocah kecil? Jadi—perburuan dimulai."
  },
  Voice_95427_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_95428_AwakerVoiceContent = {
    Text = "Aku adalah raja ledakan yang tak terlupakan! Mengumumkan! Segala sesuatu akan musnah!"
  },
  Voice_95428_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_95429_AwakerVoiceContent = {
    Text = [[
Membakar dan menghancurkan adalah segalanya bagiku, saya antusias terhadap kematian yang dibawa oleh perburuan... Apakah kamu pikir saya akan berkata begitu?
Haha, itu hanya lelucon, yang terpenting tentu saja adalah semua orang di sekeliling saya. Tidak ada yang lebih penting dari mereka, bahkan... saya sendiri tidak.]]
  },
  Voice_95429_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_95430_AwakerVoiceContent = {
    Text = "Apakah si kecil mengalami masalah? Maka ikutilah panggilan, Katie Gula akan datang dengan kehancuran. Biarkan semua masalah hilang— \"ke peupeu\" menjadi debu."
  },
  Voice_95430_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_95431_AwakerVoiceContent = {
    Text = "Rasa kekuatan, mau coba-coba seseorang yang sial?"
  },
  Voice_95431_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_95431_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_95432_AwakerVoiceContent = {
    Text = "Aku adalah raja ledakan yang tak terlupakan! Mengumumkan! Segala sesuatu akan musnah!"
  },
  Voice_95432_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_95433_AwakerVoiceContent = {
    Text = "Ratu Aralan yang legendaris, substansi keinginan yang agung Tifreyey metod, pernah aku lihat saat mengejar N. Meskipun aku tidak setuju dengan apa yang dilakukannya, namun jujur, jika itu satu-satunya cara aku bisa melihat orang-orang bertahan dari pandangan \"Dia\"…… aku juga akan membuat pilihan yang sama. Dari sudut pandang ini, aku dan dia tidak berbeda."
  },
  Voice_95433_AwakerVoiceTitle = {
    Text = "Ngobrol: Tentang Thais"
  },
  Voice_95433_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Thais\", akan terbuka."
  },
  Voice_95434_AwakerVoiceContent = {
    Text = "Rasanya sangat baik, senjatanya terawat dengan baik."
  },
  Voice_95434_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_95435_AwakerVoiceContent = {
    Text = "Aku adalah api, adalah nyala, adalah kekacauan yang tak akan pernah padam... Aku akan membawa kalian... pulang..."
  },
  Voice_95435_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_95435_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_96361_AwakerVoiceContent = {
    Text = "Menara bergaya Gotik di sini memiliki nuansa klasik, dan makhluk Pembangun di sini juga memiliki aroma yang belum pernah kutemui sebelumnya, campuran antara aroma orang mati dan sedikit aroma kehidupan, sungguh... membuatku ingin mencoba."
  },
  Voice_96361_AwakerVoiceTitle = {
    Text = "Obrolan Santai·Tentang Mythag"
  },
  Voice_96362_AwakerVoiceContent = {
    Text = "Untuk mereka yang mencari kematian, aku akan memenuhi keinginanmu."
  },
  Voice_96362_AwakerVoiceTitle = {
    Text = "Muliakan·Dua"
  },
  Voice_96363_AwakerVoiceContent = {
    Text = "Aku sudah tidak sabar untuk mulai."
  },
  Voice_96363_AwakerVoiceTitle = {Text = "Rouse"},
  Voice_96364_AwakerVoiceContent = {
    Text = "Hati tergerak, kan? Ayo, tamuku tercinta, jadilah tamu istimewa di sisiku, mari nikmati pesta ini. Biarkan aku membawamu, bersama-sama merasakan setiap resonansi lembut dari arwah."
  },
  Voice_96364_AwakerVoiceTitle = {
    Text = "Mencerahkan·Mekar"
  },
  Voice_96364_UnlockDesc = {
    Text = "Mencerahkan level 15 untuk membuka"
  },
  Voice_96365_AwakerVoiceContent = {
    Text = "Hush, jangan berbicara, mari kita sama-sama mendengarkan suara jiwa-jiwa yang telah pergi."
  },
  Voice_96365_AwakerVoiceTitle = {
    Text = "Affiniti·Satu"
  },
  Voice_96365_UnlockDesc = {
    Text = "Affiniti level 2 tercapai untuk membuka"
  },
  Voice_96366_AwakerVoiceContent = {
    Text = "Keindahan abadi adalah keyakinan kami. Mengaplikasikan pelan-pelan pada orang hidup, menghapus semua tanda keberadaan…… Ini adalah penyiksaan murni dan kejam bagi kehidupan."
  },
  Voice_96366_AwakerVoiceTitle = {
    Text = "Obrolan Santai · Tentang Krisis"
  },
  Voice_96367_AwakerVoiceContent = {
    Text = "Seperti aku, Pikman juga mengejar seni abadi, seharusnya kita bisa menjadi teman yang lebih baik. Namun dia berpendapat bahwa makan adalah tindakan yang merusak keabadian, pandangan seninya terlalu sempit."
  },
  Voice_96367_AwakerVoiceTitle = {
    Text = "Obrolan·Tentang Pikma"
  },
  Voice_96367_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Pickman\", akan terbuka."
  },
  Voice_96368_AwakerVoiceContent = {Text = "Ha!"},
  Voice_96368_AwakerVoiceTitle = {
    Text = "Pukulan·Satu"
  },
  Voice_96369_AwakerVoiceContent = {
    Text = "Tidak ada kata sifat yang dapat menggambarkan aroma memikat yang ada padamu, seperti aftertaste yang asam dan kaya dari anggur Bordeaux, serta kaya dan harum seperti kue krim, ah... Menunggu hari kematianmu mungkin akan menjadi hal terpenting dalam sisa hidupku."
  },
  Voice_96369_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Penjaga"
  },
  Voice_96370_AwakerVoiceContent = {
    Text = "Aku pernah melihat sebuah lokasi kejahatan, seorang pria dengan perlahan menguliti seorang gadis muda, memotong daging dan kuku tangannya, tetapi terus menyembuhkannya. Dia tidak ingin melihatnya mati, juga tidak ingin membuatnya hidup. Tentu saja aku tidak mungkin memberikannya kematian yang damai, hanya membuatnya terus mengalami nasib yang sama dengan gadis itu, kelihatannya sudah bertahun-tahun…… Bagi orang yang menghina kematian, ini sangat adil, bukan?"
  },
  Voice_96370_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Dibenci"
  },
  Voice_96371_AwakerVoiceContent = {
    Text = "Aku adalah dewa yang mengendalikan kematian, tetapi tolong jangan salah paham, aku tidak menciptakan kematian. Aku hanya mengikuti jejak kematian, memetik buah yang matang dan melimpah."
  },
  Voice_96371_AwakerVoiceTitle = {
    Text = "Mencerahkan·Melihat Jauh"
  },
  Voice_96371_UnlockDesc = {
    Text = "Mencerahkan level 1 untuk membuka"
  },
  Voice_96372_AwakerVoiceContent = {
    Text = "Apakah kamu juga merasa kerinduan terhadap aromaku, Yang Terhormat Penjaga?"
  },
  Voice_96372_AwakerVoiceTitle = {
    Text = "Ngobrol Santai·Sentuh"
  },
  Voice_96373_AwakerVoiceContent = {
    Text = "Hari ini, siapa yang harus dihidangkan di meja makan?"
  },
  Voice_96373_AwakerVoiceTitle = {
    Text = "Penyelidikan dimulai"
  },
  Voice_96374_AwakerVoiceContent = {
    Text = "Aku akan memberikan kalian, kehormatan dalam jamuan malam ini."
  },
  Voice_96374_AwakerVoiceTitle = {
    Text = "Penyelidikan berhasil"
  },
  Voice_96375_AwakerVoiceContent = {
    Text = "Sangat tidak anggun."
  },
  Voice_96375_AwakerVoiceTitle = {
    Text = "Serangan·Tiga"
  },
  Voice_96376_AwakerVoiceContent = {
    Text = "Aku akan membawa istirahat yang bersih."
  },
  Voice_96376_AwakerVoiceTitle = {
    Text = "Keterampilan·Satu"
  },
  Voice_96377_AwakerVoiceContent = {
    Text = "Sebelum setiap kali makan, aku selalu berbicara dengan arwah. Bagi mereka, dimakan dan dicicipi dengan sungguh-sungguh adalah perpanjangan hidup dan kemewahan terakhir. Seperti kita yang mendambakan mereka, mereka juga mendambakan kita."
  },
  Voice_96377_AwakerVoiceTitle = {
    Text = "Affiniti·Tiga"
  },
  Voice_96377_UnlockDesc = {
    Text = "Affiniti level 6 tercapai untuk membuka"
  },
  Voice_96378_AwakerVoiceContent = {
    Text = "Diam sedikit."
  },
  Voice_96378_AwakerVoiceTitle = {
    Text = "Serangan·Empat"
  },
  Voice_96379_AwakerVoiceContent = {
    Text = "Larutlah dalam bayangan!"
  },
  Voice_96379_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_96380_AwakerVoiceContent = {
    Text = "Kita sebaiknya menjaga jarak."
  },
  Voice_96380_AwakerVoiceTitle = {
    Text = "Pertahanan·Satu"
  },
  Voice_96381_AwakerVoiceContent = {
    Text = "Larutlah dalam bayangan!"
  },
  Voice_96381_AwakerVoiceTitle = {
    Text = "Keterampilan·Empat"
  },
  Voice_96382_AwakerVoiceContent = {
    Text = "Mengapa kamu begitu waspada terhadapku? Kamu tidak seharusnya, dan tidak perlu panik, menyerang orang hidup adalah bertentangan dengan estetika saya."
  },
  Voice_96382_AwakerVoiceTitle = {
    Text = "Obrolan·Tentang Makana"
  },
  Voice_96383_AwakerVoiceContent = {
    Text = "Untuk mereka yang mencari kematian, aku akan memenuhi keinginanmu."
  },
  Voice_96383_AwakerVoiceTitle = {Text = "Exalt"},
  Voice_96384_AwakerVoiceContent = {
    Text = "Sangat tidak anggun."
  },
  Voice_96384_AwakerVoiceTitle = {
    Text = "Serangan·Satu"
  },
  Voice_96385_AwakerVoiceContent = {Text = "Hati-hati."},
  Voice_96385_AwakerVoiceTitle = {
    Text = "Pertahanan·Dua"
  },
  Voice_96386_AwakerVoiceContent = {
    Text = "Walaupun antusiasme nyonya itu sangat mengharukan, baunya tercium memiliki aroma lembap yang terfermentasi. Meskipun dia terus-menerus memohon agar saya mencobanya, ini sama sekali tidak sesuai dengan selera saya, sungguh menyulitkan."
  },
  Voice_96386_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Tentang Leigh"
  },
  Voice_96386_UnlockDesc = {
    Text = "Setelah mendapatkan Pembangun \"Leigh\", akan terbuka."
  },
  Voice_96387_AwakerVoiceContent = {
    Text = "Tahukah kamu? Setiap kehidupan yang berlalu memiliki gema yang panjang. Nada-nada itu berbeda dan akan membesar sedikit demi sedikit sejak saat kematian datang, hingga perlahan menghilang di antara langit dan bumi, seperti suatu desahan yang merindukan."
  },
  Voice_96387_AwakerVoiceTitle = {
    Text = "Affiniti·Dua"
  },
  Voice_96387_UnlockDesc = {
    Text = "Affiniti level 4 tercapai untuk membuka"
  },
  Voice_96388_AwakerVoiceContent = {
    Text = "Jangan khawatir, Yang Mulia Penjaga, aku akan selalu ada di sampingmu, sampai hari ketika hidupmu menghadapi kehampaan yang tak terhindarkan. Saat itu, aku pasti akan menghabiskan tubuhmu dengan cara yang paling megah. Aku akan menyimpan jiwamu selamanya di dalam tubuhku."
  },
  Voice_96388_AwakerVoiceTitle = {
    Text = "Affiniti·Lima"
  },
  Voice_96388_UnlockDesc = {
    Text = "Affiniti level 10 tercapai untuk membuka"
  },
  Voice_96389_AwakerVoiceContent = {
    Text = "Apakah kamu tidak bisa mencium aroma dirimu sendiri? Oh, sangat disayangkan, kau telah melewatkan yang paling manis di dunia ini, yang paling... ah, mengapa kamu menghindar?"
  },
  Voice_96389_AwakerVoiceTitle = {
    Text = "Affiniti·Empat"
  },
  Voice_96389_UnlockDesc = {
    Text = "Affiniti level 8 tercapai untuk membuka"
  },
  Voice_96390_AwakerVoiceContent = {
    Text = "Aku bisa melihat lebih banyak kematian, pemandangan di seberang semakin jelas……"
  },
  Voice_96390_AwakerVoiceTitle = {
    Text = "Meningkatkan · Tiga"
  },
  Voice_96391_AwakerVoiceContent = {
    Text = "Serahkan tubuhmu padaku, biarkan aku mencicipimu dengan teliti, setiap tetes darah, setiap potongan daging, setiap tulang."
  },
  Voice_96391_AwakerVoiceTitle = {
    Text = "Muliakan Ekstrem"
  },
  Voice_96392_AwakerVoiceContent = {
    Text = "Bahan yang berbeda perlu perlakuan yang berbeda. Jeroan perlu diasinkan, tendon di bagian kaki sebaiknya direbus, bagian yang kaya lemak cocok untuk difermentasi, bagian yang memiliki rasa khusus bisa digoreng, dipanggang, bahkan dijadikan beberapa bentuk gel daging yang indah, semua ini membutuhkan pemilihan yang teliti. Tentu saja, menjaga dan menonjolkan rasa asli dari bahan makanan adalah bentuk penghormatan yang harus dilakukan."
  },
  Voice_96392_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemahaman"
  },
  Voice_96392_UnlockDesc = {
    Text = "Mencerahkan level 7 untuk membuka"
  },
  Voice_96393_AwakerVoiceContent = {
    Text = "Ini akan agak dingin."
  },
  Voice_96393_AwakerVoiceTitle = {
    Text = "Pukulan·Dua"
  },
  Voice_96394_AwakerVoiceContent = {
    Text = "Paduan makanan juga memiliki banyak hal yang perlu diperhatikan; asam dan manis, renyah dan lembut, segar dan berat, halus dan kasar—rasa yang bertingkat dan tekstur yang bertolak belakang bertabrakan, menciptakan pengalaman yang berbeda saat masuk ke mulut, mengunyah, dan menyisakan rasa. Inilah kesenangan tanpa akhir dan ajaib yang diberikan oleh makanan yang berkualitas."
  },
  Voice_96394_AwakerVoiceTitle = {
    Text = "Mencerahkan·Membangun"
  },
  Voice_96394_UnlockDesc = {
    Text = "Mencerahkan level mencapai 11 untuk membuka"
  },
  Voice_96395_AwakerVoiceContent = {
    Text = "Terima kasih banyak atas antusiasme Anda, saya sangat terhormat."
  },
  Voice_96395_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan·Dua"
  },
  Voice_96396_AwakerVoiceContent = {
    Text = "Makanan yang lezat selalu pantas untuk ditunggu lebih lama."
  },
  Voice_96396_AwakerVoiceTitle = {
    Text = "Penyelidikan dihentikan"
  },
  Voice_96397_AwakerVoiceContent = {
    Text = "Tentu saja aku bukan makhluk buas yang memakan daging mentah, menikmati proses kematian adalah sesuatu yang sakral dan elegan, kau harus berkomunikasi dengan penuh rasa hormat, memahami setiap bahan makanan dengan cita rasa yang unik."
  },
  Voice_96397_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pandangan"
  },
  Voice_96397_UnlockDesc = {
    Text = "Mencerahkan level 2 untuk membuka"
  },
  Voice_96398_AwakerVoiceContent = {
    Text = "Yang telah kembali tenang adalah arwah yang indah dan harum, bukan karena tubuh mereka berbeda antara hidup dan mati, tetapi karena jiwa mereka—pemahaman mereka tentang kematian, ketertarikan terhadap hidup, keinginan untuk diingat, adalah makanan yang sangat aku idam-idamkan."
  },
  Voice_96398_AwakerVoiceTitle = {
    Text = "Ngobrol Santai · Hal yang Disukai"
  },
  Voice_96399_AwakerVoiceContent = {
    Text = "Tidak ada parfum yang bisa menandingi keharuman alami tubuh manusia; mencium aroma dan mengenali orang adalah hal yang paling menakjubkan."
  },
  Voice_96399_AwakerVoiceTitle = {
    Text = "Mencerahkan·Pemikiran Mendalam"
  },
  Voice_96399_UnlockDesc = {
    Text = "Mencerahkan level 3 terbuka"
  },
  Voice_96400_AwakerVoiceContent = {
    Text = "Ah, betapa mendalamnya aroma itu... Aku sudah tak sabar menyambutmu masuk ke kuilku."
  },
  Voice_96400_AwakerVoiceTitle = {Text = "Awaken"},
  Voice_96401_AwakerVoiceContent = {
    Text = "Serahkan tubuhmu padaku, biarkan aku mencicipimu dengan teliti, setiap tetes darah, setiap potongan daging, setiap tulang."
  },
  Voice_96401_AwakerVoiceTitle = {
    Text = "Aliemus Muliakan·Dua"
  },
  Voice_96402_AwakerVoiceContent = {
    Text = "Aku akan membawa istirahat yang bersih."
  },
  Voice_96402_AwakerVoiceTitle = {
    Text = "Keterampilan·Dua"
  },
  Voice_96403_AwakerVoiceContent = {
    Text = "Diam sedikit."
  },
  Voice_96403_AwakerVoiceTitle = {
    Text = "Serangan·Dua"
  },
  Voice_96404_AwakerVoiceContent = {
    Text = "Aromamu yang harum sungguh memabukkan."
  },
  Voice_96404_AwakerVoiceTitle = {
    Text = "Mendapatkan Peningkatan · Satu"
  },
  Voice_98324_AwakerVoiceContent = {
    Text = "Di tengah berjuta keinginan dan niat jahat, bakarlah!"
  },
  Voice_98324_AwakerVoiceTitle = {
    Text = "Keterampilan Khusus·Pertama"
  }
})
return Text_Voice
